namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin")]
public class SettingsController : ControllerBase
{
    private readonly ISettingsService _settingsService;

    // Refactored in P1-S04: was directly injecting MongoDbContext, which violated
    // the controller-uses-service layer rule. The seed/backfill semantics now live
    // in SettingsService where domain rules belong.
    public SettingsController(ISettingsService settingsService)
    {
        _settingsService = settingsService;
    }

    [HttpGet]
    public async Task<IActionResult> GetSettings(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);

        // Sanitise — encrypted Stripe key fields must NEVER reach the frontend.
        // Null them out so they aren't serialised, then inject masked placeholders
        // as separate ad-hoc properties.
        var stripeConfig = await _settingsService.GetDecryptedStripeConfigAsync(ct);

        // Wipe encrypted blobs from the outbound entity — these are binary noise
        // to the frontend and must never leave the server.
        settings.StripePublishableKeyEncrypted = null;
        settings.StripeSecretKeyEncrypted = null;
        settings.StripeWebhookSecretEncrypted = null;

        // Return the full settings entity + masked display helpers.
        // Using an anonymous wrapper keeps the JSON shape flat (properties merge)
        // while the encrypted blobs are safely null/omitted.
        return Ok(new
        {
            // Spread all settings properties via serialisation
            settings.Id,
            settings.SetupCompleted,
            settings.MarketingSplitPercentage,
            settings.SavingsSplitPercentage,
            settings.OwnersSplitPercentage,
            settings.CancelWindowHoursGroup,
            settings.CancelWindowHoursPrivate,
            settings.CancelWindowHoursCreditGroup,
            settings.CancelWindowHoursCreditPrivate,
            settings.CancelWindowHoursOnlineGroup,
            settings.CancelWindowHoursOnlinePrivate,
            settings.CancelWindowHoursStudioGroup,
            settings.CancelWindowHoursStudioPrivate,
            settings.EnableLateReschedule,
            settings.LateRescheduleMaxPerMonth,
            settings.LateRescheduleMode,
            settings.LateRescheduleEligibleMethods,
            settings.ExpenseCategories,
            settings.StripeRoutingMode,
            settings.OnlinePaymentFeePercentage,
            settings.StudioRentalGroupPerHeadFee,
            settings.StudioRentalPrivatePerHeadFee,
            settings.StudioRentalGroupPackagePrice,
            settings.StudioRentalGroupPackageCredits,
            settings.StudioRentalPrivatePackagePrice,
            settings.StudioRentalPrivatePackageCredits,
            settings.EnableReceptionistKpiProgram,
            settings.ReceptionistKpiBonusPoolAmount,
            settings.ReceptionistDailyTaskCompletionPercent,
            settings.ReceptionistAttendanceCommissionPerHead,
            settings.ReceptionistAttendanceSplitMode,
            settings.ReceptionistDailyTasks,
            settings.ReceptionistRevenueTiers,
            settings.ReceptionistPackageSalesTiers,
            settings.ReceptionistGoogleReviewTiers,
            settings.RoleAccessSettings,
            settings.AllowOnlinePayment,
            settings.AllowPartialPayment,
            settings.AllowPayAtStudio,
            settings.DepositPercentage,
            settings.PartialPaymentLabelEn,
            settings.PartialPaymentLabelVi,
            settings.EnableCheckoutPackageUpsell,
            settings.UpsellHideForActivePackageHolders,
            settings.UpsellHeadlineEn,
            settings.UpsellHeadlineVi,
            settings.UpsellPackageIdGroup,
            settings.UpsellPackageIdPrivate,
            settings.UpsellPackageIdMixed,
            settings.EnableWaitlistSystem,
            settings.EnableSignUpEmailVerification,
            settings.EnableReservationSystem,
            settings.ReservationExpiryMinutes,
            settings.ReservationCleanupIntervalMinutes,
            settings.AllowGuestCheckout,
            settings.EnableGoogleAnalyticsEventTracking,
            settings.GoogleAnalyticsMeasurementId,
            settings.EnableVipProgram,
            settings.VipMinimumSpend,
            settings.SuperVipMinimumSpend,
            settings.SuperVipMinimumClasses,
            settings.EnableRetentionReminders,
            settings.RetentionReminderInactivityDays,
            settings.RetentionReminderTickHours,
            settings.RetentionReminderMinCreditsRemaining,
            settings.RetentionReminderWindows,
            settings.MaterialisationHorizonDays,

            // Stripe — masked display values only (never raw)
            StripeEnabled = settings.StripeEnabled,
            StripePublishableKeyMasked = SettingsEncryptionHelper.Mask(stripeConfig.PublishableKey),
            StripeSecretKeyMasked = SettingsEncryptionHelper.Mask(stripeConfig.SecretKey),
            StripeWebhookSecretMasked = SettingsEncryptionHelper.Mask(stripeConfig.WebhookSecret),
        });
    }

    [HttpPost]
    public async Task<IActionResult> UpdateSettings([FromBody] GlobalSettings update, CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.UpdateAsync(update, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            // Service-layer validation (allocation sum, negatives) → 400 with the
            // validation message verbatim so the admin UI can render it inline.
            return BadRequest(new { message = ex.Message });
        }
    }

