using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Options;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Interfaces;
using SoulPilates.Services;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/media")]
[Authorize(Roles = "Admin")]
public class MediaController : ControllerBase
{
    private readonly IMediaStorage _media;
    private readonly IStaffService _staff;
    private readonly ISchedulingService _scheduling;
    private readonly IEquipmentService _equipment;
    private readonly StorageSettings _settings;

    public MediaController(
        IMediaStorage media,
        IStaffService staff,
        ISchedulingService scheduling,
        IEquipmentService equipment,
        IOptions<StorageSettings> settings)
    {
        _media = media;
        _staff = staff;
        _scheduling = scheduling;
        _equipment = equipment;
        _settings = settings.Value;
    }

    // ── Class hero image ───────────────────────────────────────

    [HttpPost("class-image/{blueprintId}")]
    [RequestSizeLimit(15_728_640)] // 15 MB request envelope (10 MB image + overhead)
    public async Task<IActionResult> UploadClassImage(string blueprintId, IFormFile file)
        => await UploadBlueprintImageAsync(blueprintId, file, "image", "class-images", _settings.MaxImageDimensionPx);

    [HttpDelete("class-image/{blueprintId}")]
    public Task<IActionResult> DeleteClassImage(string blueprintId)
        => DeleteBlueprintImageAsync(blueprintId, "image", "class-images");

    // ── Equipment image ────────────────────────────────────────

    [HttpPost("equipment-image/{equipmentId}")]
    [RequestSizeLimit(15_728_640)] // 15 MB request envelope
    public async Task<IActionResult> UploadEquipmentImage(string equipmentId, IFormFile file)
    {
        if (!TryValidate(file, out var problem)) return problem!;

        var equipment = await _equipment.GetByIdAsync(equipmentId);
        if (equipment is null) return NotFound(new { error = "Equipment not found" });

        var oldKey = _media.KeyFromUrl(equipment.ImageUrl);
        var newKey = $"equipment-images/{equipmentId}.webp";

        await using var stream = file.OpenReadStream();
        await _media.UploadImageAsync(stream, newKey, maxDimensionPx: _settings.MaxImageDimensionPx);

        var publicUrl = _media.PublicUrlFor(newKey);
        await _equipment.UpdateImageUrlAsync(equipmentId, publicUrl);

        if (!string.IsNullOrEmpty(oldKey) && !string.Equals(oldKey, newKey, StringComparison.Ordinal))
            await _media.DeleteAsync(oldKey);

        return Ok(new { url = publicUrl, key = newKey });
    }

    [HttpDelete("equipment-image/{equipmentId}")]
    public async Task<IActionResult> DeleteEquipmentImage(string equipmentId)
    {
        var equipment = await _equipment.GetByIdAsync(equipmentId);
        if (equipment is null) return NotFound(new { error = "Equipment not found" });

        var key = _media.KeyFromUrl(equipment.ImageUrl) ?? $"equipment-images/{equipmentId}.webp";
        await _media.DeleteAsync(key);
        await _equipment.UpdateImageUrlAsync(equipmentId, null);
        return NoContent();
    }

    // ── Instructor portrait ────────────────────────────────────

    [HttpPost("instructor-photo/{staffId}")]
    [RequestSizeLimit(15_728_640)]
    public async Task<IActionResult> UploadInstructorPhoto(string staffId, IFormFile file)
    {
        if (!TryValidate(file, out var problem)) return problem!;

        var staff = await _staff.GetStaffByIdAsync(staffId);
        if (staff is null) return NotFound(new { error = "Staff not found" });

        var oldKey = _media.KeyFromUrl(staff.PhotoUrl);
        var newKey = $"instructor-photos/{staffId}.webp";

        await using var stream = file.OpenReadStream();
        await _media.UploadImageAsync(stream, newKey, maxDimensionPx: 800);

        var publicUrl = _media.PublicUrlFor(newKey);
        await _staff.UpdatePhotoUrlAsync(staffId, publicUrl);

        // Replace-on-upload: remove old key if it differs (keys are deterministic so usually equal,
        // but legacy URLs or external paths may be different).
        if (!string.IsNullOrEmpty(oldKey) && !string.Equals(oldKey, newKey, StringComparison.Ordinal))
            await _media.DeleteAsync(oldKey);

        return Ok(new { url = publicUrl, key = newKey });
    }

    [HttpDelete("instructor-photo/{staffId}")]
    public async Task<IActionResult> DeleteInstructorPhoto(string staffId)
    {
        var staff = await _staff.GetStaffByIdAsync(staffId);
        if (staff is null) return NotFound(new { error = "Staff not found" });

        var key = _media.KeyFromUrl(staff.PhotoUrl);
        if (!string.IsNullOrEmpty(key))
            await _media.DeleteAsync(key);

        await _staff.UpdatePhotoUrlAsync(staffId, null);
        return NoContent();
    }

    // ── Internal helpers ────────────────────────────────────────

    private async Task<IActionResult> UploadBlueprintImageAsync(
        string blueprintId, IFormFile file, string field, string keyPrefix, int maxDim)
    {
        if (!TryValidate(file, out var problem)) return problem!;

        var blueprint = await _scheduling.GetBlueprintByIdAsync(blueprintId);
        if (blueprint is null) return NotFound(new { error = "Class blueprint not found" });

        var oldUrl = blueprint.ImageUrl;
        var oldKey = _media.KeyFromUrl(oldUrl);
        var newKey = $"{keyPrefix}/{blueprintId}.webp";

        await using var stream = file.OpenReadStream();
        await _media.UploadImageAsync(stream, newKey, maxDimensionPx: maxDim);

        var publicUrl = _media.PublicUrlFor(newKey);
        await _scheduling.UpdateBlueprintImageAsync(blueprintId, field, publicUrl);

        if (!string.IsNullOrEmpty(oldKey) && !string.Equals(oldKey, newKey, StringComparison.Ordinal))
            await _media.DeleteAsync(oldKey);

        return Ok(new { url = publicUrl, key = newKey });
    }

    private async Task<IActionResult> DeleteBlueprintImageAsync(string blueprintId, string field, string keyPrefix)
    {
        var blueprint = await _scheduling.GetBlueprintByIdAsync(blueprintId);
        if (blueprint is null) return NotFound(new { error = "Class blueprint not found" });

        var url = blueprint.ImageUrl;
        var key = _media.KeyFromUrl(url) ?? $"{keyPrefix}/{blueprintId}.webp";

        await _media.DeleteAsync(key);
        await _scheduling.UpdateBlueprintImageAsync(blueprintId, field, null);
        return NoContent();
    }

    private bool TryValidate(IFormFile? file, out IActionResult? problem)
    {
        problem = null;

        if (file is null || file.Length == 0)
        {
            problem = BadRequest(new { error = "No file uploaded" });
            return false;
        }

        if (file.Length > _settings.MaxUploadBytes)
        {
            problem = StatusCode(StatusCodes.Status413PayloadTooLarge,
                new { error = $"File exceeds {_settings.MaxUploadBytes / 1_048_576} MB limit" });
            return false;
        }

        // Content-type whitelist
        var ct = (file.ContentType ?? "").ToLowerInvariant();
        if (ct is not ("image/jpeg" or "image/jpg" or "image/png" or "image/webp" or "image/gif"))
        {
            problem = BadRequest(new { error = $"Unsupported content type '{file.ContentType}'. Use JPEG, PNG, WebP or GIF." });
            return false;
        }

        // Magic-byte sniff (defensive: a renamed .exe should be rejected here)
        if (!HasImageMagicBytes(file))
        {
            problem = BadRequest(new { error = "File contents do not appear to be a valid image." });
            return false;
        }

        return true;
    }

    private static bool HasImageMagicBytes(IFormFile file)
    {
        Span<byte> buf = stackalloc byte[12];
        using var s = file.OpenReadStream();
        var read = s.Read(buf);
        if (read < 4) return false;

        // JPEG  FF D8 FF
        if (buf[0] == 0xFF && buf[1] == 0xD8 && buf[2] == 0xFF) return true;
        // PNG   89 50 4E 47
        if (buf[0] == 0x89 && buf[1] == 0x50 && buf[2] == 0x4E && buf[3] == 0x47) return true;
        // GIF   47 49 46 38
        if (buf[0] == 0x47 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x38) return true;
        // WebP  52 49 46 46 …. 57 45 42 50
        if (read >= 12 && buf[0] == 0x52 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x46
            && buf[8] == 0x57 && buf[9] == 0x45 && buf[10] == 0x42 && buf[11] == 0x50) return true;
        return false;
    }
}

