public async Task<GlobalSettings> UpdateRetentionAsync(RetentionSettingsPatch patch, CancellationToken ct = default)
{
    // Read-modify-write the singleton so we don't accidentally overwrite
    // unrelated fields with their zero-values. We use an explicit $set
    // builder so future migrations can swap to a true MongoDB partial
    // update without changing the call site.
    var current = await GetAsync(ct);

    // Defensive clamps — the admin UI already validates, but the API
    // is public surface area.
    if (patch.RetentionReminderInactivityDays < 1) patch.RetentionReminderInactivityDays = 1;
    if (patch.RetentionReminderTickHours < 1) patch.RetentionReminderTickHours = 1;
    if (patch.RetentionReminderMinCreditsRemaining < 0) patch.RetentionReminderMinCreditsRemaining = 0;
    patch.RetentionReminderWindows ??= new();

    var update = Builders<GlobalSettings>.Update
        .Set(s => s.EnableRetentionReminders, patch.EnableRetentionReminders)
        .Set(s => s.RetentionReminderInactivityDays, patch.RetentionReminderInactivityDays)
        .Set(s => s.RetentionReminderTickHours, patch.RetentionReminderTickHours)
        .Set(s => s.RetentionReminderMinCreditsRemaining, patch.RetentionReminderMinCreditsRemaining)
        .Set(s => s.RetentionReminderWindows, patch.RetentionReminderWindows)
        .Set(s => s.UpdatedAt, DateTime.UtcNow);

    await _settings.UpdateOneAsync(s => s.Id == current.Id, update, cancellationToken: ct);
    return await GetAsync(ct);
}

public async Task<GlobalSettings> UpdateVipAsync(VipSettingsPatch patch, CancellationToken ct = default)
{
    var current = await GetAsync(ct);

    // Defensive clamps — the API is public surface area.
    if (patch.VipMinimumSpend < 0) patch.VipMinimumSpend = 0;
    if (patch.SuperVipMinimumSpend < 0) patch.SuperVipMinimumSpend = 0;
    if (patch.SuperVipMinimumClasses < 0) patch.SuperVipMinimumClasses = 0;

    var update = Builders<GlobalSettings>.Update
        .Set(s => s.EnableVipProgram, patch.EnableVipProgram)
        .Set(s => s.VipMinimumSpend, patch.VipMinimumSpend)
        .Set(s => s.SuperVipMinimumSpend, patch.SuperVipMinimumSpend)
        .Set(s => s.SuperVipMinimumClasses, patch.SuperVipMinimumClasses)
        .Set(s => s.UpdatedAt, DateTime.UtcNow);

    await _settings.UpdateOneAsync(s => s.Id == current.Id, update, cancellationToken: ct);
    return await GetAsync(ct);
}

/// <summary>Reject anything other than the two recognised modes — protects the engine from typos in admin UI.</summary>
private static void ValidateStripeRoutingMode(GlobalSettings update)
{
    if (update.StripeRoutingMode != StripeRoutingModes.CompanyAccount &&
        update.StripeRoutingMode != StripeRoutingModes.OwnerRouted)
