using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

public class GlobalSettings : BaseEntity
{
    /// <summary>
    /// SaaS onboarding: false until the studio owner finishes the first-run setup
    /// wizard. The admin portal redirects to the wizard while this is false.
    /// </summary>
    public bool SetupCompleted { get; set; } = false;


    /// <summary>
    /// Marketing fund's share of net revenue (P&L washout). Combined with
    /// <see cref="SavingsSplitPercentage"/> and <see cref="OwnersSplitPercentage"/>
    /// this triple MUST sum to exactly 100 (within 0.01); the service-layer
    /// validation in <c>SettingsService.UpdateAsync</c> rejects anything else.
    /// Default 5/10/85 mirrors the studio's historical sheet.
    /// </summary>
    public decimal MarketingSplitPercentage { get; set; } = 5;

    /// <summary>Savings reserve's share. See <see cref="MarketingSplitPercentage"/>.</summary>
    public decimal SavingsSplitPercentage { get; set; } = 10;

    /// <summary>
    /// Owners' pool share. Default 85; together with marketing (5) + savings (10)
    /// = 100. The pool is then split per owner via <c>OwnerProfile.EquitySharePercentage</c>
    /// (introduced in P2-S02).
    /// </summary>
    public decimal OwnersSplitPercentage { get; set; } = 85;

    /// <summary>
    /// Hours before a GROUP class start that a customer can still self-cancel
    /// for a free credit refund. Below this threshold the cancellation is
    /// recorded as <c>LATE_CANCEL</c> and the credit is forfeited.
    /// (P1-S13 — was previously hardcoded to 12; kept the per-format split
    /// because group vs private classes have different operational impact.)
    /// </summary>
