namespace SoulPilates.Core.Entities;

/// <summary>
/// Studio identity & contact details collected in the onboarding wizard (Step 2).
/// Stored as a nested document on the <see cref="GlobalSettings"/> singleton so it
/// shares the tenant's settings lifecycle. Also powers the public tenant website.
/// </summary>
public class StudioProfile
{
    public string? StudioName { get; set; }
    public string? BusinessEmail { get; set; }
    public string? Phone { get; set; }
    public string? Address { get; set; }
    public string? City { get; set; }
    public string? Country { get; set; }
    public string? TimeZone { get; set; }
    public string? Currency { get; set; }
    public string? Language { get; set; }
    public string? LogoUrl { get; set; }
    public string? PrimaryColor { get; set; }
    public string? SecondaryColor { get; set; }
    public string? Instagram { get; set; }
    public string? Facebook { get; set; }
    public string? Website { get; set; }
    public List<BusinessHour> Hours { get; set; } = new();
}

/// <summary>One weekday's public opening hours (display + website; the operational
/// booking window lives in <see cref="CompanyScheduleConfig"/>).</summary>
public class BusinessHour
{
