using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Domain service for the studio's <see cref="GlobalSettings"/> singleton plus
/// the per-month <see cref="MonthlyAllocationOverride"/> table introduced in P2-S01.
/// Centralises the "first-time seed" logic so controllers don't reinvent it.
/// </summary>
public interface ISettingsService
{
    /// <summary>
    /// Returns the current settings document, creating and seeding it (with
    /// <see cref="GlobalSettings.DefaultExpenseCategories"/>) if the collection is empty
    /// or if <see cref="GlobalSettings.ExpenseCategories"/> is null/empty.
    /// </summary>
    Task<GlobalSettings> GetAsync(CancellationToken ct = default);

    /// <summary>
    /// Replaces the settings document. The caller's <see cref="GlobalSettings.Id"/>
    /// is ignored — we always upsert against the singleton row that
    /// <see cref="GetAsync"/> returns.
    ///
    /// Throws <see cref="InvalidOperationException"/> if Marketing/Savings/Owners %
    /// don't sum to 100 (within 0.01) or any single percentage is negative.
    /// </summary>
    Task<GlobalSettings> UpdateAsync(GlobalSettings update, CancellationToken ct = default);

    /// <summary>
    /// Partial update of retention-reminder fields only. Skips the full-document
    /// allocation-triple invariant required by <see cref="UpdateAsync"/>, so the
    /// admin Notifications card can save its own slice independently.
    /// </summary>
    Task<GlobalSettings> UpdateRetentionAsync(RetentionSettingsPatch patch, CancellationToken ct = default);

    /// <summary>Targeted partial-update for the VIP-program settings.</summary>
    Task<GlobalSettings> UpdateVipAsync(VipSettingsPatch patch, CancellationToken ct = default);

    // ── P2-S01: per-month allocation overrides ──────────────────────────────

    /// <summary>
    /// Returns the effective allocation percentages for the given month: the matching
    /// <see cref="MonthlyAllocationOverride"/> if one exists, otherwise the global defaults.
    /// </summary>
    Task<(decimal MarketingPct, decimal SavingsPct, decimal OwnersPct)> GetEffectiveAllocationAsync(int year, int month, CancellationToken ct = default);

    /// <summary>Returns all overrides ordered by Year DESC, Month DESC.</summary>
    Task<List<MonthlyAllocationOverride>> ListAllocationOverridesAsync(CancellationToken ct = default);

    /// <summary>
    /// Creates or updates the override row for the given Year/Month. Validates the
    /// triple-sum-to-100 invariant before writing. Upsert keyed on (Year, Month).
    /// </summary>
    Task<MonthlyAllocationOverride> UpsertAllocationOverrideAsync(MonthlyAllocationOverride payload, CancellationToken ct = default);

    /// <summary>Deletes the override row by id; no-op if missing.</summary>
    Task DeleteAllocationOverrideAsync(string id, CancellationToken ct = default);

    // ── V2 Schedule: Company Operating Hours ─────────────────────────────

    /// <summary>
    /// Returns the <see cref="CompanyScheduleConfig"/> from the global settings
    /// singleton. If the sub-document hasn't been configured yet, returns an
    /// empty config (no hours, no holidays).
    /// </summary>
    Task<CompanyScheduleConfig> GetScheduleConfigAsync(CancellationToken ct = default);

    /// <summary>
    /// Replaces the <see cref="CompanyScheduleConfig"/> on the global settings
    /// singleton. Validates that Open &lt; Close for every defined day and
    /// that holiday/override dates are valid ISO strings.
    /// </summary>
    Task<CompanyScheduleConfig> UpdateScheduleConfigAsync(CompanyScheduleConfig config, CancellationToken ct = default);

    // ── V2: Materialisation Horizon ───────────────────────────────────────

    /// <summary>
    /// Updates <see cref="GlobalSettings.MaterialisationHorizonDays"/> via a
    /// targeted MongoDB <c>$set</c>, bypassing the full-document replace path.
    /// Clamps the value to 7–365. Returns the clamped value that was written.
    /// </summary>
    Task<int> UpdateMaterialisationHorizonAsync(int horizonDays, CancellationToken ct = default);

    // ── SPM-76: Editable Email Templates ─────────────────────────────────

    /// <summary>
    /// Returns the full set of editable email templates, backfilling any
    /// built-in template that is missing from the stored settings document with
    /// its <see cref="EmailTemplateDefaults"/> default. The returned list always
    /// contains exactly the known built-in templates (in catalogue order); a
    /// stored entry with a blank Subject/BodyHtml is returned as-is so the admin
    /// UI can show "(using default)". Persists the backfill when seeding occurred.
    /// </summary>
    Task<List<EmailTemplate>> GetEmailTemplatesAsync(CancellationToken ct = default);

    /// <summary>
    /// Returns the single resolved template for <paramref name="id"/> ready for
    /// send-time use: the stored override if present, with each blank
    /// Subject/BodyHtml field replaced by its built-in default. Returns null if
    /// <paramref name="id"/> is not a known built-in template.
    /// </summary>
    Task<EmailTemplate?> GetResolvedEmailTemplateAsync(string id, CancellationToken ct = default);

    /// <summary>
    /// Validates and persists an edited email template (Subject + BodyHtml only).
    /// Validation: the template id must be a known built-in, and every token in
    /// the built-in <see cref="EmailTemplate.RequiredVariables"/> must appear —
    /// as <c>{Token}</c> — somewhere in Subject + BodyHtml combined. A blank
    /// Subject or BodyHtml is allowed (means "use the built-in default" for that
    /// field) and skips the required-variable check for the blanked field.
    ///
    /// Throws <see cref="InvalidOperationException"/> with a message naming the
    /// first missing variable when validation fails.
    /// </summary>
    Task<EmailTemplate> UpdateEmailTemplateAsync(string id, string subject, string bodyHtml, CancellationToken ct = default);

    /// <summary>Toggles the auto-send enabled state for a single email template.</summary>
    Task<EmailTemplate> SetEmailTemplateEnabledAsync(string id, bool isEnabled, CancellationToken ct = default);

    // ── Stripe Key Management ────────────────────────────────────────────

    /// <summary>
    /// Returns the decrypted Stripe configuration for internal service use.
    /// NEVER expose the return value via an API endpoint — callers are
    /// server-side services only (PaymentService, webhook handler, etc.).
    /// </summary>
    Task<StripeConfigResult> GetDecryptedStripeConfigAsync(CancellationToken ct = default);

    /// <summary>
    /// Encrypts and persists the raw Stripe keys. The caller supplies plaintext
    /// values; they are AES-256-CBC encrypted before touching the database.
    /// Pass <c>null</c> for any key field to leave its current value unchanged.
    /// </summary>
    Task UpdateStripeKeysAsync(bool enabled, string? publishableKey, string? secretKey, string? webhookSecret, CancellationToken ct = default);
}

/// <summary>
/// Decrypted Stripe configuration returned by <see cref="ISettingsService.GetDecryptedStripeConfigAsync"/>.
/// Transient in-memory object — NEVER serialised to JSON or stored in cache.
/// </summary>
public sealed class StripeConfigResult
{
    public bool Enabled { get; init; }
    public string PublishableKey { get; init; } = "";
    public string SecretKey { get; init; } = "";
    public string WebhookSecret { get; init; } = "";
    /// <summary>Always VND — hardcoded, not configurable.</summary>
    public string Currency => "VND";
}

