public async Task<GlobalSettings> UpdateProfileAsync(StudioProfile profile, CancellationToken ct = default)
{
    var current = await GetAsync(ct);

    profile.Hours ??= new();

    var update = Builders<GlobalSettings>.Update
        .Set(s => s.Profile, profile)
        .Set(s => s.UpdatedAt, DateTime.UtcNow);

    await _settings.UpdateOneAsync(s => s.Id == current.Id, update, cancellationToken: ct);
    return await GetAsync(ct);
}

