// ── Studio logo (onboarding Step 2 / branding) ─────────────

[HttpPost("studio-logo")]
[RequestSizeLimit(15_728_640)]
public async Task<IActionResult> UploadStudioLogo(IFormFile file)
{
    if (!TryValidate(file, out var problem)) return problem!;

    var key = "studio/logo.webp";
    await using var stream = file.OpenReadStream();
    await _media.UploadImageAsync(stream, key, maxDimensionPx: 800);

    var publicUrl = _media.PublicUrlFor(key);

    var settings = await _settingsService.GetAsync();
    settings.Profile.LogoUrl = publicUrl;
    await _settingsService.UpdateProfileAsync(settings.Profile);

    return Ok(new { url = publicUrl, key });
}

// ── Website photos (onboarding Step 3 — site gallery) ──────

[HttpPost("site-photo")]
[RequestSizeLimit(15_728_640)]
public async Task<IActionResult> UploadSitePhoto(IFormFile file)
{
    if (!TryValidate(file, out var problem)) return problem!;

    var key = $"site-photos/{Guid.NewGuid():N}.webp";
    await using var stream = file.OpenReadStream();
    await _media.UploadImageAsync(stream, key, maxDimensionPx: _settings.MaxImageDimensionPx);

    // The wizard collects returned URLs and saves them onto SiteContent in
    // one PATCH — no settings write here, so uploads stay parallel-safe.
    return Ok(new { url = _media.PublicUrlFor(key), key });
}

