---
// Studio Nexis — premium 8-step onboarding wizard (first-run, studio owner).
// Shown on first admin login (AdminLayout redirects here until SetupCompleted).
// Every step autosaves through the API; steps 3–7 are skippable. Standalone page.
const API = import.meta.env.PUBLIC_API_URL;
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Set up your studio — Studio Nexis</title>
    <meta name="robots" content="noindex" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet" />
    <style>
      :root{--ink:#0d1220;--muted:#616a80;--line:#e2e5f0;--bg2:#f7f8fc;--brand:#5b45e0;--brand2:#8b5cf6;--mint:#0fb6a6;--rose:#e05a7a}
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fff,#f4f5fb);min-height:100vh;-webkit-font-smoothing:antialiased}
      a{color:var(--brand);text-decoration:none}
      h1,h2,.disp{font-family:'Manrope',sans-serif;letter-spacing:-.02em}
      button{font-family:inherit}

      /* ── Top chrome ── */
      .top{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.86);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
      .top-in{max-width:1060px;margin:0 auto;padding:14px 24px;display:flex;align-items:center;gap:18px}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:18px;white-space:nowrap}
      .logo-mark{width:29px;height:29px;border-radius:9px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;font-weight:800}
      .prog-wrap{flex:1;min-width:0}
      .prog-meta{display:flex;justify-content:space-between;font-size:12.5px;color:var(--muted);font-weight:600;margin-bottom:6px}
      .prog-meta b{color:var(--ink)}
      .prog-track{height:6px;border-radius:4px;background:var(--line);overflow:hidden}
      .prog-fill{height:100%;width:0%;border-radius:4px;background:linear-gradient(90deg,var(--brand),var(--brand2));transition:width .5s cubic-bezier(.22,1,.36,1)}
      .save-chip{font-size:12.5px;font-weight:600;color:var(--muted);white-space:nowrap;display:flex;align-items:center;gap:6px;min-width:86px;justify-content:flex-end}
      .save-chip.ok{color:var(--mint)}
      .save-chip.err{color:var(--rose)}
      .finish-later{font-size:13px;color:var(--muted);font-weight:600;white-space:nowrap}
      .finish-later:hover{color:var(--ink)}
      @media(max-width:640px){.logo-txt,.finish-later{display:none}}

      /* ── Shell / steps ── */
      .shell{max-width:760px;margin:34px auto 80px;padding:0 24px}
      .step{display:none}
      .step.on{display:block;animation:stepIn .45s cubic-bezier(.22,1,.36,1)}
      @keyframes stepIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
      .card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:40px;box-shadow:0 14px 44px rgba(16,24,40,.08)}
      @media(max-width:640px){.card{padding:26px 20px}}
      .eyebrow{display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--brand);background:#efeafc;border-radius:99px;padding:6px 13px;margin-bottom:16px}
      h1{font-size:27px;font-weight:800;margin-bottom:10px}
      .lede{color:var(--muted);font-size:15.5px;line-height:1.55;margin-bottom:26px}
      .row{display:flex;justify-content:space-between;align-items:center;margin-top:30px;gap:12px;flex-wrap:wrap}
      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;padding:12px 24px;border-radius:11px;border:1px solid transparent;cursor:pointer;transition:.15s}
      .btn-primary{background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;box-shadow:0 6px 18px rgba(91,69,224,.28)}
      .btn-primary:hover{transform:translateY(-1px);box-shadow:0 9px 24px rgba(91,69,224,.34)}
      .btn-ghost{border-color:var(--line);color:var(--ink);background:#fff}
      .btn-ghost:hover{background:var(--bg2)}
      .btn:disabled{opacity:.55;cursor:not-allowed;transform:none}
      .skip-step{font-size:13.5px;color:var(--muted);font-weight:600;cursor:pointer;background:none;border:none;padding:8px 4px}
      .skip-step:hover{color:var(--ink)}

      /* ── Welcome ── */
      .time-pill{display:inline-flex;align-items:center;gap:7px;background:#e6f7f4;color:#0a8f83;font-weight:700;font-size:13px;border-radius:99px;padding:7px 14px;margin-bottom:18px}
      .benefits{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px;margin:20px 0 8px}
      .benefit{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:12px;padding:12px 14px;font-size:13.5px;font-weight:600;background:#fff;opacity:0;transform:translateY(8px);animation:pop .4s forwards}
      .benefit svg{color:var(--mint);flex-shrink:0}
      @keyframes pop{to{opacity:1;transform:none}}

      /* ── Forms ── */
      .grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
      @media(max-width:560px){.grid2{grid-template-columns:1fr}}
      .field{margin-bottom:14px}
      .field label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}
      .field label .opt{color:var(--muted);font-weight:500}
      .field input[type=text],.field input[type=email],.field input[type=tel],.field input[type=url],.field input[type=number],.field input[type=time],.field select,.field textarea{width:100%;border:1px solid var(--line);border-radius:11px;padding:11px 13px;font-size:14.5px;font-family:inherit;background:#fff;transition:.15s;color:var(--ink)}
      .field textarea{resize:vertical;min-height:74px}
      .field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.13)}
      .sect{font-size:13px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);margin:26px 0 12px;display:flex;align-items:center;gap:10px}
      .sect::after{content:"";flex:1;height:1px;background:var(--line)}

      /* hours */
      .hours .hrow{display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px dashed var(--line);font-size:13.5px;flex-wrap:wrap}
      .hours .hrow:last-child{border-bottom:none}
      .hours .day{width:88px;font-weight:700}
      .hours input[type=time]{border:1px solid var(--line);border-radius:9px;padding:7px 9px;font-size:13px;font-family:inherit}
      .hours .closed-toggle{margin-left:auto;display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted);font-weight:600;cursor:pointer}

      /* uploads */
      .upl{border:2px dashed var(--line);border-radius:14px;padding:18px;text-align:center;cursor:pointer;transition:.15s;font-size:13.5px;color:var(--muted);font-weight:600}
      .upl:hover{border-color:var(--brand);background:#faf9ff}
      .upl img{max-height:56px;max-width:180px;display:block;margin:0 auto 8px}
      .thumbs{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
      .thumbs .th{width:74px;height:74px;border-radius:12px;object-fit:cover;border:1px solid var(--line);animation:pop .35s}

      /* style presets */
      .styles{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-bottom:6px}
      .stylecard{border:1.5px solid var(--line);border-radius:15px;padding:15px;cursor:pointer;transition:.16s;background:#fff}
      .stylecard:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(16,24,40,.08)}
      .stylecard.sel{border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.14)}
      .stylecard .sw{display:flex;gap:5px;margin-bottom:10px}
      .stylecard .sw i{width:22px;height:22px;border-radius:7px;display:block}
      .stylecard h4{font-size:14px;font-weight:800;margin-bottom:3px}
      .stylecard p{font-size:12px;color:var(--muted);line-height:1.45}
      .chips{display:flex;gap:8px;flex-wrap:wrap}
      .chip{border:1.5px solid var(--line);border-radius:99px;padding:8px 17px;font-size:13.5px;font-weight:700;cursor:pointer;background:#fff;transition:.14s}
      .chip:hover{border-color:#c9cee4}
      .chip.sel{border-color:var(--brand);background:#efeafc;color:var(--brand)}

      /* template rows (services / packages / staff) */
      .tpl{border:1.5px solid var(--line);border-radius:15px;padding:14px 16px;margin-bottom:11px;transition:.15s;background:#fff}
      .tpl.sel{border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.10)}
      .tpl .tpl-head{display:flex;align-items:center;gap:11px;cursor:pointer}
      .tpl .cbx{width:21px;height:21px;border-radius:7px;border:1.7px solid #c8cde2;display:grid;place-items:center;color:#fff;flex-shrink:0;transition:.13s}
      .tpl.sel .cbx{background:linear-gradient(135deg,var(--brand),var(--brand2));border-color:transparent}
      .tpl .tpl-name{font-weight:700;font-size:14.5px}
      .tpl .tpl-sub{font-size:12.5px;color:var(--muted);margin-left:auto;text-align:right}
      .tpl .tpl-body{display:none;margin-top:13px;padding-top:13px;border-top:1px dashed var(--line)}
      .tpl.sel .tpl-body{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px}
      .tpl .tpl-body label{font-size:11.5px;font-weight:700;color:var(--muted);display:block;margin-bottom:4px}
      .tpl .tpl-body input,.tpl .tpl-body select{width:100%;border:1px solid var(--line);border-radius:9px;padding:8px 10px;font-size:13px;font-family:inherit}
      .add-row{width:100%;border:2px dashed var(--line);background:none;border-radius:13px;padding:12px;font-size:13.5px;font-weight:700;color:var(--muted);cursor:pointer}
      .add-row:hover{border-color:var(--brand);color:var(--brand)}
      .done-note{background:#e6f7f4;border-radius:12px;padding:11px 15px;font-size:13px;color:#0a8f83;font-weight:600;margin-bottom:14px;display:none}

      /* payments */
      .paycards{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:18px}
      @media(max-width:560px){.paycards{grid-template-columns:1fr}}
      .paycard{border:1.5px solid var(--line);border-radius:15px;padding:18px;cursor:pointer;transition:.15s}
      .paycard.sel{border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.13)}
      .paycard h4{font-size:15px;font-weight:800;margin-bottom:5px}
      .paycard p{font-size:12.5px;color:var(--muted);line-height:1.5}
      .stripe-fields{display:none}
      .stripe-fields.on{display:block;animation:stepIn .3s}

      /* review */
      .review{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:8px}
      @media(max-width:560px){.review{grid-template-columns:1fr}}
      .rv{display:flex;align-items:center;gap:11px;border:1px solid var(--line);border-radius:13px;padding:13px 15px}
      .rv .ic{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;flex-shrink:0;background:#e6f7f4;color:var(--mint)}
      .rv .ic.warn{background:#fdf1e7;color:#d97b2f}
      .rv h5{font-size:13.5px;font-weight:800}
      .rv p{font-size:12px;color:var(--muted)}

      /* ── AI generation overlay ── */
      .genlay{position:fixed;inset:0;z-index:60;background:radial-gradient(1100px 700px at 50% 30%,#241a55,#0d0a26);display:none;align-items:center;justify-content:center;color:#fff}
      .genlay.on{display:flex}
      .gen-in{max-width:480px;padding:32px;text-align:center}
      .orb{width:104px;height:104px;margin:0 auto 34px;border-radius:50%;background:conic-gradient(from 0deg,#8b5cf6,#5b45e0,#0fb6a6,#8b5cf6);animation:spin 2.6s linear infinite;position:relative;filter:drop-shadow(0 0 34px rgba(139,92,246,.55))}
      .orb::after{content:"";position:absolute;inset:9px;border-radius:50%;background:#141033}
      @keyframes spin{to{transform:rotate(360deg)}}
      .gen-title{font-family:'Manrope';font-size:23px;font-weight:800;margin-bottom:26px}
      .gen-lines{text-align:left;display:flex;flex-direction:column;gap:11px;min-height:250px}
      .gl{display:flex;align-items:center;gap:11px;font-size:14.5px;color:rgba(255,255,255,.4);opacity:0;transform:translateY(8px);transition:.4s}
      .gl.show{opacity:1;transform:none}
      .gl.done{color:rgba(255,255,255,.92)}
      .gl .st{width:20px;height:20px;border-radius:50%;border:2px solid rgba(255,255,255,.25);display:grid;place-items:center;flex-shrink:0;font-size:11px}
      .gl.working .st{border-color:#8b5cf6;border-top-color:transparent;animation:spin .8s linear infinite}
      .gl.done .st{border-color:var(--mint);background:var(--mint);color:#08251f}

      /* ── Celebration ── */
      .cele{text-align:center;padding:14px 0}
      .cele .big{font-size:56px;margin-bottom:14px;animation:pop .5s}
      .cele h1{font-size:30px;margin-bottom:10px}
      .next-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-top:26px}
      .nx{border:1px solid var(--line);border-radius:14px;padding:16px 12px;font-size:13.5px;font-weight:700;color:var(--ink);transition:.15s;display:block}
      .nx:hover{transform:translateY(-2px);box-shadow:0 8px 20px rgba(16,24,40,.09);border-color:#cfd3e6;color:var(--brand)}
      .nx span{display:block;font-size:21px;margin-bottom:7px}
      canvas#confetti{position:fixed;inset:0;pointer-events:none;z-index:80}
    </style>
  </head>
  <body>
    <canvas id="confetti"></canvas>

    <!-- ── Top progress chrome ── -->
    <div class="top">
      <div class="top-in">
        <div class="logo"><span class="logo-mark">N</span><span class="logo-txt">Studio&nbsp;Nexis</span></div>
        <div class="prog-wrap">
          <div class="prog-meta"><span id="stepLabel"><b>Welcome</b></span><span id="pctLabel">Step 1 of 8 · 0%</span></div>
          <div class="prog-track"><div class="prog-fill" id="progFill"></div></div>
        </div>
        <span class="save-chip" id="saveChip"></span>
        <a href="#" class="finish-later" id="finishLater">Finish later →</a>
      </div>
    </div>

    <div class="shell">

      <!-- ═══ Step 1 — Welcome ═══ -->
      <section class="step on" data-step="1">
        <div class="card">
          <span class="time-pill">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
            Takes about 5–10 minutes
          </span>
          <h1>Welcome to Studio Nexis 👋</h1>
          <p class="lede">Let's get everything ready so you can start accepting bookings today. We'll set up your studio profile, build your website, and configure your classes — step by step.</p>
          <div class="benefits" id="benefits"></div>
          <div class="row" style="justify-content:flex-end">
            <button class="btn btn-primary" data-next>Let's Build Your Studio
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
            </button>
          </div>
        </div>
      </section>

      <!-- ═══ Step 2 — Studio Information ═══ -->
      <section class="step" data-step="2">
        <div class="card">
          <span class="eyebrow">Step 2 · Studio Information</span>
          <h1>Tell us about your studio</h1>
          <p class="lede">These details flow through your whole platform — website, receipts, emails and booking pages.</p>

          <div class="grid2">
            <div class="field"><label>Studio name</label><input type="text" id="f_name" placeholder="e.g. Luna Pilates" /></div>
            <div class="field"><label>Business email</label><input type="email" id="f_email" placeholder="hello@yourstudio.com" /></div>
            <div class="field"><label>Phone number</label><input type="tel" id="f_phone" placeholder="+1 555 000 1234" /></div>
            <div class="field"><label>Website <span class="opt">(if migrating)</span></label><input type="url" id="f_site" placeholder="https://…" /></div>
          </div>
          <div class="field"><label>Studio address</label><input type="text" id="f_addr" placeholder="Street, number" /></div>
          <div class="grid2">
            <div class="field"><label>City</label><input type="text" id="f_city" placeholder="City" /></div>
            <div class="field"><label>Country</label><input type="text" id="f_country" placeholder="Country" /></div>
            <div class="field"><label>Time zone</label><select id="f_tz"></select></div>
            <div class="field"><label>Currency</label><select id="f_cur"></select></div>
            <div class="field"><label>Language</label><select id="f_lang"><option value="en">English</option><option value="vi">Tiếng Việt</option></select></div>
          </div>

          <div class="sect">Business hours</div>
          <div class="hours" id="hours"></div>

          <div class="sect">Branding</div>
          <div class="grid2">
            <div class="field">
              <label>Logo <span class="opt">(PNG / JPG)</span></label>
              <div class="upl" id="logoUpl"><span id="logoUplTxt">Click to upload your logo</span></div>
              <input type="file" id="f_logo" accept="image/*" style="display:none" />
            </div>
            <div class="field">
              <label>Brand colors <span class="opt">(optional)</span></label>
              <div style="display:flex;gap:12px;align-items:center;padding-top:6px">
                <input type="color" id="f_c1" value="#5b45e0" style="width:52px;height:40px;border:1px solid var(--line);border-radius:9px;cursor:pointer" />
                <input type="color" id="f_c2" value="#0fb6a6" style="width:52px;height:40px;border:1px solid var(--line);border-radius:9px;cursor:pointer" />
                <span style="font-size:12.5px;color:var(--muted)">Primary & accent</span>
              </div>
            </div>
          </div>

          <div class="sect">Social</div>
          <div class="grid2">
            <div class="field"><label>Instagram <span class="opt">(optional)</span></label><input type="text" id="f_ig" placeholder="@yourstudio" /></div>
            <div class="field"><label>Facebook <span class="opt">(optional)</span></label><input type="text" id="f_fb" placeholder="facebook.com/yourstudio" /></div>
          </div>

          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <button class="btn btn-primary" data-next>Continue →</button>
          </div>
        </div>
      </section>

      <!-- ═══ Step 3 — AI Website Builder ═══ -->
      <section class="step" data-step="3">
        <div class="card">
          <span class="eyebrow">Step 3 · AI Website Builder</span>
          <h1>Let's build your website ✨</h1>
          <p class="lede">Every Studio Nexis studio gets a professionally designed booking website — fast, mobile-first, SEO-ready and wired straight into your booking system. Answer a few questions and we'll personalize the copy, branding and style for you. You can fine-tune everything later.</p>

          <div class="field"><label>Describe your studio in one sentence</label><textarea id="w_desc" placeholder="A boutique reformer pilates studio in the heart of the city."></textarea></div>
          <div class="grid2">
            <div class="field"><label>What makes your studio unique?</label><input type="text" id="w_usp" placeholder="Small classes, expert instructors…" /></div>
            <div class="field"><label>Who is your ideal client?</label><input type="text" id="w_client" placeholder="Busy professionals, beginners…" /></div>
          </div>

          <div class="sect">Pick your style</div>
          <div class="styles" id="styleGrid"></div>

          <div class="sect">Tone of voice</div>
          <div class="chips" id="toneChips"></div>

          <div class="sect">Photos <span style="text-transform:none;letter-spacing:0;font-weight:500">(optional — we'll use beautiful defaults otherwise)</span></div>
          <div class="upl" id="photoUpl">Click to add studio photos</div>
          <input type="file" id="w_photos" accept="image/*" multiple style="display:none" />
          <div class="thumbs" id="photoThumbs"></div>

          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <div style="display:flex;gap:10px;align-items:center">
              <button class="skip-step" data-skip>Skip for now</button>
              <button class="btn btn-primary" id="generateBtn">✨ Generate my website</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Step 4 — Services & Classes ═══ -->
      <section class="step" data-step="4">
        <div class="card">
          <span class="eyebrow">Step 4 · Services & Classes</span>
          <h1>What do you offer?</h1>
          <p class="lede">Tick the services you run — we've pre-filled sensible durations, capacity and pricing you can adjust. Everything can be changed later.</p>
          <div class="done-note" id="svcDone"></div>
          <div id="svcList"></div>
          <button class="add-row" id="svcAdd">+ Add another service</button>
          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <div style="display:flex;gap:10px;align-items:center">
              <button class="skip-step" data-skip>Skip for now</button>
              <button class="btn btn-primary" data-next>Continue →</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Step 5 — Memberships & Packages ═══ -->
      <section class="step" data-step="5">
        <div class="card">
          <span class="eyebrow">Step 5 · Memberships & Packages</span>
          <h1>Memberships & packages</h1>
          <p class="lede">Starter pricing templates based on studios like yours — tweak the numbers to fit your market.</p>
          <div class="done-note" id="pkgDone"></div>
          <div id="pkgList"></div>
          <button class="add-row" id="pkgAdd">+ Add another package</button>
          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <div style="display:flex;gap:10px;align-items:center">
              <button class="skip-step" data-skip>Skip for now</button>
              <button class="btn btn-primary" data-next>Continue →</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Step 6 — Staff ═══ -->
      <section class="step" data-step="6">
        <div class="card">
          <span class="eyebrow">Step 6 · Your Team</span>
          <h1>Invite your team</h1>
          <p class="lede">Add instructors and front-desk staff. They'll appear on your schedule and website — you can set pay rates, commissions and availability later in the Staff area.</p>
          <div class="done-note" id="stDone"></div>
          <div id="staffList"></div>
          <button class="add-row" id="stAdd">+ Add a team member</button>
          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <div style="display:flex;gap:10px;align-items:center">
              <button class="skip-step" data-skip>Skip for now</button>
              <button class="btn btn-primary" data-next>Continue →</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Step 7 — Payments ═══ -->
      <section class="step" data-step="7">
        <div class="card">
          <span class="eyebrow">Step 7 · Payments</span>
          <h1>How will you get paid?</h1>
          <p class="lede">Connect Stripe to take online payments, or start in sandbox mode and connect later — bookings and pay-at-studio work either way.</p>

          <div class="paycards">
            <div class="paycard" data-pay="sandbox">
              <h4>🧪 Sandbox mode</h4>
              <p>Start without online payments. Take bookings with pay-at-studio; connect Stripe whenever you're ready.</p>
            </div>
            <div class="paycard" data-pay="stripe">
              <h4>💳 Connect Stripe</h4>
              <p>Accept cards online. Paste your Stripe API keys — they're encrypted and never shown again.</p>
            </div>
          </div>

          <div class="stripe-fields" id="stripeFields">
            <div class="field"><label>Publishable key</label><input type="text" id="p_pk" placeholder="pk_live_… or pk_test_…" /></div>
            <div class="field"><label>Secret key</label><input type="text" id="p_sk" placeholder="sk_live_… or sk_test_…" /></div>
            <div class="field"><label>Webhook secret <span class="opt">(optional)</span></label><input type="text" id="p_wh" placeholder="whsec_…" /></div>
          </div>

          <p style="font-size:12.5px;color:var(--muted);margin-top:8px">Taxes, cancellation policy, late fees, deposits, gift cards, POS and retail all live in <b>Settings</b> — sensible defaults are already applied.</p>

          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <div style="display:flex;gap:10px;align-items:center">
              <button class="skip-step" data-skip>Skip for now</button>
              <button class="btn btn-primary" data-next>Continue →</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Step 8 — Review & Launch ═══ -->
      <section class="step" data-step="8">
        <div class="card">
          <span class="eyebrow">Step 8 · Review & Launch</span>
          <h1>Ready for lift-off 🚀</h1>
          <p class="lede">Here's everything we've set up. You can change any of it later from your dashboard.</p>
          <div class="review" id="reviewGrid"></div>
          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <button class="btn btn-primary" id="launchBtn" style="font-size:16px;padding:14px 30px">Launch Studio 🎉</button>
          </div>
        </div>
      </section>

      <!-- ═══ Celebration ═══ -->
      <section class="step" data-step="9">
        <div class="card cele">
          <div class="big">🎉</div>
          <h1>Your studio is ready.</h1>
          <p class="lede" style="margin-bottom:0">Congratulations — your studio is live on Studio Nexis. Here's what to do next:</p>
          <div class="next-grid">
            <a class="nx" id="visitSiteBtn" href="/" target="_blank"><span>🌐</span>Visit Website</a>
            <a class="nx" href="/admin"><span>📊</span>Open Dashboard</a>
            <a class="nx" href="/admin/class-blueprints"><span>🧘</span>Add More Classes</a>
            <a class="nx" href="/admin/staff"><span>👥</span>Invite Team</a>
            <a class="nx" href="/admin/clients"><span>📇</span>Import Clients</a>
            <a class="nx" href="/admin/settings"><span>⚙️</span>Fine-tune Settings</a>
          </div>
        </div>
      </section>
    </div>

    <!-- ═══ AI generation overlay ═══ -->
    <div class="genlay" id="genlay">
      <div class="gen-in">
        <div class="orb"></div>
        <div class="gen-title" id="genTitle">Building your website…</div>
        <div class="gen-lines" id="genLines"></div>
      </div>
    </div>

    <script define:vars={{ API }}>
      (function () {
        var token = localStorage.getItem('token');
        if (!token) { window.location.href = '/admin/login'; return; }
        var A = API || '';

        // ───────────────────────── helpers ─────────────────────────
        function $(s, r) { return (r || document).querySelector(s); }
        function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
        function h(hasBody) { var o = { Authorization: 'Bearer ' + token }; if (hasBody) o['Content-Type'] = 'application/json'; return o; }
        async function api(method, path, body) {
          var res = await fetch(A + path, { method: method, headers: h(body !== undefined), body: body !== undefined ? JSON.stringify(body) : undefined });
          if (!res.ok) throw new Error(method + ' ' + path + ' → ' + res.status);
          var ctp = res.headers.get('content-type') || '';
          return ctp.includes('json') ? res.json() : null;
        }
        var chip = $('#saveChip'), chipT;
        function saving() { chip.className = 'save-chip'; chip.textContent = 'Saving…'; }
        function saved() { chip.className = 'save-chip ok'; chip.textContent = 'Saved ✓'; clearTimeout(chipT); chipT = setTimeout(function () { chip.textContent = ''; }, 2600); }
        function saveErr() { chip.className = 'save-chip err'; chip.textContent = 'Couldn’t save'; }
        function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }

        // ───────────────────────── state ─────────────────────────
        var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var S = {
          profile: { hours: [] },
          existing: { blueprints: [], packages: [], staff: [] },
          created: { services: 0, packages: 0, staff: 0 },
          payMode: null,
          siteGenerated: false,
        };
        try {
          var draft = JSON.parse(localStorage.getItem('nx-setup') || '{}');
          if (draft.payMode) S.payMode = draft.payMode;
          if (draft.siteGenerated) S.siteGenerated = draft.siteGenerated;
        } catch (e) {}
        function persist() { localStorage.setItem('nx-setup', JSON.stringify({ payMode: S.payMode, siteGenerated: S.siteGenerated })); }

        // ───────────────────────── step navigation ─────────────────────────
        var STEP_NAMES = ['Welcome','Studio Information','AI Website Builder','Services & Classes','Memberships & Packages','Your Team','Payments','Review & Launch','Done'];
        var cur = 1, TOTAL = 8;
        var steps = $$('.step');
        function show(i) {
          cur = Math.max(1, Math.min(steps.length, i));
          steps.forEach(function (s) { s.classList.toggle('on', +s.dataset.step === cur); });
          var pct = Math.round(((Math.min(cur, TOTAL) - 1) / TOTAL) * 100);
          if (cur >= 9) pct = 100;
          $('#progFill').style.width = pct + '%';
          $('#stepLabel').innerHTML = '<b>' + STEP_NAMES[cur - 1] + '</b>';
          $('#pctLabel').textContent = cur >= 9 ? 'Complete 🎉' : 'Step ' + cur + ' of ' + TOTAL + ' · ' + pct + '%';
          if (cur === 8) buildReview();
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        async function saveStep(n) {
          try {
            saving();
            if (n === 2) await saveProfile();
            if (n === 4) await saveServices();
            if (n === 5) await savePackages();
            if (n === 6) await saveStaff();
            if (n === 7) await savePayments();
            saved();
          } catch (e) { console.error(e); saveErr(); /* never trap the user on a save error */ }
        }

        $$('[data-next]').forEach(function (b) {
          b.addEventListener('click', async function () { b.disabled = true; await saveStep(cur); b.disabled = false; show(cur + 1); });
        });
        $$('[data-back]').forEach(function (b) { b.addEventListener('click', function () { show(cur - 1); }); });
        $$('[data-skip]').forEach(function (b) { b.addEventListener('click', function () { show(cur + 1); }); });

        $('#finishLater').addEventListener('click', async function (e) {
          e.preventDefault();
          try { saving(); await saveStep(cur); await api('POST', '/api/settings/complete-setup'); saved(); } catch (err) {}
          window.location.href = '/admin';
        });

        // ───────────────────────── step 1: benefits ─────────────────────────
        var BENEFITS = ['Online Booking','AI Studio Website','CRM','POS','Payments','Memberships','Staff Portal','Analytics'];
        $('#benefits').innerHTML = BENEFITS.map(function (b, i) {
          return '<div class="benefit" style="animation-delay:' + (i * 70) + 'ms">' +
            '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg>' + b + '</div>';
        }).join('');

        // ───────────────────────── step 2: studio info ─────────────────────────
        var TZS = ['Pacific/Honolulu','America/Anchorage','America/Los_Angeles','America/Denver','America/Chicago','America/New_York','America/Toronto','America/Sao_Paulo','Europe/London','Europe/Paris','Europe/Berlin','Europe/Madrid','Europe/Rome','Europe/Istanbul','Asia/Dubai','Asia/Karachi','Asia/Kolkata','Asia/Bangkok','Asia/Ho_Chi_Minh','Asia/Singapore','Asia/Hong_Kong','Asia/Shanghai','Asia/Tokyo','Asia/Seoul','Australia/Perth','Australia/Sydney','Pacific/Auckland'];
        try { if (Intl.supportedValuesOf) TZS = Intl.supportedValuesOf('timeZone'); } catch (e) {}
        var browserTz = 'UTC'; try { browserTz = Intl.DateTimeFormat().resolvedOptions().timeZone; } catch (e) {}
        $('#f_tz').innerHTML = TZS.map(function (z) { return '<option' + (z === browserTz ? ' selected' : '') + '>' + z + '</option>'; }).join('');
        var CURS = ['USD','CAD','EUR','GBP','AUD','NZD','VND','THB','SGD','HKD','JPY','KRW','INR','AED','MXN','BRL'];
        $('#f_cur').innerHTML = CURS.map(function (c) { return '<option>' + c + '</option>'; }).join('');

        function defaultHours() {
          return DAYS.map(function (_, d) { return { day: d, open: '08:00', close: '20:00', closed: d === 0 }; });
        }
        function renderHours(hours) {
          $('#hours').innerHTML = hours.map(function (r) {
            return '<div class="hrow" data-day="' + r.day + '">' +
              '<span class="day">' + DAYS[r.day] + '</span>' +
              '<input type="time" class="h-open" value="' + (r.open || '08:00') + '"' + (r.closed ? ' disabled' : '') + ' /> – ' +
              '<input type="time" class="h-close" value="' + (r.close || '20:00') + '"' + (r.closed ? ' disabled' : '') + ' />' +
              '<label class="closed-toggle"><input type="checkbox" class="h-closed"' + (r.closed ? ' checked' : '') + ' /> Closed</label>' +
              '</div>';
          }).join('');
          $$('.h-closed').forEach(function (c) {
            c.addEventListener('change', function () {
              var row = c.closest('.hrow');
              $$('.h-open,.h-close', row).forEach(function (i) { i.disabled = c.checked; });
            });
          });
        }
        function readHours() {
          return $$('#hours .hrow').map(function (row) {
            return { day: +row.dataset.day, open: $('.h-open', row).value || '08:00', close: $('.h-close', row).value || '20:00', closed: $('.h-closed', row).checked };
          });
        }

        // logo upload
        $('#logoUpl').addEventListener('click', function () { $('#f_logo').click(); });
        $('#f_logo').addEventListener('change', async function () {
          var f = this.files[0]; if (!f) return;
          $('#logoUpl').innerHTML = '<span id="logoUplTxt">Uploading…</span>';
          try {
            var fd = new FormData(); fd.append('file', f);
            var res = await fetch(A + '/api/media/studio-logo', { method: 'POST', headers: { Authorization: 'Bearer ' + token }, body: fd });
            var j = await res.json();
            if (!res.ok) throw new Error(j.error || 'upload failed');
            S.profile.logoUrl = j.url;
            $('#logoUpl').innerHTML = '<img src="' + j.url + '" alt="logo" /><span style="font-size:12px">Click to replace</span>';
          } catch (e) { $('#logoUpl').innerHTML = '<span id="logoUplTxt">Upload failed — click to retry</span>'; }
        });

        function readProfile() {
          var p = S.profile || {};
          p.studioName = $('#f_name').value.trim();
          p.businessEmail = $('#f_email').value.trim();
          p.phone = $('#f_phone').value.trim();
          p.website = $('#f_site').value.trim();
          p.address = $('#f_addr').value.trim();
          p.city = $('#f_city').value.trim();
          p.country = $('#f_country').value.trim();
          p.timeZone = $('#f_tz').value;
          p.currency = $('#f_cur').value;
          p.language = $('#f_lang').value;
          p.primaryColor = $('#f_c1').value;
          p.secondaryColor = $('#f_c2').value;
          p.instagram = $('#f_ig').value.trim();
          p.facebook = $('#f_fb').value.trim();
          p.hours = readHours();
          return p;
        }
        async function saveProfile() { S.profile = readProfile(); await api('PATCH', '/api/settings/profile', S.profile); }

        // ───────────────────────── step 3: website builder ─────────────────────────
        var PRESETS = [
          { id: 'modern-minimal',   name: 'Modern Minimal',     desc: 'Clean lines, whitespace, quiet confidence.', sw: ['#111827','#9ca3af','#f3f4f6'] },
          { id: 'luxury-wellness',  name: 'Luxury Wellness',    desc: 'Rich, serene, five-star spa energy.',        sw: ['#3b2f4d','#b49a67','#f4efe8'] },
          { id: 'earthy-organic',   name: 'Earthy Organic',     desc: 'Warm naturals, grounded and calm.',          sw: ['#5f6c3a','#a9825c','#f3ede2'] },
          { id: 'bright-energetic', name: 'Bright & Energetic', desc: 'Bold color, movement, big energy.',          sw: ['#e0455b','#f59e0b','#fdf2f4'] },
          { id: 'boutique-premium', name: 'Boutique Premium',   desc: 'Fashion-forward, editorial, chic.',          sw: ['#1f1b2e','#8b5cf6','#f5f3ff'] },
          { id: 'coastal-relaxed',  name: 'Coastal Relaxed',    desc: 'Breezy blues, soft sand, easy pace.',        sw: ['#2a637e','#62b6cb','#eef6f8'] },
        ];
        var TONES = ['Friendly','Professional','Luxury','Calm','Energetic'];
        var selPreset = 'modern-minimal', selTone = 'Friendly';

        $('#styleGrid').innerHTML = PRESETS.map(function (p) {
          return '<div class="stylecard' + (p.id === selPreset ? ' sel' : '') + '" data-preset="' + p.id + '">' +
            '<div class="sw">' + p.sw.map(function (c) { return '<i style="background:' + c + '"></i>'; }).join('') + '</div>' +
            '<h4>' + p.name + '</h4><p>' + p.desc + '</p></div>';
        }).join('');
        $$('.stylecard').forEach(function (c) {
          c.addEventListener('click', function () {
            selPreset = c.dataset.preset;
            $$('.stylecard').forEach(function (x) { x.classList.toggle('sel', x === c); });
          });
        });
        $('#toneChips').innerHTML = TONES.map(function (t) {
          return '<button class="chip' + (t === selTone ? ' sel' : '') + '" data-tone="' + t + '">' + t + '</button>';
        }).join('');
        $$('#toneChips .chip').forEach(function (c) {
          c.addEventListener('click', function () {
            selTone = c.dataset.tone;
            $$('#toneChips .chip').forEach(function (x) { x.classList.toggle('sel', x === c); });
          });
        });

        var sitePhotos = [];
        $('#photoUpl').addEventListener('click', function () { $('#w_photos').click(); });
        $('#w_photos').addEventListener('change', async function () {
          var files = Array.prototype.slice.call(this.files || []);
          for (var i = 0; i < files.length; i++) {
            try {
              var fd = new FormData(); fd.append('file', files[i]);
              var res = await fetch(A + '/api/media/site-photo', { method: 'POST', headers: { Authorization: 'Bearer ' + token }, body: fd });
              var j = await res.json();
              if (res.ok && j.url) {
                sitePhotos.push(j.url);
                var img = document.createElement('img'); img.className = 'th'; img.src = j.url;
                $('#photoThumbs').appendChild(img);
              }
            } catch (e) {}
          }
          this.value = '';
        });

        // Copy generator — personalizes content within the shared design system.
        function generateCopy() {
          var name = ($('#f_name').value || 'Your Studio').trim() || 'Your Studio';
          var city = ($('#f_city').value || '').trim();
          var desc = $('#w_desc').value.trim();
          var usp = $('#w_usp').value.trim();
          var client = $('#w_client').value.trim();
          var loc = city ? ' in ' + city : '';

          var heroByTone = {
            Friendly:     'Move well. Feel great.',
            Professional: 'Expert-led pilates & yoga' + loc + '.',
            Luxury:       'An elevated movement experience.',
            Calm:         'Breathe. Move. Restore.',
            Energetic:    'Stronger every session.',
          };
          var ctaByTone = { Friendly: 'Book your first class', Professional: 'View the schedule', Luxury: 'Reserve your session', Calm: 'Begin your practice', Energetic: 'Jump in — book now' };
          var subByTone = {
            Friendly:     'Welcome to ' + name + (desc ? ' — ' + desc.replace(/\.$/, '') : '') + '. Come move with us.',
            Professional: name + (desc ? ' — ' + desc.replace(/\.$/, '') : '') + '. Programs designed around measurable progress.',
            Luxury:       'Welcome to ' + name + ', a considered space' + loc + ' for those who take their wellbeing seriously.',
            Calm:         name + ' is a space to slow down, tune in and rebuild from the inside out.',
            Energetic:    name + ' brings expert coaching and serious energy to every single class.',
          };

          var about = 'At ' + name + ', every class is built around you.';
          if (desc) about = desc.replace(/\.?\s*$/, '.');
          if (usp) about += ' What sets us apart? ' + usp.replace(/\.?\s*$/, '.');
          if (client) about += ' Whether you’re ' + client.replace(/\.?\s*$/, '') + ' or just getting started, you’ll fit right in.';
          about += ' Book online in seconds and join us on the mat.';

          return {
            published: true,
            stylePreset: selPreset,
            tone: selTone,
            description: desc, uniqueSellingPoint: usp, idealClient: client,
            heroHeadline: heroByTone[selTone] || heroByTone.Friendly,
            heroSub: subByTone[selTone] || subByTone.Friendly,
            ctaText: ctaByTone[selTone] || ctaByTone.Friendly,
            aboutHeadline: 'About ' + name,
            aboutBody: about,
            seoTitle: name + (city ? ' — Pilates & Yoga in ' + city : ' — Pilates & Yoga Studio'),
            seoDescription: (desc || name + ' is a boutique pilates & yoga studio' + loc + '.') + ' Book classes online.',
            photoUrls: sitePhotos,
            faqs: [
              { question: 'Do I need experience to join?', answer: 'Not at all — our classes welcome every level, and instructors offer options for beginners through advanced students.' },
              { question: 'What should I bring?', answer: 'Comfortable clothes you can move in and a water bottle. Mats and equipment are provided.' },
              { question: 'How do I book a class?', answer: 'Tap "Book Now", pick a class and time that suits you, and you’re in. You’ll get an instant confirmation.' },
              { question: 'What is the cancellation policy?', answer: 'You can cancel or reschedule from your account. Full details are on our booking policy page.' },
            ],
            generatedAt: new Date().toISOString(),
          };
        }

        // Generation overlay sequence
        var GEN_LINES = ['Analyzing your brand…','Designing your homepage…','Writing your website copy…','Generating imagery…','Optimizing SEO…','Building booking pages…','Connecting your CRM…','Publishing your website…'];
        $('#generateBtn').addEventListener('click', async function () {
          var lay = $('#genlay'); lay.classList.add('on');
          var box = $('#genLines');
          box.innerHTML = GEN_LINES.map(function (l) {
            return '<div class="gl"><span class="st"></span><span>' + l + '</span></div>';
          }).join('');
          var rows = $$('.gl', box);

          // Save profile + site while the show plays (the real work).
          var work = (async function () {
            try { await saveProfile(); } catch (e) {}
            await api('PATCH', '/api/settings/site', generateCopy());
          })();

          for (var i = 0; i < rows.length; i++) {
            rows[i].classList.add('show', 'working');
            await new Promise(function (r) { setTimeout(r, 560 + Math.random() * 420); });
            rows[i].classList.remove('working'); rows[i].classList.add('done');
            rows[i].querySelector('.st').textContent = '✓';
          }
          try { await work; S.siteGenerated = true; persist(); } catch (e) { console.error(e); }
          $('#genTitle').textContent = '✨ Your website is live!';
          await new Promise(function (r) { setTimeout(r, 900); });
          lay.classList.remove('on');
          show(4);
        });

        // ───────────────────────── steps 4–6: template rows ─────────────────────────
        function tplRow(kind, t, checked) {
          var fields = '';
          if (kind === 'svc') {
            fields =
              '<div><label>Duration (min)</label><input type="number" data-f="duration" value="' + t.duration + '" /></div>' +
              '<div><label>Capacity</label><input type="number" data-f="capacity" value="' + t.capacity + '" /></div>' +
              '<div><label>Drop-in price</label><input type="number" data-f="price" value="' + t.price + '" /></div>' +
              '<div><label>Level</label><select data-f="level"><option>ALL_LEVELS</option><option>BEGINNER</option><option>INTERMEDIATE</option><option>ADVANCED</option></select></div>' +
              '<div><label>Format</label><select data-f="format"><option' + (t.format === 'GROUP' ? ' selected' : '') + '>GROUP</option><option' + (t.format === 'PRIVATE' ? ' selected' : '') + '>PRIVATE</option></select></div>';
          } else if (kind === 'pkg') {
            fields =
              '<div><label>Price</label><input type="number" data-f="price" value="' + t.price + '" /></div>' +
              '<div><label>Credits</label><input type="number" data-f="credits" value="' + t.credits + '" /></div>' +
              '<div><label>Valid (days)</label><input type="number" data-f="validity" value="' + t.validity + '" /></div>' +
              '<div><label>For</label><select data-f="format"><option' + (t.format === 'GROUP' ? ' selected' : '') + '>GROUP</option><option' + (t.format === 'PRIVATE' ? ' selected' : '') + '>PRIVATE</option></select></div>';
          } else {
            fields =
              '<div style="grid-column:span 2"><label>Full name</label><input type="text" data-f="name" value="" placeholder="Jane Doe" /></div>' +
              '<div style="grid-column:span 2"><label>Email</label><input type="email" data-f="email" value="" placeholder="jane@studio.com" /></div>' +
              '<div><label>Phone</label><input type="tel" data-f="phone" value="" /></div>' +
              '<div><label>Role</label><select data-f="role"><option>INSTRUCTOR</option><option>RECEPTIONIST</option><option>MANAGER</option><option>OWNER</option></select></div>';
          }
          var div = document.createElement('div');
          div.className = 'tpl' + (checked ? ' sel' : '');
          div.innerHTML =
            '<div class="tpl-head"><span class="cbx"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg></span>' +
            '<span class="tpl-name">' + esc(t.name) + '</span>' +
            '<span class="tpl-sub">' + esc(t.sub || '') + '</span></div>' +
            '<div class="tpl-body">' + fields + '</div>';
          $('.tpl-head', div).addEventListener('click', function (e) {
            if (e.target.closest('input,select,[contenteditable=true]')) return;
            div.classList.toggle('sel');
          });
          return div;
        }

        var SVC_TPLS = [
          { name: 'Group Reformer',    sub: '50 min · 8 spots',    duration: 50, capacity: 8,  price: 35, format: 'GROUP',   on: true },
          { name: 'Mat Pilates',       sub: '50 min · 12 spots',   duration: 50, capacity: 12, price: 25, format: 'GROUP',   on: true },
          { name: 'Yoga Flow',         sub: '60 min · 14 spots',   duration: 60, capacity: 14, price: 22, format: 'GROUP',   on: false },
          { name: 'Private Session',   sub: '55 min · 1-on-1',     duration: 55, capacity: 1,  price: 90, format: 'PRIVATE', on: true },
          { name: 'Duet',              sub: '55 min · 2 people',   duration: 55, capacity: 2,  price: 60, format: 'PRIVATE', on: false },
          { name: 'Semi-Private',      sub: '55 min · 3-4 people', duration: 55, capacity: 4,  price: 45, format: 'PRIVATE', on: false },
          { name: 'Beginner Workshop', sub: '90 min · 10 spots',   duration: 90, capacity: 10, price: 40, format: 'GROUP',   on: false },
        ];
        SVC_TPLS.forEach(function (t) { $('#svcList').appendChild(tplRow('svc', t, t.on)); });
        $('#svcAdd').addEventListener('click', function () {
          var d = tplRow('svc', { name: 'New service', sub: '' , duration: 50, capacity: 10, price: 25, format: 'GROUP' }, true);
          var nameEl = $('.tpl-name', d); nameEl.contentEditable = 'true'; nameEl.style.outline = 'none';
          $('#svcList').appendChild(d); nameEl.focus();
        });

        var PKG_TPLS = [
          { name: 'Unlimited Membership', sub: 'monthly · best value', price: 199, credits: 30, validity: 30,  format: 'GROUP',   on: false },
          { name: '8 Classes / Month',    sub: 'monthly',              price: 140, credits: 8,  validity: 30,  format: 'GROUP',   on: true },
          { name: '12 Classes / Month',   sub: 'monthly',              price: 189, credits: 12, validity: 30,  format: 'GROUP',   on: false },
          { name: '5 Class Pack',         sub: 'starter',              price: 110, credits: 5,  validity: 90,  format: 'GROUP',   on: true },
          { name: '10 Class Pack',        sub: 'popular',              price: 200, credits: 10, validity: 120, format: 'GROUP',   on: true },
          { name: '20 Class Pack',        sub: 'commit & save',        price: 360, credits: 20, validity: 180, format: 'GROUP',   on: false },
          { name: 'Private 5 Pack',       sub: '1-on-1',               price: 425, credits: 5,  validity: 120, format: 'PRIVATE', on: false },
          { name: 'Private 10 Pack',      sub: '1-on-1',               price: 800, credits: 10, validity: 180, format: 'PRIVATE', on: false },
        ];
        PKG_TPLS.forEach(function (t) { $('#pkgList').appendChild(tplRow('pkg', t, t.on)); });
        $('#pkgAdd').addEventListener('click', function () {
          var d = tplRow('pkg', { name: 'New package', sub: '', price: 100, credits: 5, validity: 90, format: 'GROUP' }, true);
          var nameEl = $('.tpl-name', d); nameEl.contentEditable = 'true'; nameEl.style.outline = 'none';
          $('#pkgList').appendChild(d); nameEl.focus();
        });

        function staffRow() {
          var d = tplRow('staff', { name: 'Team member', sub: '' }, true);
          var nameEl = $('.tpl-name', d);
          $('[data-f=name]', d).addEventListener('input', function () { nameEl.textContent = this.value || 'Team member'; });
          return d;
        }
        $('#staffList').appendChild(staffRow());
        $('#stAdd').addEventListener('click', function () { $('#staffList').appendChild(staffRow()); });

        function readRows(sel) {
          return $$(sel + ' .tpl.sel').map(function (d) {
            var o = { name: $('.tpl-name', d).textContent.trim() };
            $$('[data-f]', d).forEach(function (i) { o[i.dataset.f] = i.value; });
            return o;
          });
        }

        async function saveServices() {
          var have = S.existing.blueprints.map(function (b) { return (b.className || '').toLowerCase(); });
          var rows = readRows('#svcList').filter(function (r) { return r.name && have.indexOf(r.name.toLowerCase()) === -1; });
          for (var i = 0; i < rows.length; i++) {
            var r = rows[i];
            await api('POST', '/api/classblueprint', {
              className: r.name, format: r.format || 'GROUP', difficultyLevel: r.level || 'ALL_LEVELS',
              focusArea: 'FULL_BODY', durationMinutes: +r.duration || 50, defaultCapacity: +r.capacity || 10,
              dropInPrice: +r.price || 0, isActive: true, defaultIsPublic: true,
              description: '', benefits: [], goodFor: [], muscleAreas: [], tags: [], equipmentIds: [], equipmentTypes: [], weeklySlots: [],
            });
            S.created.services++;
            have.push(r.name.toLowerCase());
          }
        }
        async function savePackages() {
          var have = S.existing.packages.map(function (p) { return (p.name || '').toLowerCase(); });
          var rows = readRows('#pkgList').filter(function (r) { return r.name && have.indexOf(r.name.toLowerCase()) === -1; });
          for (var i = 0; i < rows.length; i++) {
            var r = rows[i];
            await api('POST', '/api/product', {
              name: r.name, type: 'PACKAGE', formatRestriction: r.format || 'GROUP',
              basePrice: +r.price || 0, credits: +r.credits || 0, validityDays: +r.validity || 90,
              isActive: true, description: '', variants: [],
            });
            S.created.packages++;
            have.push(r.name.toLowerCase());
          }
        }
        async function saveStaff() {
          var have = S.existing.staff.map(function (s) { return (s.name || '').toLowerCase(); });
          var rows = readRows('#staffList').filter(function (r) { return r.name && r.name !== 'Team member' && have.indexOf(r.name.toLowerCase()) === -1; });
          for (var i = 0; i < rows.length; i++) {
            var r = rows[i];
            await api('POST', '/api/staff', { name: r.name, role: r.role || 'INSTRUCTOR', email: r.email || null, phone: r.phone || null, isActive: true });
            S.created.staff++;
            have.push(r.name.toLowerCase());
          }
        }

        // ───────────────────────── step 7: payments ─────────────────────────
        $$('.paycard').forEach(function (c) {
          c.addEventListener('click', function () {
            S.payMode = c.dataset.pay; persist();
            $$('.paycard').forEach(function (x) { x.classList.toggle('sel', x === c); });
            $('#stripeFields').classList.toggle('on', S.payMode === 'stripe');
          });
        });
        async function savePayments() {
          if (S.payMode === 'stripe' && $('#p_sk').value.trim()) {
            await api('POST', '/api/settings/stripe-keys', {
              enabled: true,
              publishableKey: $('#p_pk').value.trim() || null,
              secretKey: $('#p_sk').value.trim() || null,
              webhookSecret: $('#p_wh').value.trim() || null,
            });
          }
        }

        // ───────────────────────── step 8: review + launch ─────────────────────────
        function buildReview() {
          var name = $('#f_name').value.trim();
          var items = [
            { ok: S.siteGenerated, t: 'Website', d: S.siteGenerated ? 'Generated & published' : 'Skipped — generate anytime' },
            { ok: true, t: 'Booking System', d: 'Live and taking bookings' },
            { ok: true, t: 'CRM', d: 'Ready — clients sync automatically' },
            { ok: !!name, t: 'Studio Profile', d: name ? name : 'Add your studio name' },
            { ok: (S.created.services + S.existing.blueprints.length) > 0, t: 'Classes', d: (S.created.services + S.existing.blueprints.length) + ' configured' },
            { ok: (S.created.packages + S.existing.packages.length) > 0, t: 'Memberships', d: (S.created.packages + S.existing.packages.length) + ' created' },
            { ok: (S.created.staff + S.existing.staff.length) > 0, t: 'Team', d: (S.created.staff + S.existing.staff.length) + ' member(s)' },
            { ok: S.payMode === 'stripe', t: 'Payments', d: S.payMode === 'stripe' ? 'Stripe connected' : 'Sandbox mode — connect later' },
          ];
          $('#reviewGrid').innerHTML = items.map(function (i) {
            var icon = i.ok
              ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg>'
              : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/></svg>';
            return '<div class="rv"><span class="ic' + (i.ok ? '' : ' warn') + '">' + icon + '</span><div><h5>' + i.t + '</h5><p>' + esc(i.d) + '</p></div></div>';
          }).join('');
        }

        $('#launchBtn').addEventListener('click', async function () {
          this.disabled = true; this.textContent = 'Launching…';
          try { saving(); await api('POST', '/api/settings/complete-setup'); saved(); } catch (e) { saveErr(); }
          localStorage.removeItem('nx-setup');
          show(9); confetti();
        });

        // ───────────────────────── confetti ─────────────────────────
        function confetti() {
          var cv = $('#confetti'), ctx = cv.getContext('2d');
          cv.width = innerWidth; cv.height = innerHeight;
          var COLORS = ['#5b45e0','#8b5cf6','#0fb6a6','#f59e0b','#e0455b','#3a86a8'];
          var ps = [];
          for (var i = 0; i < 160; i++) ps.push({ x: Math.random() * cv.width, y: -20 - Math.random() * cv.height * .5, r: 4 + Math.random() * 6, c: COLORS[i % COLORS.length], vy: 2 + Math.random() * 3.4, vx: -1.4 + Math.random() * 2.8, a: Math.random() * Math.PI });
          var t0 = Date.now();
          (function tick() {
            ctx.clearRect(0, 0, cv.width, cv.height);
            ps.forEach(function (p) {
              p.y += p.vy; p.x += p.vx; p.a += .09;
              ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.a); ctx.fillStyle = p.c;
              ctx.fillRect(-p.r / 2, -p.r / 4, p.r, p.r / 2); ctx.restore();
            });
            if (Date.now() - t0 < 4200) requestAnimationFrame(tick);
            else ctx.clearRect(0, 0, cv.width, cv.height);
          })();
        }

        // ───────────────────────── prefill from server ─────────────────────────
        (async function init() {
          try {
            var s = await api('GET', '/api/settings');
            var p = s.profile || {};
            S.profile = p;
            if (p.studioName) $('#f_name').value = p.studioName;
            if (p.businessEmail) $('#f_email').value = p.businessEmail;
            if (p.phone) $('#f_phone').value = p.phone;
            if (p.website) $('#f_site').value = p.website;
            if (p.address) $('#f_addr').value = p.address;
            if (p.city) $('#f_city').value = p.city;
            if (p.country) $('#f_country').value = p.country;
            if (p.timeZone) $('#f_tz').value = p.timeZone;
            if (p.currency) $('#f_cur').value = p.currency;
            if (p.language) $('#f_lang').value = p.language;
            if (p.primaryColor) $('#f_c1').value = p.primaryColor;
            if (p.secondaryColor) $('#f_c2').value = p.secondaryColor;
            if (p.instagram) $('#f_ig').value = p.instagram;
            if (p.facebook) $('#f_fb').value = p.facebook;
            if (p.logoUrl) $('#logoUpl').innerHTML = '<img src="' + p.logoUrl + '" alt="logo" /><span style="font-size:12px">Click to replace</span>';
            renderHours(p.hours && p.hours.length === 7 ? p.hours : defaultHours());
            if (s.site && s.site.published) S.siteGenerated = true;
          } catch (e) { renderHours(defaultHours()); }

          try {
            var results = await Promise.all([
              api('GET', '/api/classblueprint').catch(function () { return []; }),
              api('GET', '/api/product').catch(function () { return []; }),
              api('GET', '/api/staff').catch(function () { return []; }),
            ]);
            S.existing.blueprints = results[0] || [];
            S.existing.packages = (results[1] || []).filter(function (x) { return x.type === 'PACKAGE'; });
            S.existing.staff = results[2] || [];
            if (S.existing.blueprints.length) { var n = $('#svcDone'); n.style.display = 'block'; n.textContent = '✓ You already have ' + S.existing.blueprints.length + ' class type(s) — anything you tick below is added on top.'; }
            if (S.existing.packages.length) { var n2 = $('#pkgDone'); n2.style.display = 'block'; n2.textContent = '✓ You already have ' + S.existing.packages.length + ' package(s) — anything you tick below is added on top.'; }
            if (S.existing.staff.length) { var n3 = $('#stDone'); n3.style.display = 'block'; n3.textContent = '✓ You already have ' + S.existing.staff.length + ' team member(s).'; }
          } catch (e) {}

          // default payment selection
          var pre = S.payMode || 'sandbox';
          var el = $('.paycard[data-pay=' + pre + ']'); if (el) el.click();
        })();
      })();
    </script>
  </body>
</html>

