      .skip{font-size:13.5px;color:var(--muted);font-weight:600}
      .shell{max-width:600px;margin:10px auto 60px;padding:0 24px}
      .card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:38px;box-shadow:0 14px 44px rgba(16,24,40,.08)}
      .steps-dots{display:flex;gap:8px;margin-bottom:26px}
      .dot{height:5px;flex:1;border-radius:3px;background:var(--line);transition:.2s}
      .dot.on{background:linear-gradient(90deg,var(--brand),var(--brand2))}
      .step{display:none}.step.on{display:block}
      h1{font-size:26px;font-weight:800;margin-bottom:10px}
      .lede{color:var(--muted);font-size:16px;margin-bottom:26px}
      .task{display:flex;gap:14px;align-items:flex-start;padding:16px;border:1px solid var(--line);border-radius:14px;margin-bottom:12px;transition:.14s}
      .task:hover{border-color:#cfd3e6;background:var(--bg2)}
      .task .ti{width:42px;height:42px;border-radius:11px;background:#efeafc;color:var(--brand);display:grid;place-items:center;flex-shrink:0}
      .task h3{font-size:15.5px;font-weight:700;margin-bottom:3px}
      .task p{font-size:13.5px;color:var(--muted)}
      .task .arrow{margin-left:auto;color:var(--muted);align-self:center}
      .row{display:flex;justify-content:space-between;align-items:center;margin-top:28px;gap:12px}
      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;padding:12px 22px;border-radius:11px;border:1px solid transparent;cursor:pointer;transition:.15s;font-family:inherit}
      .btn-primary{background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;box-shadow:0 6px 18px rgba(91,69,224,.28)}
      .btn-primary:hover{transform:translateY(-1px)}
