      .hero-ic{width:64px;height:64px;border-radius:18px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;margin-bottom:20px;font-size:30px}
      .done-tick{width:64px;height:64px;border-radius:50%;background:#e6f7f4;color:var(--mint);display:grid;place-items:center;margin-bottom:20px}
    </style>
  </head>
  <body>
    <div class="top">
      <div class="logo"><span class="logo-mark">N</span>Studio&nbsp;Nexis</div>
      <a href="#" class="skip" id="skipLink">Skip for now →</a>
    </div>

    <div class="shell">
      <div class="card">
        <div class="steps-dots"><div class="dot on" data-d="0"></div><div class="dot" data-d="1"></div><div class="dot" data-d="2"></div></div>

        <!-- Step 1 — welcome -->
        <div class="step on" data-step="0">
          <div class="hero-ic">🎉</div>
          <h1>Welcome to your studio!</h1>
          <p class="lede">Your studio is ready on Studio Nexis. Let's take a minute to get it set up so you can start taking bookings. You can change anything later.</p>
          <div class="row" style="justify-content:flex-end">
            <button class="btn btn-primary" data-next>Let's go →</button>
          </div>
        </div>

        <!-- Step 2 — quick-start checklist -->
        <div class="step" data-step="1">
          <h1>Get your studio ready</h1>
          <p class="lede">Set these up now, or come back to them anytime from your dashboard.</p>

          <a class="task" href="/admin/access">
            <span class="ti"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg></span>
            <div><h3>Add your team</h3><p>Invite instructors and front-desk staff.</p></div>
            <span class="arrow">→</span>
          </a>

          <a class="task" href="/admin/class-blueprints">
            <span class="ti"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg></span>
            <div><h3>Create your class types</h3><p>Reformer, mat, private sessions — with pricing.</p></div>
            <span class="arrow">→</span>
          </a>

          <a class="task" href="/admin/settings">
            <span class="ti"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg></span>
            <div><h3>Studio settings &amp; schedule</h3><p>Operating hours, packages, payments and branding.</p></div>
            <span class="arrow">→</span>
          </a>

          <div class="row">
            <button class="btn btn-ghost" data-back>← Back</button>
            <button class="btn btn-primary" data-next>Continue →</button>
          </div>
        </div>

        <!-- Step 3 — finish -->
        <div class="step" data-step="2">
          <div class="done-tick"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg></div>
          <h1>You're all set 🎊</h1>
          <p class="lede">That's the basics. Head to your dashboard to manage bookings, clients and everything else — all in one place.</p>
          <div class="row" style="justify-content:flex-end">
            <button class="btn btn-primary" id="finishBtn">Go to my dashboard →</button>
          </div>
        </div>
      </div>
    </div>

    <script define:vars={{ API }}>
      (function () {
        var token = localStorage.getItem('token');
        if (!token) { window.location.href = '/admin/login'; return; }

        var cur = 0;
        var steps = document.querySelectorAll('.step');
        var dots = document.querySelectorAll('.dot');
        function show(i) {
          cur = Math.max(0, Math.min(steps.length - 1, i));
          steps.forEach(function (s, n) { s.classList.toggle('on', n === cur); });
          dots.forEach(function (d, n) { d.classList.toggle('on', n <= cur); });
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }
        document.querySelectorAll('[data-next]').forEach(function (b) { b.addEventListener('click', function () { show(cur + 1); }); });
        document.querySelectorAll('[data-back]').forEach(function (b) { b.addEventListener('click', function () { show(cur - 1); }); });

        async function complete(redirect) {
          try {
            await fetch((API || '') + '/api/settings/complete-setup', {
              method: 'POST', headers: { Authorization: 'Bearer ' + token },
            });
          } catch (e) {}
          window.location.href = redirect;
        }

        document.getElementById('finishBtn').addEventListener('click', function () {
          this.disabled = true; this.textContent = 'Finishing…';
          complete('/admin');
        });
        // "Skip for now" still marks setup done so the wizard doesn't reappear.
        document.getElementById('skipLink').addEventListener('click', function (e) {
          e.preventDefault(); complete('/admin');
        });
      })();
    </script>
  </body>
</html>

