            <a class="btn" href="/booking" id="ctaBtn">Book Now</a>
          </div>
        </div>
      </section>

      <footer>
        <div class="wrap foot">
          <span id="footName">© Studio</span>
          <div class="links">
            <a href="/booking">Schedule</a>
            <a href="/packages">Pricing</a>
            <a href="/instructors">Team</a>
            <a href="/login">Member Login</a>
            <a href="/booking-policy">Booking Policy</a>
          </div>
          <div class="socials" id="socials"></div>
        </div>
      </footer>
    </main>

    <script define:vars={{ API }}>
      (async function () {
        var A = API || '';
        function $(s) { return document.querySelector(s); }
        function esc(x) { var d = document.createElement('div'); d.textContent = x == null ? '' : String(x); return d.innerHTML; }

        var data;
        try { data = await (await fetch(A + '/api/settings/public')).json(); } catch (e) { data = null; }
        var p = (data && data.profile) || {};
        var site = (data && data.site) || {};

        if (!site.published) { document.body.classList.add('nosite'); return; }

        document.documentElement.dataset.preset = site.stylePreset || 'modern-minimal';
        if (p.primaryColor) document.documentElement.style.setProperty('--p', p.primaryColor);
        if (p.secondaryColor) document.documentElement.style.setProperty('--acc', p.secondaryColor);

        var name = p.studioName || 'Our Studio';
        document.title = site.seoTitle || name;
        $('#seoDesc').setAttribute('content', site.seoDescription || '');
        $('#brandName').textContent = name;
        if (p.logoUrl) $('#brand').innerHTML = '<img src="' + esc(p.logoUrl) + '" alt="' + esc(name) + '" /><span>' + esc(name) + '</span>';

        $('#heroH').textContent = site.heroHeadline || 'Move well. Feel great.';
        $('#heroSub').textContent = site.heroSub || '';
        if (site.ctaText) { $('#heroCta').textContent = site.ctaText; $('#ctaBtn').textContent = site.ctaText; }
        $('#ctaH').textContent = 'Ready to join ' + name + '?';

        // Photo strip — studio photos, or tasteful gradient placeholders.
        var strip = $('#heroStrip');
        var photos = (site.photoUrls || []).slice(0, 3);
        if (photos.length) {
          strip.innerHTML = photos.map(function (u) { return '<img src="' + esc(u) + '" alt="" loading="lazy" />'; }).join('');
          if (site.photoUrls.length > 3) { /* rest shown on about */ }
        } else {
          strip.innerHTML = '<div class="ph"></div><div class="ph" style="opacity:.65"></div><div class="ph" style="opacity:.45"></div>';
        }

        $('#aboutH').textContent = site.aboutHeadline || ('About ' + name);
        $('#aboutB').textContent = site.aboutBody || '';
        var aboutPhoto = (site.photoUrls || [])[3] || (site.photoUrls || [])[0];
        if (aboutPhoto) $('#aboutImg').outerHTML = '<img src="' + esc(aboutPhoto) + '" alt="' + esc(name) + '" loading="lazy" />';

        // Pricing — live from the booking system (top 3 by price).
        try {
          var pk = await (await fetch(A + '/api/products/packages')).json();
          var cur = p.currency || '';
          $('#priceCards').innerHTML = (pk || []).slice(0, 3).map(function (x) {
            return '<div class="pcard"><h3>' + esc(x.name) + '</h3>' +
              '<div class="price">' + Number(x.basePrice).toLocaleString() + (cur ? ' <span style="font-size:14px">' + esc(cur) + '</span>' : '') + '</div>' +
              '<div class="per">' + x.credits + ' credits · valid ' + x.validityDays + ' days</div>' +
              (x.description ? '<div class="meta">' + esc(x.description) + '</div>' : '') +
              '<a class="btn" href="/packages">Choose</a></div>';
          }).join('') || '<p style="color:var(--muted)">Packages coming soon — <a href="/booking" style="text-decoration:underline">book a drop-in class</a>.</p>';
        } catch (e) {}

        // Hours
        var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var hours = p.hours || [];
        $('#hoursCol').innerHTML = hours.length
          ? hours.map(function (h) {
              return '<div class="hrow"><span class="d">' + DAYS[h.day] + '</span>' +
                (h.closed ? '<span class="closed">Closed</span>' : '<span>' + esc(h.open) + ' – ' + esc(h.close) + '</span>') + '</div>';
            }).join('')
          : '<p style="color:var(--muted)">Open daily — see the <a href="/booking" style="text-decoration:underline">live schedule</a>.</p>';

        // Contact
        var pin = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>';
        var tel = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg>';
        var mail = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>';
        var c = '';
        var addr = [p.address, p.city, p.country].filter(Boolean).join(', ');
        if (addr) c += '<div class="c-item">' + pin + '<span>' + esc(addr) + '</span></div>';
        if (p.phone) c += '<div class="c-item">' + tel + '<a href="tel:' + esc(p.phone) + '">' + esc(p.phone) + '</a></div>';
        if (p.businessEmail) c += '<div class="c-item">' + mail + '<a href="mailto:' + esc(p.businessEmail) + '">' + esc(p.businessEmail) + '</a></div>';
        $('#contactCol').innerHTML = c || '<p style="color:var(--muted)">Contact details coming soon.</p>';

        // FAQ
        $('#faqList').innerHTML = (site.faqs || []).map(function (f) {
          return '<details class="qa"><summary>' + esc(f.question) + '</summary><p>' + esc(f.answer) + '</p></details>';
        }).join('');

        // Footer + socials
        $('#footName').textContent = '© ' + new Date().getFullYear() + ' ' + name + ' · Powered by Studio Nexis';
        var soc = '';
        if (p.instagram) {
          var ig = p.instagram.replace(/^@/, '');
          var igUrl = ig.indexOf('http') === 0 ? ig : 'https://instagram.com/' + ig;
          soc += '<a href="' + esc(igUrl) + '" target="_blank" rel="noopener" aria-label="Instagram"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg></a>';
        }
        if (p.facebook) {
          var fb = p.facebook.indexOf('http') === 0 ? p.facebook : 'https://' + p.facebook;
          soc += '<a href="' + esc(fb) + '" target="_blank" rel="noopener" aria-label="Facebook"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"/></svg></a>';
        }
        $('#socials').innerHTML = soc;

        document.body.classList.add('ready');
      })();
    </script>
  </body>
</html>

