---
// Studio Nexis — tenant public website ("AI Website Builder" output).
// A shared, design-system shell that renders each studio's generated content
// (branding, copy, photos, FAQs, hours) from GET /api/settings/public.
// Layout/structure stay identical across studios — only content and the
// style preset change — so every site stays fast, consistent and upgradeable.
const API = import.meta.env.PUBLIC_API_URL;
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title id="seoTitle">Welcome</title>
    <meta name="description" content="" id="seoDesc" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@600;700;800&family=Cormorant+Garamond:wght@500;600&display=swap" rel="stylesheet" />
    <style>
      /* Shared design system — presets only swap the variables below. */
      :root{--p:#111827;--p2:#374151;--acc:#9ca3af;--bg:#ffffff;--bg2:#f3f4f6;--ink:#111827;--muted:#6b7280;--line:#e5e7eb;--radius:18px;--head:'Manrope',sans-serif}
      [data-preset="luxury-wellness"]{--p:#3b2f4d;--p2:#584a70;--acc:#b49a67;--bg:#fffdf9;--bg2:#f4efe8;--ink:#2c2438;--muted:#7d7389;--line:#e8e1d5;--head:'Cormorant Garamond',serif}
      [data-preset="earthy-organic"]{--p:#5f6c3a;--p2:#77874a;--acc:#a9825c;--bg:#fffdf8;--bg2:#f3ede2;--ink:#37402a;--muted:#7d8468;--line:#e6dfd0}
      [data-preset="bright-energetic"]{--p:#e0455b;--p2:#f0607a;--acc:#f59e0b;--bg:#ffffff;--bg2:#fdf2f4;--ink:#231015;--muted:#8a6b72;--line:#f4dade}
      [data-preset="boutique-premium"]{--p:#1f1b2e;--p2:#3a3355;--acc:#8b5cf6;--bg:#ffffff;--bg2:#f5f3ff;--ink:#1f1b2e;--muted:#6f6a85;--line:#e7e3f4}
      [data-preset="coastal-relaxed"]{--p:#2a637e;--p2:#3d7f9e;--acc:#62b6cb;--bg:#fdfefe;--bg2:#eef6f8;--ink:#1d3c4a;--muted:#64808d;--line:#d9e8ec}
      *{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.6}
      h1,h2,h3{font-family:var(--head);letter-spacing:-.02em;line-height:1.15}
      a{text-decoration:none;color:inherit}
      img{max-width:100%;display:block}
      .wrap{max-width:1080px;margin:0 auto;padding:0 22px}
      .btn{display:inline-flex;align-items:center;gap:8px;background:var(--p);color:#fff;font-weight:700;font-size:15px;padding:13px 26px;border-radius:99px;transition:.18s;border:none;cursor:pointer}
      .btn:hover{background:var(--p2);transform:translateY(-1px)}
      .btn.ghost{background:transparent;color:var(--ink);border:1.5px solid var(--line)}
      .btn.ghost:hover{background:var(--bg2);transform:none}

      nav{position:sticky;top:0;z-index:30;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
      .nav-in{max-width:1080px;margin:0 auto;padding:14px 22px;display:flex;align-items:center;gap:26px}
      .brand{display:flex;align-items:center;gap:11px;font-family:var(--head);font-weight:800;font-size:19px}
      .brand img{height:34px;width:auto}
      .nav-links{display:flex;gap:22px;margin-left:auto;font-size:14px;font-weight:600;color:var(--muted)}
      .nav-links a:hover{color:var(--ink)}
      @media(max-width:760px){.nav-links{display:none}}
      nav .btn{margin-left:auto;padding:10px 20px;font-size:14px}
      @media(min-width:761px){nav .btn{margin-left:0}}

      .hero{padding:86px 0 70px;background:linear-gradient(180deg,var(--bg2),var(--bg));text-align:center}
      .hero h1{font-size:clamp(34px,6vw,58px);font-weight:800;max-width:760px;margin:0 auto 18px}
      .hero p{font-size:clamp(15px,2.2vw,18px);color:var(--muted);max-width:620px;margin:0 auto 30px}
      .hero .acts{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
      .hero-strip{display:flex;gap:14px;justify-content:center;margin-top:52px;flex-wrap:wrap}
      .hero-strip img,.hero-strip .ph{width:220px;height:150px;object-fit:cover;border-radius:var(--radius);box-shadow:0 16px 40px rgba(0,0,0,.12)}
      .hero-strip .ph{background:linear-gradient(135deg,var(--p),var(--acc));opacity:.85}
      .hero-strip>*:nth-child(2){transform:translateY(16px)}

      section{padding:72px 0}
      .sec-tag{display:inline-block;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--acc);margin-bottom:12px}
      h2{font-size:clamp(26px,4vw,38px);font-weight:800;margin-bottom:14px}
      .about{background:var(--bg)}
      .about .cols{display:grid;grid-template-columns:1.1fr .9fr;gap:46px;align-items:center}
      @media(max-width:820px){.about .cols{grid-template-columns:1fr}}
      .about p{color:var(--muted);font-size:16px}
      .about .img,.about img{border-radius:var(--radius);width:100%;height:320px;object-fit:cover}
      .about .img{background:linear-gradient(135deg,var(--p),var(--acc))}

      .pricing{background:var(--bg2)}
      .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin-top:34px}
      .pcard{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);padding:26px;display:flex;flex-direction:column;transition:.18s}
      .pcard:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(0,0,0,.09)}
      .pcard h3{font-size:18px;margin-bottom:6px}
      .pcard .price{font-size:30px;font-weight:800;font-family:var(--head);margin:8px 0 2px}
      .pcard .per{font-size:12.5px;color:var(--muted);margin-bottom:16px}
      .pcard .meta{font-size:13.5px;color:var(--muted);margin-bottom:20px}
      .pcard .btn{margin-top:auto;justify-content:center}

      .hours-contact{display:grid;grid-template-columns:1fr 1fr;gap:40px}
      @media(max-width:760px){.hours-contact{grid-template-columns:1fr}}
      .hrow{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px dashed var(--line);font-size:14.5px}
      .hrow .d{font-weight:700}
      .hrow .closed{color:var(--muted)}
      .c-item{display:flex;gap:12px;align-items:flex-start;margin-bottom:16px;font-size:15px}
      .c-item svg{color:var(--acc);flex-shrink:0;margin-top:3px}

      .faq{background:var(--bg2)}
      .qa{background:var(--bg);border:1px solid var(--line);border-radius:14px;margin-bottom:11px;overflow:hidden}
      .qa summary{padding:17px 20px;font-weight:700;font-size:15px;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center}
      .qa summary::after{content:"+";font-size:20px;color:var(--acc);font-weight:400}
      .qa[open] summary::after{content:"–"}
      .qa p{padding:0 20px 17px;color:var(--muted);font-size:14.5px}

      .cta-band{background:var(--p);color:#fff;text-align:center;border-radius:var(--radius);padding:56px 30px}
      .cta-band h2{color:#fff}
      .cta-band .btn{background:#fff;color:var(--p);margin-top:16px}
      .cta-band .btn:hover{background:var(--bg2)}

      footer{border-top:1px solid var(--line);padding:36px 0;font-size:13.5px;color:var(--muted)}
      .foot{display:flex;gap:18px;flex-wrap:wrap;align-items:center;justify-content:space-between}
      .foot .links{display:flex;gap:16px;flex-wrap:wrap}
      .foot a:hover{color:var(--ink)}
      .socials{display:flex;gap:12px}
      .socials a{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--line);border-radius:50%}
      .socials a:hover{background:var(--bg2)}

      #notReady{display:none;min-height:70vh;place-items:center;text-align:center;padding:40px}
      #notReady .in{max-width:420px}
      #notReady h1{font-size:28px;margin-bottom:10px}
      #notReady p{color:var(--muted)}
      main{display:none}
      body.ready main{display:block}
      body.nosite #notReady{display:grid}
    </style>
  </head>
  <body>
    <!-- Shown when the studio hasn't generated its website yet -->
    <div id="notReady"><div class="in">
      <h1>✨ Coming soon</h1>
      <p>This studio's website hasn't been published yet. You can still <a href="/booking" style="text-decoration:underline">book a class</a>.</p>
    </div></div>

    <main>
      <nav>
        <div class="nav-in">
