            '<div class="panel"><h6>Pay</h6>' + rows([['#f97316','💳','Card · Stripe','g','1-click'],['#0ea5e9','📱','Terminal','n','Tap'],['#16a34a','💵','Cash','n','Drawer']]) + '</div></div>' },
          { t: 'Finance', b:
