            '<div class="panel"><h6>Class popularity</h6><div class="pos-line"><span>Group Reformer</span><span>96%</span></div><div class="mbar"><i style="width:96%"></i></div><div class="pos-line"><span>Mat Pilates</span><span>84%</span></div><div class="mbar"><i style="width:84%"></i></div><div class="pos-line"><span>Yoga Flow</span><span>71%</span></div><div class="mbar"><i style="width:71%"></i></div></div></div>' },
          { t: 'Staff Portal', b:
            '<h5>Jane D. — Instructor <span>This week</span></h5>' +
            '<div class="kpis">' + kpi('Classes', '12') + kpi('Attendance', '94%') + kpi('Commission', '$640') + kpi('Rating', '4.9★') + '</div>' +
            '<div class="panel"><h6>My schedule</h6>' + rows([['#f97316','Tu','07:00 Group Reformer','g','8/8'],['#8b5cf6','We','09:30 Mat Pilates','n','9/12'],['#0ea5e9','Fr','12:00 Private — Anna','g','1/1']]) + '</div>' },
        ];
        var tabs = document.getElementById('tabs'), slider = document.getElementById('slider');
        SCREENS.forEach(function (s, i) {
          var b = document.createElement('button');
          b.className = 'tab' + (i === 0 ? ' on' : ''); b.textContent = s.t;
          b.addEventListener('click', function () {
            document.querySelectorAll('.tab').forEach(function (x) { x.classList.toggle('on', x === b); });
            slider.style.transform = 'translateX(-' + (i * 100) + '%)';
            document.getElementById('scrTitle').textContent = 'studionexis — ' + s.t.toLowerCase();
          });
          tabs.appendChild(b);
          var d = document.createElement('div'); d.className = 'slide'; d.innerHTML = s.b;
          slider.appendChild(d);
        });
      })();
    </script>
  </body>
