---
// Studio Nexis — SaaS marketing landing page (apex / control-plane host).
// Premium B2B SaaS look: orange brand, warm neutrals, CSS-drawn product
// mockups (no stock photos). Tenant subdomains with a published studio
// website are redirected to /site by the inline script in <head>.
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Studio Nexis — The operating system for pilates & yoga studios</title>
    <meta name="description" content="Booking, CRM, POS, payments, memberships, staff, finance, analytics and marketing automation — everything your pilates or yoga studio needs in one modern platform." />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <meta property="og:type" content="website" />
    <meta property="og:title" content="Studio Nexis — Run your entire studio from one beautiful platform" />
    <meta property="og:description" content="The all-in-one operating system for modern pilates & yoga studios." />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet" />
    <script is:inline>
      // Tenant subdomains with a published studio website show their own site;
      // the apex (control-plane) host keeps this SaaS marketing page.
      (async function () {
        try {
          var r = await fetch('/api/settings/public');
          if (r.ok) {
            var j = await r.json();
            if (j && j.site && j.site.published) window.location.replace('/site');
          }
        } catch (e) {}
      })();
    </script>
    <style>
      :root{
        --or:#F97316;--or2:#fb923c;--or3:#fdba74;--or-bg:#fff7ed;
        --ink:#1c1917;--ink2:#44403c;--muted:#78716c;--line:#e7e5e4;--line2:#efedeb;
        --bg:#fffdfb;--warm:#faf6f0;--card:#ffffff;
        --r:20px;--r-sm:14px;
        --sh:0 1px 2px rgba(28,25,23,.05),0 8px 28px rgba(28,25,23,.07);
        --sh-lg:0 2px 6px rgba(28,25,23,.06),0 24px 60px rgba(28,25,23,.13);
      }
      *{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.6;overflow-x:hidden}
      h1,h2,h3,.disp{font-family:'Manrope',sans-serif;letter-spacing:-.025em;line-height:1.12}
      a{text-decoration:none;color:inherit}
      .wrap{max-width:1160px;margin:0 auto;padding:0 24px}
      section{position:relative}

      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;padding:13px 26px;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:.18s;font-family:'Inter'}
      .btn-primary{background:linear-gradient(135deg,var(--or),#ea580c);color:#fff;box-shadow:0 6px 20px rgba(249,115,22,.32),inset 0 1px 0 rgba(255,255,255,.24)}
      .btn-primary:hover{transform:translateY(-1px);box-shadow:0 10px 28px rgba(249,115,22,.4),inset 0 1px 0 rgba(255,255,255,.24)}
      .btn-ghost{border-color:var(--line);color:var(--ink);background:#fff}
      .btn-ghost:hover{background:var(--warm)}
      .btn-lg{font-size:16px;padding:15px 32px;border-radius:14px}

      .tag{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--or);background:var(--or-bg);border:1px solid #ffedd5;border-radius:99px;padding:7px 15px;margin-bottom:18px}
      .h2{font-size:clamp(30px,4.4vw,44px);font-weight:800;margin-bottom:16px}
      .sub{font-size:17px;color:var(--muted);max-width:640px}
      .center{text-align:center}.center .sub{margin:0 auto}

      /* reveal on scroll */
      .rv{opacity:0;transform:translateY(22px);transition:opacity .7s cubic-bezier(.22,1,.36,1),transform .7s cubic-bezier(.22,1,.36,1)}
      .rv.in{opacity:1;transform:none}

      /* ───────── nav ───────── */
      nav{position:sticky;top:0;z-index:50;background:rgba(255,253,251,.82);backdrop-filter:blur(14px);border-bottom:1px solid var(--line2)}
      .nav-in{max-width:1160px;margin:0 auto;padding:15px 24px;display:flex;align-items:center;gap:30px}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:19px}
      .logo-mark{width:32px;height:32px;border-radius:10px;background:linear-gradient(135deg,var(--or),#ea580c);display:grid;place-items:center;color:#fff;font-weight:800;box-shadow:0 4px 12px rgba(249,115,22,.35)}
      .nav-links{display:flex;gap:26px;font-size:14px;font-weight:600;color:var(--muted)}
      .nav-links a{transition:.15s}
      .nav-links a:hover{color:var(--ink)}
      .nav-cta{margin-left:auto;display:flex;gap:10px;align-items:center}
      .nav-cta .login{font-size:14px;font-weight:600;color:var(--muted);margin-right:6px}
      .nav-cta .login:hover{color:var(--ink)}
      .nav-cta .btn{padding:10px 20px;font-size:14px}
      @media(max-width:860px){.nav-links{display:none}}

      /* ───────── hero ───────── */
      .hero{padding:84px 0 40px;overflow:hidden}
      .hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:54px;align-items:center}
      @media(max-width:980px){.hero-grid{grid-template-columns:1fr}}
      .hero h1{font-size:clamp(38px,5.4vw,62px);font-weight:800;margin-bottom:22px}
      .hero h1 em{font-style:normal;background:linear-gradient(120deg,var(--or),#ea580c);-webkit-background-clip:text;background-clip:text;color:transparent}
      .hero .sub{margin-bottom:32px}
      .hero-acts{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:26px}
      .hero-note{font-size:13px;color:var(--muted);display:flex;gap:18px;flex-wrap:wrap}
      .hero-note span{display:inline-flex;align-items:center;gap:6px}
      .hero-note svg{color:#16a34a}
      .blob{position:absolute;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0}
      .blob.b1{width:520px;height:520px;background:rgba(249,115,22,.14);top:-160px;right:-120px}
      .blob.b2{width:420px;height:420px;background:rgba(253,186,116,.18);bottom:-180px;left:-140px}

      /* dashboard mockup */
      .stage{position:relative;z-index:1}
      .dash{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-lg);overflow:hidden;transform:rotate(.6deg);animation:floaty 7s ease-in-out infinite}
      @keyframes floaty{0%,100%{transform:rotate(.6deg) translateY(0)}50%{transform:rotate(.6deg) translateY(-9px)}}
      .dash-top{display:flex;align-items:center;gap:7px;padding:11px 15px;border-bottom:1px solid var(--line2);background:#fdfbf8}
      .dash-top i{width:10px;height:10px;border-radius:50%;background:var(--line);display:block}
      .dash-top i:first-child{background:#fca5a5}.dash-top i:nth-child(2){background:#fcd34d}.dash-top i:nth-child(3){background:#86efac}
      .dash-top span{font-size:11px;color:var(--muted);margin-left:8px;font-weight:600}
      .dash-body{display:grid;grid-template-columns:1.25fr 1fr;gap:12px;padding:15px}
      .panel{border:1px solid var(--line2);border-radius:var(--r-sm);padding:13px;background:#fff}
      .panel h6{font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:9px}
      .rev-chart{display:flex;align-items:flex-end;gap:5px;height:74px}
      .rev-chart i{flex:1;border-radius:5px 5px 2px 2px;background:linear-gradient(180deg,var(--or2),var(--or));display:block;animation:grow 1.2s cubic-bezier(.22,1,.36,1) both}
      .rev-chart i:nth-child(odd){background:#ffe4cc}
      @keyframes grow{from{height:8%}}
      .cls-row{display:flex;align-items:center;gap:9px;padding:6.5px 0;border-bottom:1px dashed var(--line2);font-size:11.5px}
      .cls-row:last-child{border-bottom:none}
      .cls-dot{width:7px;height:7px;border-radius:50%;background:var(--or);flex-shrink:0}
      .cls-row b{font-weight:700}
      .cls-row .cap{margin-left:auto;font-size:10px;color:var(--muted);background:var(--warm);border-radius:6px;padding:2px 7px;font-weight:600}
      .occ{display:flex;align-items:center;gap:12px}
      .ring{width:62px;height:62px;border-radius:50%;background:conic-gradient(var(--or) 0 87%,#f3ece3 87% 100%);display:grid;place-items:center;flex-shrink:0}
      .ring i{width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center;font-size:12px;font-weight:800;font-style:normal}
      .occ p{font-size:11px;color:var(--muted);line-height:1.45}
      .mini-cal{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
      .mini-cal i{aspect-ratio:1;border-radius:6px;background:var(--warm);display:block}
      .mini-cal i.hot{background:var(--or3)}.mini-cal i.hot2{background:var(--or)}
      /* floating chips */
      .chip-f{position:absolute;display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.86);backdrop-filter:blur(10px);border:1px solid rgba(231,229,228,.9);border-radius:14px;padding:10px 15px;font-size:12.5px;font-weight:700;box-shadow:var(--sh);z-index:2;animation:floaty2 6s ease-in-out infinite}
      @keyframes floaty2{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
      .chip-f .ci{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;flex-shrink:0}
      .chip-f small{display:block;font-size:10px;color:var(--muted);font-weight:600}
      .cf1{top:-18px;left:-34px;animation-delay:.4s}
      .cf2{top:32%;right:-34px;animation-delay:1.3s}
      .cf3{bottom:-16px;left:8%;animation-delay:2.1s}
      .cf4{bottom:26%;left:-44px;animation-delay:2.8s}
      @media(max-width:1120px){.cf1{left:-8px}.cf2{right:-8px}.cf4{left:-10px}}
      @media(max-width:980px){.chip-f{display:none}}

      /* ───────── trusted by ───────── */
      .trust{padding:56px 0 30px;text-align:center}
      .trust .logos{display:flex;gap:14px 40px;justify-content:center;flex-wrap:wrap;align-items:center;margin-bottom:18px}
      .tlogo{font-family:'Manrope';font-weight:800;font-size:16.5px;color:#b8b1a9;display:flex;align-items:center;gap:8px;transition:.2s}
      .tlogo:hover{color:var(--ink2)}
      .tlogo i{width:22px;height:22px;border-radius:7px;background:currentColor;opacity:.35;display:block;font-style:normal}
      .tlogo.rnd i{border-radius:50%}
      .trust p{font-size:14px;color:var(--muted);font-weight:600}

      /* ───────── features bento ───────── */
      .features{padding:86px 0}
      .bento{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin-top:46px}
      .bcard{grid-column:span 2;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:26px;box-shadow:0 1px 2px rgba(28,25,23,.04);transition:.22s;display:flex;flex-direction:column;overflow:hidden}
      .bcard:hover{transform:translateY(-4px);box-shadow:var(--sh-lg);border-color:#f0d9c4}
      .bcard.w3{grid-column:span 3}
      @media(max-width:960px){.bcard,.bcard.w3{grid-column:span 3}}
      @media(max-width:640px){.bcard,.bcard.w3{grid-column:span 6}}
      .bic{width:42px;height:42px;border-radius:13px;background:var(--or-bg);color:var(--or);display:grid;place-items:center;margin-bottom:16px}
      .bcard h3{font-size:18px;font-weight:800;margin-bottom:7px}
      .bcard>p{font-size:13.8px;color:var(--muted);margin-bottom:16px}
      .bmock{margin-top:auto;border:1px solid var(--line2);border-radius:var(--r-sm);background:#fdfbf8;padding:12px;font-size:11px}
      /* mock primitives */
      .mrow{display:flex;align-items:center;gap:8px;padding:5.5px 0;border-bottom:1px dashed var(--line2);font-size:11px}
      .mrow:last-child{border-bottom:none}
      .mava{width:20px;height:20px;border-radius:50%;color:#fff;display:grid;place-items:center;font-size:9px;font-weight:800;flex-shrink:0;font-style:normal}
      .mtag{margin-left:auto;font-size:9.5px;font-weight:700;border-radius:6px;padding:2px 7px}
      .mtag.g{background:#dcfce7;color:#15803d}.mtag.o{background:var(--or-bg);color:var(--or)}.mtag.n{background:var(--warm);color:var(--muted)}
      .mbar{height:7px;border-radius:4px;background:var(--warm);overflow:hidden;margin:7px 0}
      .mbar i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,var(--or2),var(--or))}
      .spark{display:flex;align-items:flex-end;gap:3px;height:44px;margin-top:6px}
      .spark i{flex:1;border-radius:3px;background:#ffe4cc;display:block}
      .spark i.hi{background:var(--or)}
      .cal7{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
      .cal7 b{font-size:8.5px;color:var(--muted);text-align:center;font-weight:700}
      .cal7 i{height:22px;border-radius:5px;background:#fff;border:1px solid var(--line2);display:block}
      .cal7 i.ev{background:var(--or3);border-color:var(--or3)}
      .cal7 i.ev2{background:var(--or);border-color:var(--or)}
      .pos-line{display:flex;justify-content:space-between;font-size:11px;padding:5px 0;border-bottom:1px dashed var(--line2)}
      .pos-line:last-child{border-bottom:none;font-weight:800}
      .feat-list{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
      .feat-list span{font-size:11px;font-weight:600;color:var(--ink2);background:var(--warm);border:1px solid var(--line2);border-radius:99px;padding:4px 10px}

      /* ───────── showcase ───────── */
      .showcase{padding:86px 0;background:linear-gradient(180deg,var(--bg),var(--warm) 30%,var(--bg))}
      .tabs{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:36px 0 30px}
      .tab{border:1px solid var(--line);background:#fff;border-radius:99px;padding:9px 19px;font-size:13.5px;font-weight:700;cursor:pointer;color:var(--muted);transition:.16s;font-family:'Inter'}
      .tab:hover{color:var(--ink)}
      .tab.on{background:var(--ink);color:#fff;border-color:var(--ink)}
      .laptop{max-width:880px;margin:0 auto;position:relative}
      .screen{background:#fff;border:1px solid var(--line);border-radius:18px 18px 0 0;box-shadow:var(--sh-lg);overflow:hidden}
      .screen .dash-top{background:#faf7f2}
      .slider{display:flex;transition:transform .55s cubic-bezier(.22,1,.36,1)}
      .slide{min-width:100%;padding:18px;min-height:330px}
      .laptop .base{height:16px;background:linear-gradient(180deg,#e9e4dd,#d9d2c8);border-radius:0 0 16px 16px;box-shadow:0 12px 30px rgba(28,25,23,.16)}
      .slide h5{font-size:13px;font-weight:800;margin-bottom:12px;display:flex;align-items:center;justify-content:space-between}
      .slide h5 span{font-size:10.5px;color:var(--muted);font-weight:600}
      .kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}
      @media(max-width:640px){.kpis{grid-template-columns:repeat(2,1fr)}}
      .kpi{border:1px solid var(--line2);border-radius:12px;padding:11px;background:#fdfbf8}
      .kpi small{font-size:9.5px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:3px}
      .kpi b{font-size:17px;font-weight:800}
      .kpi em{font-style:normal;font-size:10px;font-weight:700;color:#16a34a;margin-left:5px}
      .two{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}
      @media(max-width:640px){.two{grid-template-columns:1fr}}

      /* ───────── why ───────── */
      .why{padding:86px 0}
      .why-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:44px}
      @media(max-width:960px){.why-grid{grid-template-columns:repeat(2,1fr)}}
      @media(max-width:560px){.why-grid{grid-template-columns:1fr}}
      .wcard{border:1px solid var(--line);border-radius:var(--r);padding:24px;background:#fff;transition:.2s}
      .wcard:hover{transform:translateY(-3px);box-shadow:var(--sh)}
      .wcard .bic{margin-bottom:14px}
      .wcard h4{font-size:15.5px;font-weight:800;margin-bottom:6px;font-family:'Manrope'}
      .wcard p{font-size:13px;color:var(--muted)}

      /* ───────── automation (dark) ───────── */
      .auto{background:radial-gradient(900px 500px at 70% 0%,#33281f,#1c1917 60%);color:#fff;padding:96px 0;overflow:hidden}
