  'kpi-bonus': 'Reception team',
  staff: 'Team management',
  partners: 'Referrals',
  promotions: 'Promotions',
  owners: 'Ownership',
  'audit-log': 'Audit history',
  settings: 'System settings',
};
const pageGroup = pageGroups[activePage] ?? 'Workspace';
