      color: #fff !important;
    }
    .flatpickr-day.inRange {
      background: rgba(201,123,75,.18) !important;
      border-color: transparent !important;
    }
    .flatpickr-day.flatpickr-disabled, .flatpickr-day.flatpickr-disabled:hover {
      color: var(--color-text-muted, #b3a89a) !important; opacity: .4;
    }
    .flatpickr-prev-month svg, .flatpickr-next-month svg { fill: var(--color-text-muted, #b3a89a) !important; }
