    .flatpickr-time input:focus, .flatpickr-time .flatpickr-am-pm:focus { background: rgba(255,255,255,.06) !important; }
    /* Wrap the native input so Flatpickr doesn't disturb layout */
    .flatpickr-input { cursor: pointer !important; }
