@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

/* ═══════════════════════════════════════════════════════════════════
   Soul Pilates · Admin Dashboard
   ───────────────────────────────────────────────────────────────────
   Design language: warm copper accents on cream surfaces (light) or
   warm-charcoal surfaces (dark). Inter throughout.
   Tokens are split between a base palette and a [data-theme="dark"]
   override so the entire app gracefully switches on a single attr.
   ═══════════════════════════════════════════════════════════════════ */

/* ─── Base (Warm Light) Tokens ──────────────────────────────────── */
:root {
  /* Brand — constant across modes */
  --color-brand-primary: #1f1813;
  --color-brand-accent: #F97316;
  --color-brand-accent-hover: #EA680C;
  --color-brand-accent-light: #FDBA74;
  --color-brand-accent-deep: #C2560B;
  --color-brand-accent-soft: rgba(249, 115, 22, 0.10);
  --color-brand-accent-glow: rgba(249, 115, 22, 0.18);
  --color-brand-accent-strong: rgba(249, 115, 22, 0.28);

  /* Premium gradients (orange-led, matching the brand) */
  --gradient-brand: linear-gradient(135deg, #FB923C 0%, #F97316 55%, #EA680C 100%);
  --gradient-brand-soft: linear-gradient(135deg, rgba(251,146,60,0.16), rgba(249,115,22,0.05));
  --gradient-sunset: linear-gradient(135deg, #F97316 0%, #F43F5E 100%);
  --gradient-ember: linear-gradient(135deg, #FB923C 0%, #DC2626 100%);
  --gradient-sheen: linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0) 42%);

  /* Surface — soft off-white, layered */
  --color-bg: #F6F5F2;
  --color-surface: #FFFFFF;
  --color-surface-raised: #FBFAF8;
  --color-surface-sunken: #EFEDE8;
  --color-border: rgba(23, 20, 17, 0.09);
  --color-border-subtle: rgba(23, 20, 17, 0.055);
  --color-border-strong: rgba(23, 20, 17, 0.16);

  /* Sidebar — light, layered (premium light mode) */
  --color-sidebar-bg: #FFFFFF;
  --color-sidebar-text: #5C544C;
  --color-sidebar-text-active: #17110d;
  --color-sidebar-item-active: rgba(249, 115, 22, 0.12);
  --color-sidebar-item-hover: rgba(23, 20, 17, 0.04);
  --color-sidebar-border: rgba(23, 20, 17, 0.07);

  /* Text */
  --color-text-primary: #17140F;
  --color-text-secondary: #5C544C;
  --color-text-muted: #8C8379;
  --color-text-inverse: #FFFFFF;

  /* Status — warm palette aligned with customer */
  --color-success: #3D8C5C;
  --color-success-soft: rgba(61, 140, 92, 0.10);
  --color-warning: #D4930D;
  --color-warning-soft: rgba(212, 147, 13, 0.10);
  --color-danger: #C44B4B;
  --color-danger-soft: rgba(196, 75, 75, 0.10);
  --color-info: #5C5C5C;
  --color-info-soft: rgba(92, 92, 92, 0.08);

  /* Level palette (mirrors customer) */
  --color-level-beginner: #6B7B3A;
  --color-level-beginner-soft: rgba(107, 123, 58, 0.10);
  --color-level-intermediate: #C97B4B;
  --color-level-intermediate-soft: rgba(201, 123, 75, 0.10);
  --color-level-advanced: #C44B4B;
  --color-level-advanced-soft: rgba(196, 75, 75, 0.10);
  --color-level-all: #5C5C5C;
  --color-level-all-soft: rgba(92, 92, 92, 0.08);

  /* Spacing (mirrors customer) */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 20px;
  --space-2xl: 24px;
