// ── SSO handoff from the signup flow ──────────────────────────────
// Signup happens on the apex host (different origin), which can't write
// this subdomain's localStorage. It passes the freshly-issued token in
// the URL fragment (never sent to the server); we store it, scrub the
// URL, and drop the new owner straight into their dashboard — where the
// first-run redirect takes them to the onboarding wizard.
(function () {
  const m = window.location.hash.match(/[#&]sso=([^&]+)/);
  if (!m) return;
  try {
    localStorage.setItem("token", decodeURIComponent(m[1]));
    history.replaceState(null, "", window.location.pathname);
    window.location.href = "/admin";
  } catch (e) { /* storage blocked — fall through to the manual form */ }
})();

// Wire submit handler — required because Astro bundles this <script> as
// an ES module, so `doLogin` is module-scoped and not accessible from an
// inline `onsubmit=` attribute on the form.
document.getElementById("loginForm").addEventListener("submit", doLogin);

