input.content:
---
// Studio Nexis — tenant public website ("AI Website Builder" output).
// A shared, design-system shell that renders each studio's generated content
// (branding, copy, photos, FAQs, hours) from GET /api/settings/public.
// Template modeled on the original Soul Pilates studio site (soulpilates.com.vn):
// full-bleed photo hero, editorial Fraunces headings, "Why / Story / Group or
// Private / Pricing / Gallery / Visit / FAQ / Let's Talk" flow. Only content
// and the color preset vary per studio — structure stays shared so every site
// remains fast, consistent and upgradeable.
const API = import.meta.env.PUBLIC_API_URL;
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title id="seoTitle">Welcome</title>
    <meta name="description" content="" id="seoDesc" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Fraunces:ital,opsz,wght@0,9..144,300..700;1,9..144,300..700&display=swap" rel="stylesheet" />
    {/* is:global — nearly all content below is injected at runtime from the
        studio's saved site data; Astro-scoped styles never match JS-created
        elements, so this stylesheet must be global. */}
    <style is:global>
      /* Shared design system — presets only swap the variables below. */
      :root{--p:#1c1917;--p2:#44403c;--acc:#b49a67;--acc-soft:rgba(180,154,103,.14);--bg:#fffdfa;--bg2:#f6f1e9;--ink:#1c1917;--muted:#6f675c;--line:#e8e1d5;--head:'Fraunces',serif}
      [data-preset="modern-minimal"]{--p:#111827;--p2:#374151;--acc:#6b7280;--acc-soft:rgba(107,114,128,.12);--bg:#ffffff;--bg2:#f3f4f6;--ink:#111827;--muted:#6b7280;--line:#e5e7eb}
      [data-preset="luxury-wellness"]{--p:#3b2f4d;--p2:#584a70;--acc:#b49a67;--acc-soft:rgba(180,154,103,.16);--bg:#fffdf9;--bg2:#f4efe8;--ink:#2c2438;--muted:#7d7389;--line:#e8e1d5}
      [data-preset="earthy-organic"]{--p:#5f6c3a;--p2:#77874a;--acc:#a9825c;--acc-soft:rgba(169,130,92,.14);--bg:#fffdf8;--bg2:#f3ede2;--ink:#37402a;--muted:#7d8468;--line:#e6dfd0}
      [data-preset="bright-energetic"]{--p:#e0455b;--p2:#c22b41;--acc:#f59e0b;--acc-soft:rgba(245,158,11,.14);--bg:#ffffff;--bg2:#fdf2f4;--ink:#231015;--muted:#8a6b72;--line:#f4dade}
      [data-preset="boutique-premium"]{--p:#1f1b2e;--p2:#3a3355;--acc:#8b5cf6;--acc-soft:rgba(139,92,246,.13);--bg:#ffffff;--bg2:#f5f3ff;--ink:#1f1b2e;--muted:#6f6a85;--line:#e7e3f4}
      [data-preset="coastal-relaxed"]{--p:#2a637e;--p2:#3d7f9e;--acc:#62b6cb;--acc-soft:rgba(98,182,203,.16);--bg:#fdfefe;--bg2:#eef6f8;--ink:#1d3c4a;--muted:#64808d;--line:#d9e8ec}

      *{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.65;font-size:16px}
      h1,h2,h3,.serif{font-family:var(--head);font-weight:500;letter-spacing:-.01em;line-height:1.12}
      a{text-decoration:none;color:inherit}
      img{max-width:100%;display:block}
      .wrap{max-width:1100px;margin:0 auto;padding:0 22px}
      section{padding:84px 0}
      .kicker{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--acc);margin-bottom:14px}
      h2{font-size:clamp(30px,4.6vw,44px);margin-bottom:16px}
      .lede{color:var(--muted);font-size:16.5px;max-width:640px}
      .btn{display:inline-flex;align-items:center;gap:9px;background:var(--p);color:#fff;font-weight:600;font-size:14.5px;letter-spacing:.04em;padding:15px 32px;border-radius:999px;transition:.2s;border:none;cursor:pointer}
      .btn:hover{background:var(--p2);transform:translateY(-1px)}
      .btn.light{background:#fff;color:var(--ink)}
      .btn.light:hover{background:var(--bg2)}
      .btn.ghost{background:transparent;border:1.5px solid rgba(255,255,255,.55);color:#fff}
      .btn.ghost:hover{background:rgba(255,255,255,.12);transform:none}
      .btn.ghost.dark{border-color:var(--line);color:var(--ink)}
      .btn.ghost.dark:hover{background:var(--bg2)}

      /* ── nav ── */
      nav{position:sticky;top:0;z-index:40;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
      .nav-in{max-width:1100px;margin:0 auto;padding:13px 22px;display:flex;align-items:center;gap:24px}
      .brand{display:flex;align-items:center;gap:11px;min-width:0}
      .brand img{height:36px;width:auto;max-width:120px;object-fit:contain;flex-shrink:0}
      .brand .bname{font-family:var(--head);font-weight:600;font-size:19px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
      .nav-links{display:flex;gap:22px;margin-left:auto;font-size:13.5px;font-weight:600;color:var(--muted)}
      .nav-links a:hover{color:var(--ink)}
      @media(max-width:820px){.nav-links{display:none}}
      nav .btn{padding:10px 22px;font-size:13px;margin-left:auto}
      @media(min-width:821px){nav .btn{margin-left:0}}

      /* ── hero (full-bleed photo, à la soulpilates) ── */
      .hero{position:relative;min-height:86vh;display:flex;align-items:center;color:#fff;padding:0;overflow:hidden}
      .hero-bg{position:absolute;inset:0;background-size:cover;background-position:center;transform:scale(1.04)}
      .hero::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(12,10,8,.35),rgba(12,10,8,.62) 75%)}
      .hero-in{position:relative;z-index:2;max-width:1100px;margin:0 auto;padding:130px 22px 110px;width:100%}
      .hero .loc{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.85);margin-bottom:22px}
      .hero .loc::before{content:"";width:26px;height:1px;background:var(--acc)}
      .hero h1{font-size:clamp(42px,7.5vw,84px);font-weight:400;max-width:820px;margin-bottom:22px}
      .hero h1 em{font-style:italic;color:var(--acc);filter:brightness(1.35)}
      .hero p{font-size:clamp(15.5px,2vw,18.5px);color:rgba(255,255,255,.88);max-width:560px;margin-bottom:36px}
      .hero .acts{display:flex;gap:13px;flex-wrap:wrap}
      .hero .btn{background:#fff;color:var(--ink)}
      .hero .btn:hover{background:var(--bg2)}

      /* ── why cards ── */
      .why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:44px}
      @media(max-width:820px){.why-grid{grid-template-columns:1fr}}
      .why-card{background:var(--bg);border:1px solid var(--line);border-radius:20px;padding:32px 28px;transition:.2s}
      .why-card:hover{transform:translateY(-4px);box-shadow:0 20px 44px rgba(0,0,0,.08)}
      .why-card .num{font-family:var(--head);font-style:italic;font-size:15px;color:var(--acc);display:block;margin-bottom:14px}
      .why-card h3{font-size:21px;margin-bottom:10px}
      .why-card p{font-size:14.5px;color:var(--muted)}

      /* ── story ── */
      .story{background:var(--bg2)}
      .story .cols{display:grid;grid-template-columns:1fr 1fr;gap:54px;align-items:center}
      @media(max-width:860px){.story .cols{grid-template-columns:1fr}}
      .story p{color:var(--muted);font-size:16px;margin-bottom:14px}
      .story img,.story .ph{width:100%;height:420px;object-fit:cover;border-radius:24px}
      .story .ph{background:linear-gradient(150deg,var(--p),var(--acc))}

      /* ── paths (group / private) ── */
      .paths{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:44px}
      @media(max-width:760px){.paths{grid-template-columns:1fr}}
      .path{position:relative;border-radius:24px;overflow:hidden;padding:44px 34px;color:#fff;min-height:330px;display:flex;flex-direction:column;justify-content:flex-end;background:var(--p)}
      .path.alt{background:var(--p2)}
      .path::before{content:"";position:absolute;inset:0;background:radial-gradient(480px 320px at 80% 0%,var(--acc-soft),transparent),linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.32))}
      .path>*{position:relative}
      .path .tagp{font-size:11.5px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--acc);filter:brightness(1.5);margin-bottom:10px}
      .path h3{font-size:30px;margin-bottom:10px}
      .path p{font-size:14.5px;color:rgba(255,255,255,.85);margin-bottom:22px;max-width:380px}
      .path .btn{align-self:flex-start;background:#fff;color:var(--ink);padding:12px 26px;font-size:13.5px}

      /* ── pricing ── */
      .pricing{background:var(--bg2)}
      .pcards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin-top:44px}
      .pcard{background:var(--bg);border:1px solid var(--line);border-radius:20px;padding:30px 26px;display:flex;flex-direction:column;transition:.2s}
      .pcard:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(0,0,0,.08)}
      .pcard.hot{border-color:var(--acc);box-shadow:0 0 0 3px var(--acc-soft)}
      .pcard .pn{font-size:17px;font-family:var(--head);margin-bottom:4px}
      .pcard .pp{font-family:var(--head);font-size:32px;margin:10px 0 2px}
      .pcard .pp small{font-size:13px;color:var(--muted);font-family:'Inter'}
      .pcard .pm{font-size:13px;color:var(--muted);margin-bottom:20px}
      .pcard .pd{font-size:13.5px;color:var(--muted);margin-bottom:18px}
      .pcard .btn{margin-top:auto;justify-content:center;padding:12px;font-size:13.5px}

      /* ── gallery ── */
      .gal{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:44px}
      @media(max-width:700px){.gal{grid-template-columns:repeat(2,1fr)}}
      .gal img{width:100%;height:250px;object-fit:cover;border-radius:16px;transition:.25s}
      .gal img:hover{transform:scale(1.025)}

      /* ── visit ── */
      .visit .cols{display:grid;grid-template-columns:1.05fr .95fr;gap:52px;align-items:start;margin-top:40px}
      @media(max-width:820px){.visit .cols{grid-template-columns:1fr}}
      .hrow{display:flex;justify-content:space-between;padding:10px 2px;border-bottom:1px dashed var(--line);font-size:14.5px}
      .hrow .d{font-weight:600}
      .hrow .closed{color:var(--muted)}
      .c-item{display:flex;gap:13px;align-items:flex-start;margin-bottom:18px;font-size:15px}
      .c-item svg{color:var(--acc);flex-shrink:0;margin-top:3px}
      .c-item a:hover{color:var(--acc)}
      .map-link{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:13.5px;color:var(--acc);margin-top:4px}
      .map-link:hover{text-decoration:underline}

      /* ── faq ── */
      .faq{background:var(--bg2)}
      .qa{background:var(--bg);border:1px solid var(--line);border-radius:16px;margin-bottom:11px;overflow:hidden}
      .qa summary{padding:19px 22px;font-weight:600;font-size:15px;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:14px}
      .qa summary::-webkit-details-marker{display:none}
      .qa summary::after{content:"+";font-family:var(--head);font-size:22px;color:var(--acc);flex-shrink:0;transition:.2s}
      .qa[open] summary::after{transform:rotate(45deg)}
      .qa p{padding:0 22px 19px;color:var(--muted);font-size:14.5px}

      /* ── let's talk / footer ── */
      .talk{background:var(--p);color:#fff;padding:90px 0 70px}
      .talk h2{color:#fff;font-size:clamp(34px,5.5vw,56px)}
      .talk h2 em{font-style:italic;color:var(--acc);filter:brightness(1.4)}
      .talk .lede{color:rgba(255,255,255,.8)}
      .talk .acts{display:flex;gap:13px;flex-wrap:wrap;margin-top:30px}
      .talk .contact-strip{display:flex;gap:26px;flex-wrap:wrap;margin-top:46px;padding-top:34px;border-top:1px solid rgba(255,255,255,.14);font-size:14px;color:rgba(255,255,255,.85)}
      .talk .contact-strip a{display:inline-flex;align-items:center;gap:9px}
      .talk .contact-strip a:hover{color:#fff}
      .talk .contact-strip svg{color:var(--acc);filter:brightness(1.4)}
      footer{border-top:1px solid var(--line);padding:30px 0;font-size:13px;color:var(--muted)}
      .foot{display:flex;gap:14px 22px;flex-wrap:wrap;align-items:center;justify-content:space-between}
      .foot .links{display:flex;gap:16px;flex-wrap:wrap}
      .foot a:hover{color:var(--ink)}

      /* not published fallback */
      #notReady{display:none;min-height:70vh;place-items:center;text-align:center;padding:40px}
      #notReady .in{max-width:420px}
      #notReady h1{font-size:30px;margin-bottom:10px}
      #notReady p{color:var(--muted)}
      #notReady a{text-decoration:underline}
      main{display:none}
      body.ready main{display:block}
      body.nosite #notReady{display:grid}
    </style>
  </head>
  <body>
    <div id="notReady"><div class="in">
      <h1>✨ Coming soon</h1>
      <p>This studio's website hasn't been published yet. You can still <a href="/booking">book a class</a>.</p>
    </div></div>

    <main>
      <nav>
        <div class="nav-in">
          <a class="brand" href="/site" id="brand"><span class="bname" id="brandName">Studio</span></a>
          <div class="nav-links">
            <a href="#about">About</a>
            <a href="/booking">Classes</a>
            <a href="#pricing">Pricing</a>
            <a href="/instructors">Team</a>
            <a href="#faq">FAQ</a>
            <a href="#visit">Visit</a>
          </div>
          <a class="btn" href="/booking" id="navCta">Book Now</a>
        </div>
      </nav>

      <!-- ═══ Hero ═══ -->
      <header class="hero">
        <div class="hero-bg" id="heroBg"></div>
        <div class="hero-in">
          <span class="loc" id="heroLoc">Pilates &amp; Yoga</span>
          <h1 id="heroH">Movement for <em>your</em> every day.</h1>
          <p id="heroSub"></p>
          <div class="acts">
            <a class="btn" href="/booking" id="heroCta">Book Now</a>
            <a class="btn ghost" href="#pricing">See pricing</a>
          </div>
        </div>
      </header>

      <!-- ═══ Why ═══ -->
      <section id="why">
        <div class="wrap">
          <span class="kicker">The method</span>
          <h2 id="whyH">Why pilates?</h2>
          <p class="lede">Strength, alignment and calm — built session by session.</p>
          <div class="why-grid">
            <div class="why-card"><span class="num">— 01</span><h3>Core strength &amp; tone</h3><p>Deep, functional strength that sculpts your body from the inside out. You'll stand taller and move with more power.</p></div>
            <div class="why-card"><span class="num">— 02</span><h3>Posture &amp; mobility</h3><p>Undo the desk, the phone, the commute. Precise, low-impact movement that restores alignment and eases stubborn tension.</p></div>
            <div class="why-card"><span class="num">— 03</span><h3>A clear head</h3><p>Breath-led focus that leaves you lighter than you arrived. Strength for your body, therapy for your mind.</p></div>
          </div>
        </div>
      </section>

      <!-- ═══ Story / About ═══ -->
      <section class="story" id="about">
        <div class="wrap cols">
          <div>
            <span class="kicker">Our studio</span>
            <h2 id="aboutH">About us</h2>
            <p id="aboutB"></p>
          </div>
          <div id="aboutImg" class="ph"></div>
        </div>
      </section>

      <!-- ═══ Group or Private ═══ -->
      <section id="paths">
        <div class="wrap">
          <span class="kicker">Choose your path</span>
          <h2>Group or private?</h2>
          <p class="lede">Both lead to transformation — pick what fits your goals and how you like to move.</p>
          <div class="paths">
            <div class="path">
              <div class="tagp">Together</div>
              <h3>Group classes</h3>
              <p>Energy, community and results — small classes where the instructor still knows your name and your goals.</p>
              <a class="btn" href="/booking">See the schedule</a>
            </div>
            <div class="path alt">
              <div class="tagp">Just you</div>
              <h3>Private sessions</h3>
              <p>One-on-one attention, a program built entirely around your body — the fastest way to progress.</p>
              <a class="btn" href="/booking">Book a private</a>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Pricing ═══ -->
      <section class="pricing" id="pricing">
        <div class="wrap">
          <span class="kicker">Pricing</span>
          <h2>Packages &amp; memberships</h2>
          <p class="lede">The more you commit, the more you save. Every pack works across our schedule.</p>
          <div class="pcards" id="priceCards"></div>
          <div style="text-align:center;margin-top:30px"><a class="btn ghost dark" href="/packages">View all packages →</a></div>
        </div>
      </section>

      <!-- ═══ Gallery (only if the studio uploaded photos) ═══ -->
      <section id="gallery" style="display:none">
        <div class="wrap">
          <span class="kicker">The studio</span>
          <h2>Real people. Real results.</h2>
          <div class="gal" id="galGrid"></div>
        </div>
      </section>

      <!-- ═══ Visit ═══ -->
      <section class="visit" id="visit">
        <div class="wrap">
          <span class="kicker">Come say hi</span>
          <h2 id="visitH">Visit our studio</h2>
          <div class="cols">
            <div id="contactCol"></div>
            <div id="hoursCol"></div>
          </div>
        </div>
      </section>

      <!-- ═══ FAQ ═══ -->
      <section class="faq" id="faq">
        <div class="wrap">
          <span class="kicker">Good to know</span>
          <h2>Frequently asked questions</h2>
          <div id="faqList" style="margin-top:34px"></div>
        </div>
      </section>

      <!-- ═══ Let's talk ═══ -->
      <div class="talk" id="contact">
        <div class="wrap">
          <span class="kicker">Let's talk</span>
          <h2 id="talkH">Ready when <em>you</em> are.</h2>
          <p class="lede" id="talkSub">Your first class is the hardest one to book — after that, it books itself.</p>
          <div class="acts">
            <a class="btn light" href="/booking" id="talkCta">Book Now</a>
            <a class="btn ghost" href="/packages">See packages</a>
          </div>
          <div class="contact-strip" id="talkContact"></div>
        </div>
      </div>

      <footer>
        <div class="wrap foot">
          <span id="footName">© Studio</span>
          <div class="links">
            <a href="/booking">Schedule</a>
            <a href="/packages">Pricing</a>
            <a href="/instructors">Team</a>
            <a href="/login">Member Login</a>
            <a href="/booking-policy">Booking Policy</a>
          </div>
        </div>
      </footer>
    </main>

    <script define:vars={{ API }}>
      (async function () {
        var A = API || '';
        function $(s) { return document.querySelector(s); }
        function esc(x) { var d = document.createElement('div'); d.textContent = x == null ? '' : String(x); return d.innerHTML; }

        var data;
        try { data = await (await fetch(A + '/api/settings/public')).json(); } catch (e) { data = null; }
        var p = (data && data.profile) || {};
        var site = (data && data.site) || {};

        if (!site.published) { document.body.classList.add('nosite'); return; }

        document.documentElement.dataset.preset = site.stylePreset || 'luxury-wellness';
        if (p.primaryColor) document.documentElement.style.setProperty('--p', p.primaryColor);
        if (p.secondaryColor) document.documentElement.style.setProperty('--acc', p.secondaryColor);

        var name = p.studioName || 'Our Studio';
        document.title = site.seoTitle || name;
        $('#seoDesc').setAttribute('content', site.seoDescription || '');
        $('#brandName').textContent = name;
        if (p.logoUrl) $('#brand').innerHTML = '<img src="' + esc(p.logoUrl) + '" alt="' + esc(name) + '" /><span class="bname">' + esc(name) + '</span>';

        // Hero — the studio's own photo, or the built-in default.
        var photos = site.photoUrls || [];
        $('#heroBg').style.backgroundImage = 'url(' + (photos[0] ? photos[0] : '/home/hero.jpg') + ')';
        $('#heroLoc').textContent = name + (p.city ? ' · ' + p.city : '');
        if (site.heroHeadline) {
          // Italicize the middle word for the editorial serif feel.
          var words = site.heroHeadline.split(' ');
          if (words.length >= 3) {
            var mid = Math.floor(words.length / 2);
            words[mid] = '<em>' + esc(words[mid]) + '</em>';
            $('#heroH').innerHTML = words.map(function (w, i) { return i === Math.floor(words.length / 2) ? w : esc(w); }).join(' ');
          } else { $('#heroH').textContent = site.heroHeadline; }
        }
        $('#heroSub').textContent = site.heroSub || '';
        if (site.ctaText) { $('#heroCta').textContent = site.ctaText; $('#navCta').textContent = 'Book Now'; $('#talkCta').textContent = site.ctaText; }

        $('#whyH').textContent = 'Why ' + name + '?';
        $('#aboutH').textContent = site.aboutHeadline || ('About ' + name);
        $('#aboutB').textContent = site.aboutBody || '';
        var aboutPhoto = photos[1] || photos[0] || '/home/hero2.jpg';
        $('#aboutImg').outerHTML = '<img src="' + esc(aboutPhoto) + '" alt="' + esc(name) + '" loading="lazy" />';

        // Pricing — live packages (top 4 by price, middle one highlighted).
        try {
          var pk = await (await fetch(A + '/api/products/packages')).json();
          var cur = p.currency || '';
          var top = (pk || []).slice(0, 4);
          $('#priceCards').innerHTML = top.map(function (x, i) {
            return '<div class="pcard' + (i === 1 ? ' hot' : '') + '"><div class="pn">' + esc(x.name) + '</div>' +
              '<div class="pp">' + Number(x.basePrice).toLocaleString() + (cur ? ' <small>' + esc(cur) + '</small>' : '') + '</div>' +
              '<div class="pm">' + x.credits + ' credits · valid ' + x.validityDays + ' days</div>' +
              (x.description ? '<div class="pd">' + esc(x.description) + '</div>' : '') +
              '<a class="btn" href="/packages">Choose</a></div>';
          }).join('') || '<p style="color:var(--muted)">Packages coming soon — <a href="/booking" style="text-decoration:underline">book a drop-in class</a>.</p>';
        } catch (e) {}

        // Gallery — only when the studio uploaded 3+ photos (beyond hero/about).
        if (photos.length >= 3) {
          $('#gallery').style.display = 'block';
          $('#galGrid').innerHTML = photos.slice(0, 6).map(function (u) {
            return '<img src="' + esc(u) + '" alt="' + esc(name) + '" loading="lazy" />';
          }).join('');
        }

        // Visit — contact + map + hours.
        var pin = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>';
        var tel = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg>';
        var mail = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>';
        var ig = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg>';
        var addr = [p.address, p.city, p.country].filter(Boolean).join(', ');
        var c = '';
        if (addr) {
          c += '<div class="c-item">' + pin + '<div>' + esc(addr) +
            '<br/><a class="map-link" href="https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(addr) + '" target="_blank" rel="noopener">Open in Google Maps →</a></div></div>';
        }
        if (p.phone) c += '<div class="c-item">' + tel + '<a href="tel:' + esc(p.phone) + '">' + esc(p.phone) + '</a></div>';
        if (p.businessEmail) c += '<div class="c-item">' + mail + '<a href="mailto:' + esc(p.businessEmail) + '">' + esc(p.businessEmail) + '</a></div>';
        $('#contactCol').innerHTML = c || '<p style="color:var(--muted)">Contact details coming soon.</p>';

        var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var hours = p.hours || [];
        // Show Mon-first, like a studio timetable reads.
        var ordered = hours.slice().sort(function (a, b) { return ((a.day + 6) % 7) - ((b.day + 6) % 7); });
        $('#hoursCol').innerHTML = ordered.length
          ? ordered.map(function (h) {
              return '<div class="hrow"><span class="d">' + DAYS[h.day] + '</span>' +
                (h.closed ? '<span class="closed">Closed</span>' : '<span>' + esc(h.open) + ' – ' + esc(h.close) + '</span>') + '</div>';
            }).join('')
          : '<p style="color:var(--muted)">Open daily — see the <a href="/booking" style="text-decoration:underline">live schedule</a>.</p>';

        // FAQ
        $('#faqList').innerHTML = (site.faqs || []).map(function (f) {
          return '<details class="qa"><summary>' + esc(f.question) + '</summary><p>' + esc(f.answer) + '</p></details>';
        }).join('');

        // Let's talk strip + footer
        var t = '';
        if (p.phone) t += '<a href="tel:' + esc(p.phone) + '">' + tel + esc(p.phone) + '</a>';
        if (p.businessEmail) t += '<a href="mailto:' + esc(p.businessEmail) + '">' + mail + esc(p.businessEmail) + '</a>';
        if (p.instagram) {
          var igh = p.instagram.replace(/^@/, '');
          t += '<a href="' + esc(igh.indexOf('http') === 0 ? igh : 'https://instagram.com/' + igh) + '" target="_blank" rel="noopener">' + ig + '@' + esc(igh.replace(/^https?:\/\/(www\.)?instagram\.com\//, '')) + '</a>';
        }
        $('#talkContact').innerHTML = t;
        $('#talkH').innerHTML = 'Ready to join <em>' + esc(name) + '</em>?';
        $('#footName').textContent = '© ' + new Date().getFullYear() + ' ' + name + ' · Powered by Studio Nexis';

        document.body.classList.add('ready');
      })();
    </script>
  </body>
</html>

toolUseResult.content:
---
// Studio Nexis — tenant public website ("AI Website Builder" output).
// A shared, design-system shell that renders each studio's generated content
// (branding, copy, photos, FAQs, hours) from GET /api/settings/public.
// Template modeled on the original Soul Pilates studio site (soulpilates.com.vn):
// full-bleed photo hero, editorial Fraunces headings, "Why / Story / Group or
// Private / Pricing / Gallery / Visit / FAQ / Let's Talk" flow. Only content
// and the color preset vary per studio — structure stays shared so every site
// remains fast, consistent and upgradeable.
const API = import.meta.env.PUBLIC_API_URL;
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title id="seoTitle">Welcome</title>
    <meta name="description" content="" id="seoDesc" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Fraunces:ital,opsz,wght@0,9..144,300..700;1,9..144,300..700&display=swap" rel="stylesheet" />
    {/* is:global — nearly all content below is injected at runtime from the
        studio's saved site data; Astro-scoped styles never match JS-created
        elements, so this stylesheet must be global. */}
    <style is:global>
      /* Shared design system — presets only swap the variables below. */
      :root{--p:#1c1917;--p2:#44403c;--acc:#b49a67;--acc-soft:rgba(180,154,103,.14);--bg:#fffdfa;--bg2:#f6f1e9;--ink:#1c1917;--muted:#6f675c;--line:#e8e1d5;--head:'Fraunces',serif}
      [data-preset="modern-minimal"]{--p:#111827;--p2:#374151;--acc:#6b7280;--acc-soft:rgba(107,114,128,.12);--bg:#ffffff;--bg2:#f3f4f6;--ink:#111827;--muted:#6b7280;--line:#e5e7eb}
      [data-preset="luxury-wellness"]{--p:#3b2f4d;--p2:#584a70;--acc:#b49a67;--acc-soft:rgba(180,154,103,.16);--bg:#fffdf9;--bg2:#f4efe8;--ink:#2c2438;--muted:#7d7389;--line:#e8e1d5}
      [data-preset="earthy-organic"]{--p:#5f6c3a;--p2:#77874a;--acc:#a9825c;--acc-soft:rgba(169,130,92,.14);--bg:#fffdf8;--bg2:#f3ede2;--ink:#37402a;--muted:#7d8468;--line:#e6dfd0}
      [data-preset="bright-energetic"]{--p:#e0455b;--p2:#c22b41;--acc:#f59e0b;--acc-soft:rgba(245,158,11,.14);--bg:#ffffff;--bg2:#fdf2f4;--ink:#231015;--muted:#8a6b72;--line:#f4dade}
      [data-preset="boutique-premium"]{--p:#1f1b2e;--p2:#3a3355;--acc:#8b5cf6;--acc-soft:rgba(139,92,246,.13);--bg:#ffffff;--bg2:#f5f3ff;--ink:#1f1b2e;--muted:#6f6a85;--line:#e7e3f4}
      [data-preset="coastal-relaxed"]{--p:#2a637e;--p2:#3d7f9e;--acc:#62b6cb;--acc-soft:rgba(98,182,203,.16);--bg:#fdfefe;--bg2:#eef6f8;--ink:#1d3c4a;--muted:#64808d;--line:#d9e8ec}

      *{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.65;font-size:16px}
      h1,h2,h3,.serif{font-family:var(--head);font-weight:500;letter-spacing:-.01em;line-height:1.12}
      a{text-decoration:none;color:inherit}
      img{max-width:100%;display:block}
      .wrap{max-width:1100px;margin:0 auto;padding:0 22px}
      section{padding:84px 0}
      .kicker{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--acc);margin-bottom:14px}
      h2{font-size:clamp(30px,4.6vw,44px);margin-bottom:16px}
      .lede{color:var(--muted);font-size:16.5px;max-width:640px}
      .btn{display:inline-flex;align-items:center;gap:9px;background:var(--p);color:#fff;font-weight:600;font-size:14.5px;letter-spacing:.04em;padding:15px 32px;border-radius:999px;transition:.2s;border:none;cursor:pointer}
      .btn:hover{background:var(--p2);transform:translateY(-1px)}
      .btn.light{background:#fff;color:var(--ink)}
      .btn.light:hover{background:var(--bg2)}
      .btn.ghost{background:transparent;border:1.5px solid rgba(255,255,255,.55);color:#fff}
      .btn.ghost:hover{background:rgba(255,255,255,.12);transform:none}
      .btn.ghost.dark{border-color:var(--line);color:var(--ink)}
      .btn.ghost.dark:hover{background:var(--bg2)}

      /* ── nav ── */
      nav{position:sticky;top:0;z-index:40;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
      .nav-in{max-width:1100px;margin:0 auto;padding:13px 22px;display:flex;align-items:center;gap:24px}
      .brand{display:flex;align-items:center;gap:11px;min-width:0}
      .brand img{height:36px;width:auto;max-width:120px;object-fit:contain;flex-shrink:0}
      .brand .bname{font-family:var(--head);font-weight:600;font-size:19px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
      .nav-links{display:flex;gap:22px;margin-left:auto;font-size:13.5px;font-weight:600;color:var(--muted)}
      .nav-links a:hover{color:var(--ink)}
      @media(max-width:820px){.nav-links{display:none}}
      nav .btn{padding:10px 22px;font-size:13px;margin-left:auto}
      @media(min-width:821px){nav .btn{margin-left:0}}

      /* ── hero (full-bleed photo, à la soulpilates) ── */
      .hero{position:relative;min-height:86vh;display:flex;align-items:center;color:#fff;padding:0;overflow:hidden}
      .hero-bg{position:absolute;inset:0;background-size:cover;background-position:center;transform:scale(1.04)}
      .hero::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(12,10,8,.35),rgba(12,10,8,.62) 75%)}
      .hero-in{position:relative;z-index:2;max-width:1100px;margin:0 auto;padding:130px 22px 110px;width:100%}
      .hero .loc{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.85);margin-bottom:22px}
      .hero .loc::before{content:"";width:26px;height:1px;background:var(--acc)}
      .hero h1{font-size:clamp(42px,7.5vw,84px);font-weight:400;max-width:820px;margin-bottom:22px}
      .hero h1 em{font-style:italic;color:var(--acc);filter:brightness(1.35)}
      .hero p{font-size:clamp(15.5px,2vw,18.5px);color:rgba(255,255,255,.88);max-width:560px;margin-bottom:36px}
      .hero .acts{display:flex;gap:13px;flex-wrap:wrap}
      .hero .btn{background:#fff;color:var(--ink)}
      .hero .btn:hover{background:var(--bg2)}

      /* ── why cards ── */
      .why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:44px}
      @media(max-width:820px){.why-grid{grid-template-columns:1fr}}
      .why-card{background:var(--bg);border:1px solid var(--line);border-radius:20px;padding:32px 28px;transition:.2s}
      .why-card:hover{transform:translateY(-4px);box-shadow:0 20px 44px rgba(0,0,0,.08)}
      .why-card .num{font-family:var(--head);font-style:italic;font-size:15px;color:var(--acc);display:block;margin-bottom:14px}
      .why-card h3{font-size:21px;margin-bottom:10px}
      .why-card p{font-size:14.5px;color:var(--muted)}

      /* ── story ── */
      .story{background:var(--bg2)}
      .story .cols{display:grid;grid-template-columns:1fr 1fr;gap:54px;align-items:center}
      @media(max-width:860px){.story .cols{grid-template-columns:1fr}}
      .story p{color:var(--muted);font-size:16px;margin-bottom:14px}
      .story img,.story .ph{width:100%;height:420px;object-fit:cover;border-radius:24px}
      .story .ph{background:linear-gradient(150deg,var(--p),var(--acc))}

      /* ── paths (group / private) ── */
      .paths{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:44px}
      @media(max-width:760px){.paths{grid-template-columns:1fr}}
      .path{position:relative;border-radius:24px;overflow:hidden;padding:44px 34px;color:#fff;min-height:330px;display:flex;flex-direction:column;justify-content:flex-end;background:var(--p)}
      .path.alt{background:var(--p2)}
      .path::before{content:"";position:absolute;inset:0;background:radial-gradient(480px 320px at 80% 0%,var(--acc-soft),transparent),linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.32))}
      .path>*{position:relative}
      .path .tagp{font-size:11.5px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--acc);filter:brightness(1.5);margin-bottom:10px}
      .path h3{font-size:30px;margin-bottom:10px}
      .path p{font-size:14.5px;color:rgba(255,255,255,.85);margin-bottom:22px;max-width:380px}
      .path .btn{align-self:flex-start;background:#fff;color:var(--ink);padding:12px 26px;font-size:13.5px}

      /* ── pricing ── */
      .pricing{background:var(--bg2)}
      .pcards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin-top:44px}
      .pcard{background:var(--bg);border:1px solid var(--line);border-radius:20px;padding:30px 26px;display:flex;flex-direction:column;transition:.2s}
      .pcard:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(0,0,0,.08)}
      .pcard.hot{border-color:var(--acc);box-shadow:0 0 0 3px var(--acc-soft)}
      .pcard .pn{font-size:17px;font-family:var(--head);margin-bottom:4px}
      .pcard .pp{font-family:var(--head);font-size:32px;margin:10px 0 2px}
      .pcard .pp small{font-size:13px;color:var(--muted);font-family:'Inter'}
      .pcard .pm{font-size:13px;color:var(--muted);margin-bottom:20px}
      .pcard .pd{font-size:13.5px;color:var(--muted);margin-bottom:18px}
      .pcard .btn{margin-top:auto;justify-content:center;padding:12px;font-size:13.5px}

      /* ── gallery ── */
      .gal{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:44px}
      @media(max-width:700px){.gal{grid-template-columns:repeat(2,1fr)}}
      .gal img{width:100%;height:250px;object-fit:cover;border-radius:16px;transition:.25s}
      .gal img:hover{transform:scale(1.025)}

      /* ── visit ── */
      .visit .cols{display:grid;grid-template-columns:1.05fr .95fr;gap:52px;align-items:start;margin-top:40px}
      @media(max-width:820px){.visit .cols{grid-template-columns:1fr}}
      .hrow{display:flex;justify-content:space-between;padding:10px 2px;border-bottom:1px dashed var(--line);font-size:14.5px}
      .hrow .d{font-weight:600}
      .hrow .closed{color:var(--muted)}
      .c-item{display:flex;gap:13px;align-items:flex-start;margin-bottom:18px;font-size:15px}
      .c-item svg{color:var(--acc);flex-shrink:0;margin-top:3px}
      .c-item a:hover{color:var(--acc)}
      .map-link{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:13.5px;color:var(--acc);margin-top:4px}
      .map-link:hover{text-decoration:underline}

      /* ── faq ── */
      .faq{background:var(--bg2)}
      .qa{background:var(--bg);border:1px solid var(--line);border-radius:16px;margin-bottom:11px;overflow:hidden}
      .qa summary{padding:19px 22px;font-weight:600;font-size:15px;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:14px}
      .qa summary::-webkit-details-marker{display:none}
      .qa summary::after{content:"+";font-family:var(--head);font-size:22px;color:var(--acc);flex-shrink:0;transition:.2s}
      .qa[open] summary::after{transform:rotate(45deg)}
      .qa p{padding:0 22px 19px;color:var(--muted);font-size:14.5px}

      /* ── let's talk / footer ── */
      .talk{background:var(--p);color:#fff;padding:90px 0 70px}
      .talk h2{color:#fff;font-size:clamp(34px,5.5vw,56px)}
      .talk h2 em{font-style:italic;color:var(--acc);filter:brightness(1.4)}
      .talk .lede{color:rgba(255,255,255,.8)}
      .talk .acts{display:flex;gap:13px;flex-wrap:wrap;margin-top:30px}
      .talk .contact-strip{display:flex;gap:26px;flex-wrap:wrap;margin-top:46px;padding-top:34px;border-top:1px solid rgba(255,255,255,.14);font-size:14px;color:rgba(255,255,255,.85)}
      .talk .contact-strip a{display:inline-flex;align-items:center;gap:9px}
      .talk .contact-strip a:hover{color:#fff}
      .talk .contact-strip svg{color:var(--acc);filter:brightness(1.4)}
      footer{border-top:1px solid var(--line);padding:30px 0;font-size:13px;color:var(--muted)}
      .foot{display:flex;gap:14px 22px;flex-wrap:wrap;align-items:center;justify-content:space-between}
      .foot .links{display:flex;gap:16px;flex-wrap:wrap}
      .foot a:hover{color:var(--ink)}

      /* not published fallback */
      #notReady{display:none;min-height:70vh;place-items:center;text-align:center;padding:40px}
      #notReady .in{max-width:420px}
      #notReady h1{font-size:30px;margin-bottom:10px}
      #notReady p{color:var(--muted)}
      #notReady a{text-decoration:underline}
      main{display:none}
      body.ready main{display:block}
      body.nosite #notReady{display:grid}
    </style>
  </head>
  <body>
    <div id="notReady"><div class="in">
      <h1>✨ Coming soon</h1>
      <p>This studio's website hasn't been published yet. You can still <a href="/booking">book a class</a>.</p>
    </div></div>

    <main>
      <nav>
        <div class="nav-in">
          <a class="brand" href="/site" id="brand"><span class="bname" id="brandName">Studio</span></a>
          <div class="nav-links">
            <a href="#about">About</a>
            <a href="/booking">Classes</a>
            <a href="#pricing">Pricing</a>
            <a href="/instructors">Team</a>
            <a href="#faq">FAQ</a>
            <a href="#visit">Visit</a>
          </div>
          <a class="btn" href="/booking" id="navCta">Book Now</a>
        </div>
      </nav>

      <!-- ═══ Hero ═══ -->
      <header class="hero">
        <div class="hero-bg" id="heroBg"></div>
        <div class="hero-in">
          <span class="loc" id="heroLoc">Pilates &amp; Yoga</span>
          <h1 id="heroH">Movement for <em>your</em> every day.</h1>
          <p id="heroSub"></p>
          <div class="acts">
            <a class="btn" href="/booking" id="heroCta">Book Now</a>
            <a class="btn ghost" href="#pricing">See pricing</a>
          </div>
        </div>
      </header>

      <!-- ═══ Why ═══ -->
      <section id="why">
        <div class="wrap">
          <span class="kicker">The method</span>
          <h2 id="whyH">Why pilates?</h2>
          <p class="lede">Strength, alignment and calm — built session by session.</p>
          <div class="why-grid">
            <div class="why-card"><span class="num">— 01</span><h3>Core strength &amp; tone</h3><p>Deep, functional strength that sculpts your body from the inside out. You'll stand taller and move with more power.</p></div>
            <div class="why-card"><span class="num">— 02</span><h3>Posture &amp; mobility</h3><p>Undo the desk, the phone, the commute. Precise, low-impact movement that restores alignment and eases stubborn tension.</p></div>
            <div class="why-card"><span class="num">— 03</span><h3>A clear head</h3><p>Breath-led focus that leaves you lighter than you arrived. Strength for your body, therapy for your mind.</p></div>
          </div>
        </div>
      </section>

      <!-- ═══ Story / About ═══ -->
      <section class="story" id="about">
        <div class="wrap cols">
          <div>
            <span class="kicker">Our studio</span>
            <h2 id="aboutH">About us</h2>
            <p id="aboutB"></p>
          </div>
          <div id="aboutImg" class="ph"></div>
        </div>
      </section>

      <!-- ═══ Group or Private ═══ -->
      <section id="paths">
        <div class="wrap">
          <span class="kicker">Choose your path</span>
          <h2>Group or private?</h2>
          <p class="lede">Both lead to transformation — pick what fits your goals and how you like to move.</p>
          <div class="paths">
            <div class="path">
              <div class="tagp">Together</div>
              <h3>Group classes</h3>
              <p>Energy, community and results — small classes where the instructor still knows your name and your goals.</p>
              <a class="btn" href="/booking">See the schedule</a>
            </div>
            <div class="path alt">
              <div class="tagp">Just you</div>
              <h3>Private sessions</h3>
              <p>One-on-one attention, a program built entirely around your body — the fastest way to progress.</p>
              <a class="btn" href="/booking">Book a private</a>
            </div>
          </div>
        </div>
      </section>

      <!-- ═══ Pricing ═══ -->
      <section class="pricing" id="pricing">
        <div class="wrap">
          <span class="kicker">Pricing</span>
          <h2>Packages &amp; memberships</h2>
          <p class="lede">The more you commit, the more you save. Every pack works across our schedule.</p>
          <div class="pcards" id="priceCards"></div>
          <div style="text-align:center;margin-top:30px"><a class="btn ghost dark" href="/packages">View all packages →</a></div>
        </div>
      </section>

      <!-- ═══ Gallery (only if the studio uploaded photos) ═══ -->
      <section id="gallery" style="display:none">
        <div class="wrap">
          <span class="kicker">The studio</span>
          <h2>Real people. Real results.</h2>
          <div class="gal" id="galGrid"></div>
        </div>
      </section>

      <!-- ═══ Visit ═══ -->
      <section class="visit" id="visit">
        <div class="wrap">
          <span class="kicker">Come say hi</span>
          <h2 id="visitH">Visit our studio</h2>
          <div class="cols">
            <div id="contactCol"></div>
            <div id="hoursCol"></div>
          </div>
        </div>
      </section>

      <!-- ═══ FAQ ═══ -->
      <section class="faq" id="faq">
        <div class="wrap">
          <span class="kicker">Good to know</span>
          <h2>Frequently asked questions</h2>
          <div id="faqList" style="margin-top:34px"></div>
        </div>
      </section>

      <!-- ═══ Let's talk ═══ -->
      <div class="talk" id="contact">
        <div class="wrap">
          <span class="kicker">Let's talk</span>
          <h2 id="talkH">Ready when <em>you</em> are.</h2>
          <p class="lede" id="talkSub">Your first class is the hardest one to book — after that, it books itself.</p>
          <div class="acts">
            <a class="btn light" href="/booking" id="talkCta">Book Now</a>
            <a class="btn ghost" href="/packages">See packages</a>
          </div>
          <div class="contact-strip" id="talkContact"></div>
        </div>
      </div>

      <footer>
        <div class="wrap foot">
          <span id="footName">© Studio</span>
          <div class="links">
            <a href="/booking">Schedule</a>
            <a href="/packages">Pricing</a>
            <a href="/instructors">Team</a>
            <a href="/login">Member Login</a>
            <a href="/booking-policy">Booking Policy</a>
          </div>
        </div>
      </footer>
    </main>

    <script define:vars={{ API }}>
      (async function () {
        var A = API || '';
        function $(s) { return document.querySelector(s); }
        function esc(x) { var d = document.createElement('div'); d.textContent = x == null ? '' : String(x); return d.innerHTML; }

        var data;
        try { data = await (await fetch(A + '/api/settings/public')).json(); } catch (e) { data = null; }
        var p = (data && data.profile) || {};
        var site = (data && data.site) || {};

        if (!site.published) { document.body.classList.add('nosite'); return; }

        document.documentElement.dataset.preset = site.stylePreset || 'luxury-wellness';
        if (p.primaryColor) document.documentElement.style.setProperty('--p', p.primaryColor);
        if (p.secondaryColor) document.documentElement.style.setProperty('--acc', p.secondaryColor);

        var name = p.studioName || 'Our Studio';
        document.title = site.seoTitle || name;
        $('#seoDesc').setAttribute('content', site.seoDescription || '');
        $('#brandName').textContent = name;
        if (p.logoUrl) $('#brand').innerHTML = '<img src="' + esc(p.logoUrl) + '" alt="' + esc(name) + '" /><span class="bname">' + esc(name) + '</span>';

        // Hero — the studio's own photo, or the built-in default.
        var photos = site.photoUrls || [];
        $('#heroBg').style.backgroundImage = 'url(' + (photos[0] ? photos[0] : '/home/hero.jpg') + ')';
        $('#heroLoc').textContent = name + (p.city ? ' · ' + p.city : '');
        if (site.heroHeadline) {
          // Italicize the middle word for the editorial serif feel.
          var words = site.heroHeadline.split(' ');
          if (words.length >= 3) {
            var mid = Math.floor(words.length / 2);
            words[mid] = '<em>' + esc(words[mid]) + '</em>';
            $('#heroH').innerHTML = words.map(function (w, i) { return i === Math.floor(words.length / 2) ? w : esc(w); }).join(' ');
          } else { $('#heroH').textContent = site.heroHeadline; }
        }
        $('#heroSub').textContent = site.heroSub || '';
        if (site.ctaText) { $('#heroCta').textContent = site.ctaText; $('#navCta').textContent = 'Book Now'; $('#talkCta').textContent = site.ctaText; }

        $('#whyH').textContent = 'Why ' + name + '?';
        $('#aboutH').textContent = site.aboutHeadline || ('About ' + name);
        $('#aboutB').textContent = site.aboutBody || '';
        var aboutPhoto = photos[1] || photos[0] || '/home/hero2.jpg';
        $('#aboutImg').outerHTML = '<img src="' + esc(aboutPhoto) + '" alt="' + esc(name) + '" loading="lazy" />';

        // Pricing — live packages (top 4 by price, middle one highlighted).
        try {
          var pk = await (await fetch(A + '/api/products/packages')).json();
          var cur = p.currency || '';
          var top = (pk || []).slice(0, 4);
          $('#priceCards').innerHTML = top.map(function (x, i) {
            return '<div class="pcard' + (i === 1 ? ' hot' : '') + '"><div class="pn">' + esc(x.name) + '</div>' +
              '<div class="pp">' + Number(x.basePrice).toLocaleString() + (cur ? ' <small>' + esc(cur) + '</small>' : '') + '</div>' +
              '<div class="pm">' + x.credits + ' credits · valid ' + x.validityDays + ' days</div>' +
              (x.description ? '<div class="pd">' + esc(x.description) + '</div>' : '') +
              '<a class="btn" href="/packages">Choose</a></div>';
          }).join('') || '<p style="color:var(--muted)">Packages coming soon — <a href="/booking" style="text-decoration:underline">book a drop-in class</a>.</p>';
        } catch (e) {}

        // Gallery — only when the studio uploaded 3+ photos (beyond hero/about).
        if (photos.length >= 3) {
          $('#gallery').style.display = 'block';
          $('#galGrid').innerHTML = photos.slice(0, 6).map(function (u) {
            return '<img src="' + esc(u) + '" alt="' + esc(name) + '" loading="lazy" />';
          }).join('');
        }

        // Visit — contact + map + hours.
        var pin = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>';
        var tel = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg>';
        var mail = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>';
        var ig = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg>';
        var addr = [p.address, p.city, p.country].filter(Boolean).join(', ');
        var c = '';
        if (addr) {
          c += '<div class="c-item">' + pin + '<div>' + esc(addr) +
            '<br/><a class="map-link" href="https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(addr) + '" target="_blank" rel="noopener">Open in Google Maps →</a></div></div>';
        }
        if (p.phone) c += '<div class="c-item">' + tel + '<a href="tel:' + esc(p.phone) + '">' + esc(p.phone) + '</a></div>';
        if (p.businessEmail) c += '<div class="c-item">' + mail + '<a href="mailto:' + esc(p.businessEmail) + '">' + esc(p.businessEmail) + '</a></div>';
        $('#contactCol').innerHTML = c || '<p style="color:var(--muted)">Contact details coming soon.</p>';

        var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var hours = p.hours || [];
        // Show Mon-first, like a studio timetable reads.
        var ordered = hours.slice().sort(function (a, b) { return ((a.day + 6) % 7) - ((b.day + 6) % 7); });
        $('#hoursCol').innerHTML = ordered.length
          ? ordered.map(function (h) {
              return '<div class="hrow"><span class="d">' + DAYS[h.day] + '</span>' +
                (h.closed ? '<span class="closed">Closed</span>' : '<span>' + esc(h.open) + ' – ' + esc(h.close) + '</span>') + '</div>';
            }).join('')
          : '<p style="color:var(--muted)">Open daily — see the <a href="/booking" style="text-decoration:underline">live schedule</a>.</p>';

        // FAQ
        $('#faqList').innerHTML = (site.faqs || []).map(function (f) {
          return '<details class="qa"><summary>' + esc(f.question) + '</summary><p>' + esc(f.answer) + '</p></details>';
        }).join('');

        // Let's talk strip + footer
        var t = '';
        if (p.phone) t += '<a href="tel:' + esc(p.phone) + '">' + tel + esc(p.phone) + '</a>';
        if (p.businessEmail) t += '<a href="mailto:' + esc(p.businessEmail) + '">' + mail + esc(p.businessEmail) + '</a>';
        if (p.instagram) {
          var igh = p.instagram.replace(/^@/, '');
          t += '<a href="' + esc(igh.indexOf('http') === 0 ? igh : 'https://instagram.com/' + igh) + '" target="_blank" rel="noopener">' + ig + '@' + esc(igh.replace(/^https?:\/\/(www\.)?instagram\.com\//, '')) + '</a>';
        }
        $('#talkContact').innerHTML = t;
        $('#talkH').innerHTML = 'Ready to join <em>' + esc(name) + '</em>?';
        $('#footName').textContent = '© ' + new Date().getFullYear() + ' ' + name + ' · Powered by Studio Nexis';

        document.body.classList.add('ready');
      })();
    </script>
  </body>
</html>

