  <script is:inline>
    // ── Getting-started checklist — live status from the studio's own data ──
    (function () {
      var token = localStorage.getItem('token');
      if (!token) return;
      if (localStorage.getItem('nx-gs-dismissed') === '1') return;
      var H = { Authorization: 'Bearer ' + token };
      function j(p) { return fetch(p, { headers: H }).then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; }); }

      Promise.all([j('/api/settings'), j('/api/classblueprint'), j('/api/product'), j('/api/staff')]).then(function (rs) {
        var s = rs[0] || {}, bp = rs[1] || [], pr = rs[2] || [], st = rs[3] || [];
        var state = {
          profile: !!(s.profile && s.profile.studioName),
          website: !!(s.site && s.site.published),
          classes: bp.length > 0,
          packages: pr.filter(function (x) { return x.type === 'PACKAGE'; }).length > 0,
          staff: st.length > 0,
          stripe: s.stripeEnabled === true,
        };
        var keys = Object.keys(state);
        var done = keys.filter(function (k) { return state[k]; }).length;
        if (done === keys.length) return; // fully set up — stay hidden

        keys.forEach(function (k) {
          var el = document.querySelector('.gs-item[data-k="' + k + '"]');
          if (el && state[k]) el.classList.add('done');
        });
        document.getElementById('gsBar').style.width = Math.round((done / keys.length) * 100) + '%';
        document.getElementById('gsSub').textContent = done + ' of ' + keys.length + ' complete — finish these to start taking bookings.';
        document.getElementById('gsCard').classList.add('on');
        document.getElementById('gsDismiss').addEventListener('click', function () {
          localStorage.setItem('nx-gs-dismissed', '1');
          document.getElementById('gsCard').classList.remove('on');
        });
      });
    })();
  </script>
</AdminLayout>

