//  Tab switching
const tabBtns = document.querySelectorAll(".settings-tab");
const tabPanels = {
  financial: document.getElementById("tabPanelFinancial"),
  operations: document.getElementById("tabPanelOperations"),
  payments: document.getElementById("tabPanelPayments"),
  notifications: document.getElementById("tabPanelNotifications"),
  schedule: document.getElementById("tabPanelSchedule"),
  integrations: document.getElementById("tabPanelIntegrations"),
  equipment: document.getElementById("tabPanelEquipment"),
  emails: document.getElementById("tabPanelEmails"),
