const tabMeta = {
  financial: {
    title: "Financial",
    description:
      "Revenue splits, payroll inputs, referrals, receptionist bonus settings, and studio rental pricing.",
  },
  operations: {
    title: "Operations",
    description:
      "Expense categories, staff controls, and daily operating structure.",
  },
  payments: {
    title: "Payments",
    description:
      "Payment methods, checkout behavior, invoice settings, and POS support preferences.",
  },
  notifications: {
    title: "Notifications",
    description:
      "Push rules, messaging controls, and the system alerts your team depends on.",
  },
  schedule: {
    title: "Schedule",
    description:
      "Booking windows, class availability, attendance flow, and schedule defaults.",
  },
  integrations: {
    title: "Integrations",
    description:
      "Third-party links, API-connected services, and external channels that feed the CRM.",
  },
  equipment: {
    title: "Equipment",
    description:
      "Studio machine setup, asset visibility, and maintenance-ready equipment records.",
  },
  emails: {
    title: "Emails",
    description:
      "Auto-send toggles and message templates for every studio email.",
  },
  roles: {
    title: "Roles & Access",
    description:
      "Choose which admin pages each staff role can access. Saved with Operations settings.",
  },
};

function syncSettingsMeta(target) {
  const meta = tabMeta[target];
  if (!meta) return;
  const titleEl = document.getElementById("settingsActiveTitle");
  const descEl = document.getElementById("settingsActiveDescription");
  if (titleEl) titleEl.textContent = meta.title;
  if (descEl) descEl.textContent = meta.description;
}

tabBtns.forEach((btn) => {
  btn.addEventListener("click", () => {
    const target = btn.dataset.tab;
    // Update buttons
    tabBtns.forEach((b) => b.classList.remove("active"));
    btn.classList.add("active");
    // Update panels
    Object.entries(tabPanels).forEach(([key, panel]) => {
      if (key === target) {
        panel.style.display = "";
        // Re-trigger animation
        panel.style.animation = "none";
        panel.offsetHeight; // reflow
        panel.style.animation = "";
      } else {
        panel.style.display = "none";
      }
    });
    syncSettingsMeta(target);
  });
});
syncSettingsMeta("financial");

