div.innerHTML =
  '<div class="tpl-head"><span class="cbx"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg></span>' +
  '<span class="tpl-name">' + esc(t.name) + '</span>' +
  '<span class="tpl-sub">' + esc(t.sub || '') + '</span>' +
  '<button type="button" class="tpl-chev" aria-label="Edit details"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg></button></div>' +
  '<div class="tpl-body">' + fields + '</div>';
$('.tpl-head', div).addEventListener('click', function (e) {
  // Chevron expands/collapses the details of a selected row.
  if (e.target.closest('.tpl-chev')) { if (div.classList.contains('sel')) div.classList.toggle('open'); return; }
  if (e.target.closest('input,select,[contenteditable=true]')) return;
  div.classList.toggle('sel');
  if (!div.classList.contains('sel')) div.classList.remove('open');
});
// Keep the one-line summary in sync while the owner edits details.
function summarize() {
  var g = function (f) { var el = $('[data-f=' + f + ']', div); return el ? el.value : ''; };
  var s = '';
  if (kind === 'svc') s = g('duration') + ' min · ' + g('capacity') + ' spots · ' + g('price');
  else if (kind === 'pkg') s = g('credits') + ' credits · ' + g('validity') + ' days · ' + g('price');
  else s = (g('role') || '').toLowerCase() + (g('email') ? ' · ' + g('email') : '');
  $('.tpl-sub', div).textContent = s;
}
div.addEventListener('input', summarize);
div.addEventListener('change', summarize);
return div;

