fetch(`${API}/api/client/${clientId}`, {
  headers: { Authorization: "Bearer " + token },
})
  .then((r) => r.json())
  .then((c) => {
    const initials =
      c.name
        ?.split(" ")
        .map((n) => n[0])
        .join("")
        .substring(0, 2)
        .toUpperCase() ?? "?";
    document.getElementById("clientAvatar").textContent = initials;
    document.getElementById("clientName").textContent = c.name;
    document.getElementById("clientMeta").innerHTML = [
      c.phone && `📱 ${c.phone}`,
      c.email && `✉ ${c.email}`,
      c.country && `🌍 ${c.country}`,
      c.preferredContactPlatform && `💬 ${c.preferredContactPlatform}`,
    ]
      .filter(Boolean)
      .join(" &nbsp;·&nbsp; ");
    // Lifetime value + auto VIP badge (VIP once spend ≥ 10,000,000 ₫)
    const ltvEl = document.getElementById("clientLtv");
    if (ltvEl) {
      const ltv = c.lifetimeValue || 0;
      ltvEl.innerHTML = `💰 Lifetime value: <strong style="color:var(--color-text-primary);">₫${Math.round(ltv).toLocaleString()}</strong>`;
    }
    const vipEl = document.getElementById("clientVipBadge");
    if (vipEl) {
      if (c.vipTier === "SUPER_VIP") {
        vipEl.innerHTML = "💎 SUPER VIP";
        vipEl.style.background = "linear-gradient(135deg,#8E2DE2,#4A00E0)";
        vipEl.style.color = "#fff";
        vipEl.style.display = "inline-flex";
      } else if (c.vipTier === "VIP") {
        vipEl.innerHTML = "👑 VIP";
        vipEl.style.background = "linear-gradient(135deg,#F4C430,#E0A800)";
        vipEl.style.color = "#4a3500";
        vipEl.style.display = "inline-flex";
      } else {
        vipEl.style.display = "none";
      }
    }
    if (c.tags?.length) {
      document.getElementById("clientTags").innerHTML = c.tags
        .map((t) => `<span class="tag-chip-sm">${t}</span>`)
        .join("");
    }
    document.getElementById("clientInfoCards").innerHTML = `
      <div class="card"><div class="card-body">
        <div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;color:var(--color-text-muted);margin-bottom:12px;">Health & Notes</div>
        <p style="font-size:13px;color:var(--color-text-secondary);line-height:1.6;">${c.medicalHistory || '<span style="color:var(--color-text-muted);">No medical notes on file.</span>'}</p>
        ${c.notes ? `<div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--color-border-subtle);font-size:13px;color:var(--color-text-muted);">${c.notes}</div>` : ""}
        ${c.referralSource ? `<div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--color-border-subtle);font-size:12px;color:var(--color-text-muted);">Heard about us via <strong style="color:var(--color-text-secondary);">${c.referralSource}</strong></div>` : ""}
      </div></div>
      <div class="card"><div class="card-body">
        <div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;color:var(--color-text-muted);margin-bottom:12px;">Account Info</div>
        <div style="display:flex;flex-direction:column;gap:8px;font-size:13px;">
          <div class="flex justify-between"><span class="text-muted">Member since</span><span>${c.createdAt ? new Date(c.createdAt).toLocaleDateString("en-US", { month: "short", year: "numeric" }) : "—"}</span></div>
          <div class="flex justify-between"><span class="text-muted">Partner code</span><span>${c.partnerCode || "—"}</span></div>
        </div>
      </div></div>
    `;
  })
  .catch(() => {});

