/* ═══ Modals ═══ */
function openNewSession() { document.getElementById('sessionModal').classList.add('open'); loadModalDropdowns(); }
function closeModal() { document.getElementById('sessionModal').classList.remove('open'); }
document.getElementById('sessionModal').addEventListener('click', e => { if (e.target === document.getElementById('sessionModal')) closeModal(); });

async function loadModalDropdowns() {
  if (document.getElementById('sInstructorId').options.length > 1) return;
  try {
    const prods = await fetch(`${API}/api/classblueprint`, { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
    document.getElementById('sInstructorId').innerHTML = '<option value="">Select instructor...</option>' +
      staffList.filter(s => s.isActive !== false).map(s => `<option value="${s.id}">${esc(s.name)} (${s.role})</option>`).join('');
    document.getElementById('sBlueprintId').innerHTML = '<option value="">Select a class...</option>' +
      prods.map(p => `<option value="${p.id}">${esc(p.className)}</option>`).join('');
  } catch {}
}

async function saveSession() {
  const start = new Date(document.getElementById('sStart').value);
  const end = new Date(start); end.setMinutes(end.getMinutes() + parseInt(document.getElementById('sDuration').value));
  const bpSel = document.getElementById('sBlueprintId');
  const instSel = document.getElementById('sInstructorId');
  await fetch(`${API}/api/scheduling/session/manual`, {
    method: 'POST', headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      classBlueprintId: bpSel.value,
      className: bpSel.options[bpSel.selectedIndex]?.text || 'Class',
      instructorId: instSel.value,
      instructorName: instSel.options[instSel.selectedIndex]?.text?.split(' (')[0] || 'Instructor',
      startTime: start.toISOString(), endTime: end.toISOString(),
      capacity: parseInt(document.getElementById('sCapacity').value),
      currentBookings: 0, status: 'SCHEDULED',
    }),
  });
  closeModal(); renderCalendar();
}

/* Block modal */
function openBlockModal() {
  const now = new Date(); now.setMinutes(0,0,0);
  document.getElementById('bStart').value = isoLocal(now);
  document.getElementById('bDuration').value = '60';
  document.getElementById('bReason').value = '';
  document.querySelectorAll('input[name="blockScope"]').forEach(r => { r.checked = r.value === 'GLOBAL'; });

