// ── Status badge helpers ──────────────────────────────────────
function statusBadge(s) {
  const cls = s === 'COMPLETED' ? 'badge-success'
    : s === 'CANCELLED' ? 'badge-danger'
    : s === 'NO_SHOW' ? 'badge-warning'
    : s === 'SCHEDULED' ? 'badge-default' : 'badge-warning';
  const label = s === 'NO_SHOW' ? 'NO SHOW' : s;
  return `<span class="badge ${cls}">${esc(label)}</span>`;
}

function originBadge(o) {
  const map = { MATERIALISED:'🔁', MANUAL:'✋', OVERRIDE:'⚠️', FREELANCE:'🎸' };
  return `<span style="font-size:11px;color:var(--color-text-muted);" title="${esc(o)}">${map[o] || '•'} ${esc(o)}</span>`;
}

function fillBar(bookings, capacity) {
  const pct = capacity > 0 ? Math.min(100, Math.round((bookings / capacity) * 100)) : 0;
  const cls = pct >= 100 ? 'full' : pct >= 75 ? 'high' : pct >= 40 ? 'mid' : 'low';
  return `<div class="fill-bar">
    <div class="fill-bar-track"><div class="fill-bar-fill ${cls}" style="width:${pct}%"></div></div>
    <span class="fill-pct">${pct}%</span>
  </div>`;
}

