// ── Status badge helpers ──────────────────────────────────────
// Human labels — owners shouldn't read raw enum values.
function statusBadge(s) {
  const cls = s === 'COMPLETED' ? 'badge-success'
    : s === 'CANCELLED' ? 'badge-danger'
    : s === 'NO_SHOW' ? 'badge-warning'
    : s === 'SCHEDULED' ? 'badge-default' : 'badge-warning';
  const labels = { SCHEDULED: 'Upcoming', COMPLETED: 'Completed', CANCELLED: 'Cancelled', NO_SHOW: 'No-show' };
  const label = labels[s] || (s || '').charAt(0) + (s || '').slice(1).toLowerCase().replace(/_/g, ' ');
  return `<span class="badge ${cls}">${esc(label)}</span>`;
}

function originBadge(o) {
  const map = {
    MATERIALISED: ['🔁', 'Recurring', 'Created automatically from your weekly schedule'],
    MANUAL:       ['✋', 'One-off',   'Added by hand on the calendar'],
    OVERRIDE:     ['⚠️', 'Adjusted', 'A recurring class that was changed for this date'],
    FREELANCE:    ['🎸', 'Rental',   'A freelance studio-rental session'],
  };
  const m = map[o] || ['•', (o || '').toLowerCase(), o];
  return `<span style="font-size:11px;color:var(--color-text-muted);" title="${esc(m[2])}">${m[0]} ${esc(m[1])}</span>`;
}

