    [HttpGet]
    public async Task<IActionResult> Get(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);
        var role = User.FindFirstValue(ClaimTypes.Role)
            ?? User.Claims.FirstOrDefault(c => string.Equals(c.Type, "role", StringComparison.OrdinalIgnoreCase))?.Value
            ?? string.Empty;
        var roleKey = role.Trim().ToLowerInvariant();

        var roleAccess = (settings.RoleAccessSettings ?? new List<SoulPilates.Core.Entities.RoleAccessSetting>())
            .FirstOrDefault(x => string.Equals(x.RoleKey, roleKey, StringComparison.OrdinalIgnoreCase));

        // Per-user access (User.AllowedAdminModules) arrives as `module` claims.
        var userModules = User.FindAll("module")
            .Select(c => (c.Value ?? string.Empty).Trim().ToLowerInvariant())
            .Where(v => v.Length > 0)
            .Distinct()
            .ToList();

        // Custom-access accounts: the explicit module set is authoritative and
        // fully replaces role defaults (matching the Module:{key} policy).
        var isCustom = User.HasClaim(c =>
            string.Equals(c.Type, "access_mode", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(c.Value, "custom", StringComparison.OrdinalIgnoreCase));

        List<string> merged;
        bool enabled;
        if (isCustom)
        {
            merged = userModules;
            enabled = merged.Count > 0;
        }
        else
        {
            var roleModules = roleAccess is { IsEnabled: true }
                ? roleAccess.EnabledModuleKeys
                : Enumerable.Empty<string>();
            merged = roleModules
                .Select(m => (m ?? string.Empty).Trim().ToLowerInvariant())
                .Concat(userModules)
                .Where(m => m.Length > 0)
                .Distinct()
                .ToList();
            enabled = (roleAccess?.IsEnabled ?? false) || merged.Count > 0;
        }

        // Also return the module catalog (key → label → path) so instructor-facing
        // navigation can render granted-page links without needing the admin-only
        // /api/user-access/modules endpoint.
        var catalog = (await _modules.Find(FilterDefinition<RoleModuleDefinition>.Empty).ToListAsync())
            .Select(m => new { key = m.Key, label = m.Label, path = m.Path });

        return Ok(new
        {
            role = roleKey,
            roleEnabled = enabled,
            enabledModuleKeys = merged,
            modules = catalog,
        });
    }
}

