public async Task<GlobalSettings> UpdateDisabledModulesAsync(List<string> disabledModules, CancellationToken ct = default)
{
    var current = await GetAsync(ct);

    var clean = (disabledModules ?? new List<string>())
        .Select(m => (m ?? string.Empty).Trim().ToLowerInvariant())
        .Where(m => m.Length > 0)
        .Distinct()
        .ToList();

    var update = Builders<GlobalSettings>.Update
        .Set(s => s.DisabledModules, clean)
        .Set(s => s.UpdatedAt, DateTime.UtcNow);

    await _settings.UpdateOneAsync(s => s.Id == current.Id, update, cancellationToken: ct);
    return await GetAsync(ct);
}

