    boxes.forEach(function (b) { if (!b.checked) disabled.push(b.dataset.mod); });
    fetch("/api/settings/modules", {
      method: "PATCH",
      headers: { Authorization: "Bearer " + (localStorage.getItem("token") || ""), "Content-Type": "application/json" },
