// ── Website tab: edit the generated public site ───────────────────────
(function () {
  var authH = { Authorization: "Bearer " + (localStorage.getItem("token") || "") };
  var site = {}; // full SiteContent object — preserved fields we don't edit stay intact
  var photos = [];

  function renderPhotos() {
    var box = document.getElementById("wsPhotos");
    box.innerHTML = photos.map(function (u, i) {
      return '<span class="nx-photo"><img src="' + u + '" alt="" /><button type="button" data-i="' + i + '" title="Remove">✕</button></span>';
    }).join("");
    box.querySelectorAll("button[data-i]").forEach(function (b) {
      b.addEventListener("click", function () { photos.splice(+b.dataset.i, 1); renderPhotos(); });
    });
  }

  fetch("/api/settings", { headers: authH })
    .then(function (r) { return r.json(); })
    .then(function (s) {
      site = s.site || {};
      photos = (site.photoUrls || []).slice();
      document.getElementById("wsPublished").checked = site.published === true;
      document.getElementById("wsPreset").value = site.stylePreset || "modern-minimal";
      document.getElementById("wsHeroH").value = site.heroHeadline || "";
      document.getElementById("wsHeroSub").value = site.heroSub || "";
      document.getElementById("wsCta").value = site.ctaText || "";
      document.getElementById("wsAboutH").value = site.aboutHeadline || "";
      document.getElementById("wsAboutB").value = site.aboutBody || "";
      document.getElementById("wsSeoT").value = site.seoTitle || "";
      document.getElementById("wsSeoD").value = site.seoDescription || "";
      renderPhotos();
    }).catch(function () {});

  document.getElementById("wsAddPhoto").addEventListener("click", function () {
    document.getElementById("wsPhotoFile").click();
  });
  document.getElementById("wsPhotoFile").addEventListener("change", async function () {
    for (var i = 0; i < this.files.length; i++) {
      var fd = new FormData(); fd.append("file", this.files[i]);
      try {
        var res = await fetch("/api/media/site-photo", { method: "POST", headers: authH, body: fd });
        var j = await res.json();
        if (res.ok && j.url) { photos.push(j.url); renderPhotos(); }
      } catch (e) {}
    }
    this.value = "";
  });

  document.getElementById("wsSave").addEventListener("click", function () {
    site.published = document.getElementById("wsPublished").checked;
    site.stylePreset = document.getElementById("wsPreset").value;
    site.heroHeadline = document.getElementById("wsHeroH").value.trim();
    site.heroSub = document.getElementById("wsHeroSub").value.trim();
    site.ctaText = document.getElementById("wsCta").value.trim();
    site.aboutHeadline = document.getElementById("wsAboutH").value.trim();
    site.aboutBody = document.getElementById("wsAboutB").value.trim();
    site.seoTitle = document.getElementById("wsSeoT").value.trim();
    site.seoDescription = document.getElementById("wsSeoD").value.trim();
    site.photoUrls = photos;
    fetch("/api/settings/site", {
      method: "PATCH",
      headers: Object.assign({ "Content-Type": "application/json" }, authH),
      body: JSON.stringify(site),
    }).then(function (r) {
      if (r.ok) { var m = document.getElementById("wsMsg"); m.style.display = "inline"; setTimeout(function () { m.style.display = "none"; }, 4000); }
    });
  });
})();

