/// </summary>
[ApiController]
[Route("api/dev")]
[AllowAnonymous]
public class DevSeedController : ControllerBase
{
    private const string MARK = "DEMO_SEED";          // marker on notes/text fields
    private const string REF_PREFIX = "DEMO-";         // marker on attendance refs

    private readonly MongoDbContext _db;
    private readonly string _key;
    private readonly IWebHostEnvironment _env;

    public DevSeedController(MongoDbContext db, IConfiguration config, IWebHostEnvironment env)
    {
        _db = db;
        _key = config["JwtSettings:Secret"] ?? "";
        _env = env;
    }

    // Defence-in-depth: this demo seed/purge tool must be completely inert outside
    // Development. In Production the endpoints don't exist (404), regardless of the
    // header key — so a data-purge surface never ships to a live studio.
