    [HttpPost("purge-demo")]
    public async Task<IActionResult> Purge()
    {
        if (!DevOnly()) return NotFound();
        if (!Authorised()) return StatusCode(403, new { message = "Forbidden." });

        var invCol = _db.GetCollection<Invoice>("Invoices");
        // Payments carry no free marker field, so purge them by the demo invoices they belong to.
        var demoInvoiceIds = await invCol
            .Find(Builders<Invoice>.Filter.Eq(i => i.Notes, MARK))
            .Project(i => i.Id!)
            .ToListAsync();

        var payDeleted = demoInvoiceIds.Count == 0 ? 0
            : (await _db.GetCollection<Payment>("Payments")
                .DeleteManyAsync(Builders<Payment>.Filter.In(p => p.InvoiceId, demoInvoiceIds))).DeletedCount;

        var results = new Dictionary<string, long>
        {
            ["clients"]     = (await _db.GetCollection<Client>("Clients").DeleteManyAsync(Builders<Client>.Filter.Eq(c => c.InternalNotes, MARK))).DeletedCount,
            ["sessions"]    = (await _db.GetCollection<CalendarSession>("CalendarSessions").DeleteManyAsync(Builders<CalendarSession>.Filter.Eq(s => s.OverrideNote, MARK))).DeletedCount,
            ["attendances"] = (await _db.GetCollection<Attendance>("Attendances").DeleteManyAsync(Builders<Attendance>.Filter.Regex(a => a.BookingReference, new MongoDB.Bson.BsonRegularExpression("^" + REF_PREFIX)))).DeletedCount,
            ["payments"]    = payDeleted,
            ["invoices"]    = (await invCol.DeleteManyAsync(Builders<Invoice>.Filter.Eq(i => i.Notes, MARK))).DeletedCount,
            ["packages"]    = (await _db.GetCollection<ClientPackage>("ClientPackages").DeleteManyAsync(Builders<ClientPackage>.Filter.Eq(p => p.InvoiceLineId, MARK))).DeletedCount,
            ["expenses"]    = (await _db.GetCollection<Expense>("Expenses").DeleteManyAsync(Builders<Expense>.Filter.Eq(e => e.EnteredByUserId, MARK))).DeletedCount,
            ["products"]    = (await _db.GetCollection<Product>("Products").DeleteManyAsync(Builders<Product>.Filter.Eq(p => p.Sku, MARK))).DeletedCount,
        };
        return Ok(new { message = "Demo data purged.", deleted = results });
    }
}

