/// The studio's subscription snapshot for the Plan &amp; Billing page:
/// plan name, status, and trial end. Control-plane hosts have no tenant
/// and return 404.
/// </summary>
[HttpGet("plan")]
public async Task<IActionResult> GetPlan(CancellationToken ct)
{
    if (string.IsNullOrEmpty(_tenant.Slug)) return NotFound(new { message = "No studio on this host." });
    var t = await _registry.ResolveBySlugAsync(_tenant.Slug, ct);
    if (t is null) return NotFound(new { message = "Unknown studio." });

    return Ok(new
    {
        t.Slug,
        t.DisplayName,
        plan = t.Plan,
        subscriptionStatus = t.SubscriptionStatus,
        trialEndsAt = t.TrialEndsAt,
        daysLeftInTrial = t.TrialEndsAt is { } end && end > DateTime.UtcNow
            ? (int)Math.Ceiling((end - DateTime.UtcNow).TotalDays)
            : (int?)null,
    });
}

