/// <summary>
/// Legacy fallback timezone for studios that haven't set one in their
/// profile (all pre-SaaS tenants) — keeps their schedules byte-identical.
/// </summary>
private static readonly TimeZoneInfo FallbackStudioTz =
    TimeZoneInfo.FindSystemTimeZoneById(OperatingSystem.IsWindows()
        ? "SE Asia Standard Time"
        : "Asia/Ho_Chi_Minh");

private TimeZoneInfo? _studioTzCache;

/// <summary>
/// The studio's own timezone (Profile.TimeZone, set in onboarding) for
/// local-time scheduling math. Cached per scoped service instance (one
/// request = one tenant). Unknown/blank ids fall back to the legacy zone.
/// </summary>
private async Task<TimeZoneInfo> GetStudioTzAsync()
{
    if (_studioTzCache is not null) return _studioTzCache;
    try
    {
        var tzId = (await _settingsService.GetAsync()).Profile?.TimeZone;
        _studioTzCache = string.IsNullOrWhiteSpace(tzId)
            ? FallbackStudioTz
            : TimeZoneInfo.FindSystemTimeZoneById(tzId);
    }
    catch
    {
        _studioTzCache = FallbackStudioTz;
    }
    return _studioTzCache;
}

