import re
files = ['src/pages/admin/clients.astro','src/pages/admin/products.astro','src/pages/admin/classes.astro','src/pages/admin/bookings.astro','src/pages/admin/invoices.astro']
pat = re.compile(r'<tr><td colspan="(\d+)"[^>]*>Loading[^<]*</td></tr>')
def skel(m):
    cols = int(m.group(1))
    row = '<tr class="skel-row">' + '<td><span class="skel"></span></td>' * cols + '</tr>'
    return row * 5
for f in files:
    t = open(f).read()
    # Only replace the STATIC placeholders (HTML section), not JS template literals:
    # JS ones live inside backticks; the static ones match exactly with double quotes.
    t2, n = pat.subn(skel, t)
    open(f, 'w').write(t2)
    print(f, 'replaced', n)
PYEOF

