using Microsoft.Extensions.Configuration;
using SoulPilates.Core.Multitenancy;

namespace SoulPilates.API.Middleware;

/// <summary>
/// Resolves the SaaS tenant from the request host (subdomain-per-tenant) and
/// binds the request scope to that tenant's database via <see cref="ITenantContext"/>.
///
/// Host scheme:
///   &lt;slug&gt;.studionexis.soulpilates.com.vn  → tenant "slug"
///   studionexis.soulpilates.com.vn            → no tenant (control plane / default DB)
///
/// An unknown or suspended tenant subdomain returns 404 so a stale/guessed slug
/// never silently falls through to another studio's data.
/// </summary>
public class TenantResolutionMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _baseDomain;

    public TenantResolutionMiddleware(RequestDelegate next, IConfiguration config)
    {
        _next = next;
        _baseDomain = (config["Saas:BaseDomain"] ?? "studionexis.soulpilates.com.vn").ToLowerInvariant();
    }

    public async Task InvokeAsync(HttpContext context, ITenantContext tenantContext, ITenantRegistry registry)
    {
        var host = context.Request.Host.Host.ToLowerInvariant();

        // Only a "<slug>.<baseDomain>" host carries a tenant. The bare base domain
        // (and localhost / IPs in dev) leave the default database in place.
        if (host.EndsWith("." + _baseDomain))
        {
            var prefix = host[..^(_baseDomain.Length + 1)];   // strip ".<baseDomain>"
            var slug = prefix.Split('.')[0];                  // first label only

            if (!string.IsNullOrEmpty(slug) && slug != "www")
            {
                var tenant = await registry.ResolveBySlugAsync(slug, context.RequestAborted);
                if (tenant is null)
                {
                    context.Response.StatusCode = StatusCodes.Status404NotFound;
                    await context.Response.WriteAsJsonAsync(new { message = "Unknown or inactive studio." });
                    return;
                }

                // License enforcement: a suspended tenant / expired trial / lapsed
                // subscription is blocked. Auth endpoints stay open so the owner can
                // still sign in to a billing screen; everything else is 402.
                if (!tenant.IsLicenseValid(DateTime.UtcNow))
                {
                    var path = context.Request.Path.Value ?? "";
                    var isAuth = path.StartsWith("/api/auth", StringComparison.OrdinalIgnoreCase);
                    if (!isAuth)
                    {
                        context.Response.StatusCode = StatusCodes.Status402PaymentRequired;
                        await context.Response.WriteAsJsonAsync(new
                        {
                            code = "SUBSCRIPTION_INACTIVE",
                            message = "This studio's subscription is inactive. Please renew to continue.",
                        });
                        return;
                    }
                }

                tenantContext.SetTenant(tenant);
            }
        }

        await _next(context);
    }
}

