// Studio Nexis — Mission Control (super-admin portal).
// Served in the static build on every host, but ONLY functions on the secret
// control-portal subdomain: everywhere else the /api/saas endpoints return
// 403 (tenant-bound hosts) so this page shows nothing useful. Real security
// is the control-plane Admin login + server-side guards — the secret host is
// the discretion layer on top.
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Mission Control</title>
    <meta name="robots" content="noindex,nofollow" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet" />
    <style is:global>
      :root{--or:#F97316;--or2:#FB923C;--bg:#0f0d0a;--card:#1a1613;--card2:#221d18;--line:#2e2822;--ink:#f3efe9;--muted:#9a9184;--ok:#34d399;--warn:#fbbf24;--bad:#f87171}
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Inter',system-ui,sans-serif;background:radial-gradient(900px 500px at 80% -10%,#2a2015,var(--bg) 60%);color:var(--ink);min-height:100vh;-webkit-font-smoothing:antialiased}
      h1,h2,h3{font-family:'Manrope',sans-serif;letter-spacing:-.02em}
      .wrap{max-width:1100px;margin:0 auto;padding:26px 24px 60px}
      .top{display:flex;align-items:center;gap:12px;margin-bottom:28px}
      .mark{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--or),#ea580c);display:grid;place-items:center;font-weight:800;font-family:'Manrope'}
      .top h1{font-size:19px}
      .top .sub{font-size:11.5px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}
      .top .right{margin-left:auto;display:flex;gap:10px;align-items:center;font-size:12.5px;color:var(--muted)}
      .btn{display:inline-flex;align-items:center;gap:7px;background:var(--or);color:#fff;border:none;border-radius:9px;padding:9px 16px;font-weight:700;font-size:13px;cursor:pointer;font-family:inherit}
      .btn:hover{background:#ea580c}
      .btn.ghost{background:transparent;border:1px solid var(--line);color:var(--ink)}
