        <div><h1>Mission Control</h1><div class="sub">Studio Nexis · Platform HQ</div></div>
        <div class="right"><span id="whoami"></span><button class="btn ghost sm" id="logoutBtn" style="display:none;">Sign out</button></div>
      </div>

      <div id="blocked">Nothing to see here.</div>

      <!-- Login -->
      <div id="login">
        <h2>Platform sign-in</h2>
        <p>Control-plane administrator credentials.</p>
        <div id="loginErr"></div>
