      (function () {
        var TK = 'hq-token';
        var tenants = [];

        function $(s) { return document.querySelector(s); }
        function esc(x) { var d = document.createElement('div'); d.textContent = x == null ? '' : String(x); return d.innerHTML; }
        function authH() { return { Authorization: 'Bearer ' + (sessionStorage.getItem(TK) || '') }; }

        function show(id) {
          ['login', 'dash', 'blocked'].forEach(function (x) { $('#' + x).style.display = x === id ? 'block' : 'none'; });
        }

        function pill(cls, txt) { return '<span class="pill ' + cls + '">' + esc(txt) + '</span>'; }
        function statusPill(t) {
          if (t.status === 'SUSPENDED') return pill('bad', 'Suspended');
          if (t.subscriptionStatus === 'TRIALING') return pill('warn', 'Trial');
          if (t.subscriptionStatus === 'ACTIVE') return pill('ok', 'Active');
          return pill('dim', t.subscriptionStatus || t.status || '—');
        }

        function render() {
          var q = ($('#q').value || '').toLowerCase();
          var list = tenants.filter(function (t) {
            return !q || (t.slug || '').toLowerCase().includes(q) || (t.displayName || '').toLowerCase().includes(q);
          });
          $('#rows').innerHTML = list.map(function (t) {
            var trial = t.trialEndsAt ? new Date(t.trialEndsAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '—';
            var suspended = t.status === 'SUSPENDED';
