              '<td><b>' + esc(t.displayName || t.slug) + '</b><div class="slug">' + esc(t.slug) + '</div></td>' +
              '<td>' + pill('dim', t.plan || '—') + '</td>' +
              '<td>' + statusPill(t) + '</td>' +
              '<td style="color:var(--muted);">' + trial + '</td>' +
              '<td><div class="acts">' +
                '<a class="btn ghost sm" target="_blank" rel="noopener" href="https://' + esc(t.slug) + '.' + location.host.split('.').slice(1).join('.') + '/admin/login">Open</a>' +
                (suspended
                  ? '<button class="btn sm" data-act="activate" data-slug="' + esc(t.slug) + '">Reactivate</button>'
                  : '<button class="btn danger sm" data-act="suspend" data-slug="' + esc(t.slug) + '">Suspend</button>') +
              '</div></td></tr>';
