          $('#rows').querySelectorAll('button[data-act]').forEach(function (b) {
            b.addEventListener('click', function () {
              var slug = b.dataset.slug, act = b.dataset.act;
              var verb = act === 'suspend' ? 'Suspend' : 'Reactivate';
              if (!confirm(verb + ' "' + slug + '"?' + (act === 'suspend' ? ' Their admin pages pause immediately.' : ''))) return;
              fetch('/api/saas/tenants/' + encodeURIComponent(slug) + '/status', {
                method: 'PATCH',
                headers: Object.assign({ 'Content-Type': 'application/json' }, authH()),
                body: JSON.stringify({ status: act === 'suspend' ? 'SUSPENDED' : 'ACTIVE' }),
              }).then(function (r) { if (r.ok) load(); else alert('Action failed (' + r.status + ').'); });
            });
          });
        }

        function kpis() {
          var total = tenants.length;
          var trialing = tenants.filter(function (t) { return t.subscriptionStatus === 'TRIALING' && t.status !== 'SUSPENDED'; }).length;
          var active = tenants.filter(function (t) { return t.subscriptionStatus === 'ACTIVE' && t.status !== 'SUSPENDED'; }).length;
          var suspended = tenants.filter(function (t) { return t.status === 'SUSPENDED'; }).length;
          var endingSoon = tenants.filter(function (t) {
            return t.trialEndsAt && t.status !== 'SUSPENDED' && t.subscriptionStatus === 'TRIALING' &&
              (new Date(t.trialEndsAt) - Date.now()) < 7 * 864e5 && new Date(t.trialEndsAt) > Date.now();
          }).length;
          var prices = { STARTER: 29, GROWTH: 79, PRO: 199 };
          var mrr = tenants.filter(function (t) { return t.subscriptionStatus === 'ACTIVE' && t.status !== 'SUSPENDED'; })
            .reduce(function (s, t) { return s + (prices[t.plan] || 0); }, 0);
          $('#kpis').innerHTML =
            '<div class="kpi"><small>Studios</small><b>' + total + '</b><em>' + active + ' paying · ' + trialing + ' on trial</em></div>' +
            '<div class="kpi"><small>Trials ending soon</small><b>' + endingSoon + '</b><em>within 7 days</em></div>' +
            '<div class="kpi"><small>Est. MRR</small><b>$' + mrr.toLocaleString() + '</b><em>from active plans</em></div>' +
            '<div class="kpi"><small>Suspended</small><b>' + suspended + '</b><em>paused studios</em></div>';
