              return r.ok ? r.json() : Promise.reject(r.status);
            })
            .then(function (list) {
              if (!list) return;
              tenants = list;
              show('dash');
              $('#logoutBtn').style.display = '';
              kpis(); render();
            })
            .catch(function () { show('blocked'); });
        }

