        $('#loginBtn').addEventListener('click', function () {
          $('#loginErr').style.display = 'none';
          fetch('/api/auth/login', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: $('#lEmail').value.trim(), password: $('#lPass').value }),
          }).then(function (r) { return r.ok ? r.json() : Promise.reject(r.status); })
            .then(function (d) { sessionStorage.setItem(TK, d.token); load(); })
            .catch(function () { $('#loginErr').textContent = 'Sign-in failed.'; $('#loginErr').style.display = 'block'; });
        });
        $('#lPass').addEventListener('keydown', function (e) { if (e.key === 'Enter') $('#loginBtn').click(); });

        load();
      })();
    </script>
  </body>
</html>

