/// <summary>
/// Platform finances for Mission Control: each studio's collected revenue
/// this calendar month (in that studio's own currency) plus plan mix.
/// Cross-tenant read — control-plane only.
/// </summary>
[HttpGet("finances")]
public async Task<IActionResult> GetFinances([FromServices] IServiceProvider services, CancellationToken ct)
{
    if (GuardControlPlane() is { } deny) return deny;

    var tenants = await _provisioning.ListTenantsAsync(ct);
    var monthStart = new DateTime(DateTime.UtcNow.Year, DateTime.UtcNow.Month, 1, 0, 0, 0, DateTimeKind.Utc);
    var rows = new List<object>();

    foreach (var t in tenants)
    {
        decimal revenue = 0; string currency = ""; long payments = 0;
        try
        {
            using var scope = services.CreateScope();
            scope.ServiceProvider.GetRequiredService<Core.Multitenancy.ITenantContext>()
                .SetDatabase(t.DatabaseName, t.Id, t.Slug);
            var db = scope.ServiceProvider.GetRequiredService<Infrastructure.Data.MongoDbContext>();

            var pays = db.GetCollection<Core.Entities.Payment>("Payments");
            var monthPays = await pays
                .Find(p => p.PaymentDate >= monthStart)
                .Project(p => p.AmountPaid)
                .ToListAsync(ct);
            revenue = monthPays.Sum();
            payments = monthPays.Count;

            var settings = await db.GetCollection<Core.Entities.GlobalSettings>("Settings")
                .Find(_ => true).FirstOrDefaultAsync(ct);
            currency = settings?.Profile?.Currency ?? "";
        }
        catch { /* an unreadable tenant shouldn't break the whole rollup */ }

        rows.Add(new
        {
            t.Slug,
            t.DisplayName,
            plan = t.Plan,
            subscriptionStatus = t.SubscriptionStatus,
            status = t.Status,
            revenueThisMonth = revenue,
            paymentsThisMonth = payments,
            currency,
        });
    }

    return Ok(new { monthStart, studios = rows });
}

