using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Configuration;
using SoulPilates.Core.Multitenancy;

namespace SoulPilates.API.Controllers;

/// <summary>
/// SaaS control plane — manage licensed studios (tenants). Restricted to the
/// super-admin: an Admin authenticated on the CONTROL-PLANE host (the bare base
/// domain, no tenant subdomain). A tenant's own admin can never reach it because
/// their requests resolve a tenant, which this controller rejects.
/// </summary>
[ApiController]
[Route("api/saas")]
[Authorize(Roles = "Admin")]
public class SaasController : ControllerBase
{
    private readonly ITenantProvisioningService _provisioning;
    private readonly ITenantContext _tenant;
    private readonly string _baseDomain;

    public SaasController(ITenantProvisioningService provisioning, ITenantContext tenant, IConfiguration config)
    {
        _provisioning = provisioning;
        _tenant = tenant;
        _baseDomain = config["Saas:BaseDomain"] ?? "studionexis.soulpilates.com.vn";
    }

    private IActionResult? GuardControlPlane() =>
        _tenant.IsResolved
            ? StatusCode(403, new { message = "Tenant management is only available on the control-plane host." })
            : null;

    [HttpPost("tenants")]
    public async Task<IActionResult> CreateTenant([FromBody] CreateTenantRequest req)
    {
        if (GuardControlPlane() is { } deny) return deny;
        try
        {
            var t = await _provisioning.CreateTenantAsync(req.Slug, req.DisplayName, req.AdminEmail, req.AdminPassword);
            return Ok(new { t.Id, t.Slug, t.DisplayName, t.DatabaseName, t.Status, t.Plan });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Public self-serve signup — a studio provisions its own trial from the
    /// marketing site. Anonymous, but control-plane-host-only. (Production would
    /// add email verification / captcha; the rate limiter guards abuse for now.)
    /// </summary>
    [AllowAnonymous]
    [HttpPost("signup")]
    public async Task<IActionResult> Signup([FromBody] CreateTenantRequest req)
    {
        if (GuardControlPlane() is { } deny) return deny;
        try
        {
            var t = await _provisioning.CreateTenantAsync(req.Slug, req.DisplayName, req.AdminEmail, req.AdminPassword);
            return Ok(new
            {
                t.Slug,
                t.DisplayName,
                url = $"https://{t.Slug}.{_baseDomain}",
            });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpGet("tenants")]
    public async Task<IActionResult> ListTenants()
    {
        if (GuardControlPlane() is { } deny) return deny;
        var tenants = await _provisioning.ListTenantsAsync();
        return Ok(tenants.Select(t => new
        {
            t.Id, t.Slug, t.DisplayName, t.Status, t.Plan,
            t.SubscriptionStatus, t.TrialEndsAt, t.CreatedAt, t.SuspendedAt,
            licenseValid = t.IsLicenseValid(DateTime.UtcNow),
        }));
    }

    /// <summary>Update a tenant's plan / subscription state / trial (super-admin).</summary>
    [HttpPatch("tenants/{slug}/subscription")]
    public async Task<IActionResult> SetSubscription(string slug, [FromBody] SetSubscriptionRequest req)
    {
        if (GuardControlPlane() is { } deny) return deny;
        try
        {
            var t = await _provisioning.SetSubscriptionAsync(slug, req.Plan, req.SubscriptionStatus, req.ExtendTrialDays);
            return t is null ? NotFound(new { message = "Studio not found." })
                             : Ok(new { t.Slug, t.Plan, t.SubscriptionStatus, t.TrialEndsAt, licenseValid = t.IsLicenseValid(DateTime.UtcNow) });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpPatch("tenants/{slug}/status")]
    public async Task<IActionResult> SetStatus(string slug, [FromBody] SetTenantStatusRequest req)
    {
        if (GuardControlPlane() is { } deny) return deny;
        try
        {
            var ok = await _provisioning.SetStatusAsync(slug, req.Status);
            return ok ? Ok(new { message = $"Studio '{slug}' → {req.Status}." })
                      : NotFound(new { message = "Studio not found." });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }
}

public class CreateTenantRequest
{
    public string Slug { get; set; } = null!;
    public string DisplayName { get; set; } = "";
    public string AdminEmail { get; set; } = null!;
    public string AdminPassword { get; set; } = null!;
}

public class SetTenantStatusRequest
{
    public string Status { get; set; } = null!;
}

public class SetSubscriptionRequest
{
    public string? Plan { get; set; }
    public string? SubscriptionStatus { get; set; }
    public int? ExtendTrialDays { get; set; }
}

