    public async Task<Tenant?> ResolveByCustomDomainAsync(string host, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(host)) return null;
        host = host.ToLowerInvariant();
        var key = "domain:" + host;

        if (_cache.TryGetValue(key, out var hit) && DateTime.UtcNow - hit.cachedAt < CacheTtl)
            return hit.tenant;

        var tenant = await _control.Tenants
            .Find(t => t.CustomDomain == host && t.Status == "ACTIVE")
            .FirstOrDefaultAsync(ct);

        _cache[key] = (tenant, DateTime.UtcNow);
        return tenant;
    }

    public void Invalidate(string slug)
    {
        if (!string.IsNullOrWhiteSpace(slug))
            _cache.TryRemove(slug.ToLowerInvariant(), out _);
        // Domain-keyed entries are cheap to nuke wholesale on any change.
        foreach (var k in _cache.Keys)
            if (k.StartsWith("domain:")) _cache.TryRemove(k, out _);
    }
}

