using System.Text.RegularExpressions;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MongoDB.Driver;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Multitenancy;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Provisions and manages SaaS tenants. Each tenant gets an isolated Mongo
/// database (created lazily on first write) seeded with its own admin account.
/// </summary>
public class TenantProvisioningService : ITenantProvisioningService
{
    private static readonly Regex SlugRule = new("^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])?$", RegexOptions.Compiled);
    private static readonly HashSet<string> Reserved = new(StringComparer.OrdinalIgnoreCase)
        { "www", "app", "api", "admin", "studionexis", "mail", "smtp", "control", "static", "assets" };

    private readonly ControlPlaneContext _control;
    private readonly ITenantRegistry _registry;
    private readonly IServiceProvider _services;
    private readonly MongoDbSettings _settings;
    private readonly ILogger<TenantProvisioningService> _logger;

    public TenantProvisioningService(
        ControlPlaneContext control,
        ITenantRegistry registry,
        IServiceProvider services,
        IOptions<MongoDbSettings> settings,
        ILogger<TenantProvisioningService> logger)
    {
        _control = control;
        _registry = registry;
        _services = services;
        _settings = settings.Value;
        _logger = logger;
    }

    public async Task<Tenant> CreateTenantAsync(string slug, string displayName, string adminEmail, string adminPassword, CancellationToken ct = default)
    {
        slug = (slug ?? "").Trim().ToLowerInvariant();
        if (!SlugRule.IsMatch(slug))
            throw new InvalidOperationException("Slug must be 2–40 chars, lowercase letters/numbers/hyphens, not starting/ending with a hyphen.");
        if (Reserved.Contains(slug))
            throw new InvalidOperationException($"'{slug}' is reserved.");
        if (string.IsNullOrWhiteSpace(adminEmail) || string.IsNullOrWhiteSpace(adminPassword))
            throw new InvalidOperationException("Admin email and password are required.");

        var exists = await _control.Tenants.Find(t => t.Slug == slug).AnyAsync(ct);
        if (exists) throw new InvalidOperationException($"A studio with slug '{slug}' already exists.");

        var tenant = new Tenant
        {
            Slug = slug,
            DisplayName = string.IsNullOrWhiteSpace(displayName) ? slug : displayName.Trim(),
            DatabaseName = _settings.TenantDbPrefix + slug,   // e.g. tenant_studio-a
            Status = "ACTIVE",
            Plan = "STARTER",
            SubscriptionStatus = "TRIALING",
            TrialEndsAt = DateTime.UtcNow.AddDays(14),
        };
        await _control.Tenants.InsertOneAsync(tenant, cancellationToken: ct);

        // Seed the tenant's own database with its first admin. We open a DI scope
        // and bind ITenantContext to the new tenant BEFORE resolving MongoDbContext,
        // so the context (and thus the insert) targets the tenant database.
        try
        {
            using var scope = _services.CreateScope();
            scope.ServiceProvider.GetRequiredService<ITenantContext>()
                .SetDatabase(tenant.DatabaseName, tenant.Id, tenant.Slug);
            var db = scope.ServiceProvider.GetRequiredService<MongoDbContext>();
            var users = db.GetCollection<User>("Users");

            var email = adminEmail.Trim().ToLowerInvariant();
            await users.InsertOneAsync(new User
            {
                Name = tenant.DisplayName + " Admin",
                Email = email,
                PasswordHash = PasswordHasher.Hash(adminPassword.Trim()),
                Role = "Admin",
            }, cancellationToken: ct);

            // New studios start simple: the single-studio power tools are
            // opt-in (Settings → Team Access). Legacy studios keep everything.
            var settingsCol = db.GetCollection<GlobalSettings>("Settings");
            await settingsCol.InsertOneAsync(new GlobalSettings
            {
                DisabledModules = new List<string> { "washout", "kpi-bonus", "studio-rentals", "partners" },
            }, cancellationToken: ct);
        }
        catch (Exception ex)
        {
            // Roll back the control record if seeding the tenant DB failed, so a
            // half-provisioned studio can't linger in the registry.
            _logger.LogError(ex, "Provisioning seed failed for '{Slug}' — rolling back control record.", slug);
            await _control.Tenants.DeleteOneAsync(t => t.Id == tenant.Id, ct);
            throw;
        }

        _registry.Invalidate(slug);
        _logger.LogInformation("Provisioned tenant '{Slug}' → db '{Db}'.", slug, tenant.DatabaseName);
        return tenant;
    }

    public async Task<List<Tenant>> ListTenantsAsync(CancellationToken ct = default) =>
        await _control.Tenants.Find(FilterDefinition<Tenant>.Empty)
            .SortBy(t => t.Slug).ToListAsync(ct);

    public async Task<bool> SetStatusAsync(string slug, string status, CancellationToken ct = default)
    {
        slug = (slug ?? "").Trim().ToLowerInvariant();
        status = status?.Trim().ToUpperInvariant() ?? "";
        if (status is not ("ACTIVE" or "SUSPENDED"))
            throw new InvalidOperationException("Status must be ACTIVE or SUSPENDED.");

        var update = Builders<Tenant>.Update
            .Set(t => t.Status, status)
            .Set(t => t.SuspendedAt, status == "SUSPENDED" ? DateTime.UtcNow : (DateTime?)null);
        var res = await _control.Tenants.UpdateOneAsync(t => t.Slug == slug, update, cancellationToken: ct);
        _registry.Invalidate(slug);
        return res.MatchedCount > 0;
    }

    public async Task<Tenant?> SetSubscriptionAsync(string slug, string? plan, string? subscriptionStatus, int? extendTrialDays, CancellationToken ct = default)
    {
        slug = (slug ?? "").Trim().ToLowerInvariant();
        var updates = new List<UpdateDefinition<Tenant>>();
        if (!string.IsNullOrWhiteSpace(plan))
            updates.Add(Builders<Tenant>.Update.Set(t => t.Plan, plan.Trim().ToUpperInvariant()));
        if (!string.IsNullOrWhiteSpace(subscriptionStatus))
        {
            var s = subscriptionStatus.Trim().ToUpperInvariant();
            if (s is not ("TRIALING" or "ACTIVE" or "PAST_DUE" or "CANCELED"))
                throw new InvalidOperationException("SubscriptionStatus must be TRIALING, ACTIVE, PAST_DUE, or CANCELED.");
            updates.Add(Builders<Tenant>.Update.Set(t => t.SubscriptionStatus, s));
            // Moving onto a paid subscription clears the trial clock.
            if (s == "ACTIVE") updates.Add(Builders<Tenant>.Update.Set(t => t.TrialEndsAt, (DateTime?)null));
        }
        if (extendTrialDays is int days)
            updates.Add(Builders<Tenant>.Update.Set(t => t.TrialEndsAt, DateTime.UtcNow.AddDays(days)));

        if (updates.Count == 0) return await _control.Tenants.Find(t => t.Slug == slug).FirstOrDefaultAsync(ct);

        await _control.Tenants.UpdateOneAsync(t => t.Slug == slug,
            Builders<Tenant>.Update.Combine(updates), cancellationToken: ct);
        _registry.Invalidate(slug);
        return await _control.Tenants.Find(t => t.Slug == slug).FirstOrDefaultAsync(ct);
    }
}

