/// <summary>
/// Connect the studio's own domain (or clear it with a blank value). The
/// studio admin manages this from Settings → Website; TLS provisioning for
/// the new domain is completed platform-side.
/// </summary>
[Authorize(Roles = "Admin")]
[HttpPatch("custom-domain")]
public async Task<IActionResult> SetCustomDomain([FromBody] CustomDomainRequest req, CancellationToken ct)
{
    if (string.IsNullOrEmpty(_tenant.Slug)) return NotFound(new { message = "No studio on this host." });
    try
    {
        var t = await _provisioning.SetCustomDomainAsync(_tenant.Slug, req.Domain, ct);
        return t is null ? NotFound(new { message = "Unknown studio." }) : Ok(new { customDomain = t.CustomDomain });
    }
    catch (InvalidOperationException ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

