(function () {
  var authH2 = { Authorization: "Bearer " + (localStorage.getItem("token") || "") };
  function reflect(domain) {
    document.getElementById("cdDomain").value = domain || "";
    document.getElementById("cdClear").style.display = domain ? "" : "none";
    document.getElementById("cdSteps").style.display = domain ? "block" : "none";
    if (domain) document.getElementById("cdHost").textContent = domain;
  }
  fetch("/api/me/plan", { headers: authH2 })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (p) { if (p) reflect(p.customDomain); }).catch(function () {});

  function save(domain) {
    var msg = document.getElementById("cdMsg");
    msg.style.color = "var(--color-text-muted)"; msg.textContent = "Saving…";
    fetch("/api/me/custom-domain", {
      method: "PATCH",
      headers: Object.assign({ "Content-Type": "application/json" }, authH2),
      body: JSON.stringify({ domain: domain }),
    }).then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
      .then(function (res) {
        if (res.ok) {
          reflect(res.j.customDomain);
          msg.style.color = "var(--color-success)";
          msg.textContent = res.j.customDomain ? "Connected — follow the steps below." : "Disconnected.";
        } else {
          msg.style.color = "var(--color-danger)";
          msg.textContent = res.j.message || "Could not save.";
        }
      });
  }
  document.getElementById("cdSave").addEventListener("click", function () { save(document.getElementById("cdDomain").value.trim()); });
  document.getElementById("cdClear").addEventListener("click", function () { if (confirm("Disconnect your custom domain?")) save(""); });
})();

// ── Optional modules (studio-level feature flags) ─────────────────────

