11	/// SaaS control plane — manage licensed studios (tenants). Restricted to the
12	/// super-admin: an Admin authenticated on the CONTROL-PLANE host (the bare base
13	/// domain, no tenant subdomain). A tenant's own admin can never reach it because
14	/// their requests resolve a tenant, which this controller rejects.
15	/// </summary>
16	[ApiController]
17	[Route("api/saas")]
18	[Authorize(Roles = "Admin")]
19	public class SaasController : ControllerBase
20	{
21	    private readonly ITenantProvisioningService _provisioning;
22	    private readonly ITenantContext _tenant;
23	    private readonly string _baseDomain;
24	
25	    public SaasController(ITenantProvisioningService provisioning, ITenantContext tenant, IConfiguration config)
26	    {
27	        _provisioning = provisioning;
28	        _tenant = tenant;
29	        _baseDomain = config["Saas:BaseDomain"] ?? "studionexis.soulpilates.com.vn";
30	    }
31	
32	    private IActionResult? GuardControlPlane() =>
33	        _tenant.IsResolved
34	            ? StatusCode(403, new { message = "Tenant management is only available on the control-plane host." })
35	            : null;
36	
37	    [HttpPost("tenants")]
38	    public async Task<IActionResult> CreateTenant([FromBody] CreateTenantRequest req)
39	    {
40	        if (GuardControlPlane() is { } deny) return deny;
41	        try
42	        {
43	            var t = await _provisioning.CreateTenantAsync(req.Slug, req.DisplayName, req.AdminEmail, req.AdminPassword);
44	            return Ok(new { t.Id, t.Slug, t.DisplayName, t.DatabaseName, t.Status, t.Plan });
45	        }
46	        catch (Exception ex)
47	        {
48	            return BadRequest(new { message = ex.Message });
49	        }
50	    }
51	
52	    /// <summary>
53	    /// Public self-serve signup — a studio provisions its own trial from the
54	    /// marketing site. Anonymous, but control-plane-host-only. (Production would
55	    /// add email verification / captcha; the rate limiter guards abuse for now.)
56	    /// </summary>
57	    [AllowAnonymous]
58	    [HttpPost("signup")]
59	    public async Task<IActionResult> Signup([FromBody] CreateTenantRequest req)
60	    {
61	        if (GuardControlPlane() is { } deny) return deny;
62	        try
63	        {
64	            var t = await _provisioning.CreateTenantAsync(req.Slug, req.DisplayName, req.AdminEmail, req.AdminPassword);
65	            return Ok(new
66	            {
67	                t.Slug,
68	                t.DisplayName,
69	                url = $"https://{t.Slug}.{_baseDomain}",
70	            });
71	        }
72	        catch (Exception ex)
73	        {
74	            return BadRequest(new { message = ex.Message });
75	        }
76	    }
77	
78	    /// <summary>
79	    /// Platform finances for Mission Control: each studio's collected revenue
80	    /// this calendar month (in that studio's own currency) plus plan mix.
81	    /// Cross-tenant read — control-plane only.
82	    /// </summary>
83	    [HttpGet("finances")]
84	    public async Task<IActionResult> GetFinances([FromServices] IServiceProvider services, CancellationToken ct)
85	    {
86	        if (GuardControlPlane() is { } deny) return deny;
87	
88	        var tenants = await _provisioning.ListTenantsAsync(ct);
89	        var monthStart = new DateTime(DateTime.UtcNow.Year, DateTime.UtcNow.Month, 1, 0, 0, 0, DateTimeKind.Utc);
90	        var rows = new List<object>();
91	
92	        foreach (var t in tenants)
93	        {
94	            decimal revenue = 0; var currency = ""; var payments = 0;
95	            try
96	            {
97	                using var scope = services.CreateScope();
98	                scope.ServiceProvider.GetRequiredService<ITenantContext>()
99	                    .SetDatabase(t.DatabaseName, t.Id, t.Slug);
100	                var db = scope.ServiceProvider.GetRequiredService<Infrastructure.Data.MongoDbContext>();
101	
102	                var monthPays = await db.GetCollection<Core.Entities.Payment>("Payments")
103	                    .Find(p => p.PaymentDate >= monthStart)
104	                    .Project(p => p.AmountPaid)
105	                    .ToListAsync(ct);
106	                revenue = monthPays.Sum();
107	                payments = monthPays.Count;
108	
109	                var settings = await db.GetCollection<Core.Entities.GlobalSettings>("Settings")
110	                    .Find(FilterDefinition<Core.Entities.GlobalSettings>.Empty)
111	                    .FirstOrDefaultAsync(ct);
112	                currency = settings?.Profile?.Currency ?? "";
113	            }
114	            catch { /* an unreadable tenant must not break the whole rollup */ }
115	
116	            rows.Add(new
117	            {
118	                t.Slug,
119	                t.DisplayName,
120	                plan = t.Plan,
121	                subscriptionStatus = t.SubscriptionStatus,
122	                status = t.Status,
123	                revenueThisMonth = revenue,
124	                paymentsThisMonth = payments,
125	                currency,
126	            });
127	        }
128	
129	        return Ok(new { monthStart, studios = rows });
130	    }
131	
132	    [HttpGet("tenants")]
133	    public async Task<IActionResult> ListTenants()
134	    {
135	        if (GuardControlPlane() is { } deny) return deny;
136	        var tenants = await _provisioning.ListTenantsAsync();
137	        return Ok(tenants.Select(t => new
138	        {
139	            t.Id, t.Slug, t.DisplayName, t.Status, t.Plan,
140	            t.SubscriptionStatus, t.TrialEndsAt, t.CreatedAt, t.SuspendedAt, t.CustomDomain,
141	            licenseValid = t.IsLicenseValid(DateTime.UtcNow),
142	        }));
143	    }
144	
145	    /// <summary>Update a tenant's plan / subscription state / trial (super-admin).</summary>
146	    [HttpPatch("tenants/{slug}/subscription")]
147	    public async Task<IActionResult> SetSubscription(string slug, [FromBody] SetSubscriptionRequest req)
148	    {
149	        if (GuardControlPlane() is { } deny) return deny;
150	        try
151	        {
152	            var t = await _provisioning.SetSubscriptionAsync(slug, req.Plan, req.SubscriptionStatus, req.ExtendTrialDays);
153	            return t is null ? NotFound(new { message = "Studio not found." })
154	                             : Ok(new { t.Slug, t.Plan, t.SubscriptionStatus, t.TrialEndsAt, licenseValid = t.IsLicenseValid(DateTime.UtcNow) });
155	        }
156	        catch (Exception ex)
157	        {
158	            return BadRequest(new { message = ex.Message });
159	        }
160	    }
161	
162	    [HttpPatch("tenants/{slug}/status")]
163	    public async Task<IActionResult> SetStatus(string slug, [FromBody] SetTenantStatusRequest req)
164	    {
165	        if (GuardControlPlane() is { } deny) return deny;
166	        try
167	        {
168	            var ok = await _provisioning.SetStatusAsync(slug, req.Status);
169	            return ok ? Ok(new { message = $"Studio '{slug}' → {req.Status}." })
170	                      : NotFound(new { message = "Studio not found." });
171	        }
172	        catch (Exception ex)
173	        {
174	            return BadRequest(new { message = ex.Message });
175	        }
176	    }
177	}
178	
179	public class CreateTenantRequest
180	{
181	    public string Slug { get; set; } = null!;
182	    public string DisplayName { get; set; } = "";
183	    public string AdminEmail { get; set; } = null!;
184	    public string AdminPassword { get; set; } = null!;
185	}
186	
187	public class SetTenantStatusRequest
188	{
189	    public string Status { get; set; } = null!;
190	}
191	
192	public class SetSubscriptionRequest
193	{
194	    public string? Plan { get; set; }
195	    public string? SubscriptionStatus { get; set; }
196	    public int? ExtendTrialDays { get; set; }
197	}

