// ── Studio identity card ────────────────────────────────────────────────
(function () {
  var authI = { Authorization: "Bearer " + (localStorage.getItem("token") || "") };
  var profile = null;
  var CURS = ["USD","CAD","EUR","GBP","AUD","NZD","VND","THB","SGD","HKD","JPY","KRW","INR","AED","MXN","BRL"];
  var TZS = ["Pacific/Honolulu","America/Los_Angeles","America/Denver","America/Chicago","America/New_York","America/Toronto","America/Sao_Paulo","Europe/London","Europe/Paris","Europe/Berlin","Europe/Madrid","Europe/Rome","Asia/Dubai","Asia/Kolkata","Asia/Bangkok","Asia/Ho_Chi_Minh","Asia/Singapore","Asia/Hong_Kong","Asia/Tokyo","Australia/Sydney","Pacific/Auckland"];
  try { if (Intl.supportedValuesOf) TZS = Intl.supportedValuesOf("timeZone"); } catch (e) {}
  document.getElementById("idCurrency").innerHTML = CURS.map(function (c) { return "<option>" + c + "</option>"; }).join("");
  document.getElementById("idTz").innerHTML = TZS.map(function (z) { return "<option>" + z + "</option>"; }).join("");

  nxSettingsOnce.then(function (s) {
    profile = s.profile || {};
    if (profile.studioName) document.getElementById("idName").value = profile.studioName;
    if (profile.currency) document.getElementById("idCurrency").value = profile.currency;
    if (profile.timeZone) document.getElementById("idTz").value = profile.timeZone;
    if (profile.language) document.getElementById("idLang").value = profile.language;
    if (profile.logoUrl) { var im = document.getElementById("idLogoImg"); im.src = profile.logoUrl; im.style.display = "inline-block"; }
  }).catch(function () {});

  document.getElementById("idLogoBtn").addEventListener("click", function () { document.getElementById("idLogoFile").click(); });
  document.getElementById("idLogoFile").addEventListener("change", function () {
    var f = this.files[0]; if (!f) return;
    var fd = new FormData(); fd.append("file", f);
    fetch("/api/media/studio-logo", { method: "POST", headers: authI, body: fd })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        if (j.url) {
          if (profile) profile.logoUrl = j.url;
          var im = document.getElementById("idLogoImg"); im.src = j.url; im.style.display = "inline-block";
        }
      });
    this.value = "";
  });

  document.getElementById("idSave").addEventListener("click", function () {
    if (!profile) return;
    profile.studioName = document.getElementById("idName").value.trim();
    profile.currency = document.getElementById("idCurrency").value;
    profile.timeZone = document.getElementById("idTz").value;
    profile.language = document.getElementById("idLang").value;
    fetch("/api/settings/profile", {
      method: "PATCH",
      headers: Object.assign({ "Content-Type": "application/json" }, authI),
      body: JSON.stringify(profile),
    }).then(function (r) {
      if (r.ok) { var m = document.getElementById("idMsg"); m.style.display = "inline"; setTimeout(function () { m.style.display = "none"; }, 4000); }
    });
  });
})();

