cd /opt/studionexis/SoulPilates.Astro && cat >> src/styles/global.css <<'EOF'

/* ═══════════════════════════════════════════════════════════════════
   EMBER SHELL — the "feels different" layer (2026-07-08)
   Dark rail + light canvas, bigger editorial type, taller airier tables,
   floating cards. Geometry and contrast, not just labels.
   ═══════════════════════════════════════════════════════════════════ */

/* ── The dark rail: fix sub-elements that assumed a light sidebar ── */
.sidebar { box-shadow: 4px 0 24px rgba(20, 15, 8, 0.12); }
.sidebar .nav-section-label { color: rgba(255, 255, 255, 0.34); }
.sidebar .sidebar-logo-text { color: #fff; }
.sidebar .sidebar-logo-sub { color: rgba(255, 255, 255, 0.4); }
.sidebar .collapse-toggle { color: rgba(255, 255, 255, 0.5); }
.sidebar .collapse-toggle:hover { color: #fff; background: rgba(255, 255, 255, 0.08); }
.sidebar .sidebar-status-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.sidebar .sidebar-status-title { color: rgba(255, 255, 255, 0.85); }
.sidebar .sidebar-status-sub { color: rgba(255, 255, 255, 0.4); }
.sidebar .theme-toggle { color: var(--color-sidebar-text); }
.sidebar .theme-toggle:hover { color: #fff; background: rgba(255, 255, 255, 0.06); }
.sidebar .nav-item.active {
  background: var(--gradient-brand);
  color: #fff;
  box-shadow: 0 4px 14px rgba(249, 115, 22, 0.35);
}
.sidebar .nav-item.active .nav-icon { color: #fff; }
.sidebar .nav-item.active::before { display: none; }
.sidebar .nav-adv-group { border-left-color: rgba(255, 255, 255, 0.12); }

/* ── Canvas & cards: float, don't tile ── */
body { background: var(--color-bg); }
.card {
  border-radius: 18px;
  border-color: var(--color-border-subtle);
  box-shadow: 0 1px 2px rgba(28, 23, 17, 0.04), 0 10px 30px rgba(28, 23, 17, 0.05);
}
[data-theme="dark"] .card { box-shadow: var(--shadow-card); }

/* ── Editorial page headers ── */
.page-title {
  font-family: var(--font-display) !important;
  font-size: 27px !important;
  font-weight: 800 !important;
  letter-spacing: -0.03em !important;
  line-height: 1.15;
}
.page-subtitle { font-size: 13.5px; margin-top: 4px; }
.page-header { margin-bottom: 26px; }

/* ── Tables: taller, calmer, hover that answers you ── */
.data-table thead th {
  font-size: 10.5px !important;
  font-weight: 800 !important;
  letter-spacing: 0.09em !important;
  text-transform: uppercase !important;
  padding: 12px 16px !important;
  color: var(--color-text-muted) !important;
}
.data-table tbody td { padding: 14px 16px !important; font-size: 13.5px; }
.data-table tbody tr { transition: background 0.12s ease; }
.data-table tbody tr:hover td { background: var(--color-surface-raised); }

/* ── Topbar: quiet glass strip ── */
.topbar {
  background: color-mix(in srgb, var(--color-bg) 82%, transparent);
  backdrop-filter: blur(12px);
}
.topbar-kicker { font-size: 10.5px; }
.topbar-breadcrumb { font-weight: 700; font-family: var(--font-display); }

/* ── Buttons: decisive shapes ── */
.btn { border-radius: 11px; font-weight: 700; }
.btn-primary { box-shadow: 0 5px 16px rgba(249, 115, 22, 0.30), inset 0 1px 0 rgba(255, 255, 255, 0.22); }
.btn-primary:hover { transform: translateY(-1px); }
.btn-sm { border-radius: 9px; }

/* ── Forms: soft wells ── */
.form-control {
  border-radius: 11px;
  background: var(--color-surface);
}
.form-control:focus {
  border-color: var(--color-brand-accent);
  box-shadow: 0 0 0 3px var(--color-brand-accent-soft);
}

/* ── Badges: pill discipline ── */
.badge { border-radius: 999px; font-weight: 700; letter-spacing: 0.02em; }

/* ── Breathing room ── */
.content-area { padding-top: 26px; }
EOF
wc -l src/styles/global.css

