input.old_string:
/* ═══════════════════════════════════════════════════════════════════
   EMBER SHELL — the "feels different" layer (2026-07-08)
   Dark rail + light canvas, bigger editorial type, taller airier tables,
   floating cards. Geometry and contrast, not just labels.
   ═══════════════════════════════════════════════════════════════════ */

/* ── The dark rail: fix sub-elements that assumed a light sidebar ── */
.sidebar { box-shadow: 4px 0 24px rgba(20, 15, 8, 0.12); }
.sidebar .nav-section-label { color: rgba(255, 255, 255, 0.34); }
.sidebar .sidebar-logo-text { color: #fff; }
.sidebar .sidebar-logo-sub { color: rgba(255, 255, 255, 0.4); }
.sidebar .collapse-toggle { color: rgba(255, 255, 255, 0.5); }
.sidebar .collapse-toggle:hover { color: #fff; background: rgba(255, 255, 255, 0.08); }
.sidebar .sidebar-status-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.sidebar .sidebar-status-title { color: rgba(255, 255, 255, 0.85); }
.sidebar .sidebar-status-sub { color: rgba(255, 255, 255, 0.4); }
.sidebar .theme-toggle { color: var(--color-sidebar-text); }
.sidebar .theme-toggle:hover { color: #fff; background: rgba(255, 255, 255, 0.06); }
.sidebar .nav-item.active {
  background: var(--gradient-brand);
  color: #fff;
  box-shadow: 0 4px 14px rgba(249, 115, 22, 0.35);
}
.sidebar .nav-item.active .nav-icon { color: #fff; }
.sidebar .nav-item.active::before { display: none; }
.sidebar .nav-adv-group { border-left-color: rgba(255, 255, 255, 0.12); }

/* ── Canvas & cards: float, don't tile ── */
body { background: var(--color-bg); }
.card {
  border-radius: 18px;
  border-color: var(--color-border-subtle);
  box-shadow: 0 1px 2px rgba(28, 23, 17, 0.04), 0 10px 30px rgba(28, 23, 17, 0.05);
}
[data-theme="dark"] .card { box-shadow: var(--shadow-card); }

/* ── Editorial page headers ── */
.page-title {
  font-family: var(--font-display) !important;
  font-size: 27px !important;
  font-weight: 800 !important;
  letter-spacing: -0.03em !important;
  line-height: 1.15;
}
.page-subtitle { font-size: 13.5px; margin-top: 4px; }
.page-header { margin-bottom: 26px; }

/* ── Tables: taller, calmer, hover that answers you ── */
.data-table thead th {
  font-size: 10.5px !important;
  font-weight: 800 !important;
  letter-spacing: 0.09em !important;
  text-transform: uppercase !important;
  padding: 12px 16px !important;
  color: var(--color-text-muted) !important;
}
.data-table tbody td { padding: 14px 16px !important; font-size: 13.5px; }
.data-table tbody tr { transition: background 0.12s ease; }
.data-table tbody tr:hover td { background: var(--color-surface-raised); }

/* ── Topbar: quiet glass strip ── */
.topbar {
  background: color-mix(in srgb, var(--color-bg) 82%, transparent);
  backdrop-filter: blur(12px);
}
.topbar-kicker { font-size: 10.5px; }
.topbar-breadcrumb { font-weight: 700; font-family: var(--font-display); }

/* ── Buttons: decisive shapes ── */
.btn { border-radius: 11px; font-weight: 700; }
.btn-primary { box-shadow: 0 5px 16px rgba(249, 115, 22, 0.30), inset 0 1px 0 rgba(255, 255, 255, 0.22); }
.btn-primary:hover { transform: translateY(-1px); }
.btn-sm { border-radius: 9px; }

/* ── Forms: soft wells ── */
.form-control {
  border-radius: 11px;
  background: var(--color-surface);
}
.form-control:focus {
  border-color: var(--color-brand-accent);
  box-shadow: 0 0 0 3px var(--color-brand-accent-soft);
}

/* ── Badges: pill discipline ── */
.badge { border-radius: 999px; font-weight: 700; letter-spacing: 0.02em; }

/* ── Breathing room ── */
.content-area { padding-top: 26px; }

input.new_string:
/* ═══════════════════════════════════════════════════════════════════
   NEXIS REFERENCE SHELL — rebuilt to match the owner's design mockups
   (2026-07-08). Light clean rail · pale-orange active pills · STUDIONEXIS
   wordmark · big bold titles · tinted-icon KPI cards · airy avatar tables.
   Aesthetic target: modern light SaaS (Attio / Linear-light / Notion).
   ═══════════════════════════════════════════════════════════════════ */

/* ── Sidebar: light rail, generous, thin border ── */
.sidebar {
  background: var(--color-sidebar-bg);
  border-right: 1px solid var(--color-sidebar-border);
  box-shadow: none;
}
.sidebar-header { padding: 20px 18px 8px; }

/* STUDIONEXIS wordmark logo */
.nx-wordmark { flex-direction: column; align-items: flex-start; gap: 2px; text-decoration: none; }
.nx-wordmark-row { font-family: var(--font-display); font-weight: 800; font-size: 20px; letter-spacing: -0.01em; line-height: 1; }
.nx-wordmark-row .nx-w1 { color: var(--color-text-primary); }
.nx-wordmark-row .nx-w2 { color: var(--color-brand-accent); }
.nx-wordmark .nx-wordmark-sub { font-size: 9.5px; font-weight: 700; letter-spacing: 0.22em; color: var(--color-text-muted); text-transform: uppercase; }
.sidebar.collapsed .nx-wordmark-sub { display: none; }
.sidebar.collapsed .nx-wordmark-row { font-size: 15px; }

/* Nav sections + items */
.sidebar .nav-section-label {
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.09em;
  text-transform: uppercase; color: var(--color-text-muted);
  padding: 0 12px; margin: 18px 0 6px;
}
.sidebar .nav-item {
  gap: 12px; padding: 9px 12px; border-radius: 10px; margin: 1px 8px;
  font-size: 14px; font-weight: 500; color: var(--color-sidebar-text);
  transition: background .13s ease, color .13s ease;
}
.sidebar .nav-item .nav-icon { width: 19px; height: 19px; color: currentColor; opacity: .9; }
.sidebar .nav-item:hover { background: var(--color-sidebar-item-hover); color: var(--color-text-primary); }
.sidebar .nav-item.active {
  background: var(--color-sidebar-item-active);
  color: var(--color-brand-accent);
  font-weight: 600;
  box-shadow: none;
}
.sidebar .nav-item.active .nav-icon { color: var(--color-brand-accent); opacity: 1; }
.sidebar .nav-item.active::before { display: none; }

/* Advanced group toggle sits in the same rail language */
.sidebar .nav-adv-toggle { margin: 4px 8px; padding: 9px 12px; border-radius: 10px; font-size: 14px; }

/* Bottom promo + user chip */
.sidebar-footer { border-top: 1px solid var(--color-sidebar-border); }
.sidebar .sidebar-status-card {
  background: linear-gradient(135deg, rgba(249,115,22,.07), rgba(249,115,22,.02));
  border: 1px solid #FCE6D6; border-radius: 14px;
}
.sidebar .sidebar-status-title { color: var(--color-text-primary); font-weight: 700; }
.sidebar .sidebar-status-sub { color: var(--color-text-muted); }
.sidebar .theme-toggle { color: var(--color-sidebar-text); border-radius: 10px; }
.sidebar .theme-toggle:hover { color: var(--color-text-primary); background: var(--color-sidebar-item-hover); }
.sidebar .collapse-toggle { color: var(--color-text-muted); }
.sidebar .collapse-toggle:hover { color: var(--color-text-primary); background: var(--color-sidebar-item-hover); }

/* ── Canvas & cards ── */
body { background: var(--color-bg); }
.content-area { padding-top: 24px; }
.card {
  border-radius: 16px;
  border: 1px solid var(--color-border-subtle);
  box-shadow: 0 1px 2px rgba(17,17,19,.04), 0 1px 3px rgba(17,17,19,.03);
}
.card:hover { box-shadow: 0 1px 2px rgba(17,17,19,.05), 0 8px 24px rgba(17,17,19,.06); }

/* ── Page headers: big + bold, gray subtitle (reference) ── */
.page-title {
  font-family: var(--font-display) !important;
  font-size: 30px !important; font-weight: 800 !important;
  letter-spacing: -0.025em !important; line-height: 1.12; color: var(--color-text-primary);
}
.page-subtitle { font-size: 14px; margin-top: 5px; color: var(--color-text-muted); }
.page-header { margin-bottom: 24px; align-items: flex-start; }

/* ── KPI / stat cards: tinted icon square + big number + delta ── */
.nx-kpi { background: var(--color-surface); border: 1px solid var(--color-border-subtle); border-radius: 16px; padding: 18px 18px 16px; box-shadow: 0 1px 2px rgba(17,17,19,.04); }
.nx-kpi-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.nx-kpi-ic { width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; }
.nx-kpi-ic.o { background: #FFF1E8; color: #F97316; }
.nx-kpi-ic.p { background: #F1EEFE; color: #8B5CF6; }
.nx-kpi-ic.g { background: #E9F7EF; color: #22A565; }
.nx-kpi-ic.b { background: #EAF2FE; color: #3B82F6; }
.nx-kpi-delta { font-size: 12px; font-weight: 700; color: #22A565; display: inline-flex; align-items: center; gap: 3px; }
.nx-kpi-delta.down { color: #E5484D; }
.nx-kpi-label { font-size: 12.5px; color: var(--color-text-muted); font-weight: 500; margin-bottom: 3px; }
.nx-kpi-value { font-family: var(--font-display); font-size: 27px; font-weight: 800; letter-spacing: -0.02em; }

/* ── Tables: airy rows, uppercase micro-heads, quiet hover ── */
.data-table thead th {
  font-size: 10.5px !important; font-weight: 700 !important;
  letter-spacing: 0.08em !important; text-transform: uppercase !important;
  padding: 13px 18px !important; color: var(--color-text-muted) !important;
  background: transparent !important; border-bottom: 1px solid var(--color-border-subtle) !important;
}
.data-table tbody td { padding: 15px 18px !important; font-size: 13.5px; border-color: var(--color-border-subtle) !important; }
.data-table tbody tr { transition: background .12s ease; }
.data-table tbody tr:hover td { background: var(--color-surface-raised); }

/* ── Topbar: quiet glass ── */
.topbar {
  background: color-mix(in srgb, var(--color-bg) 80%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-subtle);
}
.topbar-kicker { font-size: 10.5px; color: var(--color-brand-accent); font-weight: 700; }
.topbar-breadcrumb { font-weight: 800; font-family: var(--font-display); letter-spacing: -0.02em; }

/* ── Buttons ── */
.btn { border-radius: 10px; font-weight: 600; }
.btn-primary {
  background: var(--color-brand-accent);
  box-shadow: 0 1px 2px rgba(249,115,22,.24);
}
.btn-primary:hover { background: var(--color-brand-accent-hover); transform: translateY(-1px); }
.btn-secondary { border-radius: 10px; }
.btn-sm { border-radius: 9px; }

/* ── Forms ── */
.form-control { border-radius: 10px; background: var(--color-surface); }
.form-control:focus { border-color: var(--color-brand-accent); box-shadow: 0 0 0 3px var(--color-brand-accent-soft); }

/* ── Badges ── */
.badge { border-radius: 999px; font-weight: 700; letter-spacing: 0.01em; }

/* ── Topbar quick-search adopts the reference search-pill look ── */
.nx-qs { border-radius: 12px; min-width: 240px; background: var(--color-surface); }

