.topbar-breadcrumb { font-weight: 800; font-family: var(--font-display); letter-spacing: -0.02em; }

/* ── Buttons ── */
.btn { border-radius: 10px; font-weight: 600; }
.btn-primary {
  background: var(--color-brand-accent);
