/* ── Forms ── */
.form-control { border-radius: 10px; background: var(--color-surface); }
.form-control:focus { border-color: var(--color-brand-accent); box-shadow: 0 0 0 3px var(--color-brand-accent-soft); }

/* ── Badges ── */
.badge { border-radius: 999px; font-weight: 700; letter-spacing: 0.01em; }

/* ── Topbar quick-search adopts the reference search-pill look ── */
.nx-qs { border-radius: 12px; min-width: 240px; background: var(--color-surface); }

