/* ═══════════════════════════════════════════════════════════════════════
   NEXIS ADMIN — ground-up design system (2026-07-08)
   Written from scratch to the owner's reference mockups. Loaded AFTER
   global.css so it is the authoritative visual layer; the old stylesheet
   is now just a shrinking compatibility base. Light-first (the reference is
   a light product); theme variables keep dark mode working.

   Aesthetic: modern light SaaS — Attio / Linear-light / Notion. Light rail,
   pale-orange active pills, STUDIONEXIS wordmark, big bold titles, tinted-
   icon KPI cards, airy tables, soft floating cards.
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --nx-orange: #F97316;
  --nx-orange-ink: #EA580C;
  --nx-orange-wash: #FFF1E8;
  --nx-purple: #8B5CF6;
  --nx-purple-wash: #F1EEFE;
  --nx-green: #22A565;
  --nx-green-wash: #E9F7EF;
  --nx-blue: #3B82F6;
  --nx-blue-wash: #EAF2FE;
  --nx-radius: 16px;
  --nx-radius-sm: 10px;
  --nx-shadow: 0 1px 2px rgba(17,17,19,.04), 0 1px 3px rgba(17,17,19,.03);
  --nx-shadow-hover: 0 1px 2px rgba(17,17,19,.05), 0 10px 30px rgba(17,17,19,.06);
  --nx-font-display: 'Manrope', 'Inter', -apple-system, sans-serif;
}

body { background: var(--color-bg); }

/* ═══ Sidebar — light rail ═══ */
.sidebar {
  background: var(--color-sidebar-bg);
  border-right: 1px solid var(--color-sidebar-border);
  box-shadow: none;
}
.sidebar-header { padding: 20px 18px 6px; }
.sidebar-nav { padding: 4px 0 12px; }

/* Wordmark */
.nx-wordmark { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; text-decoration: none; }
.nx-wordmark-row { font-family: var(--nx-font-display); font-weight: 800; font-size: 21px; letter-spacing: -0.01em; line-height: 1; }
.nx-wordmark-row .nx-w1 { color: #17181C; }
[data-theme="dark"] .nx-wordmark-row .nx-w1 { color: #F4F6FA; }
.nx-wordmark-row .nx-w2 { color: var(--nx-orange); }
.nx-wordmark-sub { font-size: 9.5px; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase; color: var(--color-text-muted); }
.sidebar.collapsed .nx-wordmark-sub { display: none; }
.sidebar.collapsed .nx-wordmark-row { font-size: 16px; }

.sidebar .nav-section-label {
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.09em; text-transform: uppercase;
  color: var(--color-text-muted); padding: 0 14px; margin: 18px 0 6px;
}
.sidebar .nav-item {
  display: flex; align-items: center; gap: 12px; margin: 1px 8px; padding: 9px 12px;
  border-radius: var(--nx-radius-sm); font-size: 14px; font-weight: 500;
  color: var(--color-sidebar-text); transition: background .13s, color .13s;
}
.sidebar .nav-item .nav-icon { width: 19px; height: 19px; color: currentColor; opacity: .85; }
.sidebar .nav-item:hover { background: var(--color-sidebar-item-hover); color: var(--color-text-primary); }
.sidebar .nav-item.active { background: var(--color-sidebar-item-active); color: var(--nx-orange); font-weight: 600; box-shadow: none; }
.sidebar .nav-item.active .nav-icon { color: var(--nx-orange); opacity: 1; }
.sidebar .nav-item.active::before { display: none; }
.sidebar .nav-adv-toggle { margin: 4px 8px; padding: 9px 12px; border-radius: var(--nx-radius-sm); font-size: 14px; color: var(--color-sidebar-text); }
.sidebar .nav-adv-toggle:hover { background: var(--color-sidebar-item-hover); color: var(--color-text-primary); }
.sidebar .nav-adv-group { margin-left: 22px; border-left: 1px solid var(--color-sidebar-border); padding-left: 4px; }

.sidebar-footer { border-top: 1px solid var(--color-sidebar-border); padding: 10px 8px; }
.sidebar .sidebar-status-card {
  background: linear-gradient(135deg, rgba(249,115,22,.07), rgba(249,115,22,.02));
  border: 1px solid #FCE6D6; border-radius: 14px;
}
.sidebar .sidebar-status-title { color: var(--color-text-primary); font-weight: 700; }
.sidebar .sidebar-status-sub { color: var(--color-text-muted); }
.sidebar .theme-toggle, .sidebar .collapse-toggle { color: var(--color-sidebar-text); border-radius: var(--nx-radius-sm); }
.sidebar .theme-toggle:hover, .sidebar .collapse-toggle:hover { color: var(--color-text-primary); background: var(--color-sidebar-item-hover); }

/* ═══ Topbar — quiet glass ═══ */
.topbar {
  background: color-mix(in srgb, var(--color-bg) 80%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-subtle);
}
.topbar-context { display: none; }        /* the big in-content page title is the orientation */
.topbar-left { gap: 10px; }
.nx-qs { border-radius: 12px; min-width: 250px; background: var(--color-surface); border-color: var(--color-border-subtle); }
.topbar-avatar {
  width: 34px; height: 34px; border-radius: 50%;
  background: var(--nx-orange); color: #fff; font-weight: 700; font-size: 14px;
}

/* ═══ Content + page header ═══ */
.content-area { padding-top: 22px; }
.page-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 24px; }
.page-title {
  font-family: var(--nx-font-display); font-size: 30px; font-weight: 800;
  letter-spacing: -0.025em; line-height: 1.12; color: var(--color-text-primary);
}
.page-subtitle { font-size: 14px; margin-top: 5px; color: var(--color-text-muted); }

/* ═══ Cards ═══ */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--nx-radius);
  box-shadow: var(--nx-shadow);
}
.card:hover { box-shadow: var(--nx-shadow-hover); }
.card-header { padding: 18px 20px; border-bottom: 1px solid var(--color-border-subtle); }
.card-body { padding: 20px; }
.card-title { font-family: var(--nx-font-display); font-size: 16.5px; font-weight: 800; letter-spacing: -0.01em; color: var(--color-text-primary); }
.card-subtitle { font-size: 13px; color: var(--color-text-muted); margin-top: 3px; }
.card-eyebrow { font-size: 10.5px; font-weight: 800; letter-spacing: 0.09em; text-transform: uppercase; color: var(--nx-orange); margin-bottom: 6px; }

/* ═══ KPI / stat cards — tinted icon square + big number + delta ═══ */
.nx-kpi { background: var(--color-surface); border: 1px solid var(--color-border-subtle); border-radius: var(--nx-radius); padding: 18px; box-shadow: var(--nx-shadow); }
.nx-kpi-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.nx-kpi-ic { width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; }
.nx-kpi-ic.o { background: var(--nx-orange-wash); color: var(--nx-orange); }
.nx-kpi-ic.p { background: var(--nx-purple-wash); color: var(--nx-purple); }
.nx-kpi-ic.g { background: var(--nx-green-wash); color: var(--nx-green); }
.nx-kpi-ic.b { background: var(--nx-blue-wash); color: var(--nx-blue); }
.nx-kpi-delta { font-size: 12px; font-weight: 700; color: var(--nx-green); display: inline-flex; align-items: center; gap: 3px; }
.nx-kpi-delta.down { color: #E5484D; }
.nx-kpi-label { font-size: 12.5px; color: var(--color-text-muted); font-weight: 500; margin-bottom: 3px; }
.nx-kpi-value { font-family: var(--nx-font-display); font-size: 27px; font-weight: 800; letter-spacing: -0.02em; color: var(--color-text-primary); }

/* ═══ Tabs — underline ═══ */
.tab, .settings-tab, .cl-tab, [role="tab"] { transition: color .13s, border-color .13s; }
.tab.active, .settings-tab.active, .cl-tab.active, [role="tab"][aria-selected="true"] { color: var(--nx-orange); }

/* ═══ Tables ═══ */
.data-table thead th {
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
  padding: 13px 18px; color: var(--color-text-muted);
  background: transparent; border-bottom: 1px solid var(--color-border-subtle);
}
.data-table tbody td { padding: 15px 18px; font-size: 13.5px; border-color: var(--color-border-subtle); }
.data-table tbody tr { transition: background .12s; }
.data-table tbody tr:hover td { background: var(--color-surface-raised); }

/* ═══ Buttons ═══ */
.btn { border-radius: var(--nx-radius-sm); font-weight: 600; transition: background .14s, transform .12s, box-shadow .14s; }
.btn-primary { background: var(--nx-orange); color: #fff; border: 1px solid transparent; box-shadow: 0 1px 2px rgba(249,115,22,.24); }
.btn-primary:hover { background: var(--nx-orange-ink); transform: translateY(-1px); }
.btn-secondary { background: var(--color-surface); border: 1px solid var(--color-border); color: var(--color-text-primary); }
.btn-secondary:hover { background: var(--color-surface-raised); }
.btn-ghost { background: transparent; color: var(--color-text-secondary); }
.btn-ghost:hover { background: var(--color-surface-raised); color: var(--color-text-primary); }
.btn-sm { border-radius: 9px; padding: 7px 13px; font-size: 13px; }

/* ═══ Forms ═══ */
.form-label { font-size: 12.5px; font-weight: 600; color: var(--color-text-secondary); }
.form-control {
  border-radius: var(--nx-radius-sm); background: var(--color-surface);
  border: 1px solid var(--color-border); font-size: 14px;
}
.form-control:focus { border-color: var(--nx-orange); box-shadow: 0 0 0 3px var(--color-brand-accent-soft); }

/* ═══ Badges ═══ */
.badge { border-radius: 999px; font-weight: 700; letter-spacing: 0.01em; padding: 3px 10px; font-size: 11px; }

/* ═══ Modals / drawers ═══ */
.modal, .modal-content, .drawer-panel { border-radius: 18px; }
.modal-overlay { backdrop-filter: blur(3px); }

