input.old_string:
try {
  // Studio Nexis is a light-first product (the reference design is light).
  // Default everyone to light; only honor an EXPLICIT saved choice, so
  // people on OS-dark aren't dropped into dark mode by surprise.
  var saved = localStorage.getItem('admin-theme');
  document.documentElement.dataset.theme = (saved === 'dark' || saved === 'light') ? saved : 'light';
} catch (e) {
  document.documentElement.dataset.theme = 'light';
}

input.new_string:
try {
  // Studio Nexis is now a light-first product (reference design is light).
  // ONE-TIME reset: clear any stale saved 'dark' from before the UI
  // rebuild so everyone actually sees the new light design once. The
  // toggle still works and persists afterward for anyone who wants dark.
  if (!localStorage.getItem('nx-light-reset-2')) {
    localStorage.removeItem('admin-theme');
    localStorage.setItem('nx-light-reset-2', '1');
  }
  var saved = localStorage.getItem('admin-theme');
  document.documentElement.dataset.theme = (saved === 'dark' || saved === 'light') ? saved : 'light';
} catch (e) {
  document.documentElement.dataset.theme = 'light';
}

