          <div class="msg err" id="err"></div>
          <p class="foot-note">Already have a studio? <a href="/login">Log in</a></p>
        </form>

        <!-- Success -->
        <div class="done" id="done">
          <div class="tick"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg></div>
          <h1>Your studio is ready! 🎉</h1>
          <p class="sub">Log in with the email and password you just chose.</p>
          <div class="url-box" id="doneUrl"></div>
          <a class="btn" id="goBtn" style="display:inline-block;text-align:center;text-decoration:none;box-sizing:border-box" href="#">Go to my studio →</a>
        </div>
      </div>
