  slug="${r%%:*}"; rest="${r#*:}"; title="${rest%%:*}"; sub="${rest#*:}"
  mkdir -p "$slug"
  cat > "$slug/page.tsx" <<EOF
import { PageStub } from "@/components/ui/page-stub";

export default function Page() {
  return <PageStub title="$title" sub="$sub" />;
}
EOF
done; ls */page.tsx | wc -l

cat > /etc/systemd/system/nexis-next.service <<'EOF'
[Unit]
Description=Studio Nexis v2 (Next.js rebuild preview)
After=network.target

[Service]
WorkingDirectory=/opt/nexis
ExecStart=/usr/bin/npm run start -- -p 3100
Restart=always
RestartSec=3
Environment=NODE_ENV=production

[Install]
WantedBy=multi-user.target
EOF
cat > /etc/nginx/conf.d/new.nexis.revsports.ca.conf <<'EOF'
server {
    listen 72.62.69.9:80;
    server_name new.nexis.revsports.ca;
    return 301 https://$host$request_uri;
}
server {
    listen 72.62.69.9:443 ssl;
    server_name new.nexis.revsports.ca;
    ssl_certificate /etc/letsencrypt/live/nexis.revsports.ca/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nexis.revsports.ca/privkey.pem;
    location / {
        proxy_pass http://127.0.0.1:3100;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
EOF
systemctl daemon-reload && systemctl enable --now nexis-next >/dev/null 2>&1; sleep 4; systemctl is-active nexis-next; nginx -t 2>&1 | tail -1 && systemctl reload nginx; sleep 3
echo "local: $(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3100/dashboard)"
echo "live:  $(curl -sL -o /dev/null -w '%{http_code}' https://new.nexis.revsports.ca/dashboard)"
curl -sL https://new.nexis.revsports.ca/dashboard | grep -oc 'STUDIO\|NEXIS\|Get your studio ready' | head -1

