          { name: "Linh Nguyen", phone: "555-0103", email: "linh@example.com", channel: "zalo" },
        ],
      },
    },
  });
  console.log("seeded tenant:", tenant.slug, tenant.id);
}

main().finally(() => db.$disconnect());

