      <Card className="mt-6">
        <form method="post" action="/api/sessions" className="space-y-4 p-6">
          {error && (
            <div className="rounded-xl border border-rose/20 bg-rose/5 px-3.5 py-2.5 text-[13px] font-medium text-rose">
