        </div>
      </div>

      {/* Getting started */}
      <Card className="mb-6">
        <div className="px-5 py-4">
          <div className="flex items-center justify-between">
            <div className="font-display text-[16.5px] font-extrabold text-ink">
              Get your studio ready <span className="ml-1">🚀</span>
            </div>
