          <CardHeader eyebrow="Overview" title="Business Summary" sub="Today" />
          <div className="grid grid-cols-2 gap-3 p-5 sm:grid-cols-4">
            {await (async () => {
              const todayKey = dayKeyInTz(new Date(), tenant.timezone);
              const todayOrders = orders.filter((o) => dayKeyInTz(o.createdAt, tenant.timezone) === todayKey);
              const [newToday, bookingsToday] = await Promise.all([
                db.client.count({ where: { tenantId: tenant.id, createdAt: { gte: new Date(Date.now() - 86400_000) } } }),
                db.booking.count({ where: { tenantId: tenant.id, createdAt: { gte: new Date(Date.now() - 86400_000) } } }),
              ]);
              const classesToday = weekSessions.filter((s) => dayKeyInTz(s.startsAt, tenant.timezone) === todayKey).length;
              return [
