@import "tailwindcss";

/* ═══════════════════════════════════════════════════════════════════
   Studio Nexis — design system (from the reference mockups)
   Light SaaS: white canvas, orange brand, tinted-icon KPIs, soft cards.
   ═══════════════════════════════════════════════════════════════════ */
@theme {
  --color-canvas: #f7f7f8;
  --color-surface: #ffffff;
  --color-raised: #fafafb;
  --color-ink: #17181c;
  --color-ink-2: #565a63;
  --color-muted: #9096a0;
  --color-line: #ececee;
  --color-line-2: #f2f2f4;

  --color-brand: #f97316;
  --color-brand-ink: #ea580c;
  --color-brand-wash: #fff1e8;

  --color-purple: #8b5cf6;
  --color-purple-wash: #f1eefe;
  --color-green: #22a565;
  --color-green-wash: #e9f7ef;
  --color-blue: #3b82f6;
  --color-blue-wash: #eaf2fe;
  --color-rose: #e5484d;

  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-manrope), var(--font-inter), sans-serif;

  --radius-card: 16px;
  --shadow-card: 0 1px 2px rgb(17 17 19 / 0.04), 0 1px 3px rgb(17 17 19 / 0.03);
  --shadow-card-hover: 0 1px 2px rgb(17 17 19 / 0.05), 0 10px 30px rgb(17 17 19 / 0.06);
}

html,
body {
  height: 100%;
}
body {
  background: var(--color-canvas);
  color: var(--color-ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

* {
  scrollbar-width: thin;
  scrollbar-color: #d7d7db transparent;
}

