1	import { NextResponse } from "next/server";
2	import { rateLimit } from "@/lib/rate-limit";
3	import bcrypt from "bcryptjs";
4	import { db } from "@/lib/db";
5	import { tenantBySlugOrDomain } from "@/lib/public-tenant";
6	import { createCustomerSession, destroyCustomerSession, getCustomerSession } from "@/lib/customer-auth";
7	import { externalUrl } from "@/lib/request-url";
8	
9	// One endpoint, three modes: login, register (set password), logout, cancel.
10	export async function POST(req: Request) {
11	  if (!rateLimit(req, "pubcust", 15, 60)) {
12	    return new NextResponse("Too many attempts — slow down and try again shortly.", { status: 429 });
13	  }
14	  const form = await req.formData();
15	  const mode = String(form.get("mode") ?? "");
16	  const slug = String(form.get("slug") ?? "");
17	  const me = `/book/${slug}/me`;
18	
19	  if (mode === "logout") {
20	    await destroyCustomerSession();
21	    return NextResponse.redirect(externalUrl(req, `/book/${slug}`), 303);
22	  }
23	
24	  if (mode === "cancel") {
25	    const session = await getCustomerSession();
26	    if (!session || session.slug !== slug) return NextResponse.redirect(externalUrl(req, me), 303);
27	    const bookingId = String(form.get("bookingId") ?? "");
28	
29	    await db.$transaction(async (tx) => {
30	      const booking = await tx.booking.findFirst({
31	        where: { id: bookingId, tenantId: session.tenantId, clientId: session.clientId, status: { in: ["BOOKED", "WAITLIST"] } },
32	        include: { session: { include: { classType: true } }, tenant: true },
33	      });
34	      if (!booking) return;
35	      const pol = (booking.tenant.policies ?? {}) as { cancelWindowGroupHours?: number; cancelWindowPrivateHours?: number };
36	      const windowH = booking.session.classType.kind === "PRIVATE" ? pol.cancelWindowPrivateHours ?? 3 : pol.cancelWindowGroupHours ?? 3;
37	      const hoursOut = (booking.session.startsAt.getTime() - Date.now()) / 3600_000;
38	      if (hoursOut < windowH) return; // inside the window — portal refuses
39	
40	      await tx.booking.update({ where: { id: booking.id }, data: { status: "CANCELLED" } });
41	      if (booking.status === "BOOKED" && booking.clientPackageId) {
42	        await tx.clientPackage.update({ where: { id: booking.clientPackageId }, data: { creditsLeft: { increment: 1 } } });
43	      }
44	      if (booking.status === "BOOKED") {
45	        const next = await tx.booking.findFirst({ where: { sessionId: booking.sessionId, status: "WAITLIST" }, orderBy: { createdAt: "asc" } });
46	        if (next) {
47	          const pkg = await tx.clientPackage.findFirst({
48	            where: { tenantId: booking.tenantId, clientId: next.clientId, creditsLeft: { gt: 0 }, frozen: false, expiresAt: { gt: new Date() } },
49	            orderBy: { expiresAt: "asc" },
50	          });
51	          if (pkg) await tx.clientPackage.update({ where: { id: pkg.id }, data: { creditsLeft: { decrement: 1 } } });
52	          await tx.booking.update({ where: { id: next.id }, data: { status: "BOOKED", paymentMethod: pkg ? "package_credit" : "at_studio", clientPackageId: pkg?.id ?? null } });
53	        }
54	      }
55	    });
56	    return NextResponse.redirect(externalUrl(req, me), 303);
57	  }
58	
59	  // login / register
60	  const tenant = await tenantBySlugOrDomain(slug);
61	  if (!tenant || tenant.status === "SUSPENDED") return NextResponse.redirect(externalUrl(req, "/login"), 303);
62	  const contact = String(form.get("contact") ?? "").trim().toLowerCase();
63	  const password = String(form.get("password") ?? "");
64	  if (!contact || password.length < 6) return NextResponse.redirect(externalUrl(req, `${me}?error=missing`), 303);
65	
66	  const client = await db.client.findFirst({
67	    where: { tenantId: tenant.id, OR: [{ email: contact }, { phone: contact }] },
68	  });
69	
70	  if (mode === "register") {
71	    if (client?.passwordHash) return NextResponse.redirect(externalUrl(req, `${me}?error=haspw`), 303);
72	    const hash = await bcrypt.hash(password, 10);
73	    const target = client
74	      ? await db.client.update({ where: { id: client.id }, data: { passwordHash: hash } })
75	      : await db.client.create({
76	          data: {
77	            tenantId: tenant.id,
78	            name: String(form.get("name") ?? "").trim() || contact,
79	            email: contact.includes("@") ? contact : null,
80	            phone: contact.includes("@") ? null : contact,
81	            channel: "website",
82	            passwordHash: hash,
83	          },
84	        });
85	    await createCustomerSession({ clientId: target.id, tenantId: tenant.id, slug });
86	    return NextResponse.redirect(externalUrl(req, me), 303);
87	  }
88	
89	  // login
90	  if (!client?.passwordHash || !(await bcrypt.compare(password, client.passwordHash))) {
91	    return NextResponse.redirect(externalUrl(req, `${me}?error=bad`), 303);
92	  }
93	  await createCustomerSession({ clientId: client.id, tenantId: tenant.id, slug });
94	  return NextResponse.redirect(externalUrl(req, me), 303);
95	}

