39	      if (!ok) return NextResponse.redirect(externalUrl(req, back ?? `/schedule/${id}`), 303);
40	    }
41	    await db.classSession.update({
42	      where: { id },
43	      data: {
44	        capacity: Number.isFinite(capacity) && capacity >= 1 ? capacity : session.capacity,
45	        instructorId,
46	        location: String(form.get("location") ?? "").trim() || null,
47	      },
48	    });
49	  }
50	  return NextResponse.redirect(externalUrl(req, back ?? `/schedule/${id}`), 303);
51	}

