              </div>
            ))}
          </div>
        </section>
      )}

      {/* Contact + map */}
      <footer className="border-t px-6 py-20" style={{ borderColor: "#EFEAE21a" }}>
        <div className="mx-auto grid max-w-[1100px] gap-12 md:grid-cols-2">
