              {d.phone && <p>{d.phone}</p>}
              {d.hours && <p>{d.hours}</p>}
              {d.instagram && <p><a className="underline underline-offset-4" href={`https://instagram.com/${d.instagram}`}>@{d.instagram}</a></p>}
