          </div>
          {d.mapSrc && <iframe src={d.mapSrc} className="h-[320px] w-full border-0 grayscale" loading="lazy" referrerPolicy="no-referrer-when-downgrade" title="Map" />}
        </div>
      </footer>
    </div>
  );
}

