          <img key={g} src={g} alt="" loading="lazy" className="aspect-square w-full object-cover" />
        ))}
      </section>

      {/* Contact + map */}
      <footer className="border-t border-black/10">
        <div className="mx-auto grid max-w-[1040px] gap-10 px-6 py-14 md:grid-cols-2">
