1	import { NextResponse, type NextRequest } from "next/server";
2	import { jwtVerify } from "jose";
3	
4	const PUBLIC = ["/login", "/api/login", "/signup", "/api/signup", "/book", "/s", "/api/public", "/api/cron", "/api/media", "/api/twilio"];
5	
6	const BASE = "nexis.revsports.ca";
7	// Hosts that serve the (hidden) admin app. Everything else on the base
8	// domain is a tenant's customer world.
9	const ADMIN_HOSTS = [`app.${BASE}`, `new.${BASE}`, "localhost", "127.0.0.1"];
10	const RESERVED_SLUGS = ["app", "new", "www", "hq", "api", "mail", "admin"];
11	
12	// Pretty customer paths on a tenant host → internal slugged routes.
13	const TENANT_ALIASES: Record<string, string> = {
14	  "/": "/s/{slug}",
15	  "/book": "/book/{slug}",
16	  "/packages": "/book/{slug}/packages",
17	  "/bookings": "/book/{slug}/bookings",
18	  "/my-packages": "/book/{slug}/my-packages",
19	  "/account": "/book/{slug}/account",
20	  "/book/me": "/book/{slug}/account",
21	};
22	
23	export async function middleware(req: NextRequest) {
24	  const { pathname } = req.nextUrl;
25	  const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").split(":")[0].toLowerCase();
26	
27	  // ── Tenant hosts: <slug>.BASE and custom domains ──────────────────────
28	  let slugParam: string | null = null;
29	  if (host.endsWith(`.${BASE}`) && !ADMIN_HOSTS.includes(host)) {
30	    const slug = host.slice(0, -(BASE.length + 1));
31	    if (slug && !RESERVED_SLUGS.includes(slug)) slugParam = slug;
32	  } else if (host && host !== BASE && !ADMIN_HOSTS.includes(host)) {
33	    slugParam = `~${host}`; // custom domain
34	  }
35	
36	  if (slugParam) {
37	    const alias = TENANT_ALIASES[pathname];
38	    if (alias) {
39	      const url = new URL(alias.replaceAll("{slug}", slugParam), req.url);
40	      url.search = req.nextUrl.search; // keep ?preview=, ?d=, ?ok=…
41	      return NextResponse.rewrite(url);
42	    }
