1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { getSession } from "@/lib/auth";
4	import { externalUrl } from "@/lib/request-url";
5	
6	// The calendar's mini-POS: settle an attendee's payment and check them in.
7	// mode=credit  → consume a package credit
8	// mode=charge  → cash/transfer/card for the drop-in (+ products, voucher)
9	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
10	  const auth = await getSession();
11	  if (!auth || auth.role === "INSTRUCTOR") return NextResponse.redirect(externalUrl(req, "/login"), 303);
12	
13	  const { id } = await params;
14	  const form = await req.formData();
15	  const mode = String(form.get("mode") ?? "");
16	  const backRaw = String(form.get("back") ?? "");
17	  const back = backRaw.startsWith("/") && !backRaw.startsWith("//") ? backRaw : "/schedule";
18	  const fail = (code: string) =>
19	    NextResponse.redirect(externalUrl(req, `${back}${back.includes("?") ? "&" : "?"}checkout=${code}`), 303);
20	
21	  const booking = await db.booking.findFirst({
22	    where: { id, tenantId: auth.tenantId },
23	    include: { session: { include: { classType: true } } },
24	  });
25	  if (!booking || !["BOOKED", "CHECKED_IN"].includes(booking.status)) return fail("gone");
26	
27	  try {
28	    await db.$transaction(async (tx) => {
29	      if (mode === "credit") {
30	        const pkg = await tx.clientPackage.findFirst({
31	          where: { tenantId: auth.tenantId, clientId: booking.clientId, creditsLeft: { gt: 0 }, frozen: false, expiresAt: { gt: new Date() } },
32	          orderBy: { expiresAt: "asc" },
33	        });
34	        if (!pkg) throw new Error("no-credits");
35	        // Don't double-spend if the booking already consumed a credit.
36	        if (!booking.clientPackageId) {
37	          await tx.clientPackage.update({ where: { id: pkg.id }, data: { creditsLeft: { decrement: 1 } } });
38	        }
39	        await tx.booking.update({
40	          where: { id },
41	          data: { status: "CHECKED_IN", paymentMethod: "package_credit", clientPackageId: booking.clientPackageId ?? pkg.id },
42	        });
43	      } else {
44	        const method = ["cash", "transfer", "card"].includes(String(form.get("method"))) ? String(form.get("method")) : "cash";
45	        const lines: Array<{ kind: string; refId: string | null; productId: string | null; label: string; qty: number; unitPrice: number }> = [];
46	        let total = Number(booking.session.classType.price);
47	        lines.push({ kind: "dropin", refId: booking.sessionId, productId: null, label: `${booking.session.classType.name} (drop-in)`, qty: 1, unitPrice: total });
48	
49	        // Optional merch lines: fields named product_<id> hold quantities.
50	        for (const [key, val] of form.entries()) {
51	          if (!key.startsWith("product_")) continue;
52	          const qty = Number(val);
53	          if (!Number.isFinite(qty) || qty < 1) continue;
54	          const prod = await tx.product.findFirst({ where: { id: key.slice(8), tenantId: auth.tenantId, active: true } });
55	          if (!prod || prod.stock < qty) throw new Error("stock");
56	          lines.push({ kind: "product", refId: prod.id, productId: prod.id, label: prod.name, qty, unitPrice: Number(prod.price) });
57	          total += Number(prod.price) * qty;
58	          await tx.product.update({ where: { id: prod.id }, data: { stock: { decrement: qty } } });
59	        }
60	
61	        // Voucher (same rules as the main POS)
62	        let discount = 0;
63	        let voucherId: string | null = null;
64	        const code = String(form.get("voucherCode") ?? "").trim().toUpperCase().replace(/\s+/g, "");
65	        if (code) {
66	          const v = await tx.voucher.findUnique({ where: { tenantId_code: { tenantId: auth.tenantId, code } } });
67	          if (!v || !v.active || (v.expiresAt && v.expiresAt < new Date()) || v.usedCount >= v.maxUses) throw new Error("voucher");
68	          discount = Math.min(total, v.type === "PERCENT" ? (total * Number(v.value)) / 100 : Number(v.value));
69	          voucherId = v.id;
70	          await tx.voucher.update({ where: { id: v.id }, data: { usedCount: { increment: 1 } } });
71	        }
72	
73	        const last = await tx.order.findFirst({ where: { tenantId: auth.tenantId }, orderBy: { number: "desc" }, select: { number: true } });
74	        const order = await tx.order.create({
75	          data: {
76	            tenantId: auth.tenantId,
77	            clientId: booking.clientId,
78	            number: (last?.number ?? 0) + 1,
79	            total: (total - discount).toFixed(2),
80	            discount: discount.toFixed(2),
81	            voucherId,
82	            method,
83	            status: "PAID",
84	            items: { create: lines.map((l) => ({ ...l, unitPrice: l.unitPrice.toFixed(2) })) },
85	          },
86	        });
87	        await tx.booking.update({
88	          where: { id },
89	          data: { status: "CHECKED_IN", paymentMethod: method, orderId: order.id },
90	        });
91	      }
92	      await tx.client.update({ where: { id: booking.clientId }, data: { lastVisitAt: new Date() } });
93	    });
94	  } catch (e) {
95	    const msg = e instanceof Error ? e.message : "failed";
