16	  const profile = `/team/${id}`;
17	  const user = await db.user.findFirst({ where: { id, tenantId: auth.tenantId } });
18	  if (!user) return NextResponse.redirect(externalUrl(req, "/team"), 303);
19	
20	  if (action === "profile") {
21	    const name = String(form.get("name") ?? "").trim();
