67	      .filter((t): t is { classes: number; pct: number } => t.classes !== null && t.pct !== null && t.pct <= 100);
68	    const rows = [0, 1, 2, 3]
69	      .map((i) => ({ people: num(`head_people_${i}`), amount: num(`head_amount_${i}`) }))
70	      .filter((r): r is { people: number; amount: number } => !!r.people && r.people >= 1 && r.amount !== null);
71	    await db.user.update({
72	      where: { id },
73	      data: {
74	        commissionMode: mode,
75	        commissionRate: (num("rate") ?? Number(user.commissionRate)).toFixed(2),
76	        commissionConfig: {
77	          tiers,
78	          retroactive: form.get("retroactive") === "on",
79	          amount: num("fixedAmount") ?? 0,
80	          rows,
81	        },
82	      },
83	    });
84	    return NextResponse.redirect(externalUrl(req, `${profile}?saved=1`), 303);
85	  }
86	
87	  if (action === "rate") {
88	    const rate = Number(form.get("rate"));
89	    if (Number.isFinite(rate) && rate >= 0 && rate <= 100) {
90	      await db.user.update({ where: { id }, data: { commissionRate: rate.toFixed(2) } });
91	    }
