96	  if (action === "deactivate") await db.user.update({ where: { id }, data: { active: false } });
97	  if (action === "activate") await db.user.update({ where: { id }, data: { active: true } });
98	  return NextResponse.redirect(externalUrl(req, back), 303);
99	}

