20	  minimal: Minimal,
21	  serene: Serene,
22	  bold: Bold,
23	};
24	
25	export default async function StudioSite({ params, searchParams }: {
26	  params: Promise<{ slug: string }>;
27	  searchParams: Promise<{ preview?: string }>;
28	}) {
29	  const { slug } = await params;
30	  const { preview } = await searchParams;
31	  const tenant = await tenantBySlugOrDomain(slug);
32	  if (!tenant || tenant.status === "SUSPENDED") notFound();
33	
34	  const w = (tenant.website ?? {}) as Record<string, string> & {
35	    galleryImages?: string[];
36	    why?: string[];
37	    testimonials?: SiteQuote[];
38	    faqs?: SiteFaq[];
39	    sections?: Partial<Record<SectionId, boolean>>;
40	    teamBios?: Record<string, { bio?: string; photo?: string }>;
41	  };
42	  const fmt = moneyFormatter(tenant.currency);
43	
44	  const [packages, sessions, classTypes, instructors] = await Promise.all([
45	    db.package.findMany({ where: { tenantId: tenant.id, active: true }, orderBy: { price: "asc" }, take: 6 }),
46	    db.classSession.findMany({
47	      where: { tenantId: tenant.id, status: "SCHEDULED", isPublic: true, startsAt: { gt: new Date(), lt: new Date(Date.now() + 7 * 86400_000) } },
48	      include: { classType: true, instructor: true },
49	      orderBy: { startsAt: "asc" },
50	      take: 8,
51	    }),
52	    db.classType.findMany({ where: { tenantId: tenant.id, active: true, kind: "GROUP" }, orderBy: { name: "asc" }, take: 6 }),
53	    db.user.findMany({ where: { tenantId: tenant.id, active: true, role: "INSTRUCTOR" }, orderBy: { name: "asc" }, take: 6 }),
54	  ]);
55	
56	  const pol = (tenant.policies ?? {}) as { cancelWindowGroupHours?: number };
57	  const cancelHours = pol.cancelWindowGroupHours ?? 3;
58	
59	  const data: SiteData = {
60	    name: tenant.name,
61	    slug,
62	    brand: tenant.brandColor || "#F97316",
63	    tagline: w.tagline ?? "",
64	    about: w.about ?? "",
65	    philosophy: w.philosophy || `At ${tenant.name}, we believe strength is built with patience and precision. Every class blends classical Pilates principles with modern movement science — small groups, hands-on coaching, and programming that respects where your body is today.`,
66	    why: w.why?.length ? w.why : ["Small classes with real, hands-on coaching", "Certified instructors who know your name", "Programs for every body and every level", "A calm, welcoming space to reset"],
67	    address: w.address ?? "",
68	    phone: w.phoneNumber ?? "",
69	    instagram: w.instagram ?? "",
70	    facebook: w.facebook ?? "",
71	    tiktok: w.tiktok ?? "",
72	    hours: w.hours ?? "",
73	    hero: w.heroImage || "/studio/hero.jpg",
74	    gallery: w.galleryImages?.length
75	      ? w.galleryImages
76	      : ["gallery1", "gallery2", "gallery3", "gallery4"].map((g) => `/studio/${g}.jpg`),
77	    mapSrc: mapEmbedSrc(w.mapUrl, w.address, tenant.name),
78	    packages: packages.map((p) => ({ name: p.name, price: fmt.format(Number(p.price)), credits: p.credits, validityDays: p.validityDays })),
79	    sessions: sessions.map((s) => {
80	      const day = dayKeyInTz(s.startsAt, tenant.timezone) === dayKeyInTz(new Date(), tenant.timezone)
81	        ? "Today"
82	        : s.startsAt.toLocaleDateString("en-US", { timeZone: tenant.timezone, weekday: "short", month: "short", day: "numeric" });
83	      return { id: s.id, name: s.classType.name, day, time: timeInTz(s.startsAt, tenant.timezone), color: s.classType.color, instructor: s.instructor?.name.split(" ")[0] };
84	    }),
85	    classes: classTypes.map((c) => ({
86	      id: c.id,
87	      name: c.name,
88	      description: c.description ?? "",
89	      format: c.format ?? "",
90	      difficulty: difficultyLabel(c.difficulty),
91	      color: c.color,
92	      image: c.heroImage ?? "",
93	      benefits: c.benefits,
94	      price: fmt.format(Number(c.price)),
95	    })),
96	    team: instructors.map((u) => ({
97	      name: u.name,
98	      role: "Instructor",
99	      bio: w.teamBios?.[u.id]?.bio ?? "",
100	      photo: w.teamBios?.[u.id]?.photo ?? "",
101	    })),
102	    testimonials: w.testimonials ?? [],
103	    faqs: w.faqs?.length ? w.faqs : [
104	      { q: "I've never done Pilates — can I still join?", a: "Absolutely. Most of our classes are open to all levels and the instructor will give you options for every exercise. If you're brand new, a Gentle or All-levels class is the perfect place to start." },
105	      { q: "What should I bring or wear?", a: "Comfortable clothes you can move in and a water bottle. Grip socks are recommended for equipment classes — you can bring your own or buy a pair at the studio." },
106	      { q: "How do I book and pay?", a: "Book online in under a minute — pick a class, choose your spot, and pay with a class package or at the studio. You can also buy multi-class packages for a better rate." },
107	      { q: "What's the cancellation policy?", a: `Life happens! Cancel at least ${cancelHours} hour${cancelHours === 1 ? "" : "s"} before class starts and your credit is returned automatically.` },
108	    ],
109	    enabled: Object.fromEntries(SECTION_IDS.map((id) => [id, w.sections?.[id] ?? true])) as Record<SectionId, boolean>,
110	    bookHref: `/book/${slug}`,
111	    portalHref: `/book/${slug}/account`,
112	  };
113	
114	  const chosen = (preview && TEMPLATE_IDS.includes(preview as TemplateId) ? preview : w.template) as TemplateId;
115	  const Template = TEMPLATES[chosen] ?? Boutique;
116	  return <><TrackView slug={slug} />{Template(data)}</>;
117	}

