      }
      // Promote the oldest waitlisted client into the freed spot.
      if (wasActive) {
        const next = await tx.booking.findFirst({
          where: { sessionId: booking.sessionId, status: "WAITLIST" },
          orderBy: { createdAt: "asc" },
