24	  const qty = Math.min(5, Math.max(1, Number(form.get("qty")) || 1));
25	  const pay = String(form.get("pay") ?? ""); // "" = legacy quick-book (auto), credit, at_studio, deposit, online
26	  // Errors return to the page the form lives on; success lands on the schedule.
27	  const fromRaw = String(form.get("from") ?? "");
28	  const errBack = fromRaw.startsWith(`/book/${slug}`) && !fromRaw.startsWith("//") ? fromRaw : `/book/${slug}`;
29	  const back = `/book/${slug}`;
30	  const fail = (code: string) =>
31	    NextResponse.redirect(externalUrl(req, `${errBack}?err=${code}&s=${sessionId}`), 303);
