65	        metadata: { kind: "class", tenantId: tenant.id, sessionId, clientId: customer!.clientId, qty: String(qty) },
66	        success_url: `${origin}/api/public/stripe/class-confirm?slug=${encodeURIComponent(slug)}&sid={CHECKOUT_SESSION_ID}`,
67	        cancel_url: `${origin}/book/${slug}/class/${sessionId}?err=cancelled`,
68	      });
69	      return NextResponse.redirect(co.url!, 303);
