3	import { canAccess, homeFor } from "@/lib/access";
4	
5	const PUBLIC = ["/login", "/api/login", "/signup", "/api/signup", "/book", "/s", "/api/public", "/api/cron", "/api/media", "/api/twilio", "/api/stripe", "/api/v1", "/developers"];
6	
7	const BASE = "nexis.revsports.ca";
8	// Hosts that serve the (hidden) admin app. Everything else on the base
9	// domain is a tenant's customer world.
10	const ADMIN_HOSTS = [`app.${BASE}`, `new.${BASE}`, "localhost", "127.0.0.1"];
11	const RESERVED_SLUGS = ["app", "new", "www", "hq", "api", "mail", "admin"];
12	
13	// Pretty customer paths on a tenant host → internal slugged routes.

1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { getSession } from "@/lib/auth";
4	import { externalUrl } from "@/lib/request-url";
5	import { verifyStripeKey } from "@/lib/stripe";
6	import { randomBytes } from "crypto";
7	
8	const CURRENCIES = ["USD", "EUR", "GBP", "AUD", "CAD", "SGD", "THB", "VND", "IDR", "PHP", "MYR", "JPY", "KRW", "AED", "INR"];
9	
10	export async function POST(req: Request) {
11	  const auth = await getSession();
12	  if (!auth || ["STAFF", "INSTRUCTOR"].includes(auth.role)) return NextResponse.redirect(externalUrl(req, "/login"), 303);
13	
14	  const form = await req.formData();
15	  const section = String(form.get("section") ?? "identity");
16	  const tenant = await db.tenant.findUniqueOrThrow({ where: { id: auth.tenantId } });
17	
18	  if (section === "identity") {
19	    const name = String(form.get("name") ?? "").trim();
20	    const currency = String(form.get("currency") ?? tenant.currency);
21	    const timezone = String(form.get("timezone") ?? tenant.timezone);
22	    try {
23	      new Intl.DateTimeFormat("en-US", { timeZone: timezone });
24	    } catch {
25	      return NextResponse.redirect(externalUrl(req, "/settings?error=tz"), 303);
26	    }
27	    await db.tenant.update({
28	      where: { id: tenant.id },
29	      data: {
30	        name: name || tenant.name,
31	        currency: CURRENCIES.includes(currency) ? currency : tenant.currency,
32	        timezone,
33	        brandColor: /^#[0-9a-fA-F]{6}$/.test(String(form.get("brandColor"))) ? String(form.get("brandColor")) : tenant.brandColor,
34	      },
35	    });
36	  } else if (section === "domain") {
37	    const raw = String(form.get("customDomain") ?? "").trim().toLowerCase().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
38	    const prevPol = (tenant.policies ?? {}) as Record<string, unknown>;
39	    if (raw === "") {
40	      delete prevPol.domain;
41	      await db.tenant.update({ where: { id: tenant.id }, data: { customDomain: null, policies: prevPol as object } });
42	    } else {
43	      if (!/^(?!-)[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(raw) || raw.endsWith("nexis.revsports.ca")) {
44	        return NextResponse.redirect(externalUrl(req, "/settings?error=domain"), 303);
45	      }
46	      const taken = await db.tenant.findFirst({ where: { customDomain: raw, id: { not: tenant.id } } });
47	      if (taken) return NextResponse.redirect(externalUrl(req, "/settings?error=domaintaken"), 303);
48	      await db.tenant.update({
49	        where: { id: tenant.id },
50	        data: { customDomain: raw, policies: { ...prevPol, domain: { status: "PENDING_DNS" } } as object },
51	      });
52	    }
53	  } else if (section === "categories") {
54	    const prev = (tenant.policies ?? {}) as Record<string, unknown>;
55	    const cats = String(form.get("expenseCategories") ?? "")
56	      .split(",").map((c) => c.trim()).filter(Boolean).slice(0, 20);
57	    await db.tenant.update({
58	      where: { id: tenant.id },
59	      data: { policies: { ...prev, expenseCategories: cats } },
60	    });
61	  } else if (section === "template") {
62	    const prev = (tenant.website ?? {}) as Record<string, unknown>;
63	    const template = String(form.get("template") ?? "");
64	    const swatch = String(form.get("accent") ?? "").trim();
65	    const custom = String(form.get("accentCustom") ?? "").trim();
66	    const accent = /^#[0-9a-fA-F]{6}$/.test(swatch) ? swatch : custom;
67	    const mapUrl = String(form.get("mapUrl") ?? "").trim();
68	    await db.tenant.update({
69	      where: { id: tenant.id },
70	      data: {
71	        website: { ...prev, template: ["boutique", "luxury", "minimal", "serene", "bold"].includes(template) ? template : (prev.template ?? "boutique"), mapUrl },
72	        ...(/^#[0-9a-fA-F]{6}$/.test(accent) ? { brandColor: accent } : {}),
73	      },
74	    });
75	  } else if (section === "website") {
76	    const prev = (tenant.website ?? {}) as Record<string, unknown>;
77	    const pick = (k: string) => String(form.get(k) ?? "").trim();
78	    await db.tenant.update({
79	      where: { id: tenant.id },
80	      data: {
81	        website: {
82	          ...prev,
83	          tagline: pick("tagline"),
84	          about: pick("about"),
85	          address: pick("address"),
86	          phoneNumber: pick("phoneNumber"),
87	          instagram: pick("instagram").replace(/^@/, ""),
88	          hours: pick("hours"),
89	        },
90	      },
91	    });
92	  } else if (section === "apikey") {
93	    const act = String(form.get("action"));
94	    await db.tenant.update({
95	      where: { id: tenant.id },
96	      data: { apiKey: act === "revoke" ? null : `nx_live_${randomBytes(24).toString("hex")}` },
97	    });
98	  } else if (section === "stripe") {
99	    const prev = (tenant.policies ?? {}) as Record<string, unknown>;
100	    if (String(form.get("action")) === "disconnect") {
101	      await db.tenant.update({ where: { id: tenant.id }, data: { policies: { ...prev, stripe: {} } } });
102	    } else {
103	      const secretKey = String(form.get("secretKey") ?? "").trim();
104	      const check = secretKey.startsWith("sk_") ? await verifyStripeKey(secretKey) : { ok: false as const };
105	      if (!check.ok) return NextResponse.redirect(externalUrl(req, "/settings?tab=money&error=stripekey"), 303);
106	      await db.tenant.update({
107	        where: { id: tenant.id },
108	        data: { policies: { ...prev, stripe: { secretKey, accountLabel: check.label, connectedAt: new Date().toISOString() } } },
109	      });
110	    }
111	  } else if (section === "classsetup") {
112	    const prev = (tenant.policies ?? {}) as Record<string, unknown>;
113	    const csv = (v: FormDataEntryValue | null) =>
114	      String(v ?? "").split(",").map((s) => s.trim()).filter(Boolean).slice(0, 20);
115	    await db.tenant.update({
116	      where: { id: tenant.id },
117	      data: { policies: { ...prev, classFormats: csv(form.get("classFormats")), difficultyLevels: csv(form.get("difficultyLevels")) } },
118	    });
119	  } else if (section === "policies") {
120	    // Merge into the JSON policies blob — never replace wholesale.
121	    const prev = (tenant.policies ?? {}) as Record<string, unknown>;
122	    await db.tenant.update({
123	      where: { id: tenant.id },
124	      data: {
125	        policies: {
126	          ...prev,
127	          cancelWindowGroupHours: Math.max(0, Number(form.get("cancelWindowGroupHours") ?? 3) || 0),
128	          cancelWindowPrivateHours: Math.max(0, Number(form.get("cancelWindowPrivateHours") ?? 3) || 0),
129	          waitlistEnabled: form.get("waitlistEnabled") === "on",
130	          payAtStudio: form.get("payAtStudio") === "on",
131	        },
132	      },
133	    });
134	  }
135	  let tab = "";
136	  try { const r = req.headers.get("referer"); tab = r ? new URL(r).searchParams.get("tab") ?? "" : ""; } catch {}
137	  return NextResponse.redirect(externalUrl(req, `/settings?${tab ? `tab=${encodeURIComponent(tab)}&` : ""}saved=1`), 303);
138	}

