          </section>

          <footer className="border-t border-line-2 pt-6 text-[12px] text-muted">
            StudioNexis API v1 · Questions? Request features from your dashboard → Plan &amp; Billing → Custom features.
          </footer>
        </main>
      </div>
    </div>
  );
}

