              <div className="mt-5 space-y-8">
                {s.endpoints.map((e) => (
                  <div key={e.method + e.path} className="rounded-2xl border border-line-2 bg-surface p-6 shadow-[var(--shadow-card)]">
                    <div className="flex flex-wrap items-center gap-2.5">
