29	    const url = String(form.get("url") ?? "");
30	    const file = path.basename(url);
31	    if ((site.galleryImages ?? []).includes(url)) {
32	      site.galleryImages = (site.galleryImages ?? []).filter((u) => u !== url);
33	      await db.tenant.update({ where: { id: tenant.id }, data: { website: site as Prisma.InputJsonValue } });
34	      await unlink(path.join(ROOT, tenant.id, file)).catch(() => {});
35	    }
36	    return NextResponse.redirect(externalUrl(req, "/settings?saved=1"), 303);
37	  }
38	
39	  // Instructor portrait for the website team section (Wave 11 Y2)
40	  if (kind === "teamphoto") {
41	    const userId = String(form.get("userId") ?? "");
42	    const user = await db.user.findFirst({ where: { id: userId, tenantId: auth.tenantId } });
43	    if (!user) return NextResponse.redirect(externalUrl(req, "/website"), 303);
44	    const f = form.getAll("photos").find((x): x is File => x instanceof File && x.size > 0);
45	    const ext = f ? TYPES[f.type] : undefined;
46	    if (!f || !ext || f.size > MAX_BYTES) return NextResponse.redirect(externalUrl(req, "/website?error=phototype"), 303);
47	    await mkdir(path.join(ROOT, tenant.id), { recursive: true });
48	    const name = `team-${Date.now()}-${Math.random().toString(36).slice(2, 7)}${ext}`;
49	    await writeFile(path.join(ROOT, tenant.id, name), Buffer.from(await f.arrayBuffer()));
50	    const bios = { ...(((site as Record<string, unknown>).teamBios as Record<string, { bio?: string; photo?: string }>) ?? {}) };
51	    if (bios[userId]?.photo) await unlink(path.join(ROOT, tenant.id, path.basename(bios[userId].photo!))).catch(() => {});
52	    bios[userId] = { ...bios[userId], photo: `/api/media/${tenant.id}/${name}` };
53	    (site as Record<string, unknown>).teamBios = bios;
54	    await db.tenant.update({ where: { id: tenant.id }, data: { website: site as Prisma.InputJsonValue } });
55	    return NextResponse.redirect(externalUrl(req, "/website?saved=1"), 303);
56	  }
57	
58	  // Class blueprint hero image (video spec X7)
59	  if (kind === "classhero") {
60	    const classTypeId = String(form.get("classTypeId") ?? "");
61	    const ct = await db.classType.findFirst({ where: { id: classTypeId, tenantId: auth.tenantId } });
62	    if (!ct) return NextResponse.redirect(externalUrl(req, "/class-types"), 303);
63	    const f = form.getAll("photos").find((x): x is File => x instanceof File && x.size > 0);
64	    const ext = f ? TYPES[f.type] : undefined;
65	    if (!f || !ext || f.size > MAX_BYTES) {
66	      return NextResponse.redirect(externalUrl(req, `/class-types/${classTypeId}?error=phototype`), 303);
67	    }
68	    await mkdir(path.join(ROOT, tenant.id), { recursive: true });
69	    const name = `ct-${Date.now()}-${Math.random().toString(36).slice(2, 7)}${ext}`;
70	    await writeFile(path.join(ROOT, tenant.id, name), Buffer.from(await f.arrayBuffer()));
71	    if (ct.heroImage) await unlink(path.join(ROOT, tenant.id, path.basename(ct.heroImage))).catch(() => {});
72	    await db.classType.update({ where: { id: ct.id }, data: { heroImage: `/api/media/${tenant.id}/${name}` } });
73	    return NextResponse.redirect(externalUrl(req, `/class-types/${classTypeId}?saved=1`), 303);
74	  }
75	
76	  const files = form.getAll("photos").filter((f): f is File => f instanceof File && f.size > 0);
77	  if (files.length === 0) return NextResponse.redirect(externalUrl(req, "/settings?error=nophoto"), 303);
78	
79	  await mkdir(path.join(ROOT, tenant.id), { recursive: true });
80	  const saved: string[] = [];
81	  for (const f of files.slice(0, MAX_GALLERY)) {
82	    const ext = TYPES[f.type];
