  });
} else if (section === "stripe") {
  const prev = (tenant.policies ?? {}) as Record<string, unknown>;
  if (String(form.get("action")) === "disconnect") {
    await db.tenant.update({ where: { id: tenant.id }, data: { policies: { ...prev, stripe: {} } } });
