46	// The App Store — Pipedrive-style: your added apps show their config; a
47	// searchable marketplace popup handles browsing, adding and requesting apps.
48	export default async function AppsPage({ searchParams }: { searchParams: Promise<{ saved?: string; requested?: string }> }) {
49	  const { saved, requested } = await searchParams;
50	  const tenant = await getCurrentTenant();
51	  const apps = appsOf(tenant.policies);
52	  const hooks = webhooksOf(tenant.policies);
53	  const stripeOn = !!studioStripeConfig(tenant).secretKey;
54	  const twilioOn = !!process.env.TWILIO_ACCOUNT_SID;
55	  const icalUrl = apps.icalToken ? `https://app.nexis.revsports.ca/api/public/ical/${tenant.slug}?token=${apps.icalToken}` : null;
56	
57	  const isOn = (a: AppDef) => a.id === "stripe" ? stripeOn : a.id === "twilio" ? twilioOn : appInstalled(a.id, apps, hooks);
58	  const installed = APP_CATALOG.filter(isOn);
59	  const browse = APP_CATALOG.filter((a) => !isOn(a)).map(({ id, name, category, blurb, kind }) => ({ id, name, category, blurb, kind }));
60	
61	  const byId = Object.fromEntries(APP_CATALOG.map((a) => [a.id, a]));
62	  const panels: Record<string, React.ReactNode> = {
63	    automation: (
64	      <Panel key="automation" app={byId.automation} remove chip={<Chip on={hooks.length > 0} yes={`${hooks.length} webhook${hooks.length === 1 ? "" : "s"}`} no="No webhooks" />}>
65	        <div className="space-y-3">
66	          {hooks.map((h, i) => (
67	            <div key={i} className="rounded-xl border border-line-2 px-3.5 py-2.5">
68	              <div className="flex items-center justify-between gap-2">
69	                <code className="truncate font-mono text-[11.5px] text-ink">{h.url}</code>
70	                <form method="post" action="/api/settings"><input type="hidden" name="section" value="webhook-remove" /><input type="hidden" name="idx" value={i} /><input type="hidden" name="next" value="/apps?saved=1" /><button className="rounded-lg bg-line-2 px-2 py-1 text-[11px] font-bold text-ink-2 hover:bg-rose/10 hover:text-rose">✕</button></form>
71	              </div>
72	              <div className="mt-1 text-[11px] text-muted">{h.events.join(" · ")} · secret: <code className="font-mono">{h.secret.slice(0, 12)}…</code></div>
73	            </div>
74	          ))}
75	          <form method="post" action="/api/settings" className="space-y-2.5 border-t border-line-2 pt-3">
76	            <input type="hidden" name="section" value="webhook-add" />
77	            <input type="hidden" name="next" value="/apps?saved=1" />
78	            <input name="url" required placeholder="https:// webhook URL (from Make or Zapier)" className={field} />
79	            <div className="flex flex-wrap gap-3">
80	              {WEBHOOK_EVENTS.map((e) => (
81	                <label key={e} className="flex items-center gap-1.5 text-[12px] font-semibold text-ink-2">
82	                  <input type="checkbox" name="events" value={e} defaultChecked className="size-3.5 accent-[#F97316]" /> {e}
83	                </label>
84	              ))}
