  const w = (tenant.website ?? {}) as Record<string, string> & {
    galleryImages?: string[];
    why?: string[];
    testimonials?: SiteQuote[];
    faqs?: SiteFaq[];
    sections?: Partial<Record<SectionId, boolean>>;
    sectionOrder?: SectionId[];
