const fs = require("fs");
const off = JSON.parse(fs.readFileSync("/tmp/official_logos.json","utf8"));
const cus = JSON.parse(fs.readFileSync("/tmp/custom_logos.json","utf8"));
// merge in catalog-ish order; official where available, custom otherwise
const order = ["zapier","make","slack","discord","telegram","googlechat","teams","calendar","ga4","gtm","meta","tiktok","pinterest","snapchat","clarity","zalo","stripe","twilio","livechat","default"];
const bodies = { ...cus, ...off };
const officialSet = new Set(Object.keys(off));
let entries = "";
for (const id of order) {
  const b = bodies[id];
  if (!b) { console.error("MISSING BODY", id); process.exit(1); }
  const tag = officialSet.has(id) ? " // official (simple-icons)" : "";
  entries += "  " + id + ": wrap(`" + b + "`)," + tag + "\n";
}
const file = `// Inline SVG brand logos for the App Store. Official brand marks come from the\n// simple-icons project (used descriptively to indicate integration support);\n// Slack, Microsoft Teams, Twilio and Clarity opted out of that library, so\n// those keep clean geometric marks, as does our own Live Chat. Self-contained\n// (no external requests), so they render anywhere including under the strict CSP.\n\nexport function AppLogo({ id, className = \"\" }: { id: string; className?: string }) {\n  const svg = LOGOS[id] ?? LOGOS.default;\n  return <span className={className} aria-hidden dangerouslySetInnerHTML={{ __html: svg }} />;\n}\n\nconst wrap = (inner: string) => \`<svg viewBox=\"0 0 32 32\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\${inner}</svg>\`;\n\nconst LOGOS: Record<string, string> = {\n${entries}};\n`;
fs.writeFileSync("src/components/apps/app-logos.tsx", file);
console.log("wrote app-logos.tsx with", order.length, "entries ("+officialSet.size+" official)");
'

