3	import { useEffect, useRef, useState } from "react";
4	import type { Editor } from "grapesjs";
5	import "grapesjs/dist/css/grapes.min.css";
6	
7	// Advanced website editor (GrapesJS — open-source drag-and-drop builder).
8	// Output is saved to website.custom and, when enabled, replaces the template
9	// on the public site. Scripts are stripped server-side on save.
10	
11	const STARTER = `
12	<section style="padding:90px 24px;text-align:center;background:#faf7f2;">
13	  <h1 style="font-size:44px;margin:0;color:#1a1a1a;">Your studio, your page</h1>
14	  <p style="font-size:17px;color:#666;max-width:520px;margin:14px auto 0;">Drag blocks in from the right, click any text to edit it, and hit Save &amp; publish when you love it.</p>
15	  <a href="/book" style="display:inline-block;margin-top:22px;background:#F97316;color:#fff;padding:14px 30px;border-radius:12px;font-weight:700;text-decoration:none;">Book a class</a>
16	</section>`;
17	
18	export default function AdvancedEditorPage() {
19	  const holder = useRef<HTMLDivElement>(null);
20	  const ed = useRef<Editor | null>(null);
21	  const [status, setStatus] = useState("Loading editor…");
22	  const [enabled, setEnabled] = useState(false);
23	  const [ready, setReady] = useState(false);
24	
25	  useEffect(() => {
26	    let editor: Editor | undefined;
27	    (async () => {
28	      const grapesjs = (await import("grapesjs")).default;
29	      const d = await (await fetch("/api/website/custom")).json();
30	      if (!holder.current) return;
31	      editor = grapesjs.init({
32	        container: holder.current,
33	        height: "100%",
34	        storageManager: false,
35	        components: d.html || STARTER,
36	        style: d.css || "",
37	      });
38	      const bm = editor.BlockManager;
39	      const blk = (id: string, label: string, content: string) => bm.add(id, { id, label, content, category: "Sections" });
40	      blk("nx-hero", "Hero", `<section style="padding:80px 24px;text-align:center;background:#f5f1ea;"><h1 style="font-size:40px;margin:0;">Big headline here</h1><p style="color:#666;margin-top:12px;">A short supporting line.</p><a href="/book" style="display:inline-block;margin-top:20px;background:#F97316;color:#fff;padding:13px 28px;border-radius:12px;font-weight:700;text-decoration:none;">Book a class</a></section>`);
41	      blk("nx-text", "Text", `<section style="padding:48px 24px;max-width:720px;margin:0 auto;"><h2>Section title</h2><p style="color:#555;line-height:1.7;">Tell your story here.</p></section>`);
42	      blk("nx-2col", "Two columns", `<section style="display:flex;gap:24px;padding:48px 24px;flex-wrap:wrap;max-width:960px;margin:0 auto;"><div style="flex:1;min-width:260px;"><h3>Left</h3><p style="color:#555;">Column text.</p></div><div style="flex:1;min-width:260px;"><h3>Right</h3><p style="color:#555;">Column text.</p></div></section>`);
43	      blk("nx-image", "Image", `<img src="https://app.nexis.revsports.ca/window.svg" style="max-width:100%;display:block;margin:0 auto;" alt=""/>`);
44	      blk("nx-cta", "Book button", `<div style="text-align:center;padding:32px;"><a href="/book" style="display:inline-block;background:#F97316;color:#fff;padding:14px 30px;border-radius:12px;font-weight:700;text-decoration:none;">Book a class</a></div>`);
45	      blk("nx-footer", "Footer", `<footer style="padding:40px 24px;text-align:center;color:#888;border-top:1px solid #eee;">© Your Studio · <a href="/book" style="color:#F97316;">Book</a></footer>`);
46	      ed.current = editor;
47	      setEnabled(!!d.enabled);
48	      setReady(true);
49	      setStatus("");
50	    })();
51	    return () => editor?.destroy();
52	  }, []);
53	
54	  const save = async (publish?: boolean) => {
55	    if (!ed.current) return;
56	    setStatus("Saving…");
57	    const res = await fetch("/api/website/custom", {
58	      method: "POST",
59	      headers: { "Content-Type": "application/json" },
60	      body: JSON.stringify({ html: ed.current.getHtml(), css: ed.current.getCss(), ...(publish !== undefined ? { enabled: publish } : {}) }),
61	    }).catch(() => null);
62	    if (res?.ok) {
63	      if (publish !== undefined) setEnabled(publish);
64	      setStatus(publish ? "Published — your custom page is live!" : publish === false ? "Saved. Back on your template." : "Saved.");
65	    } else setStatus("Save failed — try again.");
66	    setTimeout(() => setStatus(""), 3500);
67	  };
68	
69	  return (
70	    <div className="flex h-[calc(100vh-120px)] min-h-[560px] flex-col">
71	      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
72	        <div>
73	          <h1 className="font-display text-[22px] font-extrabold tracking-tight text-ink">Advanced editor <span className="rounded-full bg-brand-wash px-2 py-0.5 align-middle text-[10.5px] font-bold text-brand">BETA</span></h1>
74	          <p className="text-[12px] text-muted">Full drag-and-drop control (powered by GrapesJS). {enabled ? "Your custom page is LIVE instead of the template." : "Your template stays live until you publish."}</p>
75	        </div>
76	        <div className="flex items-center gap-2">
77	          {status && <span className="text-[12px] font-bold text-brand">{status}</span>}
78	          <a href="/website" className="rounded-lg border border-line-2 px-3 py-2 text-[12px] font-bold text-ink-2 hover:text-ink">← Builder</a>
79	          <button onClick={() => save()} disabled={!ready} className="rounded-lg bg-line-2 px-3.5 py-2 text-[12px] font-bold text-ink-2 hover:text-ink disabled:opacity-50">Save draft</button>
80	          {enabled ? (
81	            <button onClick={() => save(false)} disabled={!ready} className="rounded-lg border border-line-2 px-3.5 py-2 text-[12px] font-bold text-ink-2 hover:text-ink disabled:opacity-50">Switch back to template</button>
82	          ) : null}
83	          <button onClick={() => save(true)} disabled={!ready} className="rounded-lg bg-brand px-4 py-2 text-[12px] font-bold text-white hover:bg-brand-ink disabled:opacity-50">Save &amp; publish</button>
84	        </div>
85	      </div>
86	      <div className="min-h-0 flex-1 overflow-hidden rounded-2xl border border-line-2 bg-white">
87	        <div ref={holder} className="h-full" />
88	      </div>
89	    </div>
90	  );
91	}

