52	  const bookings = await db.booking.findMany({
53	    where: { tenantId: tenant.id, clientId: cs.clientId },
54	    include: { session: { include: { classType: true, instructor: true } } },
55	    orderBy: { session: { startsAt: "desc" } },
56	    take: 100,
57	  });
58	  const now = new Date();
