62	  const waitlist = bookings.filter((b) => b.session.startsAt > now && b.status === "WAITLIST").sort((a, b) => a.session.startsAt.getTime() - b.session.startsAt.getTime());
63	  const past = bookings.filter((b) => b.session.startsAt <= now || ["CANCELLED", "LATE_CANCEL", "NO_SHOW"].includes(b.status));
