76	        <div className="flex flex-wrap items-start justify-between gap-3">
77	          <div>
78	            <h1 className="font-display text-[28px] font-extrabold tracking-tight text-ink">My Bookings</h1>
79	            <p className="mt-1 text-sm text-muted">All your past, current, and upcoming sessions.</p>
80	          </div>
