export default async function SupportPage({ searchParams }: { searchParams: Promise<{ t?: string; ok?: string; error?: string }> }) {
  const { t: sel, ok, error } = await searchParams;
  const tenant = await getCurrentTenant();
  const tickets = await db.supportTicket.findMany({ where: { tenantId: tenant.id }, orderBy: { updatedAt: "desc" }, take: 50 });
  const open = sel ? tickets.find((x) => x.id === sel) : null;
  const field = "w-full rounded-[10px] border border-line bg-surface px-3 py-2.5 text-sm outline-none placeholder:text-muted focus:border-brand focus:ring-4 focus:ring-brand/10";

  return (
    <div className="mx-auto max-w-[1100px]">
      <h1 className="font-display text-[30px] font-extrabold tracking-tight text-ink">Support</h1>
      <p className="mt-1 text-sm text-muted">Message the StudioNexis team — we usually reply within a few hours. <b className="text-ink-2">We&apos;re still in beta, so we&apos;d genuinely love your feedback on anything that feels off.</b></p>
      <div className="mt-5"><NexisSupportChat /></div>
      {ok && <div className="mt-4 rounded-xl border border-green/20 bg-green-wash px-3.5 py-2.5 text-[13px] font-medium text-green">Sent! We&apos;re on it.</div>}
      {error && <div className="mt-4 rounded-xl border border-rose/20 bg-rose/5 px-3.5 py-2.5 text-[13px] font-medium text-rose">Add a subject and a message.</div>}

      <div className="mt-6 grid grid-cols-1 gap-5 lg:grid-cols-[1fr_380px]">
        <div className="space-y-5">
          {open ? (
            <Card>
              <div className="border-b border-line-2 p-5">
                <Link href="/support" className="text-[12px] font-bold text-muted hover:text-ink">← All tickets</Link>
                <div className="mt-1 flex items-center gap-2">
                  <h2 className="font-display text-[19px] font-extrabold text-ink">{open.subject}</h2>
                  <span className={`rounded-full px-2.5 py-1 text-[10.5px] font-bold ${tone[open.status]}`}>{open.status}</span>
                  {open.kind === "bug" && <span className="rounded-full bg-rose/10 px-2.5 py-1 text-[10.5px] font-bold text-rose">BUG</span>}
                </div>
              </div>
              <div className="max-h-[420px] space-y-3 overflow-y-auto p-5">
                {(open.messages as unknown as Msg[]).map((m, i) => (
                  <div key={i} className={`max-w-[85%] rounded-2xl px-4 py-2.5 ${m.from === "hq" ? "bg-brand-wash" : "ml-auto bg-raised"}`}>
                    <div className="text-[10.5px] font-bold text-muted">{m.from === "hq" ? "StudioNexis Support" : m.name} · {new Date(m.at).toLocaleString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}</div>
                    <div className="mt-0.5 whitespace-pre-wrap text-[13.5px] text-ink">{m.text}</div>
                  </div>
                ))}
              </div>
              <form method="post" action="/api/support" className="flex gap-2 border-t border-line-2 p-4">
                <input type="hidden" name="mode" value="reply" />
                <input type="hidden" name="id" value={open.id} />
                <input name="text" required placeholder="Write a reply…" className={field} />
                <button className="shrink-0 rounded-[10px] bg-brand px-4 text-sm font-bold text-white">Send</button>
              </form>
            </Card>
          ) : (
            <Card>
              <CardHeader title="Your tickets" sub="Click one to open the conversation" />
              <ul className="divide-y divide-line-2">
                {tickets.map((t) => (
                  <li key={t.id}>
                    <Link href={`/support?t=${t.id}`} className="flex items-center justify-between px-5 py-3.5 hover:bg-raised">
                      <span className="min-w-0">
                        <span className="block truncate text-[13.5px] font-semibold text-ink">{t.kind === "bug" ? <Bug className="mr-0.5 inline size-3.5 -mt-0.5" /> : null}{t.subject}</span>
                        <span className="text-[11.5px] text-muted">{t.updatedAt.toLocaleDateString("en-US", { month: "short", day: "numeric" })} · {(t.messages as unknown[]).length} message(s)</span>
                      </span>
                      <span className={`shrink-0 rounded-full px-2.5 py-1 text-[10.5px] font-bold ${tone[t.status]}`}>{t.status}</span>
                    </Link>
                  </li>
                ))}
                {tickets.length === 0 && <li className="px-5 py-10 text-center text-sm text-muted">No tickets yet — start one on the right.</li>}
              </ul>
            </Card>
          )}
        </div>

        <div className="space-y-5">
          <Card>
            <CardHeader title="New support ticket" sub="Questions, billing, how-tos" />
            <form method="post" action="/api/support" className="space-y-3 p-5">
              <input type="hidden" name="kind" value="support" />
              <input name="subject" required placeholder="Subject" className={field} />
              <textarea name="text" rows={4} required placeholder="How can we help?" className={field} />
              <button className="w-full rounded-[10px] bg-brand py-2.5 text-sm font-bold text-white hover:bg-brand-ink">Send to support</button>
            </form>
          </Card>
          <Card>
            <CardHeader title="Report a bug" sub="We auto-attach your browser & page details" />
            <form method="post" action="/api/support" className="space-y-3 p-5">
              <input type="hidden" name="kind" value="bug" />
              <input type="hidden" name="ctx_url" id="nx-ctx-url" />
              <input type="hidden" name="ctx_screen" id="nx-ctx-screen" />
              <script dangerouslySetInnerHTML={{ __html: `document.getElementById('nx-ctx-url').value=location.href;document.getElementById('nx-ctx-screen').value=screen.width+'x'+screen.height;` }} />
              <input name="subject" required placeholder="What broke?" className={field} />
              <textarea name="text" rows={4} required placeholder="What did you do, what did you expect, what happened?" className={field} />
              <button className="w-full rounded-[10px] bg-ink py-2.5 text-sm font-bold text-canvas hover:opacity-90">Report bug</button>
            </form>
          </Card>
        </div>
      </div>
    </div>
  );
}

import type { AppsConfig, Webhook } from "@/lib/webhooks";

// The App Store catalog. Apps are browsed and explicitly "added" to a studio;
// only added apps show their configuration, so the page stays tidy instead of
// dumping every integration side by side.
export type AppDef = {
  id: string;
  name: string;
  category: string;
  icon: string;
  blurb: string;
  kind: "config" | "status"; // status = external connection (Stripe/Twilio), not self-installable
};

export const APP_CATALOG: AppDef[] = [
  { id: "zapier", name: "Zapier", category: "Automation", icon: "", blurb: "Push bookings, clients and sales to 7,000+ apps with a Zapier Catch Hook.", kind: "config" },
  { id: "make", name: "Make", category: "Automation", icon: "", blurb: "Send bookings, clients and sales into Make.com scenarios via a webhook.", kind: "config" },
  { id: "slack", name: "Slack", category: "Team alerts", icon: "", blurb: "Post booking & sale alerts to a Slack channel the moment they happen.", kind: "config" },
  { id: "discord", name: "Discord", category: "Team alerts", icon: "", blurb: "Send booking & sale alerts to your Discord server.", kind: "config" },
  { id: "telegram", name: "Telegram", category: "Team alerts", icon: "", blurb: "Get booking & sale alerts in a Telegram chat via your bot.", kind: "config" },
  { id: "googlechat", name: "Google Chat", category: "Team alerts", icon: "", blurb: "Send booking & sale alerts to a Google Chat space via a webhook.", kind: "config" },
  { id: "teams", name: "Microsoft Teams", category: "Team alerts", icon: "", blurb: "Post booking & sale alerts to a Microsoft Teams channel.", kind: "config" },
  { id: "calendar", name: "Calendar feed", category: "Calendar", icon: "", blurb: "Subscribe to your class schedule from Google, Apple or Outlook.", kind: "config" },
  { id: "ga4", name: "Google Analytics", category: "Marketing", icon: "", blurb: "Add your GA4 tag to your booking site to measure traffic and conversions.", kind: "config" },
  { id: "gtm", name: "Google Tag Manager", category: "Marketing", icon: "", blurb: "Manage all your marketing tags from one GTM container on your site.", kind: "config" },
  { id: "meta", name: "Meta Pixel", category: "Marketing", icon: "", blurb: "Add the Meta (Facebook/Instagram) Pixel to retarget visitors with ads.", kind: "config" },
  { id: "tiktok", name: "TikTok Pixel", category: "Marketing", icon: "", blurb: "Add the TikTok Pixel to track and retarget from your TikTok campaigns.", kind: "config" },
  { id: "pinterest", name: "Pinterest Tag", category: "Marketing", icon: "", blurb: "Track conversions and retarget from your Pinterest campaigns.", kind: "config" },
  { id: "snapchat", name: "Snapchat Pixel", category: "Marketing", icon: "", blurb: "Measure and retarget visitors from your Snapchat ads.", kind: "config" },
  { id: "clarity", name: "Microsoft Clarity", category: "Insights", icon: "", blurb: "Free heatmaps & session recordings to see how visitors use your site.", kind: "config" },
  { id: "zalo", name: "Zalo", category: "Support", icon: "", blurb: "Add a “Chat on Zalo” button to your booking site so clients reach you on Zalo.", kind: "config" },
  { id: "livechat", name: "Live chat widget", category: "Support", icon: "", blurb: "A chat bubble on your website and booking pages, answered from your Inbox.", kind: "config" },
  { id: "stripe", name: "Stripe payments", category: "Payments", icon: "", blurb: "Take card payments for packages, memberships and classes.", kind: "status" },
  { id: "twilio", name: "SMS & WhatsApp", category: "Messaging", icon: "", blurb: "Send confirmations and reminders by text and WhatsApp.", kind: "status" },
];

export const CONFIG_APP_IDS = APP_CATALOG.filter((a) => a.kind === "config").map((a) => a.id);

// Does this app already have real configuration? (so we never hide live setups)
export function appConfigured(id: string, apps: AppsConfig, hooks: Webhook[]): boolean {
  switch (id) {
    case "zapier": return hooks.some((h) => h.source !== "make");
    case "make": return hooks.some((h) => h.source === "make");
    case "slack": return !!apps.slackUrl;
    case "discord": return !!apps.discordUrl;
    case "googlechat": return !!apps.googleChatUrl;
    case "teams": return !!apps.teamsUrl;
    case "telegram": return !!apps.telegramToken;
    case "calendar": return !!apps.icalToken;
    case "ga4": return !!apps.pixels?.ga4;
    case "gtm": return !!apps.pixels?.gtm;
    case "meta": return !!apps.pixels?.meta;
    case "tiktok": return !!apps.pixels?.tiktok;
    case "pinterest": return !!apps.pixels?.pinterest;
    case "snapchat": return !!apps.pixels?.snapchat;
    case "clarity": return !!apps.pixels?.clarity;
    case "zalo": return !!apps.zaloId;
    case "livechat": return !apps.chatDisabled; // on by default
    default: return false;
  }
}

// An app is "in Your apps" if the studio added it OR it already has config.
export function appInstalled(id: string, apps: AppsConfig, hooks: Webhook[]): boolean {
  return (apps.installed ?? []).includes(id) || appConfigured(id, apps, hooks);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Paperclip } from "lucide-react";

// Live chat inbox for studio staff (Tidio-style, 3s polling).
type Msg = { from: "visitor" | "studio"; name: string; text: string; at: string; image?: string };
type Convo = { id: string; name: string; contact: string | null; status: string; unread: number; last: string; lastAt: string };
type Thread = { id: string; name: string | null; contact: string | null; clientId: string | null; status: string; messages: Msg[] };

export default function InboxPage() {
  const [convos, setConvos] = useState<Convo[]>([]);
  const [showAll, setShowAll] = useState(false);
  const [sel, setSel] = useState<string | null>(null);
  const [thread, setThread] = useState<Thread | null>(null);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const bottom = useRef<HTMLDivElement>(null);
  const selRef = useRef(sel);
  selRef.current = sel;
  const allRef = useRef(showAll);
  allRef.current = showAll;

  const pull = useCallback(async () => {
    try {
      const res = await fetch(`/api/chat${allRef.current ? "?all=1" : ""}`);
      const d = await res.json();
      if (d.conversations) setConvos(d.conversations);
      if (selRef.current) {
        const t = await (await fetch(`/api/chat?c=${selRef.current}`)).json();
        if (t.messages) setThread(t);
      }
    } catch {}
  }, []);

  useEffect(() => {
    pull();
    const t = setInterval(pull, 3000);
    return () => clearInterval(t);
  }, [pull]);
  useEffect(() => { bottom.current?.scrollIntoView(); }, [thread?.messages.length]);
  useEffect(() => { if (sel) pull(); }, [sel, pull]);

  const post = async (t: string, image?: string) => {
    if (!sel) return;
    setThread((th) => th ? { ...th, messages: [...th.messages, { from: "studio", name: "You", text: t, at: new Date().toISOString(), ...(image ? { image } : {}) }] } : th);
    await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: sel, text: t, ...(image ? { image } : {}) }) }).catch(() => {});
    pull();
  };
  const send = async () => {
    const t = text.trim();
    if (!t || !sel) return;
    setText("");
    post(t);
  };
  const attach = async (file: File) => {
    if (!file || !sel || busy) return;
    setBusy(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/chat/upload", { method: "POST", body: fd });
      const d = await res.json();
      if (res.ok && d.url) { await post(text.trim(), d.url); setText(""); }
      else alert(d.message || "Couldn't send that image.");
    } catch { alert("Couldn't send that image."); }
    setBusy(false);
    if (fileRef.current) fileRef.current.value = "";
  };
  const setStatus = async (close: boolean) => {
    if (!sel) return;
    await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: sel, close }) }).catch(() => {});
    pull();
  };

  return (
    <div className="mx-auto max-w-[1200px]">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="font-display text-[30px] font-extrabold tracking-tight text-ink">Inbox</h1>
          <p className="mt-1 text-sm text-muted">Live chat with visitors and clients from your website — updates every few seconds.</p>
        </div>
        <button onClick={() => { setShowAll(!showAll); setTimeout(pull, 0); }} className="rounded-lg bg-line-2 px-3 py-1.5 text-[12px] font-bold text-ink-2 hover:text-ink">
          {showAll ? "Open only" : "Show closed too"}
        </button>
      </div>

      <div className="mt-6 grid h-[560px] grid-cols-1 gap-5 lg:grid-cols-[340px_1fr]">
        <div className="overflow-y-auto rounded-2xl border border-line-2 bg-surface shadow-[var(--shadow-card)]">
          {convos.map((c) => (
            <button key={c.id} onClick={() => setSel(c.id)}
              className={`block w-full border-b border-line-2 px-4 py-3 text-left last:border-0 hover:bg-raised ${sel === c.id ? "bg-brand-wash/50" : ""}`}>
              <div className="flex items-center justify-between">
                <span className="text-[13.5px] font-bold text-ink">{c.name}{c.status === "CLOSED" ? " · closed" : ""}</span>
                <span className="flex items-center gap-1.5">
                  {c.unread > 0 && <span className="grid size-5 place-items-center rounded-full bg-brand text-[10.5px] font-bold text-white">{c.unread}</span>}
                  <span className="text-[10.5px] text-muted">{new Date(c.lastAt).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}</span>
                </span>
              </div>
              <div className="mt-0.5 truncate text-[12px] text-muted">{c.last}</div>
            </button>
          ))}
          {convos.length === 0 && <div className="p-8 text-center text-sm text-muted">No conversations yet. The chat bubble is live on your website and booking pages.</div>}
        </div>

        <div className="flex flex-col overflow-hidden rounded-2xl border border-line-2 bg-surface shadow-[var(--shadow-card)]">
          {thread ? (
            <>
              <div className="flex items-center justify-between border-b border-line-2 px-5 py-3">
                <div>
                  <div className="text-[14.5px] font-bold text-ink">{thread.name ?? "Visitor"}</div>
                  <div className="text-[11.5px] text-muted">{thread.contact ?? "no contact left"}{thread.clientId && <a href={`/clients/${thread.clientId}`} className="ml-2 font-bold text-brand hover:underline">Open client →</a>}</div>
                </div>
                <button onClick={() => setStatus(thread.status !== "CLOSED")} className={`rounded-lg px-3 py-1.5 text-[11.5px] font-bold ${thread.status === "CLOSED" ? "bg-green-wash text-green" : "bg-line-2 text-ink-2 hover:text-ink"}`}>
                  {thread.status === "CLOSED" ? "Reopen" : "Close chat"}
                </button>
              </div>
              <div className="flex-1 space-y-2 overflow-y-auto bg-raised/50 p-4">
                {thread.messages.map((m, i) => (
                  <div key={i} className={`max-w-[75%] rounded-2xl px-3.5 py-2 text-[13px] shadow-sm ${m.from === "studio" ? "ml-auto rounded-br-sm bg-brand text-white" : "rounded-tl-sm bg-surface text-ink"}`}>
                    <div className={`text-[10px] font-bold ${m.from === "studio" ? "text-white/70" : "text-muted"}`}>{m.name} · {new Date(m.at).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}</div>
                    {m.image && <a href={m.image} target="_blank" rel="noreferrer"><img src={m.image} alt="attachment" className="mt-1 max-h-52 rounded-lg object-cover" /></a>}
                    {m.text && <div className="mt-0.5 whitespace-pre-wrap">{m.text}</div>}
                  </div>
                ))}
                <div ref={bottom} />
              </div>
              <div className="flex gap-2 border-t border-line-2 p-3">
                <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(e) => e.target.files?.[0] && attach(e.target.files[0])} />
                <button onClick={() => fileRef.current?.click()} disabled={busy} title="Attach a photo" className="grid size-11 shrink-0 place-items-center rounded-xl bg-line-2 text-[17px] text-ink-2 hover:text-ink disabled:opacity-50">{busy ? "…" : <Paperclip className="size-4" />}</button>
                <input value={text} onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()}
                  placeholder="Type your reply…" className="h-11 flex-1 rounded-xl border border-line bg-surface px-3.5 text-sm outline-none focus:border-brand" />
                <button onClick={send} className="rounded-xl bg-brand px-5 text-sm font-bold text-white hover:bg-brand-ink">Send</button>
              </div>
            </>
          ) : (
            <div className="grid flex-1 place-items-center text-sm text-muted">Pick a conversation on the left.</div>
          )}
        </div>
      </div>
    </div>
  );
}

