=== apex conf ===
server {
    server_name nexis.revsports.ca;
    location /.well-known/acme-challenge/ { root /var/www/html; allow all; }
    client_max_body_size 15M;
    location /api/ { proxy_pass http://127.0.0.1:8392; proxy_http_version 1.1; proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_set_header X-Forwarded-Proto $scheme; proxy_set_header Upgrade $http_upgrade; proxy_set_header Connection "upgrade"; }
    location /studionexis-public/ { proxy_pass http://127.0.0.1:6326; proxy_set_header Host $host; }
    # Studio app is per-tenant only — hide on the apex marketing host.
    location ~ ^/(booking|packages|checkout|account|my-bookings|my-package|onboarding|register|verify-email|reset-password|forgot-password)(/|$) { return 302 /; }
    location / { proxy_pass http://127.0.0.1:3720; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }

    listen 72.62.69.9:443 ssl; # managed by Certbot
    ssl_certificate /etc/letsencrypt/live/nexis.revsports.ca/fullchain.pem; # managed by Certbot
    ssl_certificate_key /etc/letsencrypt/live/nexis.revsports.ca/privkey.pem; # managed by Certbot
    include /etc/letsencrypt/options-ssl-nginx.conf; # managed by Certbot
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem; # managed by Certbot

}
server {
    if ($host = nexis.revsports.ca) {
        return 301 https://$host$request_uri;
    } # managed by Certbot


    listen 72.62.69.9:80;
    server_name nexis.revsports.ca;
    return 404; # managed by Certbot


}=== v2-subdomains (how app. proxies) ===
# Studio Nexis v2 host carve-outs. Exact server_name beats the old
# system's wildcard, so these subdomains route to v2 while everything
# else stays on the old stack until cutover.
map $host $v2_upstream { default 127.0.0.1:3105; }

server {
    listen 72.62.69.9:80;
    server_name app.nexis.revsports.ca hq.nexis.revsports.ca new.nexis.revsports.ca dev-studio.nexis.revsports.ca dev-studio-westside.nexis.revsports.ca lol.nexis.revsports.ca recharged.nexis.revsports.ca recharged-neongalaxy.nexis.revsports.ca sunrise-yoga.nexis.revsports.ca sunrise-yoga-2.nexis.revsports.ca test-studio.nexis.revsports.ca wizard-flow-studio.nexis.revsports.ca;
    return 301 https://$host$request_uri;
}
server {
    listen 72.62.69.9:443 ssl;
    server_name app.nexis.revsports.ca hq.nexis.revsports.ca new.nexis.revsports.ca dev-studio.nexis.revsports.ca dev-studio-westside.nexis.revsports.ca lol.nexis.revsports.ca recharged.nexis.revsports.ca recharged-neongalaxy.nexis.revsports.ca sunrise-yoga.nexis.revsports.ca sunrise-yoga-2.nexis.revsports.ca test-studio.nexis.revsports.ca wizard-flow-studio.nexis.revsports.ca;
    ssl_certificate /etc/letsencrypt/live/nexis.revsports.ca-0001/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nexis.revsports.ca-0001/privkey.pem;
    client_max_body_size 12m;
    location / {
        proxy_pass http://$v2_upstream;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Host $host;
    }
}

