1	---
2	// Studio Nexis — SaaS marketing landing page (apex / control-plane host).
3	// Premium B2B SaaS look: orange brand, warm neutrals, CSS-drawn product
4	// mockups (no stock photos). Tenant subdomains with a published studio
5	// website are redirected to /site by the inline script in <head>.
6	---
7	<!doctype html>
8	<html lang="en">
9	  <head>
10	    <meta charset="UTF-8" />
11	    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
12	    <title>Studio Nexis — The operating system for pilates & yoga studios</title>
13	    <meta name="description" content="Booking, CRM, POS, payments, memberships, staff, finance, analytics and marketing automation — everything your pilates or yoga studio needs in one modern platform." />
14	    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
15	    <meta property="og:type" content="website" />
16	    <meta property="og:title" content="Studio Nexis — Run your entire studio from one beautiful platform" />
17	    <meta property="og:description" content="The all-in-one operating system for modern pilates & yoga studios." />
18	    <link rel="preconnect" href="https://fonts.googleapis.com" />
19	    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
20	    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet" />
21	    <script is:inline>
22	      // Tenant subdomains with a published studio website show their own site;
23	      // the apex (control-plane) host keeps this SaaS marketing page.
24	      (async function () {
25	        try {
26	          var r = await fetch('/api/settings/public');
27	          if (r.ok) {
28	            var j = await r.json();
29	            if (j && j.site && j.site.published) window.location.replace('/site');
30	          }
31	        } catch (e) {}
32	      })();
33	    </script>
34	    <style is:global>
35	      :root{
36	        --or:#F97316;--or2:#fb923c;--or3:#fdba74;--or-bg:#fff7ed;
37	        --ink:#1c1917;--ink2:#44403c;--muted:#78716c;--line:#e7e5e4;--line2:#efedeb;
38	        --bg:#fffdfb;--warm:#faf6f0;--card:#ffffff;
39	        --r:20px;--r-sm:14px;
40	        --sh:0 1px 2px rgba(28,25,23,.05),0 8px 28px rgba(28,25,23,.07);
41	        --sh-lg:0 2px 6px rgba(28,25,23,.06),0 24px 60px rgba(28,25,23,.13);
42	      }
43	      *{box-sizing:border-box;margin:0;padding:0}
44	      html{scroll-behavior:smooth}
45	      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.6;overflow-x:hidden}
46	      h1,h2,h3,.disp{font-family:'Manrope',sans-serif;letter-spacing:-.025em;line-height:1.12}
47	      a{text-decoration:none;color:inherit}
48	      .wrap{max-width:1160px;margin:0 auto;padding:0 24px}
49	      section{position:relative}
50	
51	      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;padding:13px 26px;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:.18s;font-family:'Inter'}
52	      .btn-primary{background:linear-gradient(135deg,var(--or),#ea580c);color:#fff;box-shadow:0 6px 20px rgba(249,115,22,.32),inset 0 1px 0 rgba(255,255,255,.24)}
53	      .btn-primary:hover{transform:translateY(-1px);box-shadow:0 10px 28px rgba(249,115,22,.4),inset 0 1px 0 rgba(255,255,255,.24)}
54	      .btn-ghost{border-color:var(--line);color:var(--ink);background:#fff}
55	      .btn-ghost:hover{background:var(--warm)}
56	      .btn-lg{font-size:16px;padding:15px 32px;border-radius:14px}
57	
58	      .tag{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--or);background:var(--or-bg);border:1px solid #ffedd5;border-radius:99px;padding:7px 15px;margin-bottom:18px}
59	      .h2{font-size:clamp(30px,4.4vw,44px);font-weight:800;margin-bottom:16px}
60	      .sub{font-size:17px;color:var(--muted);max-width:640px}
61	      .center{text-align:center}.center .sub{margin:0 auto}
62	
63	      /* reveal on scroll */
64	      .rv{opacity:0;transform:translateY(22px);transition:opacity .7s cubic-bezier(.22,1,.36,1),transform .7s cubic-bezier(.22,1,.36,1)}
65	      .rv.in{opacity:1;transform:none}
66	
67	      /* ───────── nav ───────── */
68	      nav{position:sticky;top:0;z-index:50;background:rgba(255,253,251,.82);backdrop-filter:blur(14px);border-bottom:1px solid var(--line2)}
69	      .nav-in{max-width:1160px;margin:0 auto;padding:15px 24px;display:flex;align-items:center;gap:30px}
70	      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:19px}
71	      .logo-mark{width:32px;height:32px;border-radius:10px;background:linear-gradient(135deg,var(--or),#ea580c);display:grid;place-items:center;color:#fff;font-weight:800;box-shadow:0 4px 12px rgba(249,115,22,.35)}
72	      .nav-links{display:flex;gap:26px;font-size:14px;font-weight:600;color:var(--muted)}
73	      .nav-links a{transition:.15s}
74	      .nav-links a:hover{color:var(--ink)}
75	      .nav-cta{margin-left:auto;display:flex;gap:10px;align-items:center}
76	      .nav-cta .login{font-size:14px;font-weight:600;color:var(--muted);margin-right:6px}
77	      .nav-cta .login:hover{color:var(--ink)}
78	      .nav-cta .btn{padding:10px 20px;font-size:14px}
79	      @media(max-width:860px){.nav-links{display:none}}
80	
81	      /* ───────── hero ───────── */
82	      .hero{padding:84px 0 40px;overflow:hidden}
83	      .hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:54px;align-items:center}
84	      @media(max-width:980px){.hero-grid{grid-template-columns:1fr}}
85	      .hero h1{font-size:clamp(38px,5.4vw,62px);font-weight:800;margin-bottom:22px}
86	      .hero h1 em{font-style:normal;background:linear-gradient(120deg,var(--or),#ea580c);-webkit-background-clip:text;background-clip:text;color:transparent}
87	      .hero .sub{margin-bottom:32px}
88	      .hero-acts{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:26px}
89	      .hero-note{font-size:13px;color:var(--muted);display:flex;gap:18px;flex-wrap:wrap}
90	      .hero-note span{display:inline-flex;align-items:center;gap:6px}
91	      .hero-note svg{color:#16a34a}
92	      .blob{position:absolute;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0}
93	      .blob.b1{width:520px;height:520px;background:rgba(249,115,22,.14);top:-160px;right:-120px}
94	      .blob.b2{width:420px;height:420px;background:rgba(253,186,116,.18);bottom:-180px;left:-140px}
95	
96	      /* dashboard mockup */
97	      .stage{position:relative;z-index:1}
98	      .dash{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-lg);overflow:hidden;transform:rotate(.6deg);animation:floaty 7s ease-in-out infinite}
99	      @keyframes floaty{0%,100%{transform:rotate(.6deg) translateY(0)}50%{transform:rotate(.6deg) translateY(-9px)}}
100	      .dash-top{display:flex;align-items:center;gap:7px;padding:11px 15px;border-bottom:1px solid var(--line2);background:#fdfbf8}
101	      .dash-top i{width:10px;height:10px;border-radius:50%;background:var(--line);display:block}
102	      .dash-top i:first-child{background:#fca5a5}.dash-top i:nth-child(2){background:#fcd34d}.dash-top i:nth-child(3){background:#86efac}
103	      .dash-top span{font-size:11px;color:var(--muted);margin-left:8px;font-weight:600}
104	      .dash-body{display:grid;grid-template-columns:1.25fr 1fr;gap:12px;padding:15px}
105	      .panel{border:1px solid var(--line2);border-radius:var(--r-sm);padding:13px;background:#fff}
