            <div class="twho"><span class="tava" style="background:linear-gradient(135deg,#0ea5e9,#0369a1)">AS</span><div><b>Ava Sørensen</b><small>Director, Studio North</small></div></div>
          </div>
        </div>
      </div>
    </section>

    <!-- ═══════════ PRICING ═══════════ -->
    <section class="pricing" id="pricing">
      <div class="wrap">
        <div class="center rv">

input.content:
/* Studio Nexis — marketing landing (apex host). Bespoke, self-contained
   design system scoped under .nxs so it never leaks into the app. Warm
   ivory + orange, Fraunces serif display accents, CSS-drawn product mocks. */

.nxs {
  --or: #f97316;
  --or-ink: #ea580c;
  --or-deep: #c2410c;
  --or-bg: #fff4ea;
  --or-bg2: #ffe9d6;
  --ink: #191512;
  --ink2: #4b443d;
  --muted: #857b70;
  --line: #ece6dd;
  --line2: #f3eee6;
  --bg: #fdfaf5;
  --warm: #f7f1e8;
  --card: #ffffff;
  --green: #17935a;
  --green-bg: #e6f6ec;
  --purple: #7c5cf0;
  --blue: #2f7ef0;
  --r: 22px;
  --r-sm: 14px;
  --sh: 0 1px 2px rgba(25, 21, 18, 0.05), 0 10px 30px rgba(25, 21, 18, 0.07);
  --sh-lg: 0 2px 8px rgba(25, 21, 18, 0.06), 0 30px 70px rgba(25, 21, 18, 0.15);
  --maxw: 1180px;

  font-family: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
.nxs *,
.nxs *::before,
.nxs *::after { box-sizing: border-box; }
.nxs h1, .nxs h2, .nxs h3, .nxs h4, .nxs .disp {
  font-family: var(--font-manrope), var(--font-inter), sans-serif;
  letter-spacing: -0.025em;
  line-height: 1.1;
}
.nxs .serif {
  font-family: var(--font-fraunces), Georgia, serif;
  letter-spacing: -0.01em;
}
.nxs a { color: inherit; text-decoration: none; }
.nxs button { font-family: inherit; cursor: pointer; }
.nxs .wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 24px; }
.nxs section { position: relative; }

/* dotted background texture + warm glow */
.nxs .bg-grid {
  position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background-image: radial-gradient(rgba(25, 21, 18, 0.045) 1px, transparent 1px);
  background-size: 26px 26px;
  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent 78%);
  mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent 78%);
}
.nxs .glow {
  position: absolute; border-radius: 50%; filter: blur(100px);
  pointer-events: none; z-index: 0;
}

/* ── buttons ── */
.nxs .btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 700; font-size: 15px; padding: 13px 24px; border-radius: 13px;
  border: 1px solid transparent; transition: transform 0.16s, box-shadow 0.16s, background 0.16s;
  white-space: nowrap;
}
.nxs .btn svg { width: 18px; height: 18px; }
.nxs .btn-primary {
  background: linear-gradient(135deg, #fb923c, var(--or-ink));
  color: #fff;
  box-shadow: 0 8px 22px rgba(249, 115, 22, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
.nxs .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 14px 32px rgba(249, 115, 22, 0.44), inset 0 1px 0 rgba(255, 255, 255, 0.28); }
.nxs .btn-ghost { border-color: var(--line); color: var(--ink); background: #fff; }
.nxs .btn-ghost:hover { background: var(--warm); transform: translateY(-2px); }
.nxs .btn-lg { font-size: 16px; padding: 16px 30px; border-radius: 15px; }

/* ── shared bits ── */
.nxs .eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 700; letter-spacing: 0.11em; text-transform: uppercase;
  color: var(--or-deep); background: var(--or-bg); border: 1px solid var(--or-bg2);
  border-radius: 99px; padding: 7px 14px; margin-bottom: 20px;
}
.nxs .eyebrow svg { width: 14px; height: 14px; }
.nxs .h2 { font-size: clamp(30px, 4.4vw, 46px); font-weight: 800; margin-bottom: 16px; }
.nxs .h2 em { font-style: italic; font-weight: 500; color: var(--or-ink); }
.nxs .lead { font-size: 17.5px; color: var(--muted); max-width: 640px; }
.nxs .center { text-align: center; }
.nxs .center .lead { margin-left: auto; margin-right: auto; }

/* reveal on scroll */
.nxs .rv { opacity: 0; transform: translateY(26px); transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1), transform 0.7s cubic-bezier(0.22, 1, 0.36, 1); }
.nxs .rv.in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .nxs .rv { opacity: 1; transform: none; transition: none; }
  .nxs .float, .nxs .float2, .nxs .ticker-track { animation: none !important; }
}

/* ── nav ── */
.nxs-nav {
  position: sticky; top: 0; z-index: 60;
  background: rgba(253, 250, 245, 0.8); backdrop-filter: blur(16px) saturate(1.4);
  border-bottom: 1px solid var(--line2);
}
.nxs-nav .nav-in { max-width: var(--maxw); margin: 0 auto; padding: 14px 24px; display: flex; align-items: center; gap: 32px; }
.nxs .logo { display: flex; align-items: center; gap: 11px; font-family: var(--font-manrope), sans-serif; font-weight: 800; font-size: 19px; }
.nxs .logo-mark {
  width: 34px; height: 34px; border-radius: 11px;
  background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff;
  display: grid; place-items: center; box-shadow: 0 5px 14px rgba(249, 115, 22, 0.4);
}
.nxs .logo-mark svg { width: 19px; height: 19px; }
.nxs .nav-links { display: flex; gap: 28px; font-size: 14.5px; font-weight: 600; color: var(--ink2); }
.nxs .nav-links a { transition: color 0.15s; }
.nxs .nav-links a:hover { color: var(--or-ink); }
.nxs .nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.nxs .nav-login { font-size: 14.5px; font-weight: 600; color: var(--ink2); padding: 10px 14px; }
.nxs .nav-login:hover { color: var(--ink); }
.nxs .nav-right .btn { padding: 10px 18px; font-size: 14px; }
.nxs .burger { display: none; width: 42px; height: 42px; border-radius: 11px; border: 1px solid var(--line); background: #fff; align-items: center; justify-content: center; }
.nxs .burger svg { width: 20px; height: 20px; }
@media (max-width: 900px) {
  .nxs .nav-links { display: none; }
  .nxs .nav-login { display: none; }
  .nxs .burger { display: inline-flex; }
}
.nxs-mobile {
  display: none; position: sticky; top: 63px; z-index: 55;
  background: rgba(253, 250, 245, 0.96); backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--line2); padding: 12px 24px;
}
.nxs-mobile.open { display: block; }
.nxs-mobile a { display: block; padding: 11px 4px; font-weight: 600; font-size: 15px; color: var(--ink2); border-bottom: 1px solid var(--line2); }
.nxs-mobile a:last-child { border-bottom: none; }

/* ── hero ── */
.nxs-hero { padding: 70px 0 30px; }
.nxs-hero .hero-in { position: relative; z-index: 1; text-align: center; }
.nxs-hero h1 { font-size: clamp(40px, 6vw, 74px); font-weight: 800; margin: 0 auto 22px; max-width: 900px; }
.nxs-hero h1 .em { font-family: var(--font-fraunces), Georgia, serif; font-style: italic; font-weight: 500; background: linear-gradient(120deg, var(--or), var(--or-deep)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.nxs-hero .lead { margin: 0 auto 30px; font-size: clamp(16px, 2vw, 19px); max-width: 620px; }
.nxs-hero .acts { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 20px; }
.nxs-hero .note { font-size: 13px; color: var(--muted); display: flex; gap: 20px; justify-content: center; flex-wrap: wrap; }
.nxs-hero .note span { display: inline-flex; align-items: center; gap: 6px; }
.nxs-hero .note svg { width: 15px; height: 15px; color: var(--green); }
.nxs .glow-a { width: 620px; height: 620px; background: rgba(249, 115, 22, 0.16); top: -220px; left: 50%; transform: translateX(-50%); }
.nxs .glow-b { width: 380px; height: 380px; background: rgba(124, 92, 240, 0.1); top: 120px; right: -120px; }

/* live ticker */
.nxs-ticker { margin: 34px auto 0; max-width: 560px; overflow: hidden; position: relative; z-index: 1;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); }
.nxs .ticker-track { display: flex; gap: 10px; width: max-content; animation: nxsmarq 26s linear infinite; }
.nxs-ticker:hover .ticker-track { animation-play-state: paused; }
.nxs .tk {
  display: inline-flex; align-items: center; gap: 8px; flex-shrink: 0;
  background: #fff; border: 1px solid var(--line); border-radius: 99px;
  padding: 7px 14px 7px 8px; font-size: 12.5px; font-weight: 600; box-shadow: var(--sh);
}
.nxs .tk .dot { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; }
.nxs .tk .dot svg { width: 13px; height: 13px; }
.nxs .tk b { font-weight: 700; }
@keyframes nxsmarq { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ── product window (hero + tour) ── */
.nxs-stage { margin: 44px auto 0; max-width: 1060px; position: relative; z-index: 1; }
.nxs .win {
  background: var(--card); border: 1px solid var(--line); border-radius: 18px;
  box-shadow: var(--sh-lg); overflow: hidden;
}
.nxs .win-bar { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--line2); background: #fdfbf7; }
.nxs .win-bar i { width: 11px; height: 11px; border-radius: 50%; background: var(--line); display: block; }
.nxs .win-bar i:nth-child(1) { background: #fca5a5; }
.nxs .win-bar i:nth-child(2) { background: #fcd34d; }
.nxs .win-bar i:nth-child(3) { background: #86efac; }
.nxs .win-url { margin-left: 12px; font-size: 11.5px; color: var(--muted); font-weight: 600; background: #fff; border: 1px solid var(--line2); border-radius: 8px; padding: 4px 12px; display: inline-flex; align-items: center; gap: 6px; }
.nxs .win-url svg { width: 12px; height: 12px; color: var(--green); }

/* app frame: sidebar + canvas */
.nxs .app { display: grid; grid-template-columns: 190px 1fr; min-height: 430px; }
.nxs .app-side { border-right: 1px solid var(--line2); background: #fdfbf7; padding: 14px 12px; }
.nxs .app-brand { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 13.5px; padding: 4px 8px 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .app-brand .m { width: 24px; height: 24px; border-radius: 8px; background: linear-gradient(135deg, #fb923c, var(--or-ink)); display: grid; place-items: center; color: #fff; }
.nxs .app-brand .m svg { width: 14px; height: 14px; }
.nxs .nav-i { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; font-size: 12.5px; font-weight: 600; color: var(--ink2); margin-bottom: 2px; }
.nxs .nav-i svg { width: 15px; height: 15px; color: var(--muted); }
.nxs .nav-i.on { background: var(--or-bg); color: var(--or-deep); }
.nxs .nav-i.on svg { color: var(--or-ink); }
.nxs .app-canvas { padding: 18px; overflow: hidden; }
@media (max-width: 720px) { .nxs .app { grid-template-columns: 1fr; } .nxs .app-side { display: none; } }

/* tour tabs */
.nxs-tabs { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin: 32px 0 22px; }
.nxs .tab { border: 1px solid var(--line); background: #fff; border-radius: 99px; padding: 9px 17px; font-size: 13px; font-weight: 700; color: var(--muted); transition: 0.15s; display: inline-flex; align-items: center; gap: 7px; }
.nxs .tab svg { width: 15px; height: 15px; }
.nxs .tab:hover { color: var(--ink); border-color: var(--or-bg2); }
.nxs .tab.on { background: var(--ink); color: #fff; border-color: var(--ink); }

/* generic canvas primitives */
.nxs .c-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.nxs .c-title { font-size: 16px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .c-sub { font-size: 11.5px; color: var(--muted); font-weight: 600; }
.nxs .kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
@media (max-width: 560px) { .nxs .kpis { grid-template-columns: repeat(2, 1fr); } }
.nxs .kpi { border: 1px solid var(--line2); border-radius: 13px; padding: 12px; background: #fdfbf7; }
.nxs .kpi small { font-size: 9.5px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; display: block; margin-bottom: 4px; }
.nxs .kpi b { font-size: 19px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .kpi em { font-style: normal; font-size: 10.5px; font-weight: 700; color: var(--green); margin-left: 5px; }
.nxs .kpi em.dn { color: var(--or-ink); }
.nxs .cols { display: grid; grid-template-columns: 1.35fr 1fr; gap: 12px; }
@media (max-width: 560px) { .nxs .cols { grid-template-columns: 1fr; } }
.nxs .pane { border: 1px solid var(--line2); border-radius: 13px; padding: 13px; background: #fff; }
.nxs .pane h6 { font-size: 10px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); margin: 0 0 10px; }
.nxs .bars { display: flex; align-items: flex-end; gap: 6px; height: 96px; }
.nxs .bars i { flex: 1; border-radius: 5px 5px 3px 3px; background: linear-gradient(180deg, #fdba74, var(--or)); display: block; }
.nxs .bars i.mut { background: #fde4cd; }
.nxs .row { display: flex; align-items: center; gap: 9px; padding: 7px 0; border-bottom: 1px dashed var(--line2); font-size: 12px; }
.nxs .row:last-child { border-bottom: none; }
.nxs .av { width: 22px; height: 22px; border-radius: 50%; color: #fff; display: grid; place-items: center; font-size: 9px; font-weight: 800; flex-shrink: 0; }
.nxs .pill { margin-left: auto; font-size: 9.5px; font-weight: 700; border-radius: 7px; padding: 3px 8px; }
.nxs .pill.g { background: var(--green-bg); color: var(--green); }
.nxs .pill.o { background: var(--or-bg); color: var(--or-deep); }
.nxs .pill.n { background: var(--warm); color: var(--muted); }
.nxs .pill.p { background: #efeafd; color: var(--purple); }
.nxs .bar { height: 8px; border-radius: 5px; background: var(--warm); overflow: hidden; margin: 8px 0; }
.nxs .bar i { display: block; height: 100%; border-radius: 5px; background: linear-gradient(90deg, #fb923c, var(--or)); }
.nxs .money { display: flex; justify-content: space-between; font-size: 12px; padding: 6px 0; border-bottom: 1px dashed var(--line2); }
.nxs .money:last-child { border-bottom: none; font-weight: 800; }
.nxs .cal { display: grid; grid-template-columns: repeat(7, 1fr); gap: 5px; }
.nxs .cal b { font-size: 9px; color: var(--muted); text-align: center; font-weight: 700; padding-bottom: 2px; }
.nxs .cal i { height: 30px; border-radius: 6px; background: #fff; border: 1px solid var(--line2); display: block; }
.nxs .cal i.e { background: var(--or-bg2); border-color: var(--or-bg2); }
.nxs .cal i.e2 { background: var(--or); border-color: var(--or); }
.nxs .ring { width: 66px; height: 66px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; }
.nxs .ring i { width: 46px; height: 46px; border-radius: 50%; background: #fff; display: grid; place-items: center; font-size: 12.5px; font-weight: 800; font-style: normal; }
.nxs .occ { display: flex; align-items: center; gap: 12px; }
.nxs .occ p { font-size: 11px; color: var(--muted); }

/* floating chips */
.nxs .chip {
  position: absolute; display: flex; align-items: center; gap: 9px;
  background: rgba(255, 255, 255, 0.9); backdrop-filter: blur(10px);
  border: 1px solid rgba(236, 230, 221, 0.9); border-radius: 15px; padding: 9px 14px;
  font-size: 12.5px; font-weight: 700; box-shadow: var(--sh); z-index: 3;
}
.nxs .chip small { display: block; font-size: 10px; color: var(--muted); font-weight: 600; }
.nxs .chip .ci { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; flex-shrink: 0; }
.nxs .chip .ci svg { width: 16px; height: 16px; }
.nxs .float { animation: nxsfloat 6s ease-in-out infinite; }
.nxs .float2 { animation: nxsfloat 7s ease-in-out infinite; animation-delay: 1.4s; }
@keyframes nxsfloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
.nxs .chip-tl { top: 34px; left: -30px; }
.nxs .chip-br { bottom: 40px; right: -26px; }
@media (max-width: 1160px) { .nxs .chip-tl { left: 8px; } .nxs .chip-br { right: 8px; } }
@media (max-width: 820px) { .nxs .chip { display: none; } }

/* ── logo marquee ── */
.nxs-logos { padding: 46px 0 20px; text-align: center; }
.nxs-logos p { font-size: 13px; color: var(--muted); font-weight: 600; margin-bottom: 20px; }
.nxs .logo-row { display: flex; gap: 16px 44px; justify-content: center; flex-wrap: wrap; align-items: center; }
.nxs .tlogo { font-family: var(--font-manrope), sans-serif; font-weight: 800; font-size: 16px; color: #b6ac9f; display: flex; align-items: center; gap: 9px; transition: color 0.2s; }
.nxs .tlogo:hover { color: var(--ink2); }
.nxs .tlogo svg { width: 20px; height: 20px; }

/* ── features bento ── */
.nxs-features { padding: 84px 0; }
.nxs .bento { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; margin-top: 46px; }
.nxs .bcard {
  grid-column: span 2; background: var(--card); border: 1px solid var(--line);
  border-radius: var(--r); padding: 26px; box-shadow: 0 1px 2px rgba(25, 21, 18, 0.04);
  transition: transform 0.22s, box-shadow 0.22s, border-color 0.22s; display: flex; flex-direction: column; overflow: hidden;
}
.nxs .bcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); border-color: var(--or-bg2); }
.nxs .bcard.w3 { grid-column: span 3; }
@media (max-width: 940px) { .nxs .bcard, .nxs .bcard.w3 { grid-column: span 3; } }
@media (max-width: 620px) { .nxs .bcard, .nxs .bcard.w3 { grid-column: span 6; } }
.nxs .bic { width: 44px; height: 44px; border-radius: 13px; background: var(--or-bg); color: var(--or-ink); display: grid; place-items: center; margin-bottom: 16px; }
.nxs .bic svg { width: 21px; height: 21px; }
.nxs .bcard h3 { font-size: 18.5px; font-weight: 800; margin-bottom: 7px; }
.nxs .bcard > p { font-size: 14px; color: var(--muted); margin-bottom: 16px; }
.nxs .bmock { margin-top: auto; border: 1px solid var(--line2); border-radius: var(--r-sm); background: #fdfbf7; padding: 12px; }
.nxs .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.nxs .tags span { font-size: 11px; font-weight: 600; color: var(--ink2); background: var(--warm); border: 1px solid var(--line2); border-radius: 99px; padding: 4px 10px; }
.nxs .spark { display: flex; align-items: flex-end; gap: 4px; height: 48px; }
.nxs .spark i { flex: 1; border-radius: 3px; background: #fde4cd; display: block; }
.nxs .spark i.hi { background: var(--or); }

/* ── why strip ── */
.nxs-why { padding: 84px 0; background: linear-gradient(180deg, var(--bg), var(--warm) 40%, var(--bg)); }
.nxs .why-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 44px; }
@media (max-width: 940px) { .nxs .why-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .nxs .why-grid { grid-template-columns: 1fr; } }
.nxs .wcard { border: 1px solid var(--line); border-radius: var(--r); padding: 24px; background: #fff; transition: transform 0.2s, box-shadow 0.2s; }
.nxs .wcard:hover { transform: translateY(-3px); box-shadow: var(--sh); }
.nxs .wcard .bic { margin-bottom: 14px; }
.nxs .wcard h4 { font-size: 15.5px; font-weight: 800; margin-bottom: 6px; }
.nxs .wcard p { font-size: 13px; color: var(--muted); }

/* ── automation (dark) ── */
.nxs-auto { background: radial-gradient(1000px 560px at 72% -5%, #3a2c20, #191512 62%); color: #fff; padding: 92px 0; overflow: hidden; }
.nxs-auto .eyebrow { background: rgba(249, 115, 22, 0.16); border-color: rgba(249, 115, 22, 0.3); color: #fdba74; }
.nxs-auto .h2 { color: #fff; }
.nxs-auto .lead { color: #ccc3b8; }
.nxs .flow { max-width: 470px; margin: 46px auto 0; }
.nxs .fnode { display: flex; align-items: center; gap: 14px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 15px; padding: 13px 17px; backdrop-filter: blur(6px); }
.nxs .fnode .ci { width: 38px; height: 38px; border-radius: 11px; background: rgba(249, 115, 22, 0.16); color: #fb923c; display: grid; place-items: center; flex-shrink: 0; }
.nxs .fnode .ci svg { width: 18px; height: 18px; }
.nxs .fnode b { font-size: 14.5px; display: block; }
.nxs .fnode small { font-size: 11.5px; color: #a8a097; }
.nxs .fnode .ac { margin-left: auto; font-size: 9px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #fb923c; background: rgba(249, 115, 22, 0.12); border-radius: 6px; padding: 3px 8px; }
.nxs .fline { width: 2px; height: 26px; margin: 0 auto; background: linear-gradient(180deg, rgba(249, 115, 22, 0.7), rgba(249, 115, 22, 0.12)); position: relative; overflow: hidden; }
.nxs .fline::after { content: ""; position: absolute; left: -2px; width: 6px; height: 6px; border-radius: 50%; background: #fb923c; animation: nxsdrip 1.9s linear infinite; }
@keyframes nxsdrip { from { top: -6px; opacity: 1; } to { top: 26px; opacity: 0.2; } }

/* ── mobile experience ── */
.nxs-mob { padding: 92px 0; }
.nxs .mob-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center; }
@media (max-width: 900px) { .nxs .mob-grid { grid-template-columns: 1fr; } }
.nxs .mob-list { display: flex; flex-direction: column; gap: 16px; margin-top: 28px; }
.nxs .mli { display: flex; gap: 13px; align-items: flex-start; }
.nxs .mli .bic { width: 38px; height: 38px; border-radius: 11px; margin: 0; flex-shrink: 0; }
.nxs .mli .bic svg { width: 18px; height: 18px; }
.nxs .mli b { font-size: 15px; display: block; }
.nxs .mli p { font-size: 13px; color: var(--muted); }
.nxs .phones { display: flex; justify-content: center; gap: 20px; }
.nxs .phone { width: 236px; background: #191512; border-radius: 36px; padding: 9px; box-shadow: var(--sh-lg); }
.nxs .phone .ph-in { background: #fdfbf7; border-radius: 28px; overflow: hidden; }
.nxs .phone.p2 { transform: translateY(30px) rotate(2.6deg); }
.nxs .phone.p1 { transform: rotate(-2.4deg); }
@media (max-width: 460px) { .nxs .phone.p2 { display: none; } }
.nxs .ph-head { background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff; padding: 18px 15px 15px; }
.nxs .ph-head b { font-size: 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .ph-head p { font-size: 10px; opacity: 0.9; }
.nxs .ph-body { padding: 13px; }
.nxs .ph-card { border: 1px solid var(--line2); border-radius: 12px; padding: 10px 12px; margin-bottom: 9px; background: #fff; }
.nxs .ph-card b { font-size: 11px; display: block; }
.nxs .ph-card small { font-size: 9.5px; color: var(--muted); }
.nxs .ph-btn { background: var(--or); color: #fff; border-radius: 10px; text-align: center; font-weight: 800; font-size: 11px; padding: 9px; margin-top: 4px; }

/* ── testimonials ── */
.nxs-testi { padding: 84px 0; background: var(--warm); }
.nxs .tgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 44px; }
@media (max-width: 900px) { .nxs .tgrid { grid-template-columns: 1fr; } }
.nxs .tcard { background: #fff; border: 1px solid var(--line); border-radius: var(--r); padding: 28px; display: flex; flex-direction: column; gap: 18px; transition: transform 0.2s, box-shadow 0.2s; }
.nxs .tcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); }
.nxs .tstat { font-family: var(--font-manrope), sans-serif; font-size: 32px; font-weight: 800; color: var(--or-ink); line-height: 1; }
.nxs .tstat small { display: block; font-size: 12.5px; color: var(--muted); font-weight: 600; font-family: var(--font-inter), sans-serif; margin-top: 6px; }
.nxs .tcard > p { font-size: 14.5px; color: var(--ink2); line-height: 1.65; }
.nxs .twho { display: flex; align-items: center; gap: 12px; margin-top: auto; }
.nxs .tava { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; color: #fff; font-weight: 800; font-size: 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .twho b { font-size: 13.5px; display: block; }
.nxs .twho small { font-size: 12px; color: var(--muted); }
.nxs .stars { display: flex; gap: 2px; color: var(--or); }
.nxs .stars svg { width: 15px; height: 15px; fill: currentColor; }

/* ── pricing ── */
.nxs-pricing { padding: 90px 0; }
.nxs .toggle { display: inline-flex; align-items: center; gap: 4px; background: var(--warm); border: 1px solid var(--line); border-radius: 99px; padding: 4px; margin: 22px auto 0; }
.nxs .toggle button { border: none; background: transparent; border-radius: 99px; padding: 9px 18px; font-size: 13.5px; font-weight: 700; color: var(--muted); transition: 0.16s; }
.nxs .toggle button.on { background: #fff; color: var(--ink); box-shadow: var(--sh); }
.nxs .toggle .save { font-size: 10px; color: var(--green); font-weight: 800; margin-left: 5px; }
.nxs .pgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 40px; align-items: stretch; }
@media (max-width: 900px) { .nxs .pgrid { grid-template-columns: 1fr; max-width: 420px; margin-left: auto; margin-right: auto; } }
.nxs .pcard { background: #fff; border: 1px solid var(--line); border-radius: 22px; padding: 30px; display: flex; flex-direction: column; transition: transform 0.2s, box-shadow 0.2s; position: relative; }
.nxs .pcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); }
.nxs .pcard.hi { border-color: var(--or-bg2); box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.11), var(--sh-lg); }
.nxs .pop { position: absolute; top: -13px; left: 50%; transform: translateX(-50%); background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff; font-size: 11px; font-weight: 800; letter-spacing: 0.04em; border-radius: 99px; padding: 5px 15px; box-shadow: 0 6px 14px rgba(249, 115, 22, 0.4); white-space: nowrap; }
.nxs .pname { font-size: 15px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .pfor { font-size: 12.5px; color: var(--muted); margin: 4px 0 18px; min-height: 34px; }
.nxs .pprice { font-family: var(--font-manrope), sans-serif; font-size: 46px; font-weight: 800; line-height: 1; }
.nxs .pprice small { font-size: 14px; color: var(--muted); font-weight: 600; font-family: var(--font-inter), sans-serif; }
.nxs .pnote { font-size: 11.5px; color: var(--muted); margin-top: 6px; min-height: 16px; }
.nxs .pfeats { margin: 22px 0 26px; display: flex; flex-direction: column; gap: 11px; }
.nxs .pfeats span { display: flex; gap: 9px; align-items: flex-start; font-size: 13.5px; color: var(--ink2); }
.nxs .pfeats svg { width: 17px; height: 17px; color: var(--or-ink); flex-shrink: 0; margin-top: 1px; }
.nxs .pcard .btn { margin-top: auto; width: 100%; }
.nxs .price-foot { text-align: center; margin-top: 26px; font-size: 13px; color: var(--muted); }

/* ── faq ── */
.nxs-faq { padding: 84px 0; background: var(--warm); }
.nxs .faq-list { max-width: 740px; margin: 40px auto 0; }
.nxs .qa { background: #fff; border: 1px solid var(--line); border-radius: 16px; margin-bottom: 11px; overflow: hidden; transition: box-shadow 0.2s; }
.nxs .qa[open] { box-shadow: var(--sh); }
.nxs .qa summary { padding: 19px 22px; font-weight: 700; font-size: 15px; cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 14px; }
.nxs .qa summary::-webkit-details-marker { display: none; }
.nxs .qa summary::after { content: "+"; font-size: 24px; color: var(--or-ink); font-weight: 300; transition: transform 0.2s; flex-shrink: 0; line-height: 1; }
.nxs .qa[open] summary::after { transform: rotate(45deg); }
.nxs .qa p { padding: 0 22px 19px; color: var(--muted); font-size: 14px; }

/* ── final cta ── */
.nxs-final { padding: 92px 0; }
.nxs .cta-box { background: linear-gradient(135deg, #2b2019, #191512 55%, #3a281b); border-radius: 30px; padding: 76px 40px; text-align: center; color: #fff; position: relative; overflow: hidden; }
.nxs .cta-box::before { content: ""; position: absolute; width: 520px; height: 520px; border-radius: 50%; background: rgba(249, 115, 22, 0.24); filter: blur(120px); top: -220px; right: -120px; }
.nxs .cta-box h2 { font-size: clamp(30px, 4.6vw, 48px); font-weight: 800; margin-bottom: 14px; position: relative; }
.nxs .cta-box h2 em { font-family: var(--font-fraunces), serif; font-style: italic; font-weight: 500; color: #fdba74; }
.nxs .cta-box p { color: #ccc3b8; font-size: 17px; margin-bottom: 32px; position: relative; }
.nxs .cta-box .acts { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; position: relative; }
.nxs .cta-box .btn-ghost { background: transparent; border-color: rgba(255, 255, 255, 0.25); color: #fff; }
.nxs .cta-box .btn-ghost:hover { background: rgba(255, 255, 255, 0.08); }
.nxs .cta-box .note { justify-content: center; margin-top: 20px; color: #a8a097; }
.nxs .cta-box .note svg { color: #fdba74; }

/* ── footer ── */
.nxs-foot { border-top: 1px solid var(--line2); padding: 56px 0 34px; font-size: 13.5px; color: var(--muted); }
.nxs .fgrid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 36px; margin-bottom: 38px; }
@media (max-width: 760px) { .nxs .fgrid { grid-template-columns: 1fr 1fr; } }
.nxs .fcol h5 { font-size: 12px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink2); margin-bottom: 14px; }
.nxs .fcol a { display: block; margin-bottom: 9px; transition: color 0.14s; }
.nxs .fcol a:hover { color: var(--or-ink); }
.nxs .fcol > p { max-width: 260px; }
.nxs .fbot { display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; border-top: 1px solid var(--line2); padding-top: 26px; }
.nxs .socials { display: flex; gap: 10px; }
.nxs .socials a { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid var(--line); border-radius: 10px; transition: 0.15s; }
.nxs .socials a:hover { background: var(--warm); color: var(--ink); }
.nxs .socials svg { width: 16px; height: 16px; }

toolUseResult.content:
/* Studio Nexis — marketing landing (apex host). Bespoke, self-contained
   design system scoped under .nxs so it never leaks into the app. Warm
   ivory + orange, Fraunces serif display accents, CSS-drawn product mocks. */

.nxs {
  --or: #f97316;
  --or-ink: #ea580c;
  --or-deep: #c2410c;
  --or-bg: #fff4ea;
  --or-bg2: #ffe9d6;
  --ink: #191512;
  --ink2: #4b443d;
  --muted: #857b70;
  --line: #ece6dd;
  --line2: #f3eee6;
  --bg: #fdfaf5;
  --warm: #f7f1e8;
  --card: #ffffff;
  --green: #17935a;
  --green-bg: #e6f6ec;
  --purple: #7c5cf0;
  --blue: #2f7ef0;
  --r: 22px;
  --r-sm: 14px;
  --sh: 0 1px 2px rgba(25, 21, 18, 0.05), 0 10px 30px rgba(25, 21, 18, 0.07);
  --sh-lg: 0 2px 8px rgba(25, 21, 18, 0.06), 0 30px 70px rgba(25, 21, 18, 0.15);
  --maxw: 1180px;

  font-family: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
.nxs *,
.nxs *::before,
.nxs *::after { box-sizing: border-box; }
.nxs h1, .nxs h2, .nxs h3, .nxs h4, .nxs .disp {
  font-family: var(--font-manrope), var(--font-inter), sans-serif;
  letter-spacing: -0.025em;
  line-height: 1.1;
}
.nxs .serif {
  font-family: var(--font-fraunces), Georgia, serif;
  letter-spacing: -0.01em;
}
.nxs a { color: inherit; text-decoration: none; }
.nxs button { font-family: inherit; cursor: pointer; }
.nxs .wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 24px; }
.nxs section { position: relative; }

/* dotted background texture + warm glow */
.nxs .bg-grid {
  position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background-image: radial-gradient(rgba(25, 21, 18, 0.045) 1px, transparent 1px);
  background-size: 26px 26px;
  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent 78%);
  mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent 78%);
}
.nxs .glow {
  position: absolute; border-radius: 50%; filter: blur(100px);
  pointer-events: none; z-index: 0;
}

/* ── buttons ── */
.nxs .btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 700; font-size: 15px; padding: 13px 24px; border-radius: 13px;
  border: 1px solid transparent; transition: transform 0.16s, box-shadow 0.16s, background 0.16s;
  white-space: nowrap;
}
.nxs .btn svg { width: 18px; height: 18px; }
.nxs .btn-primary {
  background: linear-gradient(135deg, #fb923c, var(--or-ink));
  color: #fff;
  box-shadow: 0 8px 22px rgba(249, 115, 22, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
.nxs .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 14px 32px rgba(249, 115, 22, 0.44), inset 0 1px 0 rgba(255, 255, 255, 0.28); }
.nxs .btn-ghost { border-color: var(--line); color: var(--ink); background: #fff; }
.nxs .btn-ghost:hover { background: var(--warm); transform: translateY(-2px); }
.nxs .btn-lg { font-size: 16px; padding: 16px 30px; border-radius: 15px; }

/* ── shared bits ── */
.nxs .eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 700; letter-spacing: 0.11em; text-transform: uppercase;
  color: var(--or-deep); background: var(--or-bg); border: 1px solid var(--or-bg2);
  border-radius: 99px; padding: 7px 14px; margin-bottom: 20px;
}
.nxs .eyebrow svg { width: 14px; height: 14px; }
.nxs .h2 { font-size: clamp(30px, 4.4vw, 46px); font-weight: 800; margin-bottom: 16px; }
.nxs .h2 em { font-style: italic; font-weight: 500; color: var(--or-ink); }
.nxs .lead { font-size: 17.5px; color: var(--muted); max-width: 640px; }
.nxs .center { text-align: center; }
.nxs .center .lead { margin-left: auto; margin-right: auto; }

/* reveal on scroll */
.nxs .rv { opacity: 0; transform: translateY(26px); transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1), transform 0.7s cubic-bezier(0.22, 1, 0.36, 1); }
.nxs .rv.in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .nxs .rv { opacity: 1; transform: none; transition: none; }
  .nxs .float, .nxs .float2, .nxs .ticker-track { animation: none !important; }
}

/* ── nav ── */
.nxs-nav {
  position: sticky; top: 0; z-index: 60;
  background: rgba(253, 250, 245, 0.8); backdrop-filter: blur(16px) saturate(1.4);
  border-bottom: 1px solid var(--line2);
}
.nxs-nav .nav-in { max-width: var(--maxw); margin: 0 auto; padding: 14px 24px; display: flex; align-items: center; gap: 32px; }
.nxs .logo { display: flex; align-items: center; gap: 11px; font-family: var(--font-manrope), sans-serif; font-weight: 800; font-size: 19px; }
.nxs .logo-mark {
  width: 34px; height: 34px; border-radius: 11px;
  background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff;
  display: grid; place-items: center; box-shadow: 0 5px 14px rgba(249, 115, 22, 0.4);
}
.nxs .logo-mark svg { width: 19px; height: 19px; }
.nxs .nav-links { display: flex; gap: 28px; font-size: 14.5px; font-weight: 600; color: var(--ink2); }
.nxs .nav-links a { transition: color 0.15s; }
.nxs .nav-links a:hover { color: var(--or-ink); }
.nxs .nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.nxs .nav-login { font-size: 14.5px; font-weight: 600; color: var(--ink2); padding: 10px 14px; }
.nxs .nav-login:hover { color: var(--ink); }
.nxs .nav-right .btn { padding: 10px 18px; font-size: 14px; }
.nxs .burger { display: none; width: 42px; height: 42px; border-radius: 11px; border: 1px solid var(--line); background: #fff; align-items: center; justify-content: center; }
.nxs .burger svg { width: 20px; height: 20px; }
@media (max-width: 900px) {
  .nxs .nav-links { display: none; }
  .nxs .nav-login { display: none; }
  .nxs .burger { display: inline-flex; }
}
.nxs-mobile {
  display: none; position: sticky; top: 63px; z-index: 55;
  background: rgba(253, 250, 245, 0.96); backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--line2); padding: 12px 24px;
}
.nxs-mobile.open { display: block; }
.nxs-mobile a { display: block; padding: 11px 4px; font-weight: 600; font-size: 15px; color: var(--ink2); border-bottom: 1px solid var(--line2); }
.nxs-mobile a:last-child { border-bottom: none; }

/* ── hero ── */
.nxs-hero { padding: 70px 0 30px; }
.nxs-hero .hero-in { position: relative; z-index: 1; text-align: center; }
.nxs-hero h1 { font-size: clamp(40px, 6vw, 74px); font-weight: 800; margin: 0 auto 22px; max-width: 900px; }
.nxs-hero h1 .em { font-family: var(--font-fraunces), Georgia, serif; font-style: italic; font-weight: 500; background: linear-gradient(120deg, var(--or), var(--or-deep)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.nxs-hero .lead { margin: 0 auto 30px; font-size: clamp(16px, 2vw, 19px); max-width: 620px; }
.nxs-hero .acts { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 20px; }
.nxs-hero .note { font-size: 13px; color: var(--muted); display: flex; gap: 20px; justify-content: center; flex-wrap: wrap; }
.nxs-hero .note span { display: inline-flex; align-items: center; gap: 6px; }
.nxs-hero .note svg { width: 15px; height: 15px; color: var(--green); }
.nxs .glow-a { width: 620px; height: 620px; background: rgba(249, 115, 22, 0.16); top: -220px; left: 50%; transform: translateX(-50%); }
.nxs .glow-b { width: 380px; height: 380px; background: rgba(124, 92, 240, 0.1); top: 120px; right: -120px; }

/* live ticker */
.nxs-ticker { margin: 34px auto 0; max-width: 560px; overflow: hidden; position: relative; z-index: 1;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); }
.nxs .ticker-track { display: flex; gap: 10px; width: max-content; animation: nxsmarq 26s linear infinite; }
.nxs-ticker:hover .ticker-track { animation-play-state: paused; }
.nxs .tk {
  display: inline-flex; align-items: center; gap: 8px; flex-shrink: 0;
  background: #fff; border: 1px solid var(--line); border-radius: 99px;
  padding: 7px 14px 7px 8px; font-size: 12.5px; font-weight: 600; box-shadow: var(--sh);
}
.nxs .tk .dot { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; }
.nxs .tk .dot svg { width: 13px; height: 13px; }
.nxs .tk b { font-weight: 700; }
@keyframes nxsmarq { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ── product window (hero + tour) ── */
.nxs-stage { margin: 44px auto 0; max-width: 1060px; position: relative; z-index: 1; }
.nxs .win {
  background: var(--card); border: 1px solid var(--line); border-radius: 18px;
  box-shadow: var(--sh-lg); overflow: hidden;
}
.nxs .win-bar { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--line2); background: #fdfbf7; }
.nxs .win-bar i { width: 11px; height: 11px; border-radius: 50%; background: var(--line); display: block; }
.nxs .win-bar i:nth-child(1) { background: #fca5a5; }
.nxs .win-bar i:nth-child(2) { background: #fcd34d; }
.nxs .win-bar i:nth-child(3) { background: #86efac; }
.nxs .win-url { margin-left: 12px; font-size: 11.5px; color: var(--muted); font-weight: 600; background: #fff; border: 1px solid var(--line2); border-radius: 8px; padding: 4px 12px; display: inline-flex; align-items: center; gap: 6px; }
.nxs .win-url svg { width: 12px; height: 12px; color: var(--green); }

/* app frame: sidebar + canvas */
.nxs .app { display: grid; grid-template-columns: 190px 1fr; min-height: 430px; }
.nxs .app-side { border-right: 1px solid var(--line2); background: #fdfbf7; padding: 14px 12px; }
.nxs .app-brand { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 13.5px; padding: 4px 8px 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .app-brand .m { width: 24px; height: 24px; border-radius: 8px; background: linear-gradient(135deg, #fb923c, var(--or-ink)); display: grid; place-items: center; color: #fff; }
.nxs .app-brand .m svg { width: 14px; height: 14px; }
.nxs .nav-i { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; font-size: 12.5px; font-weight: 600; color: var(--ink2); margin-bottom: 2px; }
.nxs .nav-i svg { width: 15px; height: 15px; color: var(--muted); }
.nxs .nav-i.on { background: var(--or-bg); color: var(--or-deep); }
.nxs .nav-i.on svg { color: var(--or-ink); }
.nxs .app-canvas { padding: 18px; overflow: hidden; }
@media (max-width: 720px) { .nxs .app { grid-template-columns: 1fr; } .nxs .app-side { display: none; } }

/* tour tabs */
.nxs-tabs { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin: 32px 0 22px; }
.nxs .tab { border: 1px solid var(--line); background: #fff; border-radius: 99px; padding: 9px 17px; font-size: 13px; font-weight: 700; color: var(--muted); transition: 0.15s; display: inline-flex; align-items: center; gap: 7px; }
.nxs .tab svg { width: 15px; height: 15px; }
.nxs .tab:hover { color: var(--ink); border-color: var(--or-bg2); }
.nxs .tab.on { background: var(--ink); color: #fff; border-color: var(--ink); }

/* generic canvas primitives */
.nxs .c-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.nxs .c-title { font-size: 16px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .c-sub { font-size: 11.5px; color: var(--muted); font-weight: 600; }
.nxs .kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
@media (max-width: 560px) { .nxs .kpis { grid-template-columns: repeat(2, 1fr); } }
.nxs .kpi { border: 1px solid var(--line2); border-radius: 13px; padding: 12px; background: #fdfbf7; }
.nxs .kpi small { font-size: 9.5px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; display: block; margin-bottom: 4px; }
.nxs .kpi b { font-size: 19px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .kpi em { font-style: normal; font-size: 10.5px; font-weight: 700; color: var(--green); margin-left: 5px; }
.nxs .kpi em.dn { color: var(--or-ink); }
.nxs .cols { display: grid; grid-template-columns: 1.35fr 1fr; gap: 12px; }
@media (max-width: 560px) { .nxs .cols { grid-template-columns: 1fr; } }
.nxs .pane { border: 1px solid var(--line2); border-radius: 13px; padding: 13px; background: #fff; }
.nxs .pane h6 { font-size: 10px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); margin: 0 0 10px; }
.nxs .bars { display: flex; align-items: flex-end; gap: 6px; height: 96px; }
.nxs .bars i { flex: 1; border-radius: 5px 5px 3px 3px; background: linear-gradient(180deg, #fdba74, var(--or)); display: block; }
.nxs .bars i.mut { background: #fde4cd; }
.nxs .row { display: flex; align-items: center; gap: 9px; padding: 7px 0; border-bottom: 1px dashed var(--line2); font-size: 12px; }
.nxs .row:last-child { border-bottom: none; }
.nxs .av { width: 22px; height: 22px; border-radius: 50%; color: #fff; display: grid; place-items: center; font-size: 9px; font-weight: 800; flex-shrink: 0; }
.nxs .pill { margin-left: auto; font-size: 9.5px; font-weight: 700; border-radius: 7px; padding: 3px 8px; }
.nxs .pill.g { background: var(--green-bg); color: var(--green); }
.nxs .pill.o { background: var(--or-bg); color: var(--or-deep); }
.nxs .pill.n { background: var(--warm); color: var(--muted); }
.nxs .pill.p { background: #efeafd; color: var(--purple); }
.nxs .bar { height: 8px; border-radius: 5px; background: var(--warm); overflow: hidden; margin: 8px 0; }
.nxs .bar i { display: block; height: 100%; border-radius: 5px; background: linear-gradient(90deg, #fb923c, var(--or)); }
.nxs .money { display: flex; justify-content: space-between; font-size: 12px; padding: 6px 0; border-bottom: 1px dashed var(--line2); }
.nxs .money:last-child { border-bottom: none; font-weight: 800; }
.nxs .cal { display: grid; grid-template-columns: repeat(7, 1fr); gap: 5px; }
.nxs .cal b { font-size: 9px; color: var(--muted); text-align: center; font-weight: 700; padding-bottom: 2px; }
.nxs .cal i { height: 30px; border-radius: 6px; background: #fff; border: 1px solid var(--line2); display: block; }
.nxs .cal i.e { background: var(--or-bg2); border-color: var(--or-bg2); }
.nxs .cal i.e2 { background: var(--or); border-color: var(--or); }
.nxs .ring { width: 66px; height: 66px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; }
.nxs .ring i { width: 46px; height: 46px; border-radius: 50%; background: #fff; display: grid; place-items: center; font-size: 12.5px; font-weight: 800; font-style: normal; }
.nxs .occ { display: flex; align-items: center; gap: 12px; }
.nxs .occ p { font-size: 11px; color: var(--muted); }

/* floating chips */
.nxs .chip {
  position: absolute; display: flex; align-items: center; gap: 9px;
  background: rgba(255, 255, 255, 0.9); backdrop-filter: blur(10px);
  border: 1px solid rgba(236, 230, 221, 0.9); border-radius: 15px; padding: 9px 14px;
  font-size: 12.5px; font-weight: 700; box-shadow: var(--sh); z-index: 3;
}
.nxs .chip small { display: block; font-size: 10px; color: var(--muted); font-weight: 600; }
.nxs .chip .ci { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; flex-shrink: 0; }
.nxs .chip .ci svg { width: 16px; height: 16px; }
.nxs .float { animation: nxsfloat 6s ease-in-out infinite; }
.nxs .float2 { animation: nxsfloat 7s ease-in-out infinite; animation-delay: 1.4s; }
@keyframes nxsfloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
.nxs .chip-tl { top: 34px; left: -30px; }
.nxs .chip-br { bottom: 40px; right: -26px; }
@media (max-width: 1160px) { .nxs .chip-tl { left: 8px; } .nxs .chip-br { right: 8px; } }
@media (max-width: 820px) { .nxs .chip { display: none; } }

/* ── logo marquee ── */
.nxs-logos { padding: 46px 0 20px; text-align: center; }
.nxs-logos p { font-size: 13px; color: var(--muted); font-weight: 600; margin-bottom: 20px; }
.nxs .logo-row { display: flex; gap: 16px 44px; justify-content: center; flex-wrap: wrap; align-items: center; }
.nxs .tlogo { font-family: var(--font-manrope), sans-serif; font-weight: 800; font-size: 16px; color: #b6ac9f; display: flex; align-items: center; gap: 9px; transition: color 0.2s; }
.nxs .tlogo:hover { color: var(--ink2); }
.nxs .tlogo svg { width: 20px; height: 20px; }

/* ── features bento ── */
.nxs-features { padding: 84px 0; }
.nxs .bento { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; margin-top: 46px; }
.nxs .bcard {
  grid-column: span 2; background: var(--card); border: 1px solid var(--line);
  border-radius: var(--r); padding: 26px; box-shadow: 0 1px 2px rgba(25, 21, 18, 0.04);
  transition: transform 0.22s, box-shadow 0.22s, border-color 0.22s; display: flex; flex-direction: column; overflow: hidden;
}
.nxs .bcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); border-color: var(--or-bg2); }
.nxs .bcard.w3 { grid-column: span 3; }
@media (max-width: 940px) { .nxs .bcard, .nxs .bcard.w3 { grid-column: span 3; } }
@media (max-width: 620px) { .nxs .bcard, .nxs .bcard.w3 { grid-column: span 6; } }
.nxs .bic { width: 44px; height: 44px; border-radius: 13px; background: var(--or-bg); color: var(--or-ink); display: grid; place-items: center; margin-bottom: 16px; }
.nxs .bic svg { width: 21px; height: 21px; }
.nxs .bcard h3 { font-size: 18.5px; font-weight: 800; margin-bottom: 7px; }
.nxs .bcard > p { font-size: 14px; color: var(--muted); margin-bottom: 16px; }
.nxs .bmock { margin-top: auto; border: 1px solid var(--line2); border-radius: var(--r-sm); background: #fdfbf7; padding: 12px; }
.nxs .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.nxs .tags span { font-size: 11px; font-weight: 600; color: var(--ink2); background: var(--warm); border: 1px solid var(--line2); border-radius: 99px; padding: 4px 10px; }
.nxs .spark { display: flex; align-items: flex-end; gap: 4px; height: 48px; }
.nxs .spark i { flex: 1; border-radius: 3px; background: #fde4cd; display: block; }
.nxs .spark i.hi { background: var(--or); }

/* ── why strip ── */
.nxs-why { padding: 84px 0; background: linear-gradient(180deg, var(--bg), var(--warm) 40%, var(--bg)); }
.nxs .why-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 44px; }
@media (max-width: 940px) { .nxs .why-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .nxs .why-grid { grid-template-columns: 1fr; } }
.nxs .wcard { border: 1px solid var(--line); border-radius: var(--r); padding: 24px; background: #fff; transition: transform 0.2s, box-shadow 0.2s; }
.nxs .wcard:hover { transform: translateY(-3px); box-shadow: var(--sh); }
.nxs .wcard .bic { margin-bottom: 14px; }
.nxs .wcard h4 { font-size: 15.5px; font-weight: 800; margin-bottom: 6px; }
.nxs .wcard p { font-size: 13px; color: var(--muted); }

/* ── automation (dark) ── */
.nxs-auto { background: radial-gradient(1000px 560px at 72% -5%, #3a2c20, #191512 62%); color: #fff; padding: 92px 0; overflow: hidden; }
.nxs-auto .eyebrow { background: rgba(249, 115, 22, 0.16); border-color: rgba(249, 115, 22, 0.3); color: #fdba74; }
.nxs-auto .h2 { color: #fff; }
.nxs-auto .lead { color: #ccc3b8; }
.nxs .flow { max-width: 470px; margin: 46px auto 0; }
.nxs .fnode { display: flex; align-items: center; gap: 14px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 15px; padding: 13px 17px; backdrop-filter: blur(6px); }
.nxs .fnode .ci { width: 38px; height: 38px; border-radius: 11px; background: rgba(249, 115, 22, 0.16); color: #fb923c; display: grid; place-items: center; flex-shrink: 0; }
.nxs .fnode .ci svg { width: 18px; height: 18px; }
.nxs .fnode b { font-size: 14.5px; display: block; }
.nxs .fnode small { font-size: 11.5px; color: #a8a097; }
.nxs .fnode .ac { margin-left: auto; font-size: 9px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #fb923c; background: rgba(249, 115, 22, 0.12); border-radius: 6px; padding: 3px 8px; }
.nxs .fline { width: 2px; height: 26px; margin: 0 auto; background: linear-gradient(180deg, rgba(249, 115, 22, 0.7), rgba(249, 115, 22, 0.12)); position: relative; overflow: hidden; }
.nxs .fline::after { content: ""; position: absolute; left: -2px; width: 6px; height: 6px; border-radius: 50%; background: #fb923c; animation: nxsdrip 1.9s linear infinite; }
@keyframes nxsdrip { from { top: -6px; opacity: 1; } to { top: 26px; opacity: 0.2; } }

/* ── mobile experience ── */
.nxs-mob { padding: 92px 0; }
.nxs .mob-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center; }
@media (max-width: 900px) { .nxs .mob-grid { grid-template-columns: 1fr; } }
.nxs .mob-list { display: flex; flex-direction: column; gap: 16px; margin-top: 28px; }
.nxs .mli { display: flex; gap: 13px; align-items: flex-start; }
.nxs .mli .bic { width: 38px; height: 38px; border-radius: 11px; margin: 0; flex-shrink: 0; }
.nxs .mli .bic svg { width: 18px; height: 18px; }
.nxs .mli b { font-size: 15px; display: block; }
.nxs .mli p { font-size: 13px; color: var(--muted); }
.nxs .phones { display: flex; justify-content: center; gap: 20px; }
.nxs .phone { width: 236px; background: #191512; border-radius: 36px; padding: 9px; box-shadow: var(--sh-lg); }
.nxs .phone .ph-in { background: #fdfbf7; border-radius: 28px; overflow: hidden; }
.nxs .phone.p2 { transform: translateY(30px) rotate(2.6deg); }
.nxs .phone.p1 { transform: rotate(-2.4deg); }
@media (max-width: 460px) { .nxs .phone.p2 { display: none; } }
.nxs .ph-head { background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff; padding: 18px 15px 15px; }
.nxs .ph-head b { font-size: 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .ph-head p { font-size: 10px; opacity: 0.9; }
.nxs .ph-body { padding: 13px; }
.nxs .ph-card { border: 1px solid var(--line2); border-radius: 12px; padding: 10px 12px; margin-bottom: 9px; background: #fff; }
.nxs .ph-card b { font-size: 11px; display: block; }
.nxs .ph-card small { font-size: 9.5px; color: var(--muted); }
.nxs .ph-btn { background: var(--or); color: #fff; border-radius: 10px; text-align: center; font-weight: 800; font-size: 11px; padding: 9px; margin-top: 4px; }

/* ── testimonials ── */
.nxs-testi { padding: 84px 0; background: var(--warm); }
.nxs .tgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 44px; }
@media (max-width: 900px) { .nxs .tgrid { grid-template-columns: 1fr; } }
.nxs .tcard { background: #fff; border: 1px solid var(--line); border-radius: var(--r); padding: 28px; display: flex; flex-direction: column; gap: 18px; transition: transform 0.2s, box-shadow 0.2s; }
.nxs .tcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); }
.nxs .tstat { font-family: var(--font-manrope), sans-serif; font-size: 32px; font-weight: 800; color: var(--or-ink); line-height: 1; }
.nxs .tstat small { display: block; font-size: 12.5px; color: var(--muted); font-weight: 600; font-family: var(--font-inter), sans-serif; margin-top: 6px; }
.nxs .tcard > p { font-size: 14.5px; color: var(--ink2); line-height: 1.65; }
.nxs .twho { display: flex; align-items: center; gap: 12px; margin-top: auto; }
.nxs .tava { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; color: #fff; font-weight: 800; font-size: 14px; font-family: var(--font-manrope), sans-serif; }
.nxs .twho b { font-size: 13.5px; display: block; }
.nxs .twho small { font-size: 12px; color: var(--muted); }
.nxs .stars { display: flex; gap: 2px; color: var(--or); }
.nxs .stars svg { width: 15px; height: 15px; fill: currentColor; }

/* ── pricing ── */
.nxs-pricing { padding: 90px 0; }
.nxs .toggle { display: inline-flex; align-items: center; gap: 4px; background: var(--warm); border: 1px solid var(--line); border-radius: 99px; padding: 4px; margin: 22px auto 0; }
.nxs .toggle button { border: none; background: transparent; border-radius: 99px; padding: 9px 18px; font-size: 13.5px; font-weight: 700; color: var(--muted); transition: 0.16s; }
.nxs .toggle button.on { background: #fff; color: var(--ink); box-shadow: var(--sh); }
.nxs .toggle .save { font-size: 10px; color: var(--green); font-weight: 800; margin-left: 5px; }
.nxs .pgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 40px; align-items: stretch; }
@media (max-width: 900px) { .nxs .pgrid { grid-template-columns: 1fr; max-width: 420px; margin-left: auto; margin-right: auto; } }
.nxs .pcard { background: #fff; border: 1px solid var(--line); border-radius: 22px; padding: 30px; display: flex; flex-direction: column; transition: transform 0.2s, box-shadow 0.2s; position: relative; }
.nxs .pcard:hover { transform: translateY(-4px); box-shadow: var(--sh-lg); }
.nxs .pcard.hi { border-color: var(--or-bg2); box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.11), var(--sh-lg); }
.nxs .pop { position: absolute; top: -13px; left: 50%; transform: translateX(-50%); background: linear-gradient(135deg, #fb923c, var(--or-ink)); color: #fff; font-size: 11px; font-weight: 800; letter-spacing: 0.04em; border-radius: 99px; padding: 5px 15px; box-shadow: 0 6px 14px rgba(249, 115, 22, 0.4); white-space: nowrap; }
.nxs .pname { font-size: 15px; font-weight: 800; font-family: var(--font-manrope), sans-serif; }
.nxs .pfor { font-size: 12.5px; color: var(--muted); margin: 4px 0 18px; min-height: 34px; }
.nxs .pprice { font-family: var(--font-manrope), sans-serif; font-size: 46px; font-weight: 800; line-height: 1; }
.nxs .pprice small { font-size: 14px; color: var(--muted); font-weight: 600; font-family: var(--font-inter), sans-serif; }
.nxs .pnote { font-size: 11.5px; color: var(--muted); margin-top: 6px; min-height: 16px; }
.nxs .pfeats { margin: 22px 0 26px; display: flex; flex-direction: column; gap: 11px; }
.nxs .pfeats span { display: flex; gap: 9px; align-items: flex-start; font-size: 13.5px; color: var(--ink2); }
.nxs .pfeats svg { width: 17px; height: 17px; color: var(--or-ink); flex-shrink: 0; margin-top: 1px; }
.nxs .pcard .btn { margin-top: auto; width: 100%; }
.nxs .price-foot { text-align: center; margin-top: 26px; font-size: 13px; color: var(--muted); }

/* ── faq ── */
.nxs-faq { padding: 84px 0; background: var(--warm); }
.nxs .faq-list { max-width: 740px; margin: 40px auto 0; }
.nxs .qa { background: #fff; border: 1px solid var(--line); border-radius: 16px; margin-bottom: 11px; overflow: hidden; transition: box-shadow 0.2s; }
.nxs .qa[open] { box-shadow: var(--sh); }
.nxs .qa summary { padding: 19px 22px; font-weight: 700; font-size: 15px; cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 14px; }
.nxs .qa summary::-webkit-details-marker { display: none; }
.nxs .qa summary::after { content: "+"; font-size: 24px; color: var(--or-ink); font-weight: 300; transition: transform 0.2s; flex-shrink: 0; line-height: 1; }
.nxs .qa[open] summary::after { transform: rotate(45deg); }
.nxs .qa p { padding: 0 22px 19px; color: var(--muted); font-size: 14px; }

/* ── final cta ── */
.nxs-final { padding: 92px 0; }
.nxs .cta-box { background: linear-gradient(135deg, #2b2019, #191512 55%, #3a281b); border-radius: 30px; padding: 76px 40px; text-align: center; color: #fff; position: relative; overflow: hidden; }
.nxs .cta-box::before { content: ""; position: absolute; width: 520px; height: 520px; border-radius: 50%; background: rgba(249, 115, 22, 0.24); filter: blur(120px); top: -220px; right: -120px; }
.nxs .cta-box h2 { font-size: clamp(30px, 4.6vw, 48px); font-weight: 800; margin-bottom: 14px; position: relative; }
.nxs .cta-box h2 em { font-family: var(--font-fraunces), serif; font-style: italic; font-weight: 500; color: #fdba74; }
.nxs .cta-box p { color: #ccc3b8; font-size: 17px; margin-bottom: 32px; position: relative; }
.nxs .cta-box .acts { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; position: relative; }
.nxs .cta-box .btn-ghost { background: transparent; border-color: rgba(255, 255, 255, 0.25); color: #fff; }
.nxs .cta-box .btn-ghost:hover { background: rgba(255, 255, 255, 0.08); }
.nxs .cta-box .note { justify-content: center; margin-top: 20px; color: #a8a097; }
.nxs .cta-box .note svg { color: #fdba74; }

/* ── footer ── */
.nxs-foot { border-top: 1px solid var(--line2); padding: 56px 0 34px; font-size: 13.5px; color: var(--muted); }
.nxs .fgrid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 36px; margin-bottom: 38px; }
@media (max-width: 760px) { .nxs .fgrid { grid-template-columns: 1fr 1fr; } }
.nxs .fcol h5 { font-size: 12px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink2); margin-bottom: 14px; }
.nxs .fcol a { display: block; margin-bottom: 9px; transition: color 0.14s; }
.nxs .fcol a:hover { color: var(--or-ink); }
.nxs .fcol > p { max-width: 260px; }
.nxs .fbot { display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; border-top: 1px solid var(--line2); padding-top: 26px; }
.nxs .socials { display: flex; gap: 10px; }
.nxs .socials a { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid var(--line); border-radius: 10px; transition: 0.15s; }
.nxs .socials a:hover { background: var(--warm); color: var(--ink); }
.nxs .socials svg { width: 16px; height: 16px; }

input.content:
import type { Metadata } from "next";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import Landing from "@/components/site/landing";

// The apex host (nexis.revsports.ca / www) serves the public marketing site.
// The admin app lives on app.<base> — hitting "/" there means a signed-in
// user, so send them to their dashboard. Middleware already gates access.
const BASE = "nexis.revsports.ca";
const MARKETING_HOSTS = [BASE, `www.${BASE}`];

export const metadata: Metadata = {
  title: "Studio Nexis — Run your whole studio from one calm place",
  description:
    "The all-in-one operating system for pilates & yoga studios: booking, payments, memberships, staff, finance and marketing — designed to work as one. Free 7-day trial, no card.",
  openGraph: {
    title: "Studio Nexis — The operating system for pilates & yoga studios",
    description: "Booking, payments, memberships, staff, finance and marketing in one beautiful platform.",
    type: "website",
  },
};

