# Studio Nexis STAGING. All *.stg.nexis.revsports.ca (apex, app, hq, tenant
# sites) proxy to the staging Next app on :3106. Fully separate from prod.
server {
    listen 72.62.69.9:80;
    server_name stg.nexis.revsports.ca *.stg.nexis.revsports.ca;
    return 301 https://$host$request_uri;
}
server {
    listen 72.62.69.9:443 ssl;
    server_name stg.nexis.revsports.ca *.stg.nexis.revsports.ca;

    ssl_certificate /etc/letsencrypt/live/stg.nexis.revsports.ca/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/stg.nexis.revsports.ca/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    client_max_body_size 15M;

    location / {
        proxy_pass http://127.0.0.1:3106;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

