1	// Per-deployment configuration. Base domains are the one thing that differs
2	// between environments (prod = nexis.revsports.ca, staging = stg.nexis.revsports.ca,
3	// and the studionexis.com move). Everything host-related derives from them, so a
4	// new environment or a domain migration only needs env changes, no code changes.
5	//
6	// NEXT_PUBLIC_ is inlined into the client bundle at build time AND readable on the
7	// server/edge at runtime, so these cover middleware, server code and client
8	// components alike. Unset → production default.
9	//
10	// A deployment can serve MORE THAN ONE base domain at once (e.g. during the
11	// studionexis.com migration both studionexis.com and nexis.revsports.ca are live).
12	// NEXT_PUBLIC_BASE_DOMAINS is a comma-separated list; the FIRST entry is the
13	// canonical one used to build outbound links. NEXT_PUBLIC_BASE_DOMAIN (singular)
14	// is still honoured for backwards compatibility.
15	const RAW = process.env.NEXT_PUBLIC_BASE_DOMAINS ?? process.env.NEXT_PUBLIC_BASE_DOMAIN ?? "nexis.revsports.ca";
16	
17	export const BASE_DOMAINS = RAW.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
18	
19	// Canonical base domain (first in the list) — used for all generated links.
20	export const BASE_DOMAIN = BASE_DOMAINS[0];
21	
22	// Canonical origins for this deployment.
23	export const APP_ORIGIN = `https://app.${BASE_DOMAIN}`;
24	export const APEX_ORIGIN = `https://${BASE_DOMAIN}`;
25	
26	// Which of our base domains does this request host belong to? Returns the
27	// matching base (longest match wins if several would match), or null when the
28	// host is none of ours — i.e. a tenant's own custom domain.
29	export function baseForHost(host: string): string | null {
30	  const h = (host ?? "").toLowerCase();
31	  let best: string | null = null;
32	  for (const b of BASE_DOMAINS) {
33	    if (h === b || h.endsWith(`.${b}`)) {
34	      if (best === null || b.length > best.length) best = b;
35	    }
36	  }
37	  return best;
38	}

1	import { NextResponse, type NextRequest } from "next/server";
2	import { jwtVerify } from "jose";
3	import { canAccess, homeFor } from "@/lib/access";
4	import { baseForHost } from "@/lib/config";
5	
6	const PUBLIC = ["/login", "/api/login", "/signup", "/api/signup", "/book", "/s", "/api/public", "/api/cron", "/api/media", "/api/twilio", "/api/stripe", "/api/v1", "/developers", "/api/hq-impersonate"];
7	
8	// Sub-hosts of a base that serve the (hidden) admin app rather than a tenant.
9	const adminHostsFor = (base: string) => [`app.${base}`, `new.${base}`];
10	const LOCAL_HOSTS = ["localhost", "127.0.0.1"];
11	const RESERVED_SLUGS = ["app", "new", "www", "hq", "api", "mail", "admin"];
12	
13	// Pretty customer paths on a tenant host → internal slugged routes.
14	const TENANT_ALIASES: Record<string, string> = {
15	  "/": "/s/{slug}",
16	  "/book": "/book/{slug}",
17	  "/packages": "/book/{slug}/packages",
18	  "/bookings": "/book/{slug}/bookings",
19	  "/my-packages": "/book/{slug}/my-packages",
20	  "/account": "/book/{slug}/account",
21	  "/book/me": "/book/{slug}/account",
22	};
23	
24	export async function middleware(req: NextRequest) {
25	  const { pathname } = req.nextUrl;
26	  const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").split(":")[0].toLowerCase();
27	
28	  // Which of our base domains (if any) does this host belong to? A deployment
29	  // can serve several at once during a domain migration; everything downstream
30	  // routes relative to the matched base so both domains behave identically.
31	  const BASE = baseForHost(host);
32	  const ADMIN_HOSTS = BASE ? [...adminHostsFor(BASE), ...LOCAL_HOSTS] : LOCAL_HOSTS;
33	
34	  // ── Super-admin portal on its own subdomain (Wave 12 Z9) ─────────────
35	  if (BASE && host === `hq.${BASE}`) {
36	    if (pathname === "/login" || pathname.startsWith("/api/") || pathname.startsWith(`/${process.env.HQ_PATH ?? "hq"}`)) {
37	      return NextResponse.next();
38	    }
39	    // Not signed in yet → the login page (the HQ page itself 404s without a
40	    // SUPERADMIN session, which reads as a broken site).
41	    const hqToken = req.cookies.get("nx_session")?.value;
42	    let ok = false;
43	    if (hqToken) {
44	      try {
45	        const { payload } = await jwtVerify(hqToken, new TextEncoder().encode(process.env.AUTH_SECRET!));
46	        ok = payload.role === "SUPERADMIN";
47	      } catch {}
48	    }
49	    if (!ok) return NextResponse.redirect(new URL("/login", req.url));
50	    const url = new URL(`/${process.env.HQ_PATH ?? "hq"}${pathname === "/" ? "" : pathname}`, req.url);
51	    url.search = req.nextUrl.search;
52	    return NextResponse.rewrite(url);
53	  }
54	
55	  // ── Apex marketing host: the public SaaS landing site. The admin app
56	  //    lives on app.<BASE>, so keep "/" here and bounce every other path
57	  //    (login, signup, dashboard, developers…) to the app host on the SAME
58	  //    base domain the visitor arrived on. ────────────────────────────────
59	  if (BASE && (host === BASE || host === `www.${BASE}`)) {
60	    if (pathname === "/") return NextResponse.next();
61	    return NextResponse.redirect(new URL(`https://app.${BASE}${pathname}${req.nextUrl.search}`));
62	  }
63	
64	  // ── Tenant hosts: <slug>.BASE and custom domains ──────────────────────
65	  let slugParam: string | null = null;
66	  if (BASE && host.endsWith(`.${BASE}`) && !ADMIN_HOSTS.includes(host)) {
67	    const slug = host.slice(0, -(BASE.length + 1));
68	    if (slug && !RESERVED_SLUGS.includes(slug)) slugParam = slug;
69	  } else if (!BASE && host && !ADMIN_HOSTS.includes(host)) {
70	    slugParam = `~${host}`; // a tenant's own custom domain (none of our bases)
71	  }
72	
73	  if (slugParam) {
74	    const alias = TENANT_ALIASES[pathname];
75	    if (alias) {
76	      const url = new URL(alias.replaceAll("{slug}", slugParam), req.url);
77	      url.search = req.nextUrl.search; // keep ?preview=, ?d=, ?ok=…
78	      return NextResponse.rewrite(url);
79	    }
80	    // Class detail pages keep their pretty /class/<id> path.
81	    if (pathname.startsWith("/class/")) {
82	      const url = new URL(`/book/${slugParam}${pathname}`, req.url);
83	      url.search = req.nextUrl.search;
84	      return NextResponse.rewrite(url);
85	    }
86	    // Already-slugged public routes and APIs pass through.
87	    if (pathname.startsWith("/s/") || pathname.startsWith("/book/") || pathname.startsWith("/api/")) {
88	      return NextResponse.next();
89	    }
90	    // Everything else (login, dashboard, any admin surface) does not exist
91	    // on a customer domain — bounce to the studio site.
92	    return NextResponse.redirect(new URL("/", req.url));
93	  }
94	
95	  // ── Admin hosts: normal auth-gated app ────────────────────────────────
96	  if (PUBLIC.some((p) => pathname === p || pathname.startsWith(p + "/"))) {
97	    return NextResponse.next();
98	  }
99	
100	  const token = req.cookies.get("nx_session")?.value;
101	  if (token) {
102	    try {
103	      const { payload } = await jwtVerify(token, new TextEncoder().encode(process.env.AUTH_SECRET!));
104	      const role = payload.role as string;
105	      if (!canAccess(role, pathname)) {
106	        return NextResponse.redirect(new URL(homeFor(role), req.url));
107	      }
108	      return NextResponse.next();
109	    } catch {
110	      // fall through to login redirect
111	    }
112	  }
113	  return NextResponse.redirect(new URL("/login", req.url));
114	}
115	
116	export const config = {
117	  matcher: ["/((?!_next/static|_next/image|favicon.ico|studio/|.*\\.(?:svg|png|jpg|jpeg|webp|ico|css|js|woff2?)).*)"],
118	};

