echo "=== docker postgres run spec (to reproduce on new server) ==="
docker inspect nexis-postgres --format '  image: {{.Config.Image}}
  cmd: {{.Config.Cmd}}
  restart: {{.HostConfig.RestartPolicy.Name}}
  ports: {{range $p,$c := .NetworkSettings.Ports}}{{$p}}->{{$c}} {{end}}
  env: {{range .Config.Env}}{{println "    " .}}{{end}}' 2>/dev/null | sed -E 's/(POSTGRES_PASSWORD=)[^ ]+/\1<masked>/'
echo "=== postgres volumes ==="; docker inspect nexis-postgres --format '{{range .Mounts}}  {{.Type}} {{.Source}} -> {{.Destination}}{{println}}{{end}}'
echo "=== env / secret files to move ==="; for f in /opt/nexis/.env /opt/nexis/.env.local.secrets /opt/nexis-staging/.env /root/.secrets/cloudflare.ini /root/.secrets/cloudflare-studionexis.ini; do [ -f "$f" ] && echo "  ✓ $f ($(stat -c%s "$f")b)" || echo "  ✗ $f (missing)"; done
echo "=== v2 nginx vhosts ==="; ls /etc/nginx/conf.d/ | grep -iE "nexis|studionexis|stg|custom-domain" 
echo "=== nexis cron files ==="; ls /etc/cron.d/ | grep -i nexis
echo "=== systemd units ==="; ls /etc/systemd/system/nexis-*.service
echo "=== node / nginx / certbot / docker versions ==="; node -v; nginx -v 2>&1; certbot --version 2>&1; docker --version

