import { chromium } from "playwright-core";

const BASE = "https://app.stg.studionexis.com";
const [email, password] = [process.argv[2], process.argv[3]];

const browser = await chromium.launch({ args: ["--no-sandbox"] });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();

// 1. public page
await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
await page.screenshot({ path: "/opt/nexis-shots/probe-login.png" });
console.log("login page shot OK");

// 2. authenticate
await page.fill('input[name="email"]', email);
await page.fill('input[name="password"]', password);
await Promise.all([page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}), page.click('button[type="submit"]')]);
console.log("after login ->", page.url());

// 3. auth-gated page, full height
await page.goto(`${BASE}/dashboard`, { waitUntil: "networkidle" });
await page.screenshot({ path: "/opt/nexis-shots/probe-dashboard.png", fullPage: true });
const title = await page.textContent("h1").catch(() => null);
console.log("dashboard h1:", title);
console.log("dashboard url:", page.url());

await browser.close();

