// Studio Nexis — full screen capture for Figma redesign.
// Runs against STAGING only. Desktop 1440px, 2x retina, full-page.
//
// Usage: node capture.mjs
// Reads credentials from env: OWNER_EMAIL, OWNER_PASS, HQ_EMAIL, HQ_PASS
import { chromium } from "playwright-core";
import { mkdirSync, writeFileSync } from "fs";

const STG = "stg.studionexis.com";
const APP = `https://app.${STG}`;
const HQ = `https://hq.${STG}`;
const OUT = "/opt/nexis-shots/out";
const VIEWPORT = { width: 1440, height: 900 };

// Dynamic ids are injected by the caller (resolved from the DB) so pages
// render with real content instead of empty states.
const IDS = JSON.parse(process.env.IDS_JSON ?? "{}");
const sub = (p) => p.replace(/\[(\w+)\]/g, (_, k) => IDS[k] ?? "");

const ADMIN = [
  "/dashboard", "/schedule", "/schedule/new", "/schedule/[id]", "/classes", "/class-types",
  "/class-types/[classTypeId]", "/bookings", "/clients", "/clients/new", "/clients/[clientId]",
  "/clients/[clientId]/edit", "/pos", "/products", "/invoices", "/expenses", "/payroll",
  "/my-earnings", "/analytics", "/billing", "/team", "/team/[userId]", "/settings", "/apps",
  "/website", "/website/setup", "/website/editor", "/locations", "/inbox", "/support",
  "/getting-started", "/welcome", "/whats-new",
];
const HQ_PAGES = [
  "/", "/studios", "/t/[tenantId]", "/analytics", "/billing", "/requests", "/support",
  "/support/[ticketId]", "/broadcasts", "/releases", "/kb", "/flags", "/logs", "/status",
  "/comms", "/chats", "/team", "/hq-settings",
];
const PUBLIC = [
  { url: `https://${STG}/`, name: "marketing-landing" },
  { url: `${APP}/login`, name: "login" },
  { url: `${APP}/signup`, name: "signup" },
  { url: `${APP}/developers`, name: "developers-api-docs" },
];
const TENANT_PATHS = ["/", "/book", "/packages", "/bookings", "/my-packages", "/account"];

const slug = (s) => s.replace(/^\//, "").replace(/\//g, "_").replace(/[^\w-]/g, "") || "index";
const results = [];

async function shoot(page, url, name, group) {
  const dir = `${OUT}/${group}`;
  mkdirSync(dir, { recursive: true });
  try {
    const res = await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
    await page.waitForTimeout(700); // let charts/animations settle
    const status = res?.status() ?? 0;
    const file = `${dir}/${name}.png`;
    await page.screenshot({ path: file, fullPage: true });
    results.push({ group, name, url, status, file });
    console.log(`  ${status}  ${group}/${name}`);
  } catch (e) {
    results.push({ group, name, url, status: "ERROR", error: String(e).slice(0, 120) });
    console.log(`  ERR  ${group}/${name}  ${String(e).slice(0, 80)}`);
  }
}

async function login(page, base, email, pass) {
  await page.goto(`${base}/login`, { waitUntil: "networkidle" });
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', pass);
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
    page.click("form button"),
  ]);
  const ok = !page.url().includes("error");
  console.log(`login ${email} -> ${ok ? "OK" : "FAILED"} (${page.url()})`);
  return ok;
}

const browser = await chromium.launch({ args: ["--no-sandbox"] });

// ── public (no auth) ──
{
  const ctx = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  console.log("\n== PUBLIC ==");
  for (const p of PUBLIC) await shoot(page, p.url, p.name, "1-public");

  console.log("\n== TENANT BOOKING SITE ==");
  const tslug = process.env.TENANT_SLUG || "dev-studio";
  for (const p of TENANT_PATHS) {
    await shoot(page, `https://${tslug}.${STG}${p}`, slug(p), "2-client-booking");
  }
  await ctx.close();
}

// ── studio admin (owner auth) ──
if (process.env.OWNER_EMAIL) {
  const ctx = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  console.log("\n== STUDIO ADMIN ==");
  if (await login(page, APP, process.env.OWNER_EMAIL, process.env.OWNER_PASS)) {
    for (const p of ADMIN) {
      const path = sub(p);
      if (path.includes("//") || /\[\w+\]/.test(path)) { console.log(`  skip ${p} (no id)`); continue; }
      await shoot(page, `${APP}${path}`, slug(p), "3-studio-admin");
    }
  }
  await ctx.close();
}

// ── HQ super-admin ──
if (process.env.HQ_EMAIL) {
  const ctx = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  console.log("\n== HQ SUPER-ADMIN ==");
  if (await login(page, HQ, process.env.HQ_EMAIL, process.env.HQ_PASS)) {
    for (const p of HQ_PAGES) {
      const path = sub(p);
      if (/\[\w+\]/.test(path)) { console.log(`  skip ${p} (no id)`); continue; }
      await shoot(page, `${HQ}${path === "/" ? "/" : path}`, slug(p), "4-hq-superadmin");
    }
  }
  await ctx.close();
}

await browser.close();
writeFileSync(`${OUT}/manifest.json`, JSON.stringify(results, null, 2));
const ok = results.filter((r) => r.status === 200).length;
