    data: {
      tenantId: T, clientId: c.id, packageId: p.id,
      creditsLeft: int(1, p.credits), expiresAt: day(p.validityDays - int(0, 20)),
      pricePaid: p.price, createdAt: when,
    },
  }));
  if (rnd() > 0.6) {
    const prod = pick(products);
    await db.order.create({
      data: {
