for (let d = -21; d <= 14; d++) {
  const date = day(d);
  const dow = (date.getUTCDay() + 6) % 7; // Mon=0
  for (const ct of types) {
    for (const slot of ct.recurringSlots) {
      if (slot.day !== dow) continue;
      const [hh, mm] = slot.time.split(":").map(Number);
      const startsAt = at(date, hh, mm);
