            tenantId: T, sessionId: session.id, clientId: c.id, status, qty: 1,
            paymentMethod: usedCredit ? "package_credit" : "at_studio",
            ...(usedCredit ? { clientPackageId: cp.id } : {}),
            createdAt: new Date(startsAt.getTime() - int(1, 6) * 86400000),
