1	// Per-deployment configuration. Base domains are the one thing that differs
2	// between environments (prod = nexis.revsports.ca, staging = stg.nexis.revsports.ca,
3	// and the studionexis.com move). Everything host-related derives from them, so a
4	// new environment or a domain migration only needs env changes, no code changes.
5	//
6	// NEXT_PUBLIC_ is inlined into the client bundle at build time AND readable on the
7	// server/edge at runtime, so these cover middleware, server code and client
8	// components alike. Unset → production default.
9	//
10	// A deployment can serve MORE THAN ONE base domain at once (e.g. during the
11	// studionexis.com migration both studionexis.com and nexis.revsports.ca are live).
12	// NEXT_PUBLIC_BASE_DOMAINS is a comma-separated list; the FIRST entry is the
13	// canonical one used to build outbound links. NEXT_PUBLIC_BASE_DOMAIN (singular)
14	// is still honoured for backwards compatibility.
15	const RAW = process.env.NEXT_PUBLIC_BASE_DOMAINS ?? process.env.NEXT_PUBLIC_BASE_DOMAIN ?? "nexis.revsports.ca";
16	
17	export const BASE_DOMAINS = RAW.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
18	
19	// Canonical base domain (first in the list) — used for all generated links.
20	export const BASE_DOMAIN = BASE_DOMAINS[0];
21	
22	// Canonical origins for this deployment.
23	export const APP_ORIGIN = `https://app.${BASE_DOMAIN}`;
24	export const APEX_ORIGIN = `https://${BASE_DOMAIN}`;
25	
26	// Which of our base domains does this request host belong to? Returns the
27	// matching base (longest match wins if several would match), or null when the
28	// host is none of ours — i.e. a tenant's own custom domain.
29	export function baseForHost(host: string): string | null {
30	  const h = (host ?? "").toLowerCase();
31	  let best: string | null = null;
32	  for (const b of BASE_DOMAINS) {
33	    if (h === b || h.endsWith(`.${b}`)) {
34	      if (best === null || b.length > best.length) best = b;
35	    }
36	  }
37	  return best;
38	}

